protected const array ID2DESC = [
0=>['No Skill','Empty skill slot','Empty slot'],
1=>['Siegel der Heilung','Siegel. Ihr bekommt 82...172 Lebenspunkt[e]. Während Ihr diese Fertigkeit benutzt, habt Ihr -40 Rüstung.','Siegel. Ihr erhaltet 82...172 Lebenspunkt[e]. Während Ihr diese Fertigkeit benutzt, habt Ihr -40 Rüstung.'],
2=>['Siegel der Wiederbelebung','Siegel. Das als Ziel ausgewählte Gruppenmitglied wird wiederbelebt. Dieses Gruppenmitglied kehrt mit 100% seiner Lebenspunkte und 25% seiner Energiepunkte ins Leben zurück. Dieses Siegel wird nur dann wieder aufgeladen, wenn Ihr einen Moralschub erhaltet.','Siegel. Das Gruppenmitglied wird wiederbelebt (100% Lebenspunkte, 25% Energiepunkte). Dieses Siegel wird nur dann wieder aufgeladen, wenn Ihr einen Moralschub erhaltet.'],
3=>['Siegel der Erbeutung','Siegel. Wählt eine Fertigkeit von einem toten Boss Eurer Klasse in der Nähe. Siegel der Erbeutung wird dauerhaft mit dieser Fertigkeit ersetzt. Wenn es sich dabei um eine Elite-Fertigkeit handelt, erhaltet Ihr pro Stufe, die Ihr erlangt habt, 250 EP.','Siegel. Wählt eine Fertigkeit von einem toten Boss Eurer Klasse in der Nähe. Siegel der Erbeutung wird dauerhaft durch diese Fertigkeit ersetzt. Handelt es sich um eine Elite-Fertigkeit, erhaltet Ihr pro Stufe, die Ihr erlangt habt, 250 EP.'],
5=>['Kraftblock','Elite-Zauber. Falls der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird dieser unterbrochen und diese Fertigkeit und alle Fertigkeiten desselben Attributs 1...12 Sekunde[n] lang deaktiviert.','Elite-Zauber. Falls der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird dieser unterbrochen und diese Fertigkeit und alle Fertigkeiten desselben Attributs 1...12 Sekunde[n] lang deaktiviert.'],
6=>['Mantra der Erde','Haltung. Wann immer Ihr Erdschaden erleidet, ist der Schaden für einen Zeitraum von 30...90 Sekunde[n] um 26...50% reduziert und Ihr erhaltet 2 Energiepunkte.','Haltung. 30...90 Sekunde[n]: Reduziert den von Euch erlittenen Erdschaden um 26...50%. Ihr erhaltet 2 Energiepunkte, wenn Ihr Erdschaden erleidet.'],
7=>['Mantra des Feuers','Haltung. Wann immer Ihr Feuerschaden erleidet, ist der Schaden für einen Zeitraum von 30...90 Sekunde[n] um 26...50% reduziert und Ihr erhaltet 2 Energiepunkte.','Haltung. 30...90 Sekunde[n]: Reduziert den von Euch erlittenen Feuerschaden um 26...50%. Ihr erhaltet 2 Energiepunkte, wenn Ihr Feuerschaden erleidet.'],
8=>['Mantra des Frosts','Haltung. Wann immer Ihr Kälteschaden erleidet, ist der Schaden für einen Zeitraum von 30...90 Sekunde[n] um 26...50% reduziert und Ihr erhaltet 2 Energiepunkte.','Haltung. 30...90 Sekunde[n]: Reduziert den von Euch erlittenen Kälteschaden um 26...50%. Ihr erhaltet 2 Energiepunkte, wenn Ihr Kälteschaden erleidet.'],
9=>['Mantra des Blitzes','Haltung. Wann immer Ihr Blitzschaden erleidet, ist der Schaden für einen Zeitraum von 30...90 Sekunde[n] um 26...50% reduziert und Ihr erhaltet 2 Energiepunkte.','Haltung. 30...90 Sekunde[n]: Reduziert den von Euch erlittenen Blitzschaden um 26...50%. Ihr erhaltet 2 Energiepunkte, wenn Ihr Blitzschaden erleidet.'],
10=>['Gebrochene Verhexung','Haltung. Wenn Ihr innerhalb der nächsten 5...80 Sekunde[n] Ziel einer Verhexung seid, misslingt diese und der Wirker erleidet 10...46 Punkt[e] Schaden.','Haltung. 5...80 Sekunde[n]: Die nächste Verhexung gegen Euch misslingt und der Wirker erleidet 10...46 Punkt[e] Schaden.'],
11=>['Verzerrung','Haltung. Ihr habt 1...5 Sekunde[n] lang eine 75%ige Chance, Angriffe zu blocken. Immer, wenn Ihr auf diese Weise einen Angriff blockt, verliert Ihr 2 Energiepunkt[e] oder Verzerrung endet.','Haltung. 1...5 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken. Blockkosten: Ihr verliert 2 Energiepunkt[e] oder Verzerrung endet.'],
13=>['Mantra der Erholung','Elite-Haltung. Die von Euch gewirkten Zauber werden 5...20 Sekunde[n] lang um 33% schneller wieder aufgeladen.','Elite-Haltung. (5...20 Sekunde[n].) Eure Zauber werden um 33% schneller wieder aufgeladen.'],
14=>['Mantra des Bestehens','Haltung. 5...25 Sekunde[n] lang halten sämtliche von Euch gewirkten Illusionsmagie-Verhexungen um 10...40% länger an.','Haltung. 5...25 Sekunde[n]: Von Euch gewirkte Illusions-Verhexungen halten um 10...40% länger an.'],
15=>['Mantra der Inschriften','Haltung. 5...25 Sekunde[n] lang werden Siegel, die Ihr erfolgreich aktiviert, während Ihr Euch in dieser Haltung befindet, um 10...40% schneller aufgeladen.','Haltung. 5...25 Sekunde[n]: Erfolgreich in dieser Haltung aktivierte Siegel werden um 10...40% schneller aufgeladen.'],
16=>['Mantra der Konzentration','Haltung. 1...38 Sekunde[n] lang werdet Ihr das nächste Mal, wenn Ihr sonst unterbrochen würdet, nicht unterbrochen.','Haltung. 1...38 Sekunde[n]: Das nächste Mal, wenn Ihr sonst unterbrochen würdet, werdet Ihr nicht unterbrochen.'],
17=>['Mantra des Abschlusses','Haltung. Ihr könnt 30...90 Sekunde[n] lang nicht unterbrochen werden, aber jedes Mal, wenn Ihr normalerweise unterbrochen würdet, verliert Ihr 10...4 Energiepunkt[e] oder Mantra des Abschlusses endet.','Haltung. 30...90 Sekunde[n]: Verhindert Unterbrechungen gegen Euch. Verhinderungskosten: Ihr verliert 10...4 Energiepunkt[e] oder Mantra des Abschlusses endet.'],
18=>['Mantra der Siegel','Haltung. 10...40 Sekunde[n] lang habt Ihr +3 Rüstung für jedes ausgerüstete Siegel. Wenn Ihr ein Siegel einsetzt, erhaltet Ihr 5...60 Lebenspunkt[e].','Haltung. (10...40 Sekunde[n].) Ihr habt +3 Rüstung für jedes Siegel. Ihr erhaltet jedesmal, wenn Ihr ein Siegel einsetzt, 5...60 Lebenspunkt[e].'],
19=>['Zerbrechlichkeit','Verhexung. 8...20 Sekunde[n] lang erleiden Gegner und umstehende Feinde jedes Mal, wenn sie unter einem neuen Zustand leiden oder sich davon erholen, 5...20 Punkt[e] Schaden.','Verhexung. Verhext außerdem den Gegner und umstehende Feinde (8...20 Sekunde[n]). Diese Gegner erleiden jedes Mal, wenn sie unter einem neuen Zustand leiden oder sich davon erholen, 5...20 Punkt[e] Schaden.'],
21=>['Inspirierte Verzauberung','Zauber. Eine Verzauberung wird vom Gegner entfernt und Ihr und erhaltet 3...15 Energiepunkt[e]. Inspirierte Verzauberung wird 20 Sekunden lang durch die dem Gegner genommene Verzauberung ersetzt.','Zauber. Entfernt beim Gegner eine Verzauberung. Entfernungswirkungen: Ihr erhaltet 3...15 Energiepunkt[e]; dieser Zauber wird durch die entfernte Verzauberung ersetzt (20 Sekunden).'],
22=>['Inspirierte Verhexung','Zauber. Eine Verhexung wird von einem Verbündeten (bzw. Euch selbst) entfernt und Ihr erhaltet 4...10 Energiepunkt[e]. Inspirierte Verhexung wird 20 Sekunden lang durch die entfernte Verhexung ersetzt.','Zauber. Entfernt beim Verbündeten (bzw. Euch selbst) eine Verhexung. Entfernungswirkungen: Ihr erhaltet 4...10 Energiepunkt[e]; dieser Zauber wird durch die entfernte Verhexung ersetzt (20 Sekunden).'],
23=>['Kraftdorn','Zauber. Wenn der Gegner einen Zauber oder einen Anfeuerungsruf wirkt, wird dieser unterbrochen und der Gegner erleidet 30...120 Punkt[e] Schaden.','Zauber. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: Richtet 30...120 Punkt[e] Schaden an.'],
24=>['Kraftleck','Zauber. Wenn der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird dieser unterbrochen und der Gegner verliert 3...17 Energiepunkt[e].','Zauber. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: Gegner verliert 3...17 Energiepunkt[e].'],
25=>['Kraftentzug','Zauber. Wenn der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird dieser unterbrochen und Ihr erhaltet 1...31 Energiepunkt[e].','Zauber. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: Ihr erhaltet 1...31 Energiepunkt[e].'],
26=>['Empathie','Verhexung. 5...15 Sekunde[n] lang erleidet der Gegner bei jedem seiner Angriffe 10...55 Punkt[e] Schaden und verursacht 1...15 Punkt[e] weniger Schaden.','Verhexung. (5...15 Sekunde[n].) Gegner erleidet bei jedem seiner Angriffe 10...55 Punkt[e] Schaden und fügt 1...15 Punkt[e] weniger Schaden zu.'],
27=>['Täuschungen brechen','Zauber. Entfernt eine Mesmer-Verhexung vom anvisierten Gegner. Dabei erleidet der Gegner 15...75 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.','Zauber. Entfernt eine Mesmer-Verhexung vom anvisierten Gegner. Dabei erleidet der Gegner 15...75 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.'],
28=>['Rückschlag','Verhexung. 10 Sekunden lang erleidet der Gegner für jeden gewirkten Zauber 35...140 Punkt[e] Schaden.','Verhexung. 10 Sekunden: Gegner erleidet bei jedem seiner Zauber 35...140 Punkt[e] Schaden.'],
29=>['Blackout','Fertigkeit. 2...8 Sekunde[n] lang werden alle Fertigkeiten des berührten Gegners deaktiviert und alle Eure eigenen Fertigkeiten werden 5 Sekunden lang deaktiviert.','Berührungs-Fertigkeit. 2...8 Sekunde[n]: Deaktiviert Fertigkeiten. Eure Fertigkeiten werden deaktiviert (5 Sekunden).'],
30=>['Ablenkung','Verhexung. 6 Sekunden lang, benötigt das Wiederaufladen dieser Fertigkeit zusätzlich 10...56 Sekunde[n], wenn der Gegner das nächste Mal eine Fertigkeit benutzt.','Verhexung. 6 Sekunden: Nächste benutzte Fertigkeit des Gegners benötigt +10...56 Sekunde[n] zum Wiederaufladen.'],
31=>['Trugbild beschwören','Verhexung. 4...18 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -5.','Verhexung. 4...18 Sekunde[n]: Verursacht -5 Lebenspunktdegeneration.'],
32=>['Illusion der Schwäche','Verzauberung. Ihr verliert 50...240 Lebenspunkt[e]. "Illusion der Schwäche" endet, wenn der Schaden Eure Lebenspunkte unter 25% Eurer maximalen Lebenspunkte bringt. Wenn "Illusion der Schwäche" endet, bekommt Ihr 50...240 Lebenspunkt[e].','Verzauberung. Ihr verliert 50...240 Lebenspunkt[e]. Wirkung am Ende: Ihr erhaltet 50...240 Lebenspunkt[e]. Endet, wenn Eure Lebenspunkte durch Schaden unter 25% Eurer maximalen Lebenspunkte gebracht werden.'],
33=>['Illusion der Waffen','Elite-Verzauberung. 30 Sekunden lang sind Eure Nahkampfangriffe weder erfolgreich noch erfolglos. Stattdessen verursacht Illusion der Waffen bei jedem Nahkampfangriff 20...60 Punkt[e] Schaden an Euren Gegnern. Ihr habt +5 Rüstung pro ausgerüsteter Illusionsmagie-Fertigkeit.','Elite-Verzauberung. (30 Sekunden.) Richtet anstatt von Schaden oder Effekten aus Nahkampfangriffen 20...60 Punkt[e] Schaden bei Gegnern an. Ihr habt +5 Rüstung pro ausgerüsteter Illusionsmagie-Fertigkeit. Eure Nahkampfangriffe sind weder erfolgreich noch erfolglos.'],
34=>['Sympathisches Gesicht','Verzauberung. 4...10 Sekunde[n] lang verlieren alle umstehenden Feinde jedes Mal, wenn der Verbündete (bzw. Ihr selbst) im Nahkampf getroffen wird, sämtliches Adrenalin sowie drei Energiepunkte.','Verzauberung. 4...10 Sekunde[n]: Alle umstehenden Feinde verlieren jedes Mal sämtliches Adrenalin und 3 Energiepunkte, wenn ein Nahkampfangriff den Verbündeten (bzw. Euch selbst) trifft.'],
35=>['Ignoranz','Verhexung. 8...20 Sekunde[n] lang kann der Gegner keine Siegel benutzen.','Verhexung. 8...20 Sekunde[n]: Gegner kann keine Siegel benutzen.'],
36=>['Arkanes Rätsel','Verhexung. 5...15 Sekunde[n] lang brauchen der Gegner und alle umstehenden Feinde doppelt so lange, um ihre Zauber zu wirken. Wenn diese Verhexung endet, erhaltet Ihr 1...7 Energiepunkt[e].','Verhexung. Verhext den Gegner und umstehende Feinde (5...15 Sekunde[n]). Verdoppelt die Wirkzeit von Zaubern. Wirkung am Ende: Ihr erhaltet 1...7 Energiepunkt[e].'],
37=>['Illusion der Eile','Verzauberung. 5...11 Sekunde[n] lang seid Ihr nicht mehr verkrüppelt und bewegt Euch um 33% schneller. Wenn Illusion der Eile endet, werdet Ihr 3 Sekunde[n] lang in den Zustand der Verkrüppelung versetzt.','Verzauberung. (5...11 Sekunde[n].) Ihr bewegt Euch um 33% schneller. Anfangswirkung: Beseitigt Zustand der Verkrüppelung. Wirkung am Ende: Ihr werdet (3 Sekunde[n]) lang in den Zustand der Verkrüppelung versetzt.'],
38=>['Kanalisieren','Verzauberung. 8...56 Sekunde[n] lang erhaltet für jeden Gegner in dem Bereich jeweils einen Energiepunkt, wann immer Ihr einen Zauber wirkt.','Verzauberung. 8...56 Sekunde[n]: Ihr erhaltet jedes Mal 1 Energiepunkt pro Gegner im Bereich, wenn Ihr einen Zauber wirkt.'],
39=>['Energiewelle','Elite-Zauber. Der anvisierte Gegner verliert 1...10 Energie. Für jeden verlorenen Energiepunkt nimmt er 7 Schaden, und alle Gegner in der Nähe erleiden 75 % dieses Schadens.','Elite-Zauber. Verursacht 1...10 Energieverlust. Fügt dem Ziel für jeden verlorenen Energiepunkt 7 Schaden zu, und Gegnern in der Nähe 75 % dieses Schadens.'],
40=>['Ätherschmaus','Zauber. Der Gegner verliert 3 Punkte Energie. Für jeden verlorenen Energiepunkt erfahrt Ihr 20...65 Punkt[e] Heilung.','Zauber. Lässt 3 Energiepunkte verlieren. Ihr erhaltet pro verlorenem Energiepunkt 20...65 Lebenspunkt[e].'],
41=>['Herr über den Äther','Verhexung. Ihr verliert Eure gesamte Energie. 5...10 Sekunde[n] lang unterliegt der Gegner einer Energiedegeneration von -1...3 und Ihr erfreut Euch einer zusätzlichen Energieregeneration von 1...3.','Verhexung. Ihr verliert alle Energiepunkte. Gegner hat -1...3 Energiedegeneration und Ihr habt +1...3 Energieregeneration (5...10 Sekunde[n]).'],
42=>['Energiebrand','Zauber. Der Gegner verliert 1...10 Energiepunkt[e] und erleidet für jeden verlorenen Energiepunkt 9 Punkt[e] Schaden.','Zauber. Lässt 1...10 Energiepunkt[e] verlieren. Richtet pro verlorenem Energiepunkt 9 Punkt[e] Schaden an.'],
43=>['Ungeschick','Verhexung. 4 Sekunden lang werden der Gegner und umstehende Feinde mit Ungeschick verhext. Beim nächsten Angriff jedes Feindes wird der Angriff unterbrochen und der Feind erleidet 10...80 Punkt[e] Schaden.','Verhexung. 4 Sekunde[n]: Verhext auch umstehende Feinde. Unterbricht nächsten Angriff. Unterbrechungswirkung: Richtet 10...80 Punkt[e] Schaden an.'],
44=>['Phantomschmerz','Verhexung. 10 Sekunden lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...4. Wenn Phantomschmerz endet, erleidet dieser Gegner eine Tiefe Wunde, die seine maximalen Lebenspunkte 5...20 Sekunde[n] lang um 20% reduziert.','Verhexung. 10 Sekunden: Verursacht -1...4 Lebenspunktdegeneration. Wirkung am Ende: Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]).'],
45=>['Ätherische Bürde','Verhexung. 6...12 Sekunden lang bewegt sich der Gegner um 50% langsamer. Wenn Ätherische Bürde endet, erhaltet Ihr 10...18 Energiepunkt[e].','Verhexung. 6...12 Sekunden: Gegner bewegt sich um 50% langsamer. Wirkung am Ende: Ihr erhaltet 10...18 Energiepunkt[e].'],
46=>['Schuld','Verhexung. 6 Sekunde[n] lang schlägt der nächste Zauber des Widersachers auf einen anderen Widersacher fehl und Ihr entzieht jenem Widersacher bis zu 5...14 Energiepunkt[e].','Verhexung. 6 Sekunde[n]: Nächster Zauber des Gegners schlägt fehl und Ihr entzieht ihm 5...14 Energiepunkt[e]. Zauber des Gegners muss auf einen Eurer Verbündeten gerichtet sein, sonst keine Wirkung.'],
47=>['Unbeholfenheit','Elite-Verhexung. 4 Sekunde[n] lang erleiden der Gegner und alle umstehenden Gegner bei ihrem nächsten Angriff 30...135 Punkt[e] Schaden und werden 10 Sekunden lang geblendet.','Elite-Verhexung. (4 Sekunde[n].) Außerdem werden alle umstehenden Feinde verhext. Richtet 30...135 Punkt[e] Schaden an. Verursacht Zustand "Blindheit" (10 Sekunden). Kein Effekt, wenn der verhexte Gegner nicht angreift.'],
48=>['Geist des Versagens','Verhexung. 30 Sekunden lang besteht eine 25%ige Wahrscheinlichkeit, dass der Gegner bei seinen Angriffen nicht trifft. Ihr erhaltet für jeden misslungenen Angriff 1...3 Energiepunkt[e].','Verhexung. 30 Sekunden: Die Angriffe des Gegners gehen mit 25%iger Wahrscheinlichkeit daneben. Ihr erhaltet für jeden misslungenen Angriff des Gegners 1...3 Energiepunkt[e].'],
49=>['Geistiges Wrack','Verhexung. Ist der Gegner das Ziel einer Eurer Mesmer-Fertigkeiten, die keine Verhexung ist, verliert er 5...40 Sekunden lang 1 Energiepunkt und erleidet 5...25 Schadenspunkt[e] pro verlorenem Energiepunkt. Sinken die Energiepunkte des Gegners auf 0, erleidet er 15...100 Punkt[e] Schaden und Geistiges Wrack endet.','Verhexung. (5...40 Sekunden.) Der Gegner verliert 1 Energiepunkt, wenn er Ziel Eurer Mesmer-Fertigkeiten (keine Verhexung) ist. Fügt 5...25 Punkt[e] Schaden pro verlorenem Energiepunkt zu. Sinken die Energiepunkte des Gegners auf 0, erleidet er 15...100 Punkt[e] Schaden und Geistiges Wrack endet.'],
50=>['Verschwendung','Verhexung. Nach 3 Sekunden erleidet der anvisierte Gegner 20...100 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens. Wenn dieser Gegner erfolgreich eine Fertigkeit anwendet, endet Verschwendung frühzeitig und richtet keinen Schaden an.','Verhexung. (3 Sekunden.) Effekt endet: Richtet beim Ziel 20...100 Schaden und bei benachbarten Gegnern 75 % dieses Schadens an. Kein Effekt und vorzeitiges Ende, wenn der anvisierte Gegner eine Fertigkeit verwendet.'],
51=>['Schande','Verhexung. 6 Sekunde[n] lang schlägt der nächste Zauber des Gegners auf einen Verbündeten fehl und Ihr entzieht dem Widersacher bis zu 5...14 Energiepunkt[e].','Verhexung. 6 Sekunde[n]: Nächster Zauber des Gegners schlägt fehl und Ihr entzieht ihm 5...14 Energiepunkt[e]. Zauber des Gegners muss auf einen seiner Verbündeten gerichtet sein, sonst keine Wirkung.'],
52=>['Panik','Elite-Verhexung. 1...10 Sekunde[n] lang wirkt die Verhexung "Panik" auf den Gegner und alle Gegner in der Nähe. Verwendet ein mit "Panik" verhexter Gegner eine Fertigkeit erfolgreich, werden alle Gegner in der Nähe unterbrochen.','Elite-Verhexung. Verhext außerdem Feinde in der Nähe des Gegners (1...10 Sekunde[n]). Unterbricht alle Gegner in der Nähe, wenn ein verhexter Gegner eine Fertigkeit erfolgreich aktiviert.'],
53=>['Migräne','Elite-Verhexung. 5...20 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...8 und benötigt 100% länger, um Fertigkeiten zu aktivieren.','Elite-Verhexung. (5...20 Sekunde[n].) Verursacht -1...8 Lebenspunktdegeneration und verdoppelt die Aktivierungszeit von Fertigkeiten.'],
54=>['Verkrüppelnde Qual','Elite-Verhexung. 5...20 Sekunde[n] lang sind Bewegung und Angriffe des Ziels um 50% langsamer. Der Gegner unterliegt außerdem einer Lebenspunktdegeneration von -1...8.','Elite-Verhexung. (5...20 Sekunde[n].) Bewegung und Angriffe des Gegners sind um 50% langsamer und er hat -1...8 Lebenspunktdegeneration.'],
55=>['Fieberträume','Elite-Verhexung. 10...25 Sekunde[n] lang leiden jedes Mal, wenn der Gegner unter einem neuen Zustand leidet, alle Feinde in dem Bereich ebenfalls unter diesem. Wenn der Gegner mit zwei oder mehr Zuständen belegt ist, wird er für 1...3 Sekunde[n] benommen sein.','Elite-Verhexung. 10...25 Sekunde[n]: Alle neuen Zustände, die der Gegner erhält, gehen auch auf Feinde im Bereich über. Wenn der Gegner mit zwei oder mehr Zuständen belegt ist, wird er für 1...3 Sekunde[n] benommen sein.'],
56=>['Beruhigende Bilder','Verhexung. 8...20 Sekunde[n] lang können der Gegner und alle umstehenden Feinde kein Adrenalin bekommen.','Verhexung. Verhext den Gegner und umstehende Feinde (8...20 Sekunde[n]). Diese Gegner erhalten kein Adrenalin.'],
57=>['Schrei der Frustration','Zauber. Wenn der anvisierte Gegner eine Fertigkeit verwendet, wird er dabei gestört, so wie auch alle anderen Gegner im Bereich. Er erleidet 15...75 Schaden, und die anderen Gegner jeweils 75 % dieses Schadens.','Zauber. Wenn der anvisierte Gegner eine Fertigkeit verwendet, wird er dabei gestört, so wie auch alle anderen Gegner im Bereich. Er erleidet 15...75 Schaden, und die anderen Gegner jeweils 75 % dieses Schadens.'],
58=>['Siegel der Mitternacht','Elite-Siegel. Ihr werdet gemeinsam mit dem berührten Gegner 15 Sekunden lang geblendet.','Elite-Berührungs-Siegel. 15 Sekunden: Verursacht Zustand Blindheit. Ihr leidet an Blindheit (15 Sekunden).'],
59=>['Siegel der Müdigkeit','Siegel. Der Gegner und alle Feinde in der Nähe verlieren 3...8 Energiepunkt[e] und leiden 1...12 Sekunde[n] lang an Schwäche.','Siegel. Wirkt auch auf Feinde in der Nähe des Gegners. Verursacht einen Verlust von 3...8 Energiepunkt[en] und den Zustand "Schwäche" (1...12 Sekunde[n]).'],
61=>['Blutsauger-Siegel','Siegel. Unterbricht die Aktion des Gegners. Falls diese Aktion ein Zauber war, bekommt Ihr 3...15 Energiepunkt[e].','Siegel. Unterbricht eine Aktion. Unterbrechungswirkung: Ihr erhaltet 3...15 Energiepunkt[e], falls die Aktion ein Zauber war.'],
62=>['Siegel der Demut','Siegel. Die Elite-Fertigkeit des Gegners wird 1...16 Sekunde[n] lang deaktiviert. Eure Nicht-Mesmer-Fertigkeiten werden 4 Sekunde[n] lang deaktiviert.','Siegel. Deaktiviert Elite-Fertigkeit (1...16 Sekunde[n]). Deaktiviert Eure Nicht-Mesmer-Fertigkeiten. (4 Sekunde[n]).'],
63=>['Schlussstein-Siegel','Elite-Siegel. Alle Eure Siegel außer dem Schlussstein-Siegel werden wieder aufgeladen. Wenn Ihr in den nächsten 20 Sekunden die nächsten 0...6 Mal ein Siegel gegen einen Gegner einsetzt, erleiden alle anderen umstehenden Feinde 15...60 Punkt[e] Schaden und werden unterbrochen.','Elite-Siegel. (20 Sekunden.) Eure nächsten 0...6 Siegel unterbrechen den Gegner und alle umstehende Feinde und fügen ihnen 15...60 Punkt[e] Schaden zu. Anfangswirkung: lädt Eure anderen Siegel wieder auf.'],
65=>['Arkane Mimikry','Zauber. 20 Sekunden lang wird Arkane Mimikry die Elite-Fertigkeit des Verbündeten, mit der er sich nicht verwandelt.','Zauber. Diese Fertigkeit wird zur Elite-Fertigkeit des Verbündeten (20 Sekunden). Sich selbst als Ziel wählen nicht möglich. Keine Wirkung, wenn Elite-Fertigkeit des Verbündeten eine Verwandlung ist.'],
66=>['Geistfesseln','Verhexung. 5...20 Sekunde[n] lang verliert der Gegner bei jedem Angriff 5 Energiepunkte.','Verhexung. 5...20 Sekunde[n]: Gegner verliert bei jedem seiner Angriffe 5 Energiepunkte.'],
67=>['Verhexung brechen','Zauber. Entfernt eine Verhexung vom Verbündeten (bzw. Euch selbst). Beim Entfernen einer Verhexung erleiden alle Gegner in der Nähe dieses Verbündeten 30...120 Punkt[e] Schaden.','Zauber. Entfernt beim Verbündeten (bzw. Euch selbst) eine Verhexung. Entfernungswirkung: Richtet bei Feinden in der Nähe 30...120 Punkt[e] Schaden an.'],
68=>['Verzauberung entziehen','Zauber. Entfernt eine Verzauberung vom Gegner. Wenn eine Verzauberung entfernt wird, bekommt Ihr 8...17 Energiepunkt[e] und 40...120 Lebenspunkt[e].','Zauber. Entfernt beim Gegner eine Verzauberung. Entfernungswirkung: Ihr erhaltet 8...17 Energiepunkt[e] und 40...120 Lebenspunkt[e].'],
69=>['Verzauberung brechen','Zauber. Entfernt eine Verzauberung vom Gegner. Beim Entfernen einer Verzauberung erleidet dieser 14...100 Punkt[e] Schaden.','Zauber. Entfernt beim Gegner eine Verzauberung. Entfernungswirkung: Richtet 14...100 Punkt[e] Schaden an.'],
72=>['Elementarwiderstand','Haltung. 30...90 Sekunde[n] lang bekommt Ihr +40 Rüstung gegen Elementarschaden, verliert jedoch 24...12 Rüstung gegen physischen Schaden.','Haltung. 30...90 Sekunde[n]: Ihr habt +40 Rüstung gegen Elementarschaden. Ihr habt -24...12 Rüstung gegen physischen Schaden.'],
73=>['Körperlicher Widerstand','Haltung. 30...90 Sekunde[n] lang bekommt Ihr +40 Rüstung gegen physischen Schaden, verliert jedoch 24...12 Rüstung gegen Elementarschaden.','Haltung. 30...90 Sekunde[n]: Ihr habt +40 Rüstung gegen physischen Schaden. Ihr habt -24...12 Rüstung gegen Elementarschaden.'],
74=>['Echo','Elite-Verzauberung. 30 Sekunde[n] lang wird Echo durch die nächste von Euch benutzte Fertigkeit ersetzt. Echo wirkt 30 Sekunden lang wie diese Fertigkeit.','Elite-Verzauberung. 30 Sekunde[n]: Echo wird zur nächsten von Euch benutzten Fertigkeit (30 Sekunden).'],
75=>['Arkanes Echo','Verzauberung. Falls Ihr in den nächsten 20 Sekunde[n] einen Zauber wirkt, wird Arkanes Echo 20 Sekunden lang durch diesen Zauber ersetzt. Arkanes Echo endet vorzeitig, wenn Ihr eine Fertigkeit benutzt, die kein Zauber ist.','Verzauberung. 20 Sekunde[n]: Arkanes Echo wird zum nächsten von Euch benutzten Zauber (20 Sekunden). Diese Verzauberung endet, wenn Ihr eine Fertigkeit benutzt, die kein Zauber ist.'],
76=>['Eingebildete Bürde','Verhexung. 8...20 Sekunde[n] lang bewegt sich der Gegner um 50% langsamer.','Verhexung. (8...20 Sekunde[n].) Gegner bewegt sich um 50% langsamer.'],
77=>['Chaossturm','Zauber. An der Position des Gegners wird ein Chaossturm erzeugt, der 10 Sekunden lang anhält. Umstehende Feinde erleiden pro Sekunde 5...25 Punkt[e] Schaden und verlieren 0...2 Energiepunkt[e].','Zauber. Fügt pro Sekunde 5...25 Punkt[e] Schaden zu und verursacht einen Verlust von 0...2 Energiepunkt[en] (10 Sekunde[n]). Trifft umstehende Feinde um anfängliche Position des Ziels.'],
78=>['Epidemie','Zauber. Verteilt alle negativen Zustände und ihre verbleibende Dauer vom Gegner auf alle ihn umstehenden Feinde.','Zauber. Zustände des Gegners übertragen sich auf umstehende Feinde.'],
79=>['Energieentzug','Elite-Zauber. Der Gegner verliert 2...9 Energiepunkt[e]. Ihr erhaltet für jeden verlorenen Energiepunkt 3 Energiepunkte.','Elite-Zauber. Lässt 2...9 Energiepunkt[e] verlieren. Ihr erhaltet pro verlorenem Energiepunkt 3 Energiepunkte.'],
80=>['Energie abzapfen','Zauber. Der Gegner verliert 4...7 Energiepunkt[e]. Ihr erhaltet für jeden verlorenen Energiepunkt 2 Energiepunkte.','Zauber. Lässt 4...7 Energiepunkt[e] verlieren. Ihr erhaltet pro verlorenem Energiepunkt 2 Energiepunkte.'],
81=>['Arkaner Diebstahl','Zauber. 5...35 Sekunde[n] lang wird ein zufällig gewählter Zauber des Gegners deaktiviert und Arkaner Diebstahl wird durch diesen Zauber ersetzt.','Zauber. 5...35 Sekunde[n]: Deaktiviert einen willkürlichen Zauber. Diese Fertigkeit wird zum betreffenden Zauber.'],
82=>['Mantra der Zurückrufung','Elite-Verzauberung. 20 Sekunde[n] lang erhaltet Ihr daraus keinen Vorteil. Allerdings erhaltet Ihr, wenn Mantra der Zurückrufung endet, 10...25 Energiepunkt[e].','Elite-Verzauberung. 20 Sekunde[n]: Wirkung am Ende: Ihr erhaltet 10...25 Energiepunkt[e].'],
83=>['Knochenschreck beleben','Zauber. Der nächste Kadaver wird als Knochenschreck der Stufe 1...17 belebt.','Zauber. Erstellt einen Knochenschreck der Stufe 1...17. Benutzt frischen Kadaver.'],
84=>['Knochenteufel beleben','Zauber. Der nächste Kadaver wird als Knochenteufel der Stufe 1...17 belebt. Knochenteufel können aus der Ferne angreifen.','Zauber. Erstellt einen Knochenteufel der Stufe 1...17, der aus der Ferne angreifen kann. Benutzt frischen Kadaver.'],
85=>['Knochendiener beleben','Zauber. Der nächste Kadaver wird als zwei Knochendiener der Stufe 0...12 belebt.','Zauber. Erstellt zwei Knochendiener der Stufe 0...12. Benutzt frischen Kadaver.'],
86=>['Grenths Ausgleich','Elite-Zauber. Wenn der Gegner mehr Lebenspunkte als Ihr hat, erhaltet Ihr die Hälfte der Differenz (bis zu Euren maximalen Lebenspunkten) und der Gegner verliert die gleiche Punktzahl. Falls dieser Gegner weniger Lebenspunkte hat als Ihr, verliert Ihr die Hälfte der Differenz und er erhält die gleiche Menge.','Elite-Zauber. Ihr erhaltet die Hälfte der Differenz zwischen den Lebenspunkten des Gegners und Euren Lebenspunkten. Der Gegner verliert dieselbe Punktzahl. Falls der Gegner weniger Lebenspunkte hat als Ihr, verliert Ihr die Hälfte der Differenz und er erhält die gleiche Menge.'],
87=>['Veratas Starren','Zauber. Hat der anvisierte feindliche belebte Untote einen Meister, so wird die Bindung an diesen Meister zerstört, und er reagiert auf alle anderen Kreaturen feindlich. Hat er keinen Meister, so werdet Ihr zu seinem Meister und heilt ihn um 60...80. (Bei Todesmagie von 4 oder darunter beträgt die Chance eines Fehlschlags 50 %.)','Zauber. Macht den anvisierten untoten Diener herrenlos. Ist er bereits herrenlos, so werdet Ihr zu seinem Meister und heilt ihn um 60...80. Chance eines Fehlschlags 50 %, sofern Todesmagie nicht mindestens 5 beträgt.'],
88=>['Veratas Aura','Verzauberung. Alle belebten feindlichen Untoten in dem Bereich werden an Euch gebunden. Nach 120...300 Sekunde[n] verliert Veratas Aura ihre Wirkung. Wenn Veratas Aura endet, verliert Ihr Eure Verbindung zu allen an Euch gebundenen Untoten. (Bei einer Todesmagie von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Verzauberung. 120...300 Sekunde[n]: Ihr werdet zum Meister aller feindlichen untoten Diener im Bereich. Wirkung am Ende: Eure untoten Diener werden herrenlos. Mindestens Todesmagie 5, sonst 50%ige Chance auf Misserfolg.'],
89=>['Tödliche Kühlung','Zauber. Der Gegner erleidet 5...50 Punkte Kälteschaden. Sind seine Lebenspunkte über 50%, verursacht Ihr zusätzlich 5...50 Punkt[e] Schattenschaden.','Zauber. Richtet 5...50 Punkt[e] Kälteschaden an. Richtet zusätzlich 5...50 Punkt[e] Schaden an, falls der Gegner mehr als 50% seiner maximalen Lebenspunkte hatte.'],
90=>['Veratas Opfer','Zauber. 5...10 Sekunde[n] lang erfahren Eure untoten Verbündeten eine Lebenspunktregeneration von +10. Alle Zustände werden von diesen Verbündeten entfernt und auf Euch übertragen. Wenn dieser Zauber erfolgreich ist und Ihr 3 oder weniger Diener kontrolliert, wird Veratas Opfer sofort wieder aufgeladen.','Zauber. 5...10 Sekunde[n]: 10 verbündete untote Diener erhalten +10 Lebenspunktregeneration. Wird sofort wieder aufgeladen, falls Ihr 3 oder weniger Diener kontrolliert. Überträgt alle Zustände der betroffenen Diener auf Euch.'],
91=>['Brunnen der Kraft','Elite-Brunnenzauber. Nutzt die nächstbeste Leiche oder opfert 66 % Eurer Lebenspunkte, um an ihrem Fundort einen Brunnen der Kraft zu erzeugen. Für 10...30 Sekunden erhalten Verbündete in Bereich des Brunnens +1...6 Lebenspunktregeneration und +2 Energieregeneration.','Elite-Brunnenzauber. (10...30 Sekunden). Verbündete in diesem Brunnen erhalten +1...6 Lebenspunktregeneration und +2 Energieregeneration. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
92=>['Brunnen des Blutes','Brunnenzauber. Nutzt die nächstbeste Leiche oder opfert 66 % Eurer Lebenspunkte, um an ihrem Fundort einen Brunnen des Blutes zu erzeugen. Für 8...20 Sekunden erhalten Verbündete in diesem Bereich +1...6 Lebenspunktregeneration.','Brunnenzauber. (8...20 Sekunden). Verbündete in diesem Brunnen erhalten +1...6 Lebenspunktregeneration. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
93=>['Brunnen des Leidens','Brunnenzauber. Nutzt die nächstbeste Leiche oder opfert 66 % Eurer Lebenspunkte, um an ihrem Fundort einen Brunnen des Leidens zu erzeugen. Für 10...30 Sekunden erleiden Gegner in diesem Bereich -1...6 Lebenspunktdegeneration.','Brunnenzauber. (10...30 Sekunden). Gegner in diesem Brunnen haben -1...6 Lebenspunktdegeneration. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
94=>['Gottloser Brunnen','Brunnenzauber. Nutzt die nächstbeste Leiche oder opfert 66 % Eurer Lebenspunkte, um an ihrem Fundort einen Brunnen des Profanen zu erzeugen. Für 8...20 Sekunden verlieren Gegner in diesem Bereich ihre sämtlichen Verzauberungen und können auch nicht mehr Ziel weiter verzaubert werden. (Bei Todesmagie von 4 oder darunter beträgt die Chance eines Fehlschlags 50 %.)','Brunnenzauber. (8...20 Sekunden). Gegner in diesem Brunnen verlieren alle Verzauberungen und können nicht Ziel späterer Verzauberungen werden. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte. 50 % Chance auf Fehlschlag, wenn Todesmagie nicht mindestens 5 beträgt.'],
95=>['Explosion der Verwesung','Zauber. Der Kadaver, der Eurem Ziel am nächsten ist, explodiert und sendet eine Schockwelle aus, die allen in der Nähe befindlichen Gegnern 24...120 Punkt[e] Schaden zufügt.','Zauber. Lässt einen Kadaver explodieren und richtet bei Gegnern in der Nähe 24...120 Punkt[e] Schaden an. Benutzt frischen Kadaver.'],
96=>['Seelenschmaus','Zauber. Benutzt den Kadaver, der Euch am nächsten ist, um 50...280 Lebenspunkt[e] zu erhalten.','Zauber. Ihr erhaltet 50...280 Lebenspunkt[e]. Benutzt frischen Kadaver.'],
97=>['Nekrotische Verwechslung','Zauber. Nutzt eine zufällige Leiche oder opfert 30...20 % Lebenspunkte, um Euch an den Ort des Zielgegners zu teleportieren. Ihr seid 6 Sekunden lang erkrankt, und alle Gegner in der Nähe werden 5...20 Sekunden lang vergiftet.','Zauber. Nutzt eine zufällige Leiche oder opfert 30...20 % Lebenspunkte, um Euch an den Ort des Zielgegners zu teleportieren. Ihr seid 6 Sekunden lang erkrankt, und alle Gegner in der Nähe werden 5...20 Sekunden lang vergiftet.'],
98=>['Kadaver verzehren','Zauber. Benutzt einen willkürlichen Kadaver, um zu seiner Position zu teleportieren, und Ihr erhaltet 25...100 Lebenspunkt[e] und 5...20 Energiepunkt[e].','Zauber. Teleportiert zur Position eines Kadavers. Ihr erhaltet 25...100 Lebenspunkt[e] und 5...20 Energiepunkt[e]. Benutzt frischen Kadaver.'],
99=>['Parasitäre Fesseln','Verhexung. 20 Sekunden lang unterliegt der Gegner einer Lebenspunktdegeneration von -1. Wenn Parasitäre Fesseln endet, wird der Wirker um 30...120 Lebenspunkt[e] geheilt.','Verhexung. (20 Sekunden.) Verursacht -1 Lebenspunktdegeneration. Wirkung am Ende: Ihr werdet um 30...120 Lebenspunkt[e] geheilt.'],
100=>['Seelenwiderhaken','Verhexung. 30 Sekunden lang erleidet der Gegner immer dann 15...30 Punkt[e] Schaden, wenn er von einer Verzauberung oder einer Verhexung getroffen wird.','Verhexung. 30 Sekunden: Richtet 15...30 Punkt[e] Schaden an, wenn eine Verzauberung oder Verhexung auf den Gegner gewirkt wird.'],
101=>['Widerhaken','Verhexung. Der Gegner erleidet 30 Sekunden lang 4...16 Punkt[e] mehr Schaden, wenn ihm physischer Schaden zugefügt wird.','Verhexung. 30 Sekunden: Gegner erleidet jedes Mal 4...16 Punkt[e] Schaden, wenn er physischen Schaden erhält.'],
102=>['Schattenschlag','Zauber. Der Gegner erleidet 12...48 Punkt[e] Schattenschaden. Sind seine Lebenspunkte über 50%, entzieht Ihr ihm bis zu 12...48 Lebenspunkt[e].','Zauber. Richtet 12...48 Punkt[e] Schaden an. Entzieht bis zu 12...48 Lebenspunkt[e], falls der Gegner mehr als 50% seiner maximalen Lebenspunkte hatte.'],
103=>['Preis des Versagens','Verhexung. 30 Sekunden lang besteht eine 25%ige Wahrscheinlichkeit, dass die Angriffe des Gegners fehlschlagen. Für jeden Fehlschlag im Kampf erleidet er 1...46 Punkt[e] Schaden.','Verhexung. 30 Sekunden: Die Angriffe des Gegners gehen mit 25%iger Wahrscheinlichkeit daneben. Gegner erleidet für jeden misslungenen Angriff 1...46 Punkt[e] Schaden.'],
104=>['Todesnova','Verzauberung. Falls der Verbündete (bzw. Ihr selbst) innerhalb der nächsten 30 Sekunden stirbt, erleiden alle umstehenden Feinde 26...100 Punkt[e] Schaden und werden 15 Sekunde[n] lang vergiftet.','Verzauberung. 30 Sekunden: Falls der Verbündete (bzw. Ihr selbst) stirbt, erhalten umstehende Feinde 26...100 Punkt[e] Schaden und Zustand Gift (15 Sekunde[n]).'],
105=>['Tödlicher Schwarm','Zauber. Tödlicher Schwarm breitet sich langsam aus und fügt bis zu drei Zielen in dem Bereich 30...90 Punkt[e] Kälteschaden zu.','Zauber. Tödlicher Schwarm breitet sich langsam aus und richtet 30...90 Punkt[e] Kälteschaden an. Trifft zwei weitere Feinde im Bereich.'],
106=>['Verrottendes Fleisch','Zauber. Der als Ziel ausgewählte Gegner aus Fleisch und Blut erkrankt 10...25 Sekunde[n] lang und verliert allmählich Lebenspunkte.','Zauber. Verursacht Zustand Krankheit (10...25 Sekunde[n]).'],
107=>['Ansteckung','Elite-Zauber. Falls der Gegner bereits an einem Zustand leidet, leidet er 3...15 Sekunde[n] lang unter Krankheit, Gift und Schwäche.','Elite-Zauber. Verursacht Zustände Krankheit, Gift und Schwäche (3...15 Sekunde[n]). Gegner muss bereits einen Zustand haben, sonst keine Wirkung.'],
108=>['Leiden','Verhexung. 6...30 Sekunde[n] lang unterliegen der Gegner und alle in der Nähe befindlichen Feinde einer Lebenspunktdegeneration von -0...3.','Verhexung. Verhext den Gegner und Feinde in der Nähe (6...30 Sekunde[n]). Die Betroffenen haben -0...3 Lebenspunktdegeneration.'],
109=>['Leben abzapfen','Verhexung. 12...24 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von 1...3 und Ihr selbst erfreut Euch einer zusätzlichen Lebenspunktregeneration von 1...3.','Verhexung. 12...24 Sekunde[n]: Gegner hat -1...3 Lebenspunktdegeneration. Ihr habt +1...3 Lebenspunktregeneration.'],
110=>['Unheiliger Schmaus','Zauber. Entzieht bis zu 1...4 Gegnern in dem Bereich bis zu 10...65 Lebenspunkt[e].','Zauber. Entzieht 1...4 Feind[en] im Bereich um Euch 10...65 Lebenspunkt[e].'],
111=>['Das Blut erwecken','Verzauberung. 20...44 Sekunde[n] lang erhöht sich Euer Blutmagie- und Flücheattribut um 2, aber jedes Mal, wenn Ihr Lebenspunkte opfert, opfert Ihr 50% mehr als normal.','Verzauberung. 20...44 Sekunde[n]: Ihr habt +2 Blutmagie und Flüche. Ihr opfert 50% mehr Lebenspunkte als normal.'],
112=>['Verzauberungsschändung','Zauber. Der Zielgegner und alle in seiner Nähe befindlichen Gegner erleiden 6...60 Punkt[e] Schattenschaden sowie zusätzlich 4...20 Punkt[e] Schattenschaden für jede auf ihnen liegende Verzauberung.','Zauber. Richtet beim Gegner und Feinden in der Nähe 6...60 Punkt[e] Schaden an. Richtet zusätzlich 4...20 Punkt[e] Schaden für jede auf ihnen liegende Verzauberung an.'],
113=>['Verdorbenes Fleisch','Elite-Verzauberung. 20...44 Sekunden lang sind Verbündete in diesem Bereich immun gegen Krankheit, und jeder, der diese Verbündeten im Nahkampf trifft, erkrankt für 3...15 Sekunden.','Elite-Verzauberung. (20...44 Sekunden.) Gegner, die Verbündete im Bereich im Nahkampf treffen, werden Erkrankt (3...15 Sekunden lang); dieser Verbündete ist immun gegen Krankheit.'],
114=>['Aura des Lich','Elite-Verzauberung. Alle Kadaver in Hörweite werden benutzt und Ihr belebt einen Knochenschreck der Stufe 1...17 sowie einen für jeden auf diese Weise benutzten Kadaver. 5...45 Sekunde[n] lang ist Euer Todesmagie-Attribut um +1 erhöht.','Elite-Verzauberung. Benutzt alle Kadaver in Hörweite. Belebt einen Knochenschreck der Stufe 1...17 sowie einen für jeden benutzten Kadaver. Ihr habt +1 Todesmagie (5...45 Sekunde[n]).'],
115=>['Bluterneuerung','Verzauberung. 7 Sekunden lang erfreut Ihr Euch einer Lebenspunktregeneration von +3...6. Wenn Bluterneuerung endet, bekommt Ihr 40...190 Lebenspunkt[e].','Verzauberung. (7 Sekunden.) Ihr habt +3...6 Lebenspunktregeneration. Wirkung am Ende: Heilt Euch für 40...190 Lebenspunkt[e].'],
116=>['Dunkle Aura','Verzauberung. 30 Sekunden lang fügt "Dunkle Aura" jedes Mal, wenn der Verbündete (bzw. Ihr selbst) Lebenspunkte opfert, allen umstehenden Feinden 5...50 Punkt[e] Schattenschaden zu. Außerdem verliert Ihr 5...20 Lebenspunkt[e].','Verzauberung. 30 Sekunden: Richtet bei umstehenden Gegnern jedes Mal 5...50 Punkt[e] Schaden an, wenn der Verbündete (bzw. Ihr selbst) Lebenspunkte opfert. Schadenskosten: Ihr verliert 5...20 Lebenspunkt[e].'],
117=>['Schwächen','Zauber. Das ausgewählte Ziel leidet 10...30 Sekunde[n] lang an Schwäche.','Zauber. Verursacht Zustand Schwäche (10...30 Sekunde[n]).'],
118=>['Schwächendes Blut','Zauber. Der Gegner und alle Feinde in der Nähe leiden 5...20 Sekunde[n] lang unter Schwäche.','Zauber. Verursacht beim Gegner und Feinden in der Nähe Zustand Schwäche (5...20 Sekunde[n]).'],
119=>['Blut ist Kraft','Elite-Verzauberung. 10 Sekunden lang erhält der Verbündete +3...6 Energieregeneration.','Elite-Verzauberung. 10 Sekunden: +3...6 Energieregeneration. Sich selbst als Ziel wählen nicht möglich.'],
120=>['Blut des Meisters','Zauber. Alle Eure untoten Verbündeten werden um 30...116 Lebenspunkt[e] geheilt. Ihr opfert pro Diener, der auf diese Weise geheilt wird, zusätzlich 2% maximale Lebenspunkte.','Zauber. Heilt Eure untoten Diener um 30...116 Lebenspunkt[e]. Heilkosten: +2% Lebenspunktopfer pro geheiltem Diener.'],
121=>['Boshafter Geist','Elite-Verhexung. 10...25 Sekunde[n] lang fügt Boshafter Geist jedes Mal, wenn der Gegner angreift oder eine Fertigkeit benutzt, diesem und allen ihn umstehenden Verbündeten 15...45 Punkt[e] Schattenschaden zu.','Elite-Verhexung. 10...25 Sekunde[n]: Richtet beim Gegner und umstehenden Feinden jedes Mal 15...45 Punkt[e] Schaden an, wenn der Gegner angreift oder eine Fertigkeit benutzt.'],
122=>['Unheilvoller Eingriff','Verhexung. 5...20 Sekunde[n] lang verschafft Heilung dem Gegner 20% weniger Vorteile. Wenn der Gegner stirbt, während er mit Unheilvoller Eingriff verhext ist, wird ein herrenloser Knochenschreck der Stufe 1...17 belebt.','Verhexung. 5...20 Sekunde[n]: Verringert die Wirkung von Heilungen beim Gegner um 20%. Stirbt der Gegner, während er verhext ist, wird ein herrenloser Knochenschreck der Stufe 1...17 belebt.'],
123=>['Heimtückischer Parasit','Verhexung. 5...15 Sekunde[n] lang entzieht Ihr dem Gegner jedes Mal, wenn sein Angriff trifft, bis zu 15...45 Lebenspunkt[e].','Verhexung. 5...15 Sekunde[n]: Entzieht jedes Mal 15...45 Lebenspunkt[e], wenn ein Angriff des Gegners trifft.'],
124=>['Rückenschauer','Verhexung. 10...40 Sekunde[n] lang wird der Gegner jedes Mal, wenn er beim Anwenden einer Fertigkeit mit Kälteschaden getroffen wird, unterbrochen und Ihr verliert 8...3 Energiepunkt[e] oder Rückenschauer endet.','Verhexung. 10...40 Sekunde[n]: Kälteschaden unterbricht die Fertigkeiten des Gegners. Unterbrechungskosten: Ihr verliert 8...3 Energiepunkt[e] oder Rückenschauer endet.'],
125=>['Verwelken','Elite-Verhexung. 5...35 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -2...4 und einer Energiedegeneration von -1. Wenn die Energie des Gegners auf 0 gefallen ist, nimmt dieser Gegner 15...75 Punkt[e] Schaden und Verwelken endet.','Elite-Verhexung. 5...35 Sekunde[n]: Verursacht -2...4 Lebenspunktdegeneration und -1 Energiedegeneration. Richtet 15...75 Punkt[e] Schaden an, wenn die Energiepunkte des Gegners auf 0 sinken. Endet, wenn die Energiepunkte des Gegners auf 0 sinken.'],
126=>['Lebensübertragung','Elite-Verhexung. 6...12 Sekunde[n] lang unterliegen der Gegner und ihn umstehende Feinde einer Lebenspunktdegeneration von -3...8, die Euch als Lebenspunktregeneration zugute kommt.','Elite-Verhexung. Verhext auch den Gegner umstehende Feinde (6...12 Sekunde[n]). Verursacht -3...8 Lebenspunktdegeneration. Ihr habt +3...8 Lebenspunktregeneration.'],
127=>['Zeichen der Subversion','Verhexung. 6 Sekunde[n] lang schlägt der nächste Zauber des Gegners auf einen seiner Verbündeten fehl und Ihr entzieht dem Widersacher bis zu 10...92 Lebenspunkt[e].','Verhexung. 6 Sekunde[n]: Nächster Zauber des Gegners schlägt fehl und Ihr entzieht ihm 10...92 Lebenspunkt[e]. Zauber des Gegners muss auf einen seiner Verbündeten gerichtet sein, sonst keine Wirkung.'],
128=>['Seelenfresser','Elite-Verhexung. 10 Sekunden lang entzieht Ihr dem Gegner jedes Mal, wenn er einen Zauber wirkt, bis zu 16...80 Lebenspunkt[e].','Elite-Verhexung. 10 Sekunden: Entzieht jedes Mal 16...80 Lebenspunkt[e], wenn der Gegner einen Zauber wirkt.'],
129=>['Fleisch schänden','Verhexung. 5...35 Sekunde[n] lang erhält der Gegner bei einer Heilung nur zwei Drittel der Lebenspunkte.','Verhexung. 5...35 Sekunde[n]: Verringert die Wirkung von Heilungen beim Gegner um 33%. Nur Fertigkeiten mit dem Wort "heilen" in der Beschreibung sind betroffen.'],
130=>['Dämonenfleisch','Verzauberung. Während der nächsten 30...60 Sekunde[n] erleiden jedes Mal, wenn Ihr eine Fertigkeit auf einen Feind anwendet, alle umstehenden Feinde 5...20 Punkt[e] Schattenschaden.','Verzauberung. (30...60 Sekunde[n].) Jedes Mal, wenn Ihr eine Fertigkeit auf einen Feind anwendet, erleiden alle umstehenden Feinde 5...20 Punkt[e] Schattenschaden.'],
131=>['Siegel der Widerhaken','Siegel. Ihr fügt 3...15 Sekunde[n] lang Eurem Gegner und allen umstehenden Gegnern eine Blutung zu.','Siegel. Der Gegner und umstehende Feinde leiden an einer Blutung (3...15 Sekunde[n]).'],
132=>['Pest-Siegel','Elite-Siegel. Alle negativen Zustände mit 100...200% ihrer verbleibenden Dauer werden von Euch auf den Gegner übertragen. (Bei Flüchen von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Elite-Siegel. Alle Zustände mit 100...200% ihrer verbleibenden Dauer werden von Euch auf den Gegner übertragen. Mindestens Flüche 5, sonst 50%ige Chance auf Misserfolg.'],
133=>['Dunkler Pakt','Zauber. Fügt dem Gegner 20...60 Punkt[e] Schattenschaden zu.','Zauber. Richtet 20...60 Punkt[e] Schaden an.'],
134=>['Orden der Schmerzen','Verzauberung. 5 Sekunden lang fügt ein Gruppenmitglied jedes Mal, wenn es einem Gegner physischen Schaden zufügt, +3...16 Punkt[e] Schaden zu.','Verzauberung. Verzaubert alle Gruppenmitglieder (5 Sekunden). +3...16 Punkt[e] Schaden, wenn diese Gruppenmitglieder physischen Schaden anrichten.'],
135=>['Mutlosigkeit','Verhexung. Während der nächsten 4...18 Sekunde[n] greift der Gegner um 50% langsamer an und er unterliegt einer Lebenspunktdegeneration von -1...3.','Verhexung. 4...18 Sekunde[n]: Gegner greift um 50% langsamer an und hat -1...3 Lebenspunktdegeneration.'],
136=>['Schatten der Angst','Verhexung. Der Zielgegner und alle umstehenden Gegner greifen während der nächsten 5...30 Sekunde[n] 50% langsamer an.','Verhexung. Verhext den Gegner und umstehende Feinde (5...30 Sekunde[n]). Sie greifen um 50% langsamer an.'],
137=>['Totenstarre','Verhexung. 8...20 Sekunde[n] lang kann der Gegner nicht blocken.','Verhexung. 8...20 Sekunde[n]: Gegner kann nicht blocken.'],
138=>['Dunkles Band','Verzauberung. Während der nächsten 30...60 Sekunde[n] erleidet der Diener, der Euch am nächsten ist, jedes Mal, wenn Ihr Schaden unterliegt, 75% dieses Schadens an Eurer Stelle.','Verzauberung. 30...60 Sekunde[n]: Überträgt 75% des erlittenen Schadens von Euch auf Euren am nächsten befindlichen Diener.'],
139=>['Zustand einflößen','Verzauberung. Während der nächsten 15...60 Sekunde[n] wird jeder Zustand, den Ihr erhaltet, stattdessen auf Euren nächsten Diener übertragen.','Verzauberung. 15...60 Sekunde[n]: Überträgt jeden Zustand, den Ihr erhaltet, von Euch auf Euren am nächsten befindlichen untoten Diener.'],
140=>['Unwohlsein','Verhexung. 5...35 Sekunde[n] lang unterliegt der Gegner einer Energiedegeneration von -1 und Ihr erleidet eine Lebenspunktdegeneration von -1. Wenn die Energie des Gegners auf 0 gefallen ist, erleidet er 5...50 Punkt[e] Schaden und Unwohlsein endet.','Verhexung. 5...35 Sekunde[n]: Verursacht -1 Energiedegeneration. Richtet 5...50 Punkt[e] Schaden an, wenn die Energiepunkte des Gegners auf 0 sinken. Ihr habt -1 Lebenspunktdegeneration. Endet, wenn die Energiepunkte des Gegners auf 0 sinken.'],
141=>['Verzauberungen entreißen','Zauber. Entfernt 5...9 Verzauberung[en] vom Gegner. Für jede entfernte Mönch-Verzauberung verliert Ihr 55...25 Lebenspunkt[e].','Zauber. Entfernt 5...9 Verzauberung[en] beim Gegner. Entfernungskosten: Ihr verliert für jede entfernte Mönch-Verzauberung 55...25 Lebenspunkt[e].'],
142=>['Bleibender Fluch','Elite-Verhexung. 6...30 Sekunde[n] lang unterliegen der Gegner und alle in der Nähe befindlichen Feinde einer Lebenspunktdegeneration von -1...4 und Heilung verschafft ihnen um 25% weniger Vorteile.','Elite-Verhexung. 6...30 Sekunde[n]: Gegner und Feinde in der Nähe haben -1...4 Lebenspunktdegeneration. Heilung verschafft ihnen um 25% weniger Vorteile.'],
143=>['Verzauberung rauben','Zauber. Entfernt 0...2 Verzauberung[en] vom Gegner. Beim Entfernen einer Verzauberung entzieht Ihr 5...65 Lebenspunkt[e].','Zauber. Entfernt 0...2 Verzauberung[en] beim Gegner. Entfernungswirkung: Ihr entzieht 5...65 Lebenspunkt[e].'],
144=>['Frostbeulen','Zauber. Ihr werdet 10 Sekunden lang vergiftet. Gegner in dem Bereich Eures Gegners erleiden 10...44 Punkt[e] Kälteschaden und verlieren 1...2 Verzauberungen.','Zauber. Richtet bei Feinden im Bereich um das Ziel 10...44 Punkt[e] Kälteschaden an; entfernt 1...2 Verzauberungen bei den Betroffenen. Ihr werdet vergiftet (10 Sekunden).'],
145=>['Siegel der Qual','Siegel. Ihr leidet 25 Sekunden lang unter einer Blutung. Alle in der Nähe befindlichen Gegner erleiden 10...70 Punkt[e] Schaden.','Siegel. Richtet bei Feinden in Eurer Nähe 10...70 Punkt[e] Schaden an. Ihr beginnt zu bluten (25 Sekunden).'],
146=>['Blutopfer','Elite-Zauber. Ihr erhaltet 8...20 Energiepunkt[e].','Elite-Zauber. Ihr erhaltet 8...20 Energiepunkt[e].'],
147=>['Dunkle Wut','Verzauberung. 5 Sekunden lang erhält jedes Gruppenmitglied bei einem erfolgreichen Angriff einen Adrenalinstoß. (Bei einer Blutmagie von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Verzauberung. Verzaubert Gruppenmitglieder (5 Sekunden). Die Betroffenen erhalten jedes Mal einen Adrenalinstoß, wenn sie mit einem Angriff einen Treffer landen. Mindestens Blutmagie 5, sonst 50%ige Chance auf Misserfolg.'],
148=>['Orden des Vampirs','Elite-Verzauberung. 5 Sekunden lang entzieht ein Gruppenmitglied, das nicht mit einer anderen Nekromanten-Verzauberung belegt ist, jedes Mal, wenn es einem Gegner physischen Schaden zufügt, diesem Gegner bis zu 3...16 Lebenspunkt[e].','Elite-Verzauberung. Verzaubert alle Gruppenmitglieder (5 Sekunden). Die Betroffenen entziehen mit jedem Angriff, der physischen Schaden anrichtet, 3...16 Lebenspunkt[e]. Gruppenmitglieder, die unter dem Einfluss einer anderen Nekromanten-Verzauberung stehen, sind nicht betroffen.'],
149=>['Pest aussenden','Zauber. Übertragt 1...3 negative Zustände und ihre verbleibende Dauer von Euch auf den Gegner und alle umstehenden Feinde.','Zauber. Übertragt 1...3 Zustände und ihre verbleibende Dauer von Euch auf den Gegner und alle umstehenden Feinde.'],
150=>['Zeichen des Schmerzes','Verhexung. 30 Sekunden lang fügt "Zeichen des Schmerzes" immer dann, wenn der Zielgegner physischen Schaden nimmt, umstehenden Feinden 10...40 Punkte Schattenschaden zu.','Verhexung. 30 Sekunden: Richtet bei umstehenden Feinden jedes Mal 10...40 Punkt[e] Schaden an, wenn der Gegner physischen Schaden erleidet.'],
151=>['Schmaus der Verdorbenheit','Elite-Zauber. Der Gegner und alle umstehenden Feinde erleiden 16...80 Punkt[e] Schattenschaden. Ihr entzieht allen getroffenen Gegnern, die unter einer Verhexung leiden, bis zu 8...40 Lebenspunkt[e].','Elite-Zauber. Richtet beim Gegner und umstehenden Feinden 16...80 Punkt[e] Schaden an. Entzieht jedem verhexten Feind 8...40 Lebenspunkt[e].'],
152=>['Geschmack des Todes','Zauber. Entzieht dem belebten untoten Verbündeten bis zu 100...400 Lebenspunkt[e].','Zauber. Entzieht verbündetem untotem Diener 100...400 Lebenspunkt[e].'],
153=>['Vampir-Starren','Zauber. Entzieht dem Gegner bis zu 18...60 Lebenspunkt[e].','Zauber. Entzieht 18...60 Lebenspunkt[e].'],
154=>['Pest-Berührung','Fertigkeit. Übertragt 1...3 negative Zustände und ihre verbleibende Dauer von Euch auf den berührten Gegner.','Berührungs-Fertigkeit. Überträgt 1...3 Zustände von Euch auf den Gegner.'],
155=>['Abscheuliche Berührung','Fertigkeit. Der Gegner erleidet durch die Berührung 20...65 Punkt[e] Schaden.','Berührungs-Fertigkeit. Richtet 20...65 Punkt[e] Schaden an.'],
156=>['Vampir-Berührung','Fertigkeit. Entzieht dem Gegner durch die Berührung 29...74 Lebenspunkt[e].','Berührungs-Fertigkeit. Entzieht 29...74 Lebenspunkt[e].'],
157=>['Blutritual','Verzauberung. 8...14 Sekunde[n] lang erfreut sich der berührte Verbündete einer Energieregeneration von +3. Blutritual kann nicht auf den Wirker angewendet werden.','Verzauberung. 8...14 Sekunde[n]: +3 Energieregeneration. Sich selbst als Ziel wählen nicht möglich.'],
158=>['Berührung der Qual','Fertigkeit. Der berührte Gegner erleidet 20...58 Punkt[e] Schattenschaden.','Berührungs-Fertigkeit. Richtet 20...58 Punkt[e] Schaden an.'],
159=>['Rüstung schwächen','Zauber. Der Gegner und ihn umstehende Feinde leiden 5...20 Sekunde[n] lang an Beschädigter Rüstung.','Zauber. Betrifft auch umstehende Feinde. Verursacht Zustand Beschädigte Rüstung (5...20 Sekunde[n]).'],
160=>['Windgeschwindigkeit','Verzauberung. 5...13 Sekunde[n] lang bewegt sich der Verbündete (bzw. Ihr selbst) um 33% schneller.','Verzauberung. (5...13 Sekunde[n].) Der Verbündete (bzw. Ihr selbst) bewegt sich um 33% schneller.'],
162=>['Orkan','Zauber. Der Gegner wird 2 Sekunden lang zu Boden geworfen. (Bei Luftmagie von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Zauber. Wirft zu Boden. Mindestens Luftmagie 5, sonst 50%ige Chance auf Misserfolg.'],
163=>['Wirbelsturm','Zauber. Alle umstehenden Feinde erleiden 15...75 Punkte Kälteschaden. Angreifende Gegner werden von "Wirbelsturm" erfasst und zu Boden geworfen. Wenn Ihr Überzaubert seid, trifft dieser Zauber Feinde in der Nähe, anstatt umstehende Feinde.','Zauber. Trifft umstehende Feinde. Richtet 15...75 Punkte Kälteschaden an. Wirft angreifende Feinde zu Boden. Trifft Feinde in der Nähe, anstatt umstehende Feinde, wenn Überzaubert.'],
164=>['Elementareinstimmung','Elite-Verzauberung. 25...60 Sekunden lang seid Ihr auf Luft, Feuer, Wasser und Erde eingestimmt und erhaltet +1...2 auf diese Attribute. Ihr erhaltet jedes Mal 1 Energie plus 50 % der Grund-Energiekosten der Fertigkeit, wenn Ihr Magie einsetzt, die mit einem dieser Elemente verbunden ist.','Elite-Verzauberung. (25...60 Sekunden.) Eure Elementarattribute werden um 1...2 erhöht. Ihr erhaltet 1 plus 50 % der Grund-Energiekosten aller Luft-, Feuer-, Wasser- und Erd-Magiefertigkeiten, die Ihr benutzt.'],
165=>['Erdrüstung','Verzauberung. 30 Sekunden lang erhaltet Ihr 24...60 Rüstung, bewegt Euch jedoch um 50...14% langsamer.','Verzauberung. (30 Sekunden.) Ihr habt +24...60 Rüstung. Ihr bewegt Euch um 50...14% langsamer.'],
166=>['Kinetik-Rüstung','Verzauberung. Ihr erhaltet für 12 Sekunden +20...80 Rüstung. Jedes Mal, wenn Ihr einen Zauber wirkt, wird Kinetische Rüstung für 12 Sekunden erneuert.','Verzauberung. (12 Sekunden.) Ihr habt +20...80 Rüstung. Erneuerungsbonus: Wirkt einen Zauber.'],
167=>['Eruption','Zauber. An der Position des Gegners wird eine Eruption erzeugt. 5 Sekunden lang erleiden Feinde in der Nähe dieser Position pro Sekunde 10...40 Punkt[e] Erdschaden und werden 10 Sekunden lang geblendet.','Zauber. Richtet 10...40 Punkt[e] Erdschaden pro Sekunde an (5 Sekunden). Trifft Feinde in der Nähe der ursprünglichen Position des Ziels. Verursacht Zustand "Blindheit" (10 Sekunden).'],
168=>['Magnet-Aura','Verzauberung. Für 1...8 Sekunden blockt Ihr den nächsten gegen Euch gerichteten Angriff und Euer Angreifer erleidet 10...50 Punkte Schaden. Wenn Ihr Überzaubert seid, werden alle Gruppenmitglieder in Hörweite ebenfalls verzaubert.','Verzauberung. (1...8 Sekunden.) Blockt den nächsten gegen Euch gerichteten Angriff und reflektiert 10...50 Schaden zum Angreifer. Wenn Ihr Überzaubert seid, werden alle Gruppenmitglieder in Hörweite ebenfalls verzaubert.'],
169=>['Erdeinstimmung','Verzauberung. 36...60 Sekunde[n] lang seid Ihr auf Erde eingestimmt. Jedes Mal, wenn Ihr Erdmagie verwendet, erhaltet Ihr 1 Energiepunkt sowie 30% der Basisenergiekosten der Fertigkeit.','Verzauberung. (36...60 Sekunde[n].) Ihr erhaltet 1 Energiepunkt plus 30% der Energiekosten zurück, wenn Ihr Erdmagie-Fertigkeiten benutzt.'],
170=>['Erdbeben','Zauber. An der Position des Gegners wird ein Erdbeben erzeugt. Alle Gegner in diesem Gebiet werden zu Boden geworfen und erleiden 26...100 Punkt[e] Erdschaden.','Zauber. Richtet 26...100 Punkt[e] Erdschaden an. Trifft auch Feinde in der Nähe des Ziels. Wirft zu Boden.'],
171=>['Steinigung','Zauber. Sendet einen großen Stein aus, der dem Gegner 45...105 Punkt[e] Erdschaden zufügt, falls er trifft. Wenn Steinigung einen Gegner trifft, der unter Schwäche leidet, wird er zu Boden geworfen.','Zauber. Geschoss: Richtet 45...105 Punkt[e] Erdschaden an. Wirft Gegner zu Boden, falls dieser geschwächt ist.'],
172=>['Steindolche','Zauber. Sendet zwei Steindolche aus. Jeder Steindolch fügt dem Gegner 8...33 Punkte Erdschaden zu, wenn er trifft. Wenn Ihr Überzaubert seid, verursacht jedes Geschoss für 1...5 Sekunden Blutung.','Zauber. Zwei Geschosse: Richten je 8...33 Punkte Erdschaden an. Der Gegner leidet 1...5 Sekunden lang an einer Blutung.'],
173=>['Zupackende Erde','Verhexung. 5...20 Sekunde[n] lang bewegen sich alle Feinde in der Nähe um 50% langsamer.','Verhexung. Verhext Feinde in Eurer Nähe (5...20 Sekunde[n]). Diese Feinde bewegen sich um 50% langsamer.'],
174=>['Nachbeben','Zauber. Umstehende Feinde erleiden 15...85 Punkte Erdschaden. Zu Boden geworfene Feinde erleiden 15...85 Punkte zusätzlichen Erdschaden.','Zauber. Richtet bei in der Nähe befindlichen Feinden 15...85 Punkte Erdschaden an. Zu Boden geworfene Feinde erleiden zusätzlich 15...85 Punkte Erdschaden.'],
175=>['Abwehr gegen Elemente','Abwehrzauber. Ihr erzeugt an Eurer aktuellen Position eine Abwehr gegen Elemente. 8...20 Sekunde[n] lang erhalten Verbündete, die keine Geister sind, in dem Bereich +24 Rüstung gegen Elementarschaden.','Abwehrzauber. (8...20 Sekunde[n].) Verbündete in dieser Abwehr haben +24 Rüstung gegen Elementarschaden. Geister sind nicht betroffen.'],
176=>['Abwehr gegen Nahkampf','Abwehrzauber. Ihr erzeugt an Eurer aktuellen Position eine Abwehr gegen Nahkampf. 5...20 Sekunde[n] lang haben Verbündete, die keine Geister sind, in diesem Bereich eine 50%ige Chance, Nahkampfangriffe zu blocken.','Abwehrzauber. (5...20 Sekunde[n].) Verbündete in dieser Abwehr können Nahkampfangriffe mit 50%iger Wahrscheinlichkeit blocken. Verbündete Geister sind nicht betroffen.'],
177=>['Abwehr gegen Feinde','Abwehrzauber. Ihr erzeugt an Eurer aktuellen Position eine Abwehr gegen Feinde. 8...20 Sekunde[n] lang bewegen sich Gegner, die keine Geister sind, in diesem Bereich um 50% langsamer.','Abwehrzauber. (8...20 Sekunde[n].) Feinde in dieser Abwehr bewegen sich um 50% langsamer.'],
178=>['Ätherwunder','Elite-Verzauberung. Alle Verzauberungen gehen verloren. 8...20 Sekunde[n] lang erhaltet Ihr eine Energieregeneration von +6. Wenn Ätherwunder endet, verliert Ihr für jeden Energiepunkt, den Ihr habt, 2 Lebenspunkt[e].','Elite-Verzauberung. (8...20 Sekunde[n].) Ihr habt +6 Energieregeneration. Wirkung am Ende: Ihr verliert für jeden Energiepunkt, den Ihr habt, 2 Lebenspunkt[e]. Alle Verzauberungen gehen verloren.'],
179=>['Brandbänder','Verhexung. Nach 3 Sekunden erleiden der Gegner und alle Feinde in der Nähe 20...80 Punkte Feuerschaden und werden 1...3 Sekunden lang in Brand gesetzt. Wird früher aktiviert, wenn der anvisierte Gegner stirbt.','Verhexung. (3 Sekunden.) Richtet bei Feinden in der Nähe des Ziels 20...80 Punkte Feuerschaden an und verursacht den Zustand Brennen (1...3 Sekunden). Wird auch aktiviert, wenn der anvisierte Gegner stirbt.'],
180=>['Wiederherstellungs-Aura','Verzauberung. 60 Sekunden lang gewinnt Ihr jedes Mal, wenn Ihr einen Zauber wirkt, 0...1 Energie und Heilung in Höhe von 200...500% der jeweiligen Energiekosten.','Verzauberung. (60 Sekunden.) Ihr gewinnt jedes Mal, wenn Ihr einen Zauber wirkt, 0...1 Energie und Heilung in Höhe von 200...500% der jeweiligen Energiekosten.'],
181=>['Äthererneuerung','Elite-Verzauberung. 5...20 Sekunde[n] lang bekommt Ihr jedes Mal, wenn Ihr einen Zauber wirkt, 1...4 Energiepunkt[e] und 5...20 Lebenspunkt[e] für jede Verzauberung, die auf Euch liegt.','Elite-Verzauberung. (5...20 Sekunde[n].) Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr für jede Verzauberung auf Euch 1...4 Energiepunkt[e] und 5...20 Lebenspunkt[e].'],
182=>['Flammenbeschwörung','Verzauberung. 60 Sekunden lang richten Eure Angriffe 5...20 Punkt[e] zusätzlichen Feuerschaden an, wenn Ihr eine Feuerwaffe führt.','Verzauberung. (60 Sekunden.) Eure Angriffe richten +5...20 Punkt[e] Feuerschaden an. Keine Wirkung, falls Eure Waffe keinen Feuerschaden verursacht.'],
183=>['Inferno','Zauber. Alle umstehenden Feinde erleiden 30...135 Punkt[e] Feuerschaden.','Zauber. Richtet bei umstehenden Feinden 30...135 Punkt[e] Feuerschaden an.'],
184=>['Feuereinstimmung','Verzauberung. 36...60 Sekunde[n] lang seid Ihr auf Feuer eingestimmt. Jedes Mal, wenn Ihr Feuermagie verwendet, erhaltet Ihr 1 Energiepunkt sowie 30% der Basisenergiekosten der Fertigkeit.','Verzauberung. (36...60 Sekunde[n].) Ihr erhaltet 1 Energiepunkt plus 30% der Energiekosten zurück, wenn Ihr Feuermagie-Fertigkeiten benutzt.'],
185=>['Geistige Verbrennung','Elite-Zauber. Gegner und umstehende Feinde erleiden 15...60 Punkt[e] Feuerschaden. Falls Ihr mehr Energie als der Gegner habt, erleiden er und alle umstehenden Feinde zusätzlich 15...60 Punkt[e] Feuerschaden und werden 1...10 Sekunde[n] lang in Brand gesetzt.','Elite-Zauber. Richtet 15...60 Punkt[e] Feuerschaden an. Falls Ihr mehr Energie habt als der Gegner, erhält er zusätzlich 15...60 Punkt[e] Feuerschaden und Zustand Brennen (1...10 Sekunde[n]). Trifft den Gegner und umstehende Feinde.'],
186=>['Feuerball','Zauber. Schleudert einen Feuerball, der anvisierte Gegner und alle Gegner in der Nähe für 7...112 Feuerschaden trifft.','Zauber. Projektil: Fügt dem Ziel und Gegnern in der Nähe 7...112 Feuerschaden zu.'],
187=>['Meteor','Zauber. Der Gegner und alle umstehenden Feinde erleiden 7...112 Punkt[e] Feuerschaden und werden zu Boden geworfen.','Zauber. Richtet 7...112 Punkt[e] Feuerschaden an und wirft zu Boden. Trifft auch umstehende Feinde um den Gegner.'],
188=>['Flammenstoß','Zauber. Alle Feinde in der Nähe erleiden 15...120 Punkt[e] Feuerschaden.','Zauber. Richtet bei allen Feinden in Eurer Nähe 15...120 Punkt[e] Feuerschaden an.'],
189=>['Anrufung von Rodgort','Zauber. Der Gegner und alle Feinde in der Nähe erleiden 15...120 Punkt[e] Feuerschaden und werden 1...3 Sekunde[n] lang in Brand gesetzt.','Zauber. Richtet 15...120 Punkt[e] Feuerschaden an. Wirkt auch auf Feinde in der Nähe des Gegners. Verursacht Zustand Brennen (1...3 Sekunde[n]).'],
190=>['Zeichen des Rodgort','Verhexung. Der Gegner und alle Feinde in der Nähe werden mit dem Zeichen des Rodgort verhext. 10...35 Sekunde[n] lang wird jeder Feind jedes Mal, wenn er Feuerschaden erleidet, 1...4 Sekunde[n] lang in Brand gesetzt.','Verhexung. Verhext außerdem den Gegner umstehende Feinde (10...35 Sekunde[n]). Verursacht Zustand Brennen (1...4 Sekunde[n]), wenn die Betroffenen Feuerschaden erleiden.'],
191=>['Feueropfer','Zauber. Der Gegner erleidet 20...75 Punkt[e] Feuerschaden und wird für 1...3 Sekunde[n] in Brand gesetzt.','Zauber. Richtet 20...75 Punkt[e] Feuerschaden an. Verursacht Zustand Brennen (1...3 Sekunde[n]).'],
192=>['Meteorschauer','Zauber. An der Position des Gegners wird ein Meteorschauer erzeugt. Während der nächsten 9 Sekunden erleiden umstehende Gegner 7...112 Punkt[e] Feuerschaden und werden alle 3 Sekunden zu Boden geworfen.','Zauber. Richtet 7...112 Punkt[e] Feuerschaden an und wirft alle 3 Sekunden zu Boden (9 Sekunden). Trifft umstehende Feinde um anfängliche Position des Ziels.'],
193=>['Phönix','Zauber. An Eurer Position steigt ein feuriger Phönix empor, fliegt zu Eurem Ziel und explodiert, sobald er dort aufschlägt. Diese Explosion richtet beim Gegner und umstehenden Feinden 10...60 Punkte Feuerschaden an. Wenn Ihr Überzaubert seid, werden Verbündete im Explosionsradius für 20...80 Lebenspunkte geheilt.','Zauber. Geschoss: Richtet beim Gegner und umstehenden Feinden 10...60 Punkte Feuerschaden an. Heilt Verbündete für 20...80, wenn Ihr Überzaubert seid.'],
194=>['Feuergeschoss','Zauber. Sendet ein Feuergeschoss aus, das dem Gegner 20...65 Punkte Feuerschaden zufügt, falls es trifft. Wenn Ihr Überzaubert seid, trifft dieser Zauber umstehende Feinde ebenfalls.','Zauber. Geschoss: Richtet 20...65 Punkte Feuerschaden an. Wenn Überzaubert, werden auch umstehende Gegner getroffen.'],
195=>['Lavabecken','Zauber. 5 Sekunden lang erleiden umstehende Gegner am Wirkungsort dieses Zaubers 5...50 Punkte Feuerschaden pro Sekunde. Wenn Ihr Überzaubert seid, trifft dieser Zauber Feinde in der Nähe, anstatt umstehende Feinde.','Zauber. Richtet 5...50 Punkte Feuerschaden pro Sekunde an (5 Sekunden). Trifft Feinde in der Nähe Eurer ursprünglichen Position. Wenn Überzaubert, dann wird die Reichweite zu In der Nähe erhöht.'],
196=>['Sengende Hitze','Zauber. An der Position des Gegners wird Sengende Hitze erzeugt. 5 Sekunden lang erleiden Feinde in der Nähe pro Sekunde je 10...40 Punkt[e] Feuerschaden. Wenn Sengende Hitze endet, werden die im Wirkungsbereich befindlichen Feinde 3 Sekunden lang in Brand gesetzt.','Zauber. Richtet 10...40 Punkt[e] Feuerschaden pro Sekunde an (5 Sekunden). Trifft Feinde in der Nähe der ursprünglichen Position des Ziels. Wirkung am Ende: Verursacht Zustand Brennen (3 Sekunden).'],
197=>['Feuersturm','Zauber. An der Position des Gegners wird ein Feuersturm erzeugt. Während der nächsten 10 Sekunden erleiden umstehende Gegner 5...35 Punkt[e] Feuerschaden pro Sekunde.','Zauber. Richtet 5...35 Punkt[e] Feuerschaden pro Sekunde an (10 Sekunden). Trifft umstehende Feinde um anfängliche Position des Ziels.'],
198=>['Glyphe der Elementarkraft','Glyphe. 25 Sekunden lang sind Eure Elementarattribute für Eure nächsten 10 Zauber um 2 erhöht.','Glyphe. (25 Sekunden.) Erhöht Eure Elementarattribute für Eure nächsten 10 Zauber um +2.'],
199=>['Glyphe der Energie','Elite-Glyphe. Eure nächsten 1...3 Zauber verursachen kein Überzaubern und kosten 10...25 Energiepunkte weniger. Eure Elementarattribute sind um 1...2 erhöht.','Elite-Glyphe. Eure nächsten 1...3 Zauber verursachen kein Überzaubern und kosten 10...25 Energiepunkte weniger. Ihr erhaltet 1...2 aus alle Elementarattribute.'],
200=>['Glyphe der geringeren Energie','Glyphe. Während der nächsten 15 Sekunden kostet das Wirken Eurer nächsten 2 Zauber 10...18 Energiepunkte weniger.','Glyphe. (15 Sekunden.) Eure nächsten 2 Zauber kosten 10...18 Energiepunkt[e] weniger.'],
201=>['Glyphe der Konzentration','Glyphe. 15 Sekunden lang können Eure nächsten 1 Zauber nicht unterbrochen werden und berücksichtigen die Auswirkungen von Benommenheit nicht.','Glyphe. (15 Sekunden.) Eure nächsten 1 Zauber können nicht unterbrochen werden. Sie bleiben vom Zustand Benommenheit unbeeinflusst.'],
202=>['Glyphe der Opferung','Glyphe. 15 Sekunde[n] lang wirkt Euer nächster Zauber sofort, benötigt aber für die Wiederaufladung 30 Sekunde[n] länger. Endet vorzeitig, wenn Ihr eine Nicht-Zauber-Fertigkeit verwendet.','Glyphe. (15 Sekunden.) Euer nächster wirkt Zauber sofort, benötigt aber für die Wiederaufladung 30 Sekunde[n] länger. Endet, wenn Ihr eine Nicht-Zauber-Fertigkeit verwendet.'],
203=>['Glyphe der Erneuerung','Elite-Glyphe. 15 Sekunden lang wird Euer nächster Zauber sofort wieder aufgeladen.','Elite-Glyphe. (15 Sekunden.) Euer nächster Zauber wird sofort wieder aufgeladen.'],
204=>['Rost','Verhexung. Richtet beim Gegner und umstehenden Feinden 10...85 Punkte Kälteschaden an. 5...20 Sekunden lang benötigen der Gegner und alle umstehenden Feinden doppelt so lange, um Siegel zu aktivieren. Wenn Ihr Überzaubert seid, werden Siegel von Gegnern, die von Rost getroffen sind, unterbrochen und für 1...10 Sekunden deaktiviert.','Verhexung. Richtet beim Gegner und umstehenden Feinden 10...85 Punkte Kälteschaden an. Verhext den Gegner und umstehende Feinde (5...20 Sekunden). Verdoppelt die Aktivierungszeit von Siegeln. Unterbricht und deaktiviert Siegel für 1...10 Sekunden, wenn Ihr Überzaubert seid.'],
205=>['Blitzwelle','Elite-Verhexung. Nach 3 Sekunden wird der Gegner zu Boden geworfen, erleidet 14...100 Punkt[e] Blitzschaden und leidet 5...20 Sekunde[n] lang an Beschädigter Rüstung. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Elite-Verhexung. (3 Sekunden.) Wirkung am Ende: Richtet 14...100 Punkt[e] Blitzschaden an, wirft zu Boden und verursacht Beschädigte Rüstung (5...20 Sekunde[n]). 25% Rüstungsdurchdringung.'],
206=>['Frostrüstung','Verzauberung. 10...34 Sekunde[n] lang bekommt Ihr +40 Rüstung gegen physischen Schaden und Eure Wassermagie ist um +1 erhöht.','Verzauberung. (10...34 Sekunde[n].) Ihr bekommt +40 Rüstung gegen physischen Schaden und Eure Wassermagie ist um +1 erhöht.'],
207=>['Frost beschwören','Verzauberung. 60 Sekunden lang richten Eure Angriffe 5...20 Punkt[e] zusätzlichen Kälteschaden an, wenn Ihr eine Kältewaffe führt.','Verzauberung. (60 Sekunden.) Eure Angriffe richten +5...20 Punkt[e] Kälteschaden an. Keine Wirkung, falls Eure Waffe keinen Kälteschaden verursacht.'],
208=>['Wassereinstimmung','Verzauberung. 36...60 Sekunde[n] lang seid Ihr auf Wasser eingestimmt. Jedes Mal, wenn Ihr Wassermagie verwendet, erhaltet Ihr 1 Energiepunkt sowie 30% der Basisenergiekosten der Fertigkeit.','Verzauberung. (36...60 Sekunde[n].) Ihr erhaltet 1 Energiepunkt plus 30% der Energiekosten zurück, wenn Ihr Wassermagie-Fertigkeiten benutzt.'],
209=>['Geistige Erfrierung','Elite-Verhexung. Der Gegner erleidet 10...60 Punkt[e] Kälteschaden. Wenn Ihr mehr Energie als der Gegner habt, erleidet dieser zusätzlich 10...60 Punkt[e] Kälteschaden und bewegt sich 1...5 Sekunde[n] lang um 90% langsamer. Dieser Zauber ruft Erschöpfung hervor.','Elite-Verhexung. Richtet 10...60 Punkt[e] Kälteschaden an. Falls Ihr mehr Energie habt als der Gegner, erhält er zusätzlich +10...60 Punkt[e] Kälteschaden und bewegt sich um 90% langsamer (1...5 Sekunde[n]).'],
210=>['Eisgefängnis','Verhexung. 8...20 Sekunde[n] lang werden die Beine des Gegners von Eis umschlossen, wodurch seine Bewegungen um 66% langsamer werden.','Verhexung. (8...20 Sekunde[n].) Gegner bewegt sich um 66% langsamer.'],
211=>['Eisdornen','Verhexung. Der Gegner sowie umstehende Feinde erleiden 20...80 Punkt[e] Kälteschaden und bewegen sich 2...6 Sekunde[n] lang um 66% langsamer.','Verhexung. Verhext den Gegner und umstehende Feinde (2...6 Sekunde[n]). Diese Feinde bewegen sich um 66% langsamer. Anfangswirkung: Richtet 20...80 Punkt[e] Kälteschaden an.'],
212=>['Frostexplosion','Verhexung. Alle in der Nähe befindlichen Gegner erleiden 10...85 Punkt[e] Kälteschaden und bewegen sich 3...8 Sekunde[n] lang um 66% langsamer.','Verhexung. Verhext Feinde in Eurer Nähe. Diese Feinde bewegen sich um 66% langsamer (3...8 Sekunde[n]). Anfangswirkung: Richtet bei Feinden in Eurer Nähe 10...85 Punkt[e] Kälteschaden an.'],
213=>['Scherbensturm','Verhexung. Sendet eine Eisscherbe aus, die dem Gegner 10...85 Punkt[e] Kälteschaden zufügt, wenn sie trifft und dazu führt, dass er sich 2...6 Sekunde[n] lang um 66% langsamer bewegt.','Verhexung. Geschoss: Richtet 10...85 Punkt[e] Kälteschaden an. Gegner bewegt sich um 66% langsamer (2...6 Sekunde[n]).'],
214=>['Eisspeer','Verzauberung. Sendet einen Eisspeer aus, der dem Gegner 10...60 Punkte Kälteschaden zufügt, wenn er trifft. Wenn Ihr Überzaubert seid, habt Ihr 5 Sekunden lang +1...4 Lebenspunktregeneration.','Verzauberung. Geschoss: Richtet 10...60 Punkte Kälteschaden an. Wenn Ihr Überzaubert seid, erhaltet Ihr für 5 Sekunden +1...4 Lebenspunktregeneration.'],
215=>['Strudel','Zauber. An der Position des Gegners wird ein Strudel erzeugt. 10 Sekunden lang erleiden umstehende Feinde in diesem Bereich pro Sekunde 10...25 Punkt[e] Kälteschaden. Wenn Strudel trifft, wird dadurch das Wirken von Zaubern unterbrochen.','Zauber. Richtet jede Sekunde 10...25 Punkt[e] Kälteschaden an und unterbricht Zauber (10 Sekunden). Trifft umstehende Feinde um anfängliche Position des Ziels.'],
216=>['Eisennebel','Verzauberung. 8...15 Sekunden lang habt Ihr +15 Rüstung. Eure Luftmagie-Zauber, die einen Gegner als Ziel haben, werden 33 % schneller aktiviert und wiederaufgeladen, aber Ihr seid 2 Punkte überlastet.','Verzauberung. (8...15 Sekunden) Ihr erhaltet +15 Rüstung. Eure Luftmagie-Zauber, die einen Gegner als Ziel haben, werden 33 % schneller aktiviert und wiederaufgeladen, aber Ihr seid 2 Punkte überlastet.'],
217=>['Kristallwelle','Zauber. Umstehende Gegner erleiden 10...70 Punkte Schaden, werden jedoch von sämtlichen negativen Zuständen geheilt. Jeder entfernte Zustand verursacht 5...15 Schaden.','Zauber. Richtet bei allen umstehenden Feinden 10...70 Punkte Schaden an. Diese Gegner verlieren alle Zustände und erleiden für jeden entfernten Zustand 5...15 Schaden.'],
218=>['Obsidianfleisch','Elite-Verzauberung. 8...20 Sekunde[n] lang erhaltet Ihr +20 Rüstung und könnt nicht zum Ziel von feindlichen Zaubern werden. Dafür könnt Ihr nicht angreifen und erleidet -2 Energiedegeneration.','Elite-Verzauberung. (8...20 Sekunde[n].) Ihr erhaltet +20 Rüstung und könnt nicht zum Ziel von feindlichen Zaubern werden. Ihr könnt nicht angreifen und erleidet -2 Energiedegeneration.'],
219=>['Obsidianflamme','Zauber. Fügt dem Gegner 22...112 Punkt[e] Schaden zu. Dieser Zauber ignoriert Rüstung.','Zauber. Richtet 22...112 Punkt[e] Schaden an.'],
220=>['Blitzblendung','Zauber. Der als Ziel ausgewählte Feind wird 3...8 Sekunde[n] lang geblendet.','Zauber. Verursacht Zustand Blindheit (3...8 Sekunde[n]).'],
221=>['Blitzbeschwörung','Verzauberung. 60 Sekunden lang richten Eure Angriffe 5...20 Punkt[e] zusätzlichen Blitzschaden an, wenn Ihr eine Blitzwaffe führt.','Verzauberung. (60 Sekunden.) Eure Angriffe richten +5...20 Punkt[e] Blitzschaden an. Keine Wirkung, falls Eure Waffe keinen Blitzschaden verursacht.'],
222=>['Blitzschlag','Verhexung. Fügt dem Gegner 10...60 Punkte Blitzschaden zu. Dieser Zauber hat eine Rüstungsdurchdringung von 25%. Wenn Ihr Überzaubert seid, wird dieser Gegner für 3 Sekunden mit Blitzschlag verhext. Wenn diese Verhexung endet, wird diesem Gegner noch einmal 20...40 Punkte Blitzschaden zugefügt.','Verhexung. Richtet 10...60 Punkte Blitzschaden an. 25% Rüstungsdurchdringung. Verhext für 3 Sekunden, wenn Überzaubert. Wirkung am Ende: Richtet 20...40 Punkte Blitzschaden an.'],
223=>['Kettenblitz','Zauber. Der Gegner und bis zu zwei andere in der Nähe befindliche Feinde erleiden 10...85 Punkt[e] Blitzschaden. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Zauber. Richtet 10...85 Punkt[e] Blitzschaden an. Trifft den Gegner und zwei Feinde in seiner Nähe. 25% Rüstungsdurchdringung.'],
224=>['Schwächende Aufladung','Zauber. Der Gegner wird getroffen, erleidet 25...50 Punkt[e] Blitzschaden und leidet 5...20 Sekunde[n] lang an Schwäche. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Zauber. Richtet 25...50 Punkt[e] Blitzschaden an. Verursacht Zustand Schwäche (5...20 Sekunde[n]). 25% Rüstungsdurchdringung.'],
225=>['Lufteinstimmung','Verzauberung. 36...60 Sekunde[n] lang seid Ihr auf Luft eingestimmt. Jedes Mal, wenn Ihr Luftmagie verwendet, erhaltet Ihr 1 Energiepunkt sowie 30% der Basisenergiekosten der Fertigkeit.','Verzauberung. (36...60 Sekunde[n].) Ihr erhaltet 1 Energiepunkt plus 30% der Energiekosten zurück, wenn Ihr Luftmagie-Fertigkeiten benutzt.'],
226=>['Geistiger Schock','Elite-Zauber. Der Gegner erleidet 10...50 Punkt[e] Blitzschaden. Wenn Ihr mehr Energie als der Gegner habt, erleidet er 10...50 Punkt[e] zusätzlichen Blitzschaden und wird zu Boden geworfen. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Elite-Zauber. Richtet 10...50 Punkt[e] Blitzschaden an. Wenn Ihr mehr Energie als der Gegner habt, erleidet er +10...50 Punkt[e] Blitzschaden und wird zu Boden geworfen. 25% Rüstungsdurchdringung.'],
227=>['Schimmerndes Zeichen','Elite-Verhexung. 10 Sekunde[n] lang erleiden der Feind und alle umstehenden Gegner pro Sekunde 5...25 Punkt[e] Schaden. Gegner, die Angriffsfertigkeiten verwenden, werden 3 Sekunde[n] lang geblendet. Diese Verhexung endet, wenn Ihr eine Fertigkeit mit diesem Gegner als Ziel verwendet.','Elite-Verhexung. (10 Sekunde[n].) Richtet beim Gegner und umstehenden Feinden pro Sekunde 5...25 Punkt[e] Schaden an. Blendet Gegner, die Angriffsfertigkeiten verwenden. Endet, wenn Ihr eine Fertigkeit mit diesem Gegner als Ziel verwendet.'],
228=>['Donnerschlag','Elite-Zauber. Erzeugt eine massive Schockwelle am Standort des anvisierten Gegners. Fügt dem Ziel und allen Gegnern in der Nähe 10...50 Blitzschaden zu. Getroffene Gegner werden unterbrochen und erleiden für 5...20 Sekunden Zerborstene Rüstung und Schwäche. Dieser Zauber besitzt 25 % Rüstungspenetration.','Elite-Zauber. Teilt 10...50 Blitzschaden aus. Trifft auch Gegner in der Nähe. Fügt Zerborstene Rüstung und Schwäche zu (5...20 Sekunden). Verursacht Unterbrechung. 25 % Rüstungspenetration.'],
229=>['Kugelblitz','Zauber. Sendet einen Kugelblitz aus, der dem Gegner 10...100 Punkte Blitzschaden zufügt. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Zauber. Geschoss: Richtet 10...100 Punkte Blitzschaden an. 25% Rüstungsdurchdringung.'],
230=>['Blitzspeer','Zauber. Schleudert einen Blitzspeer, der, falls er trifft, 15...50 Punkte Blitzschaden zufügt. Blitzspeer unterbricht angreifende Gegner. Dieser Zauber hat eine Rüstungsdurchdringung von 25% und trifft alle Feinde zwischen Euch und Eurem Ziel.','Zauber. Geschoss: Richtet 15...50 Punkte Blitzschaden an. Unterbricht, wenn Euch Euer Ziel angreift. 25% Rüstungsdurchdringung. Trifft alle Feinde zwischen Euch und Eurem Ziel.'],
231=>['Schock','Fertigkeit. Der berührte Gegner wird zu Boden geworfen und erleidet 10...60 Punkt[e] Blitzschaden. Diese Fertigkeit hat eine Rüstungsdurchdringung von 25%.','Berührungs-Fertigkeit. Richtet 10...60 Punkt[e] Blitzschaden an. Wirft zu Boden. 25% Rüstungsdurchdringung.'],
232=>['Blitz-Berührung','Fertigkeit. Der berührte Gegner und alle umstehenden Feinde erleiden 10...60 Punkte Blitzschaden, sind für 1...4 Sekunden geblendet und erleiden für 1...10 Sekunden Beschädigte Rüstung. Diese Fertigkeit hat eine Rüstungsdurchdringung von 25%.','Berührungs-Fertigkeit. Richtet 10...60 Punkte Blitzschaden an. Trifft auch umstehende Feinde um den Gegner. Verursacht für 1...4 Sekunden Blind und für 1...10 Sekunden Beschädigte Rüstung bei allen getroffenen Gegnern. 25% Rüstungsdurchdringung.'],
233=>['Wirbelnde Aura','Verzauberung. Für 3...7 Sekunden seid Ihr mit Wirbelnde Aura verzaubert und habt 1...6 Lebenspunktregeneration und eine 50%ige Wahrscheinlichkeit, dass Geschosse geblockt werden. Wenn Ihr Überzaubert seid, wenn Ihr diesen zauber wirkt, werden alle Gruppenmitglieder in Hörweite ebenfalls verzaubert.','Verzauberung. (3...7 Sekunden.) Ihr habt +1...6 Lebenspunktregeneration und eine 50%ige Chance, zu blocken. Wenn Überzaubert, werden alle Gruppenmitglieder in Hörweite ebenfalls verzaubert.'],
234=>['Tiefgefrieren','Verhexung. Die Position des Gegners wird tiefgefroren. Alle Feinde in diesem Bereich erleiden 10...85 Punkt[e] Kälteschaden und bewegen sich 10 Sekunden lang um 66% langsamer.','Verhexung. Verhext auch Feinde im Bereich Eures Gegners (10 Sekunden). Diese Feinde bewegen sich um 66% langsamer. Anfangswirkung: Richtet 10...85 Punkt[e] Kälteschaden an.'],
235=>['Verschwommene Sicht','Verhexung. 4...10 Sekunde[n] lang werden der Gegner und alle umstehenden Feinde mit Verschwommener Sicht verhext. Solange diese Verhexung wirkt, besteht eine 50%ige Chance, dass die Angriffe dieser Gegner fehlschlagen.','Verhexung. Verhext den Gegner und umstehende Feinde (4...10 Sekunde[n]). Die Angriffe der Betroffenen gehen mit 50%iger Wahrscheinlichkeit daneben.'],
236=>['Nebelform','Elite-Verzauberung. 10...45 Sekunde[n] lang erleidet Ihr 33% weniger Schaden von Feinden, die an den Auswirkungen einer Wassermagie-Verhexung leiden. Immer wenn Ihr einen Elementarzauber wirkt, werden alle Verbündete in Hörweite, die keine Geister sind, um 50...250% der Energiekosten dieses Zaubers geheilt.','Elite-Verzauberung. (10...45 Sekunde[n].) Ihr erleidet 33% weniger Schaden von Feinden, die an den Auswirkungen einer Wassermagie-Verhexung leiden. Verbündete in Hörweite, die keine Geister sind, werden um 50...250% der Energiekosten Eurer Elementarzauber geheilt.'],
237=>['Wasserdreizack','Elite-Zauber. Sendet einen schnellen Wasserdreizack aus, der dem Gegner 10...90 Punkt[e] Kälteschaden zufügt, wenn er trifft. Trifft er einen Gegner, der sich bewegt, wird dieser zu Boden geworfen.','Elite-Zauber. Schnelles Geschoss: Richtet 10...90 Punkt[e] Kälteschaden an und wirft Feinde, die sich bewegen, zu Boden. Schleudert 2 zusätzliche Geschosse auf umstehende Feinde.'],
238=>['Nebelrüstung','Verzauberung. 8...20 Sekunde[n] lang erhaltet Ihr +10...40 Rüstung und bewegt Euch um 33% schneller.','Verzauberung. (8...20 Sekunde[n].) Ihr habt +10...40 Rüstung und bewegt Euch um 33% schneller.'],
239=>['Abwehr gegen Schaden','Elite-Abwehrzauber. Errichtet an dieser Position eine Abwehr gegen Schaden. 5...15 Sekunde[n] lang erhalten in diesem Bereich befindliche Verbündete, die keine Geister sind, +1...3 Lebenspunktregeneration, +12...24 Rüstung und zusätzlich +12...24 Rüstung gegen Elementarschaden. Dieser Zauber wird 20 Sekunden lang deaktiviert.','Elite-Abwehrzauber. (5...15 Sekunde[n].) Verbündete in dieser Abwehr haben +1...3 Lebenspunktregeneration, +12...24 Rüstung und zusätzlich +12...24 Rüstung gegen Elementarschaden. Geister sind nicht betroffen. Dieser Zauber wird 20 Sekunden lang deaktiviert.'],
240=>['Peinigung','Zauber. Dieser Angriff fügt 10...55 Punkt[e] heiligen Schaden zu. Wenn Euer Ziel angreift, erleidet es zusätzlich 10...35 Punkt[e] heiligen Schaden.','Zauber. Richtet 10...55 Punkt[e] heiligen Schaden an. Richtet zusätzlich 10...35 Punkt[e] heiligen Schaden an, falls der Gegner gerade angreift.'],
241=>['Lebensbindung','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, wird immer dann, wenn der Verbündete bei einem Angriff Schaden erleidet, die Hälfte dieses Schadens auf Euch weitergeleitet. Der dadurch von Euch erlittene Schaden wird um 3...30 Punkt[e] reduziert.','Verzauberung. Die Hälfte des Schadens, den der Verbündete durch Angriffe erleidet, wird auf Euch weitergeleitet. Der weitergeleitete Schaden wird um 3...30 Punkt[e] reduziert. Sich selbst als Ziel wählen nicht möglich.'],
242=>['Balthasars Geist','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, erhält der Verbündete (bzw. Ihr selbst), nachdem er Schaden erlitten hat, Adrenalin und Energiepunkte. (Die erhaltene Adrenalinmenge erhöht sich je nach Eurem Rang bei Peinigungsgebeten.)','Verzauberung. Der Verbündete (bzw. Ihr selbst) erhält Adrenalin und 1 Energiepunkt, wenn er Schaden erleidet.'],
243=>['Stärke der Ehre','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, fügt der Verbündete (bzw. Ihr selbst) im Nahkampf zusätzlich 5...25 Punkt[e] Schaden zu.','Verzauberung. Der Verbündete (bzw. Ihr selbst) richtet im Nahkampf zusätzlich 5...25 Punkt[e] Schaden an.'],
244=>['Lebenseinstimmung','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, fügt der Verbündete (bzw. Ihr selbst) mit seinen Angriffen 30% weniger Schaden zu, erhält aber bei der Heilung 14...50% mehr Lebenspunkte.','Verzauberung. Verbündeter (bzw. Ihr selbst) erhält bei Heilung um 14...50% mehr Lebenspunkte. Er richtet mit Angriffen 30% weniger Schaden an.'],
245=>['Schutzgeist','Verzauberung. 5...23 Sekunde[n] lang verliert der Verbündete (bzw. Ihr selbst) bei einem Schaden aus einem einzelnen Angriff oder Zauber höchstens 10% der maximalen Lebenspunkte.','Verzauberung. 5...23 Sekunde[n]: Erlittener Schaden wird auf 10% der maximalen Lebenspunkte des Verbündeten (bzw. von Euch selbst) reduziert.'],
246=>['Göttliche Intervention','Verzauberung. 10 Sekunden lang wird das nächste Mal, wenn der Verbündete (bzw. Ihr selbst) Schaden erleidet, der tödlich wäre, dieser Schaden aufgehoben und der Verbündete stattdessen für 26...240 Lebenspunkt[e] geheilt.','Verzauberung. 10 Sekunden: Hebt den nächsten Schaden auf, der zum Tod des Verbündeten (bzw. von Euch selbst) führen würde. Aufhebungswirkung: Heilt um 26...240 Lebenspunkt[e].'],
247=>['Symbol des Zorns','Zauber. Erzeugt ein Symbol des Zorns am Standort des anvisierten Gegners. Benachbarte Gegner werden 5 Sekunden lang von 10...40 heiligem Schaden getroffen.','Zauber. Teilt jede Sekunde 10...40 heiligen Schaden aus (5 Sekunden). Trifft Gegner um den ursprünglichen Standort des anvisierten Gegners herum.'],
248=>['Vergeltung','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, wirft dieser Zauber jedes Mal, wenn der Verbündete (bzw. Ihr selbst) Angriffsschaden erleidet, 33% des Schadens auf die Quelle zurück (maximal 5...20 Schadenspunkt[e]).','Verzauberung. Wirft 33% des Schadens durch Angriffe (maximal 5...20 Punkt[e]) auf den Verursacher zurück.'],
249=>['Heiliger Zorn','Verzauberung. Während der folgenden 10...30 Sekunde[n] wirft dieser Zauber die nächsten 1...10 Mal, wenn der Verbündete Angriffsschaden erleidet, 66% des Schadens auf den Verursacher zurück (maximal 5...50 Schadenspunkt[e]).','Verzauberung. (10...30 Sekunde[n].) Wirft 66% des Schadens durch Angriffe (maximal 5...50 Punkt[e]) auf den Verursacher zurück. Endet nach 1...10 Schadenszufügung[en]. Sich selbst als Ziel wählen nicht möglich.'],
250=>['Essenzbindung','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, bekommt Ihr jedes Mal, wenn Euer Verbündeter (oder Ihr selbst) physischen oder Elementarschaden erleidet, 1 Energiepunkt.','Verzauberung. Ihr erhaltet jedes Mal 1 Energiepunkt, wenn der Verbündete (bzw. Ihr selbst) physischen oder Elementarschaden erleidet.'],
251=>['Geißelheilung','Verhexung. 30 Sekunden lang erleidet der Heiler jedes Mal, wenn er den Zielgegner heilt, 15...80 Punkt[e] heiligen Schaden.','Verhexung. 30 Sekunden: Wenn der Gegner geheilt wird, erleidet der Heiler 15...80 Punkt[e] heiligen Schaden.'],
252=>['Verbannung','Zauber. Der Gegner erleidet 20...65 Punkt[e] heiligen Schaden. Dieser Zauber fügt herbeigerufenen Kreaturen doppelten Schaden zu.','Zauber. Richtet 20...65 Punkt[e] heiligen Schaden an. Fügt herbeigerufenen Kreaturen doppelten Schaden zu.'],
253=>['Geißelopfer','Verhexung. 8...20 Sekunde[n] lang opfern der Gegner und umstehende Feinde jedes Mal, wenn sie Leben opfern, doppelt soviel wie normal.','Verhexung. Verhext den Gegner und umstehende Feinde (8...20 Sekunde[n]). Verdoppelt Lebenspunktopfer.'],
254=>['Energischer Geist','Verzauberung. 30 Sekunden lang wird der Verbündete (oder Ihr selbst) jedes Mal, wenn er angreift oder einen Zauber wirkt, um 5...20 Lebenspunkt[e] geheilt.','Verzauberung. 30 Sekunden: Heilt jedes Mal um 5...20 Lebenspunkt[e], wenn der Verbündete (bzw. Ihr selbst) angreift oder einen Zauber wirkt.'],
255=>['Wachsamer Geist','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, erfreut sich der Verbündete (bzw. Ihr selbst) einer zusätzlichen Lebenspunktregeneration von 2. Wenn Wachsamer Geist endet, wird er für 30...180 Lebenspunk[e] geheilt.','Verzauberung. +2 Lebenspunktregeneration. Wirkung am Ende: Heilt um 30...180 Lebenspunkt[e].'],
256=>['Gesegnete Aura','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, halten von Euch gewirkte Mönch-Verzauberungen um 10...35% länger.','Verzauberung. Von Euch gewirkte Mönch-Verzauberungen halten um 10...35% länger an.'],
257=>['Aegis','Verzauberung. 6...15 Sekunde[n] lang erhalten alle Gruppenmitglieder in Hörweite eine 50%ige Chance, Angriffe zu blocken.','Verzauberung. Verzaubert alle Gruppenmitglieder in Hörweite (6...15 Sekunden). 50%ige Chance zu blocken.'],
258=>['Wächter','Verzauberung. 2...7 Sekunde[n] lang bekommt der Verbündete (bzw. Ihr selbst) eine 50%ige Chance, Angriffe zu blocken.','Verzauberung. 2...7 Sekunde[n]: 50%ige Chance, Angriffe zu blocken.'],
259=>['Ablenkungsschild','Elite-Verzauberung. 3...10 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine 75%ige Chance Angriffe zu blocken und erhält 15...30 Rüstung.','Elite-Verzauberung. 3...10 Sekunde[n]: 75%ige Chance zu blocken. +15...30 Rüstung.'],
260=>['Glaubensaura','Elite-Verzauberung. 3 Sekunde[n] lang erhält der Verbündete (bzw. Ihr selbst) bei seiner Heilung 50...100% mehr Lebenspunkte und erleidet 5...50% weniger Schaden.','Elite-Verzauberung. 3 Sekunde[n]: Der Verbündete (bzw. Ihr selbst) erhält bei seiner Heilung 50...100% mehr Lebenspunkte und erleidet 5...50% weniger Schaden.'],
261=>['Schild der Regeneration','Elite-Verzauberung. Für 5...13 Sekunden erhält der anvisierte Verbündete +3...10 Lebenspunktregeneration und 20...45 Rüstung.','Elite-Verzauberung. (5...13 Sekunden). +3...10 Lebenspunktregeneration und +20...45 Rüstung.'],
262=>['Schild des Urteils','Elite-Verzauberung. 8...20 Sekunde[n] lang wird jeder, der den Verbündeten (bzw. Euch selbst) angreift, zu Boden geworfen und erleidet 5...50 Punkt[e] heiligen Schaden.','Elite-Verzauberung. 8...20 Sekunde[n]: Richtet bei den Verbündeten (bzw. Euch selbst) angreifenden Feinden 5...50 Punkt[e] heiligen Schaden an. Wirft zu Boden.'],
263=>['Band des Schutzes','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, kann der Verbündete (bzw. Ihr selbst) nur 5% seiner maximalen Lebenspunkte durch Schaden von einem einzelnen Angriff oder Zauber auf einmal erleiden. Wenn Band des Schutzes Schaden verhindert, verliert Ihr 6...3 Energiepunkt[e] oder der Zauber endet.','Verzauberung. Verbündeter (bzw. Ihr selbst) kann durch einen einzelnen Angriff oder Zauber nicht mehr als 5% seiner maximalen Lebenspunkte verlieren. Jedes Mal, wenn Schaden reduziert wird, verliert Ihr 6...3 Energiepunkt[e] oder dieser Zauber endet.'],
264=>['Pazifismus','Verhexung. 4...8 Sekunde[n] lang kann der Gegner nicht angreifen. Diese Wirkung endet, wenn er Schaden erleidet.','Verhexung. 4...8 Sekunde[n]: Gegner kann nicht angreifen. Endet, wenn der Gegner Schaden erleidet.'],
265=>['Freundschaft','Elite-Verhexung. 4...12 Sekunde[n] lang können umstehende Gegner nicht angreifen. Freundschaft endet für jeden Gegner, sobald er Schaden erleidet.','Elite-Verhexung. 4...12 Sekunde[n]: Umstehende Feinde können nicht angreifen. Endet bei Feinden, die Schaden erleiden.'],
266=>['Frieden und Harmonie','Elite-Verzauberung. Der Verbündete (bzw. Ihr selbst) verliert 0...9 Zustände und Verhexungen. 1...3 Sekunde[n] lang enden Zustände und Verhexungen bei diesem Verbündeten um 90% schneller. All Eure Peinigungsgebete werden 20 Sekunden lang deaktiviert.','Elite-Verzauberung. Der Verbündete (bzw. Ihr selbst) verliert 0...9 Zustände und Verhexungen. Zustände und Verhexungen beim Verbündeten enden um 90% schneller (1...3 Sekunde[n]). Deaktiviert Eure Peinigungsgebete (20 Sekunde[n]).'],
267=>['Einblick des Richters','Verzauberung. 8...20 Sekunde[n] lang fügen Angriffe des Verbündeten (bzw. Eure eigenen) heiligen Schaden zu und haben eine um 20% erhöhte Rüstungsdurchdringung.','Verzauberung. 8...20 Sekunde[n]: Wandelt Angriffe des Verbündeten (bzw. von Euch selbst) in heiligen Schaden um und fügt +20% Rüstungsdurchdringung hinzu.'],
268=>['Unnachgiebige Aura','Elite-Verzauberung. Während Ihr diese Verzauberung aufrechterhaltet, heilen Eure Mönch-Zauber zusätzlich um +15...60% Lebenspunkt[e]. Wenn diese Verzauberung endet, wird nach dem Zufallsprinzip ein anderes Gruppenmitglied mit kompletten Lebens- und Energiepunkten wiederbelebt und an Eure Position teleportiert.','Elite-Verzauberung. Eure Mönch-Zauber heilen zusätzlich um +15...60% Lebenspunkt[e]. Wirkung am Ende: Ein nach dem Zufallsprinzip mit kompletten Lebens- und Energiepunkten wiederbelebtes anderes Gruppenmitglied wird an Eure Position teleportiert.'],
269=>['Schutzzeichen','Elite-Verzauberung. 10 Sekunden lang wird der Verbündete (oder Ihr selbst) immer dann, wenn er Schaden erleiden müsste, stattdessen um diese Punktzahl, höchstens jedoch um 6...60 Punkt[e] geheilt. Alle Eure Schutzgebete werden 5 Sekunden lang deaktiviert.','Elite-Verzauberung. 10 Sekunden: Wandelt erlittenen Schaden in Heilung um (maximal 6...60 Lebenspunkt[e]). Alle Eure Schutzgebete werden deaktiviert (5 Sekunden).'],
270=>['Lebenssperre','Elite-Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, wird dem Verbündeten zugefügter Schaden um 20...50% reduziert. Sind Eure Lebenspunkte unter 50%, wenn der Verbündete Schaden erleidet, endet Lebenssperre.','Elite-Verzauberung. Reduziert Schaden um 20...50%. Sich selbst als Ziel wählen nicht möglich. Habt Ihr weniger als 50% Eurer maximalen Lebenspunkte, wenn der Verbündete Schaden erleidet, endet Lebenssperre.'],
271=>['Eifererfeuer','Verzauberung. Während der nächsten 60 Sekunden erleiden jedes Mal, wenn Ihr eine Fertigkeit auf einen Verbündeten anwendet, alle diesen Verbündeten umstehenden Feinde Feuerschaden in Höhe von 5...35 Punkt[en] und Ihr verliert 1 Energiepunkte.','Verzauberung. 60 Sekunden: Jedes Mal, wenn Ihr eine Fertigkeit auf einen Verbündeten anwendet, erleiden alle umstehenden Feinde um diesen Verbündeten 5...35 Punkt[e] Feuerschaden. Schadenskosten: Ihr verliert 1 Energiepunkt[e].'],
272=>['Balthasars Aura','Verzauberung. 8 Sekunden lang erleiden umstehende Gegner um den Verbündeten (bzw. Euch selbst) herum pro Sekunde 10...30 Punkt[e] heiligen Schaden.','Verzauberung. 8 Sekunden: Richtet pro Sekunde 10...30 Punkt[e] heiligen Schaden bei umstehenden Feinden um den Verbündeten (bzw. Euch selbst) an.'],
273=>['Zauberbrecher','Elite-Verzauberung. 5...17 Sekunde[n] lang kann der Verbündete nicht zum Ziel von feindlichen Zaubern werden.','Elite-Verzauberung. (5...17 Sekunde[n].) Der Verbündete kann nicht zum Ziel von feindlichen Zaubern werden.'],
274=>['Heilender Samen','Verzauberung. 10 Sekunde[n] lang erhalten der anvisierte Verbündete und alle umstehenden Verbündeten 3...30 Lebenspunkt[e], wenn der Verbündete Schaden erleidet.','Verzauberung. 10 Sekunde[n]: Der Verbündete und umstehende Verbündete erhalten jedes Mal 3...30 Lebenspunkt[e], wenn dieser Verbündete Schaden erleidet. Sich selbst als Ziel wählen nicht möglich.'],
275=>['Zustand bessern','Zauber. Entfernt einen Zustand (Gift, Krankheit, Blindheit, Benommenheit, Blutung, Verkrüppelung, Brennen, Schwäche, Beschädigte Rüstung oder Tiefe Wunde) von einem Verbündeten. Wenn ein Zustand entfernt wurde, wird der Verbündete um 5...70 Lebenspunkt[e] geheilt.','Zauber. Entfernt einen Zustand. Entfernungswirkung: Heilt um 5...70 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
276=>['Zustand wiederherstellen','Elite-Zauber. Entfernt alle Zustände (Gift, Krankheit, Blindheit, Benommenheit, Blutung, Verkrüppelung, Brennen, Schwäche, Beschädigte Rüstung und Tiefe Wunde) vom Verbündeten. Für jeden entfernten Zustand wird dieser Verbündete um 10...70 Lebenspunkt[e] geheilt.','Elite-Zauber. Entfernt alle Zustände. Entfernungswirkung: Heilt für jeden entfernten Zustand um 10...70 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
277=>['Leiden heilen','Zauber. Entfernt einen Zustand (Gift, Krankheit, Blindheit, Benommenheit, Blutung, Verkrüppelung, Brennen, Schwäche, Beschädigte Rüstung oder Tiefe Wunde) vom Verbündeten (bzw. Euch selbst). Für jeden verbleibenden Zustand wird dieser Verbündete um 5...70 Lebenspunkt[e] geheilt.','Zauber. Entfernt einen Zustand. Entfernungswirkung: Heilt um 5...70 Lebenspunkt[e] pro verbleibendem Zustand.'],
278=>['Zustände reinigen','Zauber. Entfernt alle Zustände (Gift, Krankheit, Blindheit, Benommenheit, Blutung, Verkrüppelung, Brennen, Schwäche, Beschädigte Rüstung und Tiefe Wunde) von einem Verbündeten.','Zauber. Entfernt alle Zustände.'],
279=>['Göttliche Heilung','Zauber. Heilt Euch selbst und Gruppenmitglieder in Hörweite um 15...60 Punkt[e].','Zauber. Heilt Euch selbst und Gruppenmitglieder in Hörweite um 15...60 Punkt[e].'],
280=>['Gebiet heilen','Zauber. Heilt Euch selbst und alle umstehenden Geschöpfe um 30...180 Punkt[e].','Zauber. Heilt Euch und umstehende Verbündete und Feinde um 30...180 Lebenspunkt[e].'],
281=>['Fürbitte der Heilung','Zauber. Heilt Verbündeten (bzw. Euch selbst) um 30...80 Lebenspunkt[e].','Zauber. Heilt um 30...80 Lebenspunkt[e].'],
282=>['Wort der Heilung','Elite-Zauber. Heilt Verbündeten (bzw. Euch selbst) für 5...100 Lebenspunkt[e]. Er wird für zusätzliche 30...115 Lebenspunkt[e] geheilt, wenn seine Lebenspunkte unter 50% liegen.','Elite-Zauber. Heilt um 5...100 Lebenspunkt[e]. Heilt um weitere 30...115 Lebenspunkt[e], falls der Verbündete (bzw. Ihr selbst) weniger als 50% seiner maximalen Lebenspunkte hat.'],
283=>['Dwaynas Kuss','Zauber. Heilt Verbündeten um 20...65 Lebenspunkt[e] und um zusätzlich 15...40 Lebenspunkt[e] für jede Verzauberung oder Verhexung, die auf diesem Verbündeten liegt.','Zauber. Heilt um 20...65 Lebenspunkt[e]. Heilt für jede Verzauberung und Verhexung auf dem Verbündeten um weitere 15...40 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
284=>['Göttlicher Segen','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, wird jedes Mal, wenn Ihr ein Schutzgebet oder Gunst der Götter auf einen Verbündeten wirkt, dieser um 15...60 Lebenspunkt[e] geheilt und Ihr verliert 1 Energiepunkte.','Verzauberung. Wenn Ihr ein Schutzgebet oder Gunst der Götter auf einen Verbündeten wirkt, wird dieser um 15...60 Lebenspunkt[e] geheilt. Heilkosten: Ihr verliert 1 Energiepunkt.'],
285=>['Heilende Hände','Elite-Verzauberung. Während der nächsten 10 Sekunde[n] wird der Verbündete (bzw. Ihr selbst) jedes Mal, wenn er Schaden erleidet, um 5...35 Lebenspunkt[e] geheilt.','Elite-Verzauberung. 10 Sekunde[n]: Heilt jedes Mal um 5...35 Lebenspunkt[e], wenn das Ziel Schaden erleidet.'],
286=>['Anderen heilen','Zauber. Heilt Verbündeten für 35...180 Lebenspunkt[e].','Zauber. Heilt um 35...180 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
287=>['Gruppe heilen','Zauber. Heilt die ganze Gruppe um 30...75 Lebenspunkt[e].','Zauber. Heilt die gesamte Gruppe um 30...75 Lebenspunkt[e].'],
288=>['Heilender Hauch','Verzauberung. 15 Sekunde[n] lang erfreut sich der Verbündete (bzw. Ihr selbst) einer Lebenspunktregeneration in Höhe von +4...9.','Verzauberung. 15 Sekunde[n]: +4...9 Lebenspunktregeneration.'],
289=>['Lebendige Segnung','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, erhält der Verbündete (bzw. Ihr selbst) +40...200 maximale Lebenspunkte.','Verzauberung. +40...200 maximale Lebenspunkte.'],
290=>['Genesung','Verzauberung. Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, erfreut sich der Verbündete (bzw. Ihr selbst) einer zusätzlichen Lebenspunktregeneration von 1...4.','Verzauberung. +1...4 Lebenspunktregeneration.'],
291=>['Ersatzleben','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, bekommt Ihr jedes Mal, wenn der Verbündete (bzw. Ihr selbst) einen Gegner trifft, 2...17 Lebenspunkt[e].','Verzauberung. Ihr erhaltet jedes Mal 2...17 Lebenspunkt[e], wenn der Verbündete (bzw. Ihr selbst) einen Gegner trifft.'],
292=>['Leben einflößen','Zauber. Ihr verliert die Hälfte Eurer aktuellen Lebenspunkte. Der Verbündete wird um 100...136% der Punkte geheilt, die Ihr verloren habt.','Zauber. Heilt um 100...136% der Hälfte Eurer aktuellen Lebenspunkte. Ihr verliert die Hälfte Eurer aktuellen Lebenspunkte. Sich selbst als Ziel wählen nicht möglich.'],
293=>['Siegel der Hingabe','Siegel. Heilt Verbündeten (bzw. Euch selbst) um 20...120 Lebenspunkt[e].','Siegel. Heilt um 20...120 Lebenspunkt[e].'],
294=>['Siegel des Urteils','Elite-Siegel. Der Gegner wird zu Boden geworfen. Er und alle umstehenden Feinde erleiden 15...75 Punkt[e] heiligen Schaden.','Elite-Siegel. Wirft Gegner zu Boden. Richtet beim Gegner und umstehenden Feinden 15...75 Punkt[e] heiligen Schaden an.'],
295=>['Siegel der Reinigung','Siegel. Entfernt alle Verhexungen und Zustände vom Verbündeten (bzw. Euch selbst). Für jede entfernte Verhexung und jeden entfernten Zustand verliert Ihr jeweils 10 Energiepunkte.','Siegel. Entfernt alle Verhexungen und Zustände. Entfernungskosten: Je 10 Energiepunkte.'],
296=>['Siegel des Ruins','Siegel. Gegner erleidet 30...60 Punkt[e] heiligen Schaden. Falls er gerade angreift, wird er zu Boden geworfen.','Siegel. Richtet 30...60 Punkt[e] heiligen Schaden an. Wirft den Gegner zu Boden, falls dieser gerade angreift.'],
297=>['Gesegnetes Siegel','Siegel. Für jede Verzauberung, die Ihr aufrechterhaltet, bekommt Ihr 3 Energiepunkte. Auf diese Weise bekommt Ihr höchstens 3...24 Energiepunkt[e].','Siegel. Ihr bekommt 3 Energiepunkte für jede Verzauberung, die Ihr aufrechterhaltet. Auf diese Weise bekommt Ihr höchstens 3...24 Energiepunkt[e].'],
298=>['Märtyrer','Elite-Zauber. Übertragt alle Zustände und ihre verbleibende Dauer von Euren Verbündeten auf Euch selbst.','Elite-Zauber. Überträgt alle Zustände aller Verbündeten auf Euch.'],
299=>['Schützende Hände','Verzauberung. 8 Sekunden lang werden der Schaden, den der Verbündete erleidet, und die Lebenspunkte, die diesem entzogen werden, um 3...18 Punkt[e] reduziert. Wenn Schützende Hände endet, wird der Verbündete um 5...50 Lebenspunkt[e] geheilt.','Verzauberung. (8 Sekunde[n].) Reduziert erlittenen Schaden und entzogene Lebenspunkte um 3...18 Punkt[e]. Wirkung am Ende: Heilt um 5...50 Lebenspunkt[e].'],
300=>['Gebot der Reinheit','Fertigkeit. Alle Verzauberungen gehen verloren. Für jede verlorene Verzauberung erhaltet Ihr 0...80 Lebenspunkt[e] und verliert eine Verhexung sowie einen Zustand (maximal 1...8 Verhexung[en] und Zustand[f:"Zustände"]).','Fertigkeit. Für jede Verzauberung auf Euch erhaltet Ihr 0...80 Lebenspunkt[e] und verliert eine Verhexung sowie einen Zustand (maximal 1...8 Verhexungen und Zustände). Ihr verliert alle Verzauberungen.'],
301=>['Verhexung entfernen','Zauber. Entfernt eine Verhexung vom Verbündeten (bzw. Euch selbst).','Zauber. Entfernt beim Verbündeten (bzw. Euch selbst) eine Verhexung.'],
302=>['Verhexung zerschlagen','Zauber. Entfernt eine Verhexung vom Verbündeten (bzw. Euch selbst). Beim Entfernen einer Verhexung erleiden Gegner in dem Bereich 10...85 Punkt[e] heiligen Schaden.','Zauber. Entfernt beim Verbündeten (bzw. Euch selbst) eine Verhexung. Entfernungswirkung: Richtet bei Feinden im Bereich des Verbündeten (bzw. von Euch selbst) 10...85 Punkt[e] heiligen Schaden an.'],
303=>['Verhexungen umwandeln','Zauber. Entfernt alle Verhexungen vom Verbündeten. Er erhält 8...20 Sekunde[n] lang +10 Rüstung für jede entfernte Nekromanten-Verhexung.','Zauber. Entfernt alle Verhexungen; +10 Rüstung für jede entfernte Nekromanten-Verhexung (8...20 Sekunde[n]). Sich selbst als Ziel wählen nicht möglich.'],
304=>['Licht von Dwayna','Zauber. Alle toten Gruppenmitglieder in dem Bereich werden wieder belebt und kehren mit 25% ihrer Lebenspunkte und 0 Energiepunkten ins Leben zurück.','Zauber. Alle toten Gruppenmitglieder im Bereich werden wiederbelebt (25% Lebenspunkte, 0 Energiepunkte).'],
305=>['Wiederbeleben','Zauber. Das als Ziel ausgewählte Gruppenmitglied wird wieder belebt und kehrt mit 25% seiner Lebenspunkte und 0 Energiepunkten ins Leben zurück.','Zauber. Das Gruppenmitglied wird wiederbelebt (25% Lebenspunkte, 0 Energiepunkte).'],
306=>['Wiedergeburt','Zauber. Das als Ziel ausgewählte Gruppenmitglied wird wieder belebt, kehrt mit 25% seiner Lebenspunkte und 0 Energiepunkten ins Leben zurück und wird zu Eurer aktuellen Position teleportiert. Alle seine Fertigkeiten werden 10...3 Sekunde[n] lang deaktiviert. Dieser Zauber verbraucht Eure gesamten verbliebenen Energiepunkte.','Zauber. Das Gruppenmitglied wird wiederbelebt (25% Lebenspunkte, 0 Energiepunkte). Teleportiert das Ziel zu Euch. Deaktiviert die Fertigkeiten des Ziels (10...3 Sekunde[n]). Ihr verliert alle Energiepunkte.'],
307=>['Umkehrung des Schicksals','Verzauberung. 8 Sekunden lang erhält der Verbündete, wenn er das nächste Mal Schaden erleiden oder Lebenspunkte einbüßen würde, stattdessen den entsprechenden Wert als Lebenspunkte (maximal 15...80).','Verzauberung. (8 Sekunde[n].) Wandelt den nächsten erlittenen Schaden bzw. die nächsten entzogenen Lebenspunkte (maximal 15...80 Punkt[e]) in Heilung um.'],
308=>['Beistand','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, erfreut sich der Verbündete einer Regeneration von je +1 Lebens- und Energiepunkt. Ihr verliert jedoch 1 Energiepunkt für jeden Zauber, den er wirkt.','Verzauberung. +1 Lebenspunktregeneration und +1 Energieregeneration. Sich selbst als Ziel wählen nicht möglich. Ihr verliert jedes Mal 1 Energiepunkt, wenn der Verbündete einen Zauber wirkt.'],
309=>['Heiliger Schleier','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, dauert das Wirken von Verhexungen auf einen Verbündeten doppelt so lange. Wenn Heiliger Schleier endet, wird eine Verhexung vom Verbündeten (bzw. Euch selbst) entfernt.','Verzauberung. Verdoppelt die Wirkzeit von Verhexungen, die auf den Verbündeten (bzw. Euch selbst) angewendet werden. Wirkung am Ende: Entfernt eine Verhexung.'],
310=>['Göttlicher Geist','Verzauberung. 1...14 Sekunde[n] lang kostet Euch das Wirken von Mönch-Zaubern 5 Energiepunkte weniger. (Mindestkosten: 1 Energiepunkt).','Verzauberung. 1...14 Sekunde[n]: Mönch-Zauber kosten Euch 5 Energiepunkte weniger. Mindestkosten: 1 Energiepunkt.'],
311=>['Zustände entziehen','Zauber. Alle negativen Zustände werden vom Verbündeten auf Euch übertragen. Für jeden übertragenen Zustand erhaltet Ihr 6...26 Lebenspunkt[e].','Zauber. Überträgt alle Zustände des Verbündeten auf Euch. Übertragungswirkung: Ihr erhaltet für jeden Zustand 6...26 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
312=>['Heiliger Schlag','Fertigkeit. Der berührte Gegner erleidet 10...55 Punkt[e] heiligen Schaden. Wenn Euer Ziel zu Boden geworfen wurde, erleidet es zusätzlich 10...55 Punkt[e] heiligen Schaden.','Berührungs-Fertigkeit. Richtet 10...55 Punkt[e] heiligen Schaden an. Richtet zusätzlich 10...55 Punkt[e] heiligen Schaden an, falls der Gegner zu Boden geworfen ist.'],
313=>['Heilende Berührung','Zauber. Berührt einen Verbündeten und heilt ihn für 20...80 Lebenspunkt[e]. Lebenspunktgewinn durch Gunst der Götter wird bei diesem Zauber verdoppelt.','Berührungs-Zauber. Heilt um 20...80 Lebenspunkt[e]. Lebenspunktgewinn durch Gunst der Götter wird bei diesem Zauber verdoppelt.'],
314=>['Leben erneuern','Zauber. Berührt den Körper eines gefallenen Gruppenmitglieds. Dieses wird mit 20...65% seines Lebens und 42...90% seiner Energie wiederbelebt.','Berührungs-Zauber. Das Gruppenmitglied wird wiederbelebt (20...65% Lebenspunkte, 42...90% Energiepunkte).'],
315=>['Rache','Verzauberung. Das tote Gruppenmitglied wird mit allen Lebenspunkten und voller Energie wiederbelebt. 30 Sekunden lang fügt dieses Gruppenmitglied 25% mehr Schaden zu. Wenn diese Verzauberung endet, stirbt es. Beim Tod unter dem Einfluss dieser Verzauberung gibt es keinen Sterbemalus.','Verzauberung. 30 Sekunden: Das Gruppenmitglied wird wiederbelebt (volle Lebenspunkte, volle Energiepunkte). Der Verbündete richtet 25% mehr Schaden an und erhält keinen Sterbemalus. Wirkung am Ende: Der Verbündete stirbt.'],
316=>['Bis ans Limit!','Schrei. Für jeden Feind in Hörweite (höchstens 1...6) erhaltet Ihr einen Adrenalinstoß. 10...20 Sekunde[n] lang werden Eure maximalen Lebenspunkte um 10...60 erhöht.','Schrei. (10...20 Sekunde[n].) Ihr erhaltet +10...60 maximale Lebenspunkte. Anfangswirkung: Ihr erhaltet für jeden Feind in Hörweite einen Adrenalinstoß (maximal 1...6).'],
317=>['Kampfwut','Elite-Haltung. 5...20 Sekunde[n] lang bewegt Ihr Euch um 33% schneller und Ihr erhaltet die doppelte Menge Adrenalin aus Angriffen. Kampfwut endet, wenn Ihr eine Nicht-Adrenalinfertigkeit verwendet.','Elite-Haltung. 5...20 Sekunde[n]: Ihr bewegt Euch um 33% schneller und erhaltet die doppelte Menge Adrenalin aus Euren Angriffen. Endet, wenn Ihr eine Nicht-Adrenalinfertigkeit verwendet.'],
318=>['Schmerz trotzen','Elite-Fertigkeit. 20 Sekunde[n] lang habt Ihr zusätzlich 90...300 Lebenspunkt[e], zusätzliche 20 Punkte Rüstung und Ihr erleidet 1...10 Punkt[e] weniger Schaden.','Elite-Fertigkeit. 20 Sekunde[n]: Ihr habt +90...300 maximale Lebenspunkte, +20 Rüstung und erleidet -1...10 Punkt[e] weniger Schaden.'],
319=>['Ansturm','Haltung. 8...20 Sekunde[n] lang bewegt Ihr Euch um 25% schneller als normal.','Haltung. 8...20 Sekunde[n]: Ihr bewegt Euch um 25% schneller.'],
320=>['Lähmung','Schwertangriff. Wenn dieser Angriff trifft, erleidet Euer Ziel 3...15 Sekunde[n] lang eine Verkrüppelung, was seine Bewegungen verlangsamt.','Schwertangriff. Verursacht Zustand Verkrüppelung (3...15 Sekunde[n]).'],
321=>['Rundumschlag','Nahkampfangriff. Alles Adrenalin geht verloren. Wenn dieser Angriff erfolgreich ist, dann erfolgt ein kritischer Treffer und jegliche Haltung, die von Eurem Gegner eingenommen wird, endet. Ein Blocken ist bei diesem Angriff nicht möglich.','Nahkampfangriff. Immer ein kritischer Treffer. Entfernt eine Haltung. Kann nicht geblockt werden. Ihr verliert alles Adrenalin.'],
322=>['Kraftangriff','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr 10...40 Punkt[e] zusätzlichen Schaden zu.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an.'],
323=>['Verzweiflungsschlag','Nahkampfangriff. Wenn dieser Angriff trifft, fügt Ihr +10...40 Punkt[e] Schaden zu und Euer Ziel leidet unter einem der folgenden Zustände: Tiefe Wunde (20 Sekunden lang), Schwäche (20 Sekunden lang), Blutung (25 Sekunden lang) oder Verkrüppelung (15 Sekunden lang). Nachdem Ihr einen Verzweiflungsschlag ausgeführt habt, werdet Ihr zu Boden geworfen.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an. Verursacht willkürlich einen der folgenden Zustände: Tiefe Wunde (20 Sekunden), Schwäche (20 Sekunden), Blutung (25 Sekunden) oder Verkrüppelung (15 Sekunden). Ihr werdet zu Boden geworfen.'],
324=>['Rausch des Sieges','Nahkampfangriff. Wenn dieser Schlag trifft, verursacht Ihr +20...40 Punkt[e] Schaden. Wenn Ihr mehr Lebenspunkte als der Gegner habt, erhaltet Ihr 1...2 Adrenalinstöße.','Nahkampfangriff. Richtet +20...40 Punkt[e] Schaden an. Wenn Ihr mehr Lebenspunkte als der Gegner habt, erhaltet Ihr 1...2 Punkte Adrenalin.'],
325=>['Ablenkungsschlag','Nahkampfangriff. Richtet Eure Waffen auf das Ziel. Dadurch fügt Ihr keinen Schaden zu, unterbrecht aber die aktuelle Aktion des Ziels (und die Aktionen von umstehenden Gegnern bei Eurem Ziel).','Nahkampfangriff. Greift den Gegner und umstehende Feinde an. Unterbricht eine Aktion. Treffer verursachen keinen Schaden.'],
326=>['Schlag des Beschützers','Nahkampfangriff. Trifft dieser Schlag einen Gegner in der Bewegung, fügt Ihr 10...40 Punkt[e] zusätzlichen Schaden zu.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an, falls der Gegner sich bewegt.'],
327=>['Greifenschlag','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn dieser Angriff geblockt wird, wird Euer Ziel zu Boden geworfen und erleidet 10...34 Punkt[e] Schaden.','Nahkampfangriff. Richtet +5...20 Punkt[e] Schaden an. Wirft zu Boden und richtet 10...34 Punkt[e] Schaden an, falls geblockt.'],
328=>['Reiner Schlag','Schwertangriff. Wenn Reiner Schlag trifft, fügt Ihr +1...30 Punkt[e] Schaden zu. Wenn Ihr keine Haltung einnehmt, ist ein Blocken bei Reinem Schlag nicht möglich.','Schwertangriff. Richtet +1...30 Punkt[e] Schaden an. Kann nicht geblockt werden, es sei denn, Ihr nehmt eine Haltung ein.'],
329=>['Schädel spalten','Elite-Nahkampfangriff. Bei einem Treffer unterbricht dieser Angriff die aktuelle Aktion des Ziels. Wenn dieser Gegner einen Zauber gewirkt hat, ist der Gegner 15 Sekunden lang benommen.','Elite-Nahkampfangriff. Unterbricht eine Aktion. Fügt dem Ziel den Zustand Benommen (15 Sekunden) zu, falls es einen Zauber wirkt.'],
330=>['Zyklonaxt','Axtangriff. Führt mit kreisender Axt einen Angriff gegen alle umstehenden Gegner für 4...12 Punkt[e] zusätzlichen Schaden aus.','Axtangriff. Richtet bei allen umstehenden Feinden +4...12 Punkt[e] Schaden an.'],
331=>['Hammerstreich','Hammerangriff. Alles Adrenalin geht verloren. Trifft Hammerstreich, wird Euer Ziel zu Boden geworfen.','Hammerangriff. Wirft zu Boden. Ihr verliert alles Adrenalin.'],
332=>['Bullenstoß','Nahkampfangriff. Trifft dieser Angriff einen Gegner, der sich bewegt, fügt Ihr 5...30 Punkt[e] zusätzlichen Schaden zu und Euer Ziel wird zu Boden geworfen.','Nahkampfangriff. Richtet +5...30 Punkt[e] Schaden an und wirft zu Boden, falls der Gegner sich bewegt.'],
333=>['Ich werde Euch rächen!','Schrei. Für jeden toten Verbündeten erhaltet Ihr 10 Sekunden lang eine Lebenspunktregeneration von +3...7 und Eure Angriffsgeschwindigkeit erhöht sich um 25%.','Schrei. Ihr habt +3...7 Lebenspunktregeneration und greift um 25% schneller an (10 Sekunden pro totem Verbündetem).'],
334=>['Harkenaxt','Axtangriff. Wenn dieser Angriff einen Gegner trifft, der an einer tiefen Wunde leidet, fügt Ihr 4...16 Punkt[e] zusätzlichen Schaden zu und dieser Gegner erleidet 15 Sekunden lang eine Verkrüppelung.','Axtangriff. Richtet +4...16 Punkt[e] Schaden an und verursacht Zustand Verkrüppelung (15 Sekunden), falls Gegner eine Tiefe Wunde hat.'],
335=>['Spalten','Elite-Axtangriff. Beim Zuschlagen mit diesem Angriff verursacht Ihr +10...40 Schaden und trefft 1...2 benachbarte Gegner mit 10...40 Hiebschaden.','Elite-Axtangriff. Verursacht +10...40 Schaden und trifft 1...2 benachbarte Gegner mit 10...40 Hiebschaden.'],
336=>['Henkerschlag','Axtangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr 15...45 Punkt[e] zusätzlichen Schaden zu.','Axtangriff. Richtet +15...45 Punkt[e] Schaden an.'],
337=>['Zerstückeln','Axtangriff. Wenn dieser Axtschlag trifft, fügt er dem Gegner eine Tiefe Wunde zu, die seine maximalen Lebenspunkte 5...20 Sekunde[n] lang um 20% verringert.','Axtangriff. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]).'],
338=>['Ausweiden','Elite-Axtangriff. Wenn Ausweiden trifft, fügt Ihr 10...45 Punkt[e] zusätzlichen Schaden und eine Tiefe Wunde zu. Dadurch werden die maximalen Lebenspunkte Eures Ziels 5...20 Sekunde[n] lang um 20% verringert.','Elite-Axtangriff. Richtet +10...45 Punkt[e] Schaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]).'],
339=>['Durchdringender Schlag','Axtangriff. Wenn dieser Angriff erfolgreich ist, trefft Ihr für 10...25 Punkt[e] zusätzlichen Schaden. Dieser Axtangriff hat eine Rüstungsdurchdringung von 20%.','Axtangriff. Richtet +10...25 Punkt[e] Schaden an. 20% Rüstungsdurchdringung.'],
340=>['Unterbrechender Hieb','Axtangriff. Wenn dieser Angriff erfolgreich ist, unterbricht er die aktuelle Aktion des Ziels. Beruhte diese Aktion auf einer Fertigkeit, wird diese Fertigkeit für weitere 20 Sekunden deaktiviert.','Axtangriff. Unterbricht eine Aktion. Unterbrechungswirkung: Unterbrochene Fertigkeit wird +20 Sekunden lang deaktiviert.'],
341=>['Schneller Hieb','Axtangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +1...20 Punkt[e] Schaden zu. Wird Schneller Hieb geblockt, erleidet Euer Ziel 1...20 Punkt[e] Schaden und erleidet 20 Sekunden lang eine Tiefe Wunde.','Axtangriff. Richtet +1...20 Punkt[e] Schaden an. Richtet 1...20 Punkt[e] Schaden an und verursacht Zustand Tiefe Wunde (20 Sekunden), falls geblockt.'],
342=>['Axtdrehung','Axtangriff. Wenn dieser Angriff einen Gegner trifft, der an einer tiefen Wunde leidet, fügt Ihr 5...25 Punkt[e] mehr Schaden zu und dieser Gegner leidet 20 Sekunden lang unter Schwäche.','Axtangriff. Richtet +5...25 Punkt[e] Schaden an und verursacht Zustand Schwäche (20 Sekunden), falls Gegner eine Tiefe Wunde hat.'],
343=>['Für höhere Gerechtigkeit!','Schrei. 20 Sekunden lang erhaltet Ihr jedes Mal, wenn Ihr Adrenalin bekommt, um 100% mehr.','Schrei. 20 Sekunden: Ihr erhaltet 100% mehr Adrenalin.'],
344=>['Schauer','Haltung. 5 Sekunden lang ist Eure Angriffsrate um 33% erhöht, aber Ihr fügt 25% weniger Schaden zu.','Haltung. 5 Sekunden: Ihr greift um 33% schneller an. Ihr richtet 25% weniger Schaden an.'],
345=>['Verteidigungshaltung','Haltung. 1...5 Sekunde[n] lang habt Ihr eine 75%ige Chance, Nahkampf- und Geschossangriffe zu blocken. Wenn Verteidigungshaltung endet, erhaltet Ihr für jede Nahkampfangriffsfertigkeit, die Ihr besitzt, einen Adrenalinstoß (maximal 0...4).','Haltung. (1...5 Sekunde[n].) Ihr habt eine 75%ige Chance zu blocken. Wirkung am Ende: Ihr erhaltet für jede Nahkampfangriffsfertigkeit, die Ihr besitzt, einen Adrenalinstoß (maximal 0...4).'],
346=>['Raserei','Haltung. Ihr greift 8 Sekunden lang 33 % schneller an, erleidet aber 175...125 % Schaden.','Haltung. (8 Sekunden) Ihr greift 33 % schneller an. Ihr erleidet 175...125 % Schaden.'],
347=>['Schmerz ertragen','Fertigkeit. 7...18 Sekunde[n] lang habt Ihr zusätzlich 90...300 Lebenspunkt[e].','Fertigkeit. 7...18 Sekunde[n]: Ihr habt +90...300 maximale Lebenspunkte.'],
348=>['Passt auf Euch auf!','Schrei. Gruppenmitglieder in Hörweite erhalten 10 Sekunde[n] lang +5...25 Rüstung. Dieser Schrei endet nach 10 Angriff[en].','Schrei. 10 Sekunde[n]: Gruppenmitglieder in Hörweite haben +5...25 Rüstung. Endet nach 10 erhaltenen Angriff[en].'],
349=>['Sprinten','Haltung. 8...14 Sekunde[n] lang bewegt Ihr Euch um 25% schneller als normal.','Haltung. 8...14 Sekunde[n]: Ihr bewegt Euch um 25% schneller.'],
350=>['Bauchklatscher','Hammerangriff. Wenn dieser Angriff einen zu Boden geworfenen Gegner trifft, führt die entstehende Staubwolke bei umstehenden Feinden 3...7 Sekunde[n] lang zu Blindheit.','Hammerangriff. Verursacht bei umstehenden Feinden den Zustand Blindheit (3...7 Sekunde[n]), falls der Gegner zu Boden geworfen wurde.'],
351=>['Mächtiger Schlag','Hammerangriff. Bei einem Treffer fügt dieser Angriff 10...40 Punkt[e] zusätzlichen Schaden zu.','Hammerangriff. Richtet +10...40 Punkt[e] Schaden an.'],
352=>['Vernichtender Schlag','Hammerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr 1...20 Punkt[e] zusätzlichen Schaden zu. Wenn Ihr einen Feind am Boden trefft, fügt Ihr eine Tiefe Wunde zu. Dadurch werden die maximalen Lebenspunkte Eures Ziels 5...20 Sekunde[n] lang um 20% verringert.','Hammerangriff. Richtet +1...20 Punkt[e] Schaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls Gegner zu Boden geworfen ist.'],
353=>['Grober Schwung','Hammerangriff. Greift alle umstehenden Feinde an. Jeder getroffene Gegner erleidet +1...20 Punkt[e] Schaden.','Hammerangriff. Ihr greift alle umstehenden Feinde an und verursacht +1...20 Punkt[e] Schaden.'],
354=>['Erdrüttler','Elite-Hammerangriff. Der Gegner und alle umstehenden Feinde werden zu Boden geworfen. (Bei einer Hammerbeherrschung von 4 oder weniger besteht eine 50%ige Chance für einen Misserfolg.)','Elite-Hammerangriff. Wirft Gegner und umstehende Feinde zu Boden. Mindestens Hammerbeherrschung 5, sonst 50%ige Chance auf Misserfolg.'],
355=>['Verheerender Hammer','Elite-Hammerangriff. Trifft Verheerender Hammer, wird Euer Ziel zu Boden geworfen und leidet 5...20 Sekunde[n] lang unter Schwäche.','Elite-Hammerangriff. Wirft zu Boden. Verursacht Zustand Schwäche (5...20 Sekunde[n]).'],
356=>['Brutaler Schlag','Hammerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Brutaler Schlag geblockt wird, wird Eurer Ziel zu Boden geworfen und erleidet 5...20 Punkt[e] Schaden.','Hammerangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet 5...20 Punkt[e] Schaden an und wirft zu Boden, falls geblockt.'],
357=>['Gegenschlag','Hammerangriff. Trifft dieser Angriff einen angreifenden Gegner, wird dieser Gegner zu Boden geworfen.','Hammerangriff. Wirft den Gegner zu Boden, falls dieser gerade angreift.'],
358=>['Rückenbrecher','Elite-Hammerangriff. Wenn Rückenbrecher trifft, verursacht Ihr 1...20 Punkt[e] Schaden und Euer Ziel wird zu Boden geworfen. Wenn Ihr mindestens 8 Stärke habt, dauert dieser Effekt 4 Sekunden.','Elite-Hammerangriff. Richtet +1...20 Punkt[e] Schaden an. Wirft den Gegner zu Boden. Dieser Effekt wirkt bei Stärke 8 oder höher 4 Sekunden lang.'],
359=>['Heftiger Schlag','Hammerangriff. Alles Adrenalin geht verloren. Trifft dieser Angriff einen Gegner, der unter Schwäche leidet, wird er zu Boden geworfen und Ihr fügt 1...30 Punkt[e] zusätzlichen Schaden zu.','Hammerangriff. Richtet +1...30 Punkt[e] Schaden an und wirft den Gegner zu Boden, falls dieser geschwächt ist. Ihr verliert alles Adrenalin.'],
360=>['Umwerfender Schlag','Hammerangriff. Wenn dieser Hammerschlag trifft, leidet Euer Ziel 5...20 Sekunde[n] lang unter Schwäche.','Hammerangriff. Verursacht Zustand Schwäche (5...20 Sekunde[n]).'],
361=>['Dolyak-Siegel','Siegel. 8...20 Sekunde[n] lang habt Ihr +10...40 Rüstung und könnt nicht zu Boden geworfen werden, aber Eure Bewegungen sind um 75% verlangsamt.','Siegel. 8...20 Sekunde[n]: Ihr habt +10...40 Rüstung und könnt nicht zu Boden geworfen werden. Ihr bewegt Euch um 75% langsamer.'],
362=>['Verschlagenheit des Kriegers','Fertigkeit. 5...11 Sekunde[n] lang ist ein Blocken bei Euren Nahkampfangriffen nicht möglich.','Fertigkeit. 5...11 Sekunde[n]: Eure Nahkampfangriffe können nicht geblockt werden.'],
363=>['Heftiger Schildschlag','Fertigkeit. Die nächsten 5...11 Sekunden wird, solange Ihr ein Schild benutzt, die nächste Nahkampfangriff-Fertigkeit geblockt, die gegen Euch eingesetzt wird, der Angreifer wird niedergeschlagen, und die geblockte Fertigkeit kann 15 Sekunden länger nicht eingesetzt werden.','Fertigkeit. (5...11 Sekunden.) Ihr blockt die nächste Nahkampfangriff-Fertigkeit. Verursacht Niederschlag und +15 Sekunden Wiederaufladung. Kein Effekt, sofern Ihr keinen Schild benutzt.'],
364=>['Angriff!','Elite-Schrei. Alle Verbündeten in Hörweite verlieren den Zustand Verkrüppelung. 5...13 Sekunde[n] lang bewegen sich diese Verbündeten um 33% schneller als normal.','Elite-Schrei. (5...13 Sekunde[n].) Verbündete in Hörweite bewegen sich um 33% schneller. Anfangswirkung: Diese Verbündeten verlieren den Zustand Verkrüppelung.'],
365=>['Der Sieg ist mein!','Elite-Schrei. Ihr erhaltet für jeden Zustand, unter dem der Gegner leidet, 10...68 Lebenspunkt[e] und 3...7 Energiepunkt[e].','Elite-Schrei. Ihr erhaltet für jeden Zustand des Gegners 10...68 Lebenspunkt[e] und 3...7 Energiepunkt[e].'],
366=>['Fürchtet mich!','Schrei. Alle Gegner in der Nähe verlieren 2...6 Energiepunkt[e]. 1...15 Sekunde[n] lang erhöht sich Eure Chance auf kritische Treffer durch Nahkampfangriffe auf stationäre Feinde um +5...30%.','Schrei. (1...15 Sekunde[n].) Eure Chance auf kritische Treffer durch Nahkampfangriffe auf stationäre Feinde erhöht sich um +5...30%. Anfangswirkung: Feinde in der Nähe verlieren 2...6 Energiepunkt[e].'],
367=>['Schilde hoch!','Schrei. 5...11 Sekunde[n] lang erhaltet Ihr und alle Gruppenmitglieder in Hörweite +60 Rüstung gegen Geschosse.','Schrei. 5...11 Sekunde[n]: Gruppenmitglieder in Hörweite haben +60 Rüstung gegen Geschossangriffe.'],
368=>['Ich überlebe!','Schrei. Für jeden Zustand, unter dem Ihr leidet, erfreut Ihr Euch einer zusätzlichen Lebenspunktregeneration von 3. Diese Regeneration endet nach 5...11 Sekunde[n].','Schrei. 5...11 Sekunde[n]: Ihr habt für jeden Zustand auf Euch +3 Lebenspunktregeneration.'],
370=>['Berserkerhaltung','Haltung. Für 8...14 Sekunden greift Ihr um 33 % schneller an und erhaltet 100 % mehr Adrenalin. Die Berserkerhaltung endet, wenn Ihr eine Fertigkeit verwendet.','Haltung. (8...14 Sekunden). Ihr greift um 33 % schneller an und erhaltet 100 % mehr Adrenalin. Endet, wenn Ihr eine Fertigkeit verwendet.'],
371=>['Ausgeglichene Haltung','Haltung. 8...20 Sekunde[n] lang könnt Ihr nicht zu Boden geworfen werden und erleidet keinen zusätzlichen Schaden durch kritische Angriffe.','Haltung. 8...20 Sekunde[n]: Ihr könnt nicht zu Boden geworfen werden und erleidet keinen zusätzlichen Schaden durch kritische Treffer.'],
372=>['Gladiatoren-Verteidigung','Elite-Haltung. 5...11 Sekunde[n] lang habt Ihr eine 75%ige Chance, Angriffe zu blocken. Immer, wenn Ihr einen Nahkampfangriff auf diese Weise blockt, erleidet der Angreifer 5...35 Punkt[e] Schaden.','Elite-Haltung. 5...11 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken. Angreifer erleidet jedes Mal 5...35 Punkt[e] Schaden, wenn Ihr einen Nahkampfangriff auf diese Weise blockt.'],
373=>['Pfeilablenkung','Haltung. 1...6 Sekunde[n] lang habt Ihr eine Chance von 75%, Angriffe zu blocken. Wenn Ihr einen Geschossangriff blockt, leiden umstehende Feinde 5...15 Sekunde[n] lang unter einer Blutung.','Haltung. (1...6 Sekunde[n].) Ihr habt eine 75%ige Chance, Angriffe zu blocken. Wenn Ihr einen Geschossangriff blockt, erleiden umstehende Feinde eine Blutung (5...15 Sekunde[n]).'],
374=>['Ausdauer des Kriegers','Elite-Fertigkeit. 5...35 Sekunde[n] lang erhaltet Ihr 3 Energiepunkte für jeden Treffer den Ihr mit einem Nahkampfangriff erzielt. Ausdauer des Kriegers kann Eure Energiepunkte höchstens auf 10...25 erhöhen.','Elite-Fertigkeit. 5...35 Sekunde[n]: Ihr erhaltet jedes Mal 3 Energiepunkte, wenn Ihr mit einem Nahkampfangriff trefft. Kein Energieerhalt wenn Ihr mehr als 10...25 Energiepunkt[e] habt.'],
375=>['Zwergen-Kampfhaltung','Elite-Haltung. 5...11 Sekunde[n] lang gilt Folgendes, falls Ihr einen Hammer schwingt: Ihr greift um 33% schneller an, Ihr erhaltet +40 Rüstung, und wenn Ihr einen Gegner mit einer Angriffsfertigkeit trefft, wird dessen Aktion unterbrochen.','Elite-Haltung. (5...11 Sekunde[n].) Ihr greift um 33% schneller an, Ihr erhaltet +40 Rüstung und Eure Angriffsfertigkeiten unterbrechen Aktionen. Keine Wirkung, falls Ihr keinen Hammer besitzt.'],
376=>['Disziplinierte Haltung','Haltung. 1...4 Sekunde[n] lang gewinnt Ihr +10 Rüstung und habt eine 75%ige Chance Angriffe zu blocken. Disziplinierte Haltung endet, sobald Ihr eine Adrenalin-Fertigkeit verwendet.','Haltung. (1...4 Sekunde[n].) Ihr habt eine 75% Chance zu blocken und +10 Rüstung. Endet, sobald Ihr eine Adrenalin-Fertigkeit verwendet.'],
377=>['Wachsame Haltung','Haltung. 1...6 Sekunde[n] lang blockt Ihr jede gegen Euch gerichtete Angriffsfertigkeit. Für jedes erfolgreiche Blocken erhaltet Ihr Adrenalin und 5 Energiepunkte. Wachsame Haltung endet, sobald Ihr eine Fertigkeit verwendet.','Haltung. 1...6 Sekunde[n]: Ihr blockt Angriffsfertigkeiten. Für jedes Blocken erhaltet Ihr Adrenalin und 5 Energiepunkte. Endet, sobald Ihr eine Fertigkeit verwendet.'],
378=>['Schildhaltung','Haltung. 1...6 Sekunde[n] lang habt Ihr, solange Ihr einen Schild benutzt, eine 75%ige Chance, Angriffe zu blocken. Für jeden Rang in Stärke wird der erlittene Schaden um 2 Punkte reduziert (maximal 15 Lebenspunkte Schadensreduzierung).','Haltung. (1...6 Sekunde[n].) Ihr habt eine 75%ige Chance zu blocken. Für jeden Rang in Stärke wird der erlittene Schaden um 2 Punkte reduziert (maximal 15 Lebenspunkte Schadensreduzierung). Keine Wirkung, falls Ihr keinen Schild mitführt.'],
379=>['Angriff des Bullen','Elite-Haltung. Für 1...7 Sekunden bewegt Ihr Euch um 50 % schneller. Wenn Ihr im Nahkampf einen sich bewegenden Gegner trefft, wird er niedergeschlagen. Der Angriff des Bullen endet, wenn Ihr eine Fertigkeit verwendet.','Elite-Haltung. (1...7 Sekunden). Ihr bewegt Euch um 50 % schneller. Verursacht Niederschlagen, wenn Ihr einen sich bewegenden Gegner im Nahkampf trefft.Endet, wenn Ihr eine Fertigkeit verwendet.'],
380=>['Bonettis Verteidigung','Haltung. 5...11 Sekunde[n] lang habt Ihr eine 75%ige Chance, Nahkampf- und Geschossangriffe zu blocken. Für jeden erfolgreichen Block eines Nahkampfangriffs erhaltet Ihr 5 Energiepunkte. Bonettis Verteidigung endet, sobald Ihr eine Fertigkeit verwendet.','Haltung. 5...11 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken. Für jeden geblockten Nahkampfangriff erhaltet Ihr 5 Energiepunkte. Endet, sobald Ihr eine Fertigkeit verwendet.'],
381=>['Hundert Klingen','Elite-Fertigkeit. 15 Sekunde[n] lang erleiden alle umstehenden Feinde jedes Mal, wenn Ihr mit einem Schwert angreift, 10...35 Punkt[e] Hiebschaden.','Elite-Fertigkeit. (15 Sekunde[n].) Richtet jedes Mal, wenn Ihr mit einem Schwert angreift, bei allen umstehenden Feinden 10...35 Punkt[e] Hiebschaden an.'],
382=>['Arterienabtrennung','Schwertangriff. Wenn dieser Angriff erfolgreich ist, leidet der Gegner 5...25 Sekunde[n] lang unter einer Blutung und verliert Lebenspunkte über Zeit.','Schwertangriff. Verursacht Zustand Blutung (5...25 Sekunde[n]).'],
383=>['Galrath-Hieb','Schwertangriff. Bei einem Treffer fügt dieser Angriff 1...40 Punkte Schaden zu.','Schwertangriff. Richtet +1...40 Punkt[e] Schaden an.'],
384=>['Schnittwunde','Schwertangriff. Wenn dieser Angriff einen Gegner mit einer Blutung trifft, fügt Ihr 5...20 Punkt[e] zusätzlichen Schaden zu und dieser Gegner erleidet eine Tiefe Wunde, die seine maximalen Lebenspunkte 5...20 Sekunde[n] lang um 20% verringert.','Schwertangriff. Richtet +5...20 Punkt[e] Schaden an und verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls der Gegner blutet.'],
385=>['Endstoß','Schwertangriff. Alles Adrenalin geht verloren. Wenn Endstoß trifft, fügt Ihr 5...40 Punkt[e] mehr Schaden zu. Dieser Schaden wird verdoppelt, wenn die Lebenspunkte Eures Ziels unter 50% lagen.','Schwertangriff. Richtet +5...40 Punkt[e] Schaden an. Richtet zusätzlich +5...40 Punkt[e] Schaden an, falls der Gegner weniger als 50% seiner maximalen Lebenspunkte hat. Ihr verliert alles Adrenalin.'],
386=>['Suchende Klinge','Schwertangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +1...20 Punkt[e] Schaden zu. Wenn Suchende Klinge geblockt wird, blutet das Ziel 25 Sekunden lang und erleidet 1...20 Punkt[e] Schaden.','Schwertangriff. Richtet 1...20 Punkt[e] Schaden an. Richtet 1...20 Punkt[e] Schaden an und verursacht Zustand Blutung (25 Sekunden), falls geblockt.'],
387=>['Entgegnung','Fertigkeit. 8 Sekunden lang blockt Ihr, solange Ihr ein Schwert führt, den nächsten gegen Euch gerichteten Nahkampfangriff und Euer Angreifer wird mit 20...80 Punkt[en] Schaden getroffen.','Fertigkeit. 8 Sekunden: Ihr blockt den nächsten Nahkampfangriff; der Angreifer erleidet 20...80 Punkt[e] Schaden. Keine Wirkung, falls Ihr kein Schwert benutzt.'],
388=>['Tödliche Entgegnung','Fertigkeit. 8 Sekunden lang blockt Ihr, solange Ihr ein Schwert führt, den nächsten gegen Euch gerichteten Nahkampfangriff, Euer Angreifer wird mit 15...90 Punkt[en] Schaden getroffen und blutet 3...25 Sekunde[n] lang.','Fertigkeit. 8 Sekunden: Ihr blockt den nächsten Nahkampfangriff; der Angreifer erleidet 15...90 Punkt[e] Schaden. Verursacht Zustand Blutung (3...25 Sekunde[n]). Keine Wirkung, falls Ihr kein Schwert benutzt.'],
389=>['Blütezeit','Elite-Fertigkeit. Alle Eure Angriffsfertigkeiten werden wieder aufgeladen. Für jede mithilfe von "Blütezeit" wieder aufgeladene Fertigkeit erhaltet Ihr 2...7 Energiepunkt[e].','Elite-Fertigkeit. Lädt Eure Angriffsfertigkeiten wieder auf. Ihr erhaltet für jede wieder aufgeladene Fertigkeit 2...7 Energiepunkt[e].'],
390=>['Wilder Hieb','Schwertangriff. Wenn dieser Angriff erfolgreich ist, unterbricht er die Aktion des Feindes. Wenn es sich dabei um einen Zauber gehandelt hat, verursacht Ihr 1...40 Punkt[e] zusätzlichen Schaden.','Schwertangriff. Unterbricht eine Aktion. Unterbrechungswirkung: Richtet +1...40 Punkt[e] Schaden an, falls die Aktion ein Zauber war.'],
391=>['Jägerschuss','Bogenangriff. Wenn der Jägerschuss trifft, leidet Euer Gegner 3...25 Sekunde[n] lang an einer Blutung.','Bogenangriff. Verursacht Zustand Blutung (3...25 Sekunde[n]).'],
392=>['Festnageln','Bogenangriff. Wenn Festnageln trifft, leidet Euer Ziel 3...15 Sekunde[n] lang an einer Verkrüppelung.','Bogenangriff. Verursacht Zustand Verkrüppelung (3...15 Sekunde[n]).'],
393=>['Verkrüppelungs-Schuss','Elite-Bogenangriff. Wenn Verkrüppelungs-Schuss trifft, leidet Euer Ziel 4...14 Sekunde[n] lang an einer Verkrüppelung. Dieser Angriff kann nicht geblockt werden.','Elite-Bogenangriff. Kann nicht geblockt werden. Verursacht Zustand Verkrüppelung (4...14 Sekunde[n]).'],
394=>['Kraftschuss','Bogenangriff. Wenn Kraftschuss trifft, erleidet der Gegner 25...50 Schaden.','Bogenangriff. Der Gegner erleidet 25...50 Punkt[e] Schaden.'],
395=>['Sperrfeuer','Elite-Bogenangriff. Entfernt alle Eure Vorbereitungen. Schießt Pfeile auf Euren Zielgegner und bis zu 5 um ihn herum stehende Feinde. Bei Treffern verursachen diese Pfeile 5...20 Punkt[e] Schaden.','Elite-Bogenangriff. Verursacht +5...20 Punkt[e] Schaden. Trifft 5 um Euren Zielgegner herum stehende Feinde. Entfernt alle Eure Vorbereitungen.'],
396=>['Doppelschuss','Bogenangriff. Zwei Pfeile werden gleichzeitig auf den Gegner abgefeuert. Diese Pfeile fügen 25% weniger Schaden zu.','Bogenangriff. Ihr feuert zwei Pfeile gleichzeitig auf den Gegner ab. Diese Pfeile richten 25% weniger Schaden an.'],
397=>['Schnellschuss','Elite-Bogenangriff. Schießt einen Pfeil ab, der sich doppelt so schnell bewegt.','Elite-Bogenangriff. Ihr feuert einen Pfeil ab, der mit doppelter Geschwindigkeit fliegt.'],
398=>['Durchbohr-Angriff','Bogenangriff. Wenn "Durchbohr-Angriff" trifft, fügt Ihr fügt Ihr 5...25 Punkt[e] zusätzlichen Schaden zu. Dieser Angriff hat eine Rüstungsdurchdringung von 10%.','Bogenangriff. Richtet +5...25 Punkt[e] Schaden an. 10% Rüstungsdurchdringung.'],
399=>['Ablenk-Schuss','Bogenangriff. Wenn "Ablenk-Schuss" trifft, unterbricht er die Aktion des Gegners, fügt aber nur 1...16 Punkt[e] Schaden zu. Beruhte die unterbrochene Aktion auf einer Fertigkeit, wird diese Fertigkeit für weitere 20 Sekunden deaktiviert.','Bogenangriff. Unterbricht eine Aktion. Unterbrechungswirkung: Unterbrochene Fertigeit wird +20 Sekunde[n] lang deaktiviert. Treffer richten nur 1...16 Punkt[e] Schaden an.'],
400=>['Präzisionsschuss','Bogenangriff. Wenn Präzisionsschuss trifft, fügt Ihr +3...10 Punkt[e] Schaden zu. Bei Präzisionsschuss ist ein Blocken nicht möglich. Diese Aktion kann leicht unterbrochen werden.','Bogenangriff. Richtet +3...10 Punkt[e] Schaden an. Kann nicht geblockt werden. Leicht zu unterbrechen.'],
402=>['Entschlossener Schuss','Bogenangriff. Wenn "Entschlossener Schuss" trifft, fügt Ihr 5...20 Punkt[e] zusätzlichen Schaden zu. Wenn dieser Angriff fehlschlägt, werden alle Eure Angriffsfertigkeiten wieder aufgeladen.','Bogenangriff. Richtet +5...20 Punkt[e] Schaden an. Lädt Eure Angriffsfertigkeiten auf, falls der Angriff nicht trifft.'],
403=>['Ankündigungs-Schuss','Bogenangriff. Schießt einen Pfeil ab, der sich dreimal so schnell bewegt und nicht geblockt werden kann.','Bogenangriff. Ihr feuert einen Pfeil ab, der mit dreifacher Geschwindigkeit fliegt. Kann nicht geblockt werden.'],
404=>['Giftpfeil','Elite-Bogenangriff. Wenn Giftpfeil trifft, wird Euer Ziel 5...20 Sekunde[n] lang vergiftet.','Elite-Bogenangriff. Verursacht Zustand Gift (5...20 Sekunde[n]).'],
405=>['Eidschuss','Elite-Bogenangriff. Wenn der Eidschuss trifft, werden alle Fertigkeiten außer Eidschuss wieder aufgeladen. Wenn er verfehlt, werden alle Eure Fertigkeiten 10...4 Sekunden lang deaktiviert. (Bei einer Fachkenntnis von 7 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Elite-Bogenangriff. Lädt bei einem Treffer alle Fertigkeiten außer Eidschuss wieder auf. Deaktiviert alle Fertigkeiten (10...4 Sekunden), falls der Angriff verfehlt. Bei einer Fachkenntnis von 8 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.'],
406=>['Entkräftungs-Schuss','Bogenangriff. Wenn Entkräftungs-Schuss trifft, verliert Euer Ziel 1...10 Energiepunkt[e].','Bogenangriff. Lässt 1...10 Energiepunkt[e] verlieren.'],
407=>['Kurzdistanzschuss','Bogenangriff. Ein Pfeil wird abgeschossen, der nur die halbe Reichweite zurücklegt, aber dafür +10...40 Punkt[e] Schaden zufügt.','Mitteldistanz-Bogenangriff. Richtet +10...40 Punkt[e] Schaden an.'],
408=>['Erschütterungsschuss','Bogenangriff. Trifft Erschütterungsschuss, während der Gegner einen Zauber wirkt, wird dieser Zauber unterbrochen und Euer Ziel leidet 5...20 Sekunde[n] lang an Benommenheit. Dieser Angriff fügt nur 1...16 Punkt[e] Schaden zu.','Bogenangriff. Unterbricht einen Zauber. Unterbrechungswirkung: Verursacht Zustand Benommenheit (5...20 Sekunde[n]). Treffer richten nur 1...16 Punkt[e] Schaden an.'],
409=>['Bestrafungs-Schuss','Elite-Bogenangriff. Trifft "Bestrafungs-Schuss", fügt Ihr +10...20 Punkt[e] Schaden zu und Euer Ziel wird unterbrochen.','Elite-Bogenangriff. Richtet +10...20 Punkt[e] Schaden an. Unterbricht eine Aktion.'],
411=>['Tier zähmen','Fertigkeit. Das Tier wird gezähmt. Einmal gezähmt, reist Euer Tiergefährte mit Euch, wann immer Ihr die Fertigkeit "Tier zähmen" benutzt. Tiere, die mehr als 4 Stufen höher als Ihr stehen, können nicht gezähmt werden.','Fertigkeit. Das Tier wird gezähmt. Einmal gezähmt, reist Euer Tiergefährte mit Euch, wann immer Ihr die Fertigkeit "Tier zähmen" benutzt. Tiere, die mehr als 4 Stufen höher als Ihr stehen, können nicht gezähmt werden.'],
412=>['Ruf des Schutzes','Schrei. 120 Sekunden lang erhält Euer Tiergefährte eine Basisschadens-Reduzierung von 5...20.','Schrei. 120 Sekunden: Euer Tiergefährte hat 5...20 Punkt[e] Schadensreduzierung.'],
415=>['Ruf der Eile','Schrei. 30 Sekunden lang erhöht sich die Angriffsgeschwindigkeit Eures Tiergefährten um 33% und er bewegt sich um 33% schneller.','Schrei. (30 Sekunden.) Bewegung und Angriff Eures Tiergefährten sind 33% schneller.'],
422=>['Tier wiederbeleben','Fertigkeit. Belebt alle verbündeten Tiergefährten im Bereich wieder, und zwar mit 10...94 % Lebenspunkten.','Fertigkeit. Belebt alle verbündeten Tiergefährten im Bereich wieder (10...94 % Lebenspunkte).'],
423=>['Symbiotisches Band','Schrei. 120...300 Sekunde[n] lang erfreut sich Eurer Tiergefährte einer Lebenspunktregeneration von 1...3 und die Hälfte jeglichen Schadens, der Eurem Tiergefährten zugefügt wird, wird auf Euch umgeleitet.','Schrei. 120...300 Sekunde[n]: Euer Tiergefährte hat +1...3 Lebenspunktregeneration. Die Hälfte des Eurem Tiergefährten zugefügten Schadens wird auf Euch umgeleitet.'],
424=>['Dreck werfen','Fertigkeit. Der berührte Gegner und umstehende Feinde werden 3...15 Sekunde[n] lang geblendet.','Berührungs-Fertigkeit. Verursacht Zustand Blindheit (3...15 Sekunde[n]). Betrifft den Gegner und umstehende Feinde.'],
425=>['Abducken','Haltung. 5...11 Sekunde[n] lang bewegt Ihr Euch um 33% schneller und habt eine 27...75%ige Chance, Geschosse zu blocken. Abducken endet, wenn Ihr angreift.','Haltung. 5...11 Sekunde[n]: Ihr bewegt Euch um 33% schneller und habt eine 27...75%ige Chance, Geschossangriffe zu blocken. Endet, sobald Ihr angreift.'],
426=>['Wilder Schuss','Bogenangriff. Trifft Wilder Schuss, wird die Aktion Eures Ziels unterbrochen. Wenn diese Aktion ein Zauber war, fügt Ihr +13...28 Punkt[e] Schaden zu.','Bogenangriff. Unterbricht eine Aktion. Unterbrechungswirkung: Richtet +13...28 Punkt[e] Schaden an, falls die Aktion ein Zauber war.'],
427=>['Gegengift-Siegel','Siegel. Reinigt Euch von Gift, Krankheit, Blindheit und einem weiteren Zustand.','Siegel. Entfernt Gift, Krankheit, Blindheit und einen weiteren Zustand von Euch.'],
428=>['Flammenpfeile','Elite-Bogenangriff. Schießt Pfeile auf den Gegner und bis zu 2 Feinde in seiner Nähe. Diese Feinde werden 1...3 Sekunde[n] lang in Brand gesetzt.','Elite-Bogenangriff. Trifft 2 Feind[e] in der Nähe Eures Gegners und verursacht Brennen (1...3 Sekunde[n]).'],
429=>['Melandrus Pfeile','Elite-Vorbereitung. 18 Sekunden lang verursachen Eure Pfeiltreffer eine Blutung, die 3...25 Sekunde[n] lang anhält und 8...28 Punkt[e] zusätzlichen Schaden anrichtet, sofern das Ziel einer Verzauberung unterliegt.','Elite-Vorbereitung. 18 Sekunden: Eure Pfeile verursachen den Zustand Blutung (3...25 Sekunde[n]) und richten bei verzauberten Feinden +8...28 Punkt[e] Schaden an.'],
430=>['Schützenwette','Elite-Vorbereitung. 18 Sekunde[n] lang erhaltet Ihr für jeden Eurer Pfeiltreffer 5...10 Energiepunkt[e], aber Ihr verliert jedes Mal 10 Energiepunkte, wenn Eure Pfeile ihr Ziel verfehlen.','Elite-Vorbereitung. 18 Sekunde[n]: Ihr erhaltet jedes Mal 5...10 Energiepunkt[e], wenn einer Eurer Pfeile trifft. Ihr verliert bei Fehlschüssen 10 Energiepunkte.'],
431=>['Brandpfeile','Vorbereitung. 24 Sekunden lang explodieren Eure Pfeile beim Aufschlag und fügen dem Gegner und allen umstehenden Feinden 3...18 Punkt[e] Feuerschaden zu.','Vorbereitung. 24 Sekunden: Eure Pfeile richten beim Gegner und umstehenden Feinden 3...18 Punkt[e] Feuerschaden an.'],
432=>['Wind lesen','Vorbereitung. 24 Sekunden lang bewegen sich Eure Pfeile doppelt so schnell wie normal und fügen zusätzlich 3...10 Punkt[e] Schaden zu.','Vorbereitung. 24 Sekunden: +3...10 Punkt[e] Schaden. Eure Pfeile fliegen mit doppelter Geschwindigkeit.'],
433=>['Zündelpfeile','Vorbereitung. 24 Sekunden lang richten Eure Pfeile Feuerschaden an und fügen zusätzlich 3...24 Punkt[e] Feuerschaden zu.','Vorbereitung. 24 Sekunden: +3...24 Punkt[e] Feuerschaden. Eure Pfeile richten Feuerschaden an.'],
434=>['Würgegas','Vorbereitung. 1...12 Sekunde[n] lang richten Eure Pfeile 1...8 Punkt[e] mehr Schaden an und verbreiten beim Aufschlag Würgegas unter allen umstehenden Gegnern. Würgegas unterbricht Gegner beim Wirken von Zaubern.','Vorbereitung. 1...12 Sekunde[n]: +1...8 Punkt[e] Schaden. Verbreitet Würgegas unter umstehenden Feinden um den Gegner. Würgegas unterbricht Zauber.'],
435=>['Gift auftragen','Vorbereitung. 24 Sekunden lang werden Gegner, die von Eurem physischen Angriff getroffen werden, 3...15 Sekunde[n] lang vergiftet.','Vorbereitung. 24 Sekunden: Eure physischen Angriffe verursachen den Zustand Gift (3...15 Sekunde[n]).'],
436=>['Tier erquicken','Fertigkeit. Ihr heilt Euren Tiergefährten um 40...120 Lebenspunkt[e]. Ist Euer Gefährte tot, wird er mit 10...58% der Lebenspunkte wiederbelebt. Wenn Ihr die Fertigkeit \'Tier erquicken\' benutzt, reist Euer Tiergefährte mit Euch.','Fertigkeit. Euer Tiergefährte gewinnt 40...120 Lebenspunkt[e]. Euer Tiergefährte wird wiederbelebt (10...58% Lebenspunkte). Wenn Ihr die Fertigkeit \'Tier erquicken\' benutzt, reist Euer Tiergefährte mit Euch.'],
437=>['Bestiensprung','Tiergefährtenangriff. Euer Tiergefährte führt einen Bestiensprung aus, der 5...20 Punkt[e] zusätzlichen Schaden zufügt. Trifft dieser Angriff einen Gegner, der einen Zauber wirkt, wird er zu Boden geworfen.','Tiergefährtenangriff. Richtet +5...20 Punkt[e] Schaden an. Wirft zu Boden, falls der Gegner einen Zauber wirkt.'],
438=>['Verkrüppelungs-Schlag','Tiergefährtenangriff. Euer Tiergefährte versucht einen Verstümmelnden Schlag, der +5...20 Schaden verursacht. Wenn der Angriff trifft, wird der Gegner für 3...15 Sekunden verkrüppelt.','Tiergefährtenangriff. Verursacht +5...20 Schaden. Fügt bei Treffer den Zustand Verkrüppelt zu (3...15 Sekunden).'],
439=>['Wilder Ausfall','Tiergefährtenangriff. Euer Tiergefährte greift mit einem Wilden Ausfall an, der +5...35 Punkt[e] Schaden zufügt. Trifft dieser Angriff einen angreifenden Gegner, leidet dieser 5...25 Sekunde[n] lang an einer Blutung.','Tiergefährtenangriff. Richtet +5...35 Punkt[e] Schaden an. Verursacht Zustand Blutung (5...25 Sekunde[n]), falls der Gegner gerade angreift.'],
440=>['Aasfresser-Schlag','Tiergefährtenangriff. Euer Tiergefährte greift mit Aasfresser-Schlag an und fügt +10...25 Punkte Schaden zu. Wenn dieser Angriff einen Gegner trifft, der unter einem Zustand leidet, erhaltet Ihr 3...15 Energiepunkt[e].','Tiergefährtenangriff. Richtet +10...25 Punkt[e] Schaden an. Ihr erhaltet 3...15 Energiepunkt[e], falls Gegner einen Zustand hat.'],
441=>['Melandrus Angriff','Tiergefährtenangriff. Euer Tiergefährte greift mit Melandrus Angriff an und fügt allen Feinden in der Nähe +5...20 Punkt[e] Schaden zu.','Tiergefährtenangriff. Richtet bei Feinden in der Nähe +5...20 Punkt[e] Schaden an.'],
442=>['Wilder Schlag','Elite-Tiergefährtenangriff. Euer Tiergefährte greift mit Wilder Schlag an und fügt +13...28 Punkte Schaden zu. Wenn dieser Angriff trifft, erhaltet Ihr Adrenalin und 3...10 Energiepunkt[e].','Elite-Tiergefährtenangriff. Richtet +13...28 Punkt[e] Schaden an. Ihr erhaltet Adrenalin und 3...10 Energiepunkt[e].'],
443=>['Raubtier-Sprung','Tiergefährtenangriff. Euer Tiergefährte greift mit einem Raubtier-Sprung an und fügt +5...35 Punkte Schaden zu. Wenn dieser Angriff trifft, erhält Euer Tiergefährte 5...50 Lebenspunkt[e].','Tiergefährtenangriff. Richtet +5...35 Punkt[e] Schaden an. Euer Tiergefährte erhält 5...50 Lebenspunkt[e], falls dieser Angriff trifft.'],
444=>['Schonungsloser Schlag','Tiergefährtenangriff. Euer Tiergefährte greift mit Schonungsloser Schlag an und fügt +5...35 Punkte Schaden zu. Wenn dieser Angriff einen Gegner trifft, dessen Lebenspunkte unter 50% sind, erleidet er zusätzlich 5...35 Punkt[e] Schaden.','Tiergefährtenangriff. Richtet +5...35 Punkt[e] Schaden an. Richtet zusätzlich +5...35 Punkt[e] Schaden an, falls der Gegner weniger als 50% seiner maximalen Lebenspunkte hat.'],
445=>['Unterbrechender Ausfall','Tiergefährtenangriff. Euer Tiergefährte greift mit Unterbrechender Ausfall an und fügt +1...12 Punkte Schaden zu. Wenn dieser Angriff einen Gegner trifft, der eine Fertigkeit verwendet, wird diese unterbrochen und für weitere 20 Sekunde[n] deaktiviert.','Tiergefährtenangriff. Richtet +1...12 Punkt[e] Schaden an. Unterbricht eine Fertigkeit. Unterbrechungswirkung: Unterbrochene Fertigkeit wird 20 Sekunde[n] lang deaktiviert.'],
446=>['Trollsalbe','Fertigkeit. 13 Sekunden lang erfreut Ihr Euch einer Lebenspunktregeneration von +3...10.','Fertigkeit. 13 Sekunden: Ihr habt +3...10 Lebenspunktregeneration.'],
447=>['Otyughs Schrei','Schrei. 10...25 Sekunde[n] lang erhält Euer Tiergefährte +24 Rüstung und kann nicht geblockt werden.','Schrei. 10...25 Sekunde[n]: Euer Tiergefährte hat +24 Rüstung und seine Angriffe können nicht geblockt werden.'],
448=>['Flucht','Elite-Haltung. 1...8 Sekunde[n] lang bewegt Ihr Euch um 33% schneller und habt eine 75%ige Chance Angriffe zu blocken.','Elite-Haltung. 1...8 Sekunde[n]: Ihr bewegt Euch um 33% schneller und habt eine 75%ige Chance zu blocken.'],
449=>['Geübte Haltung','Elite-Haltung. 20...35 Sekunde[n] lang laden sich Eure Vorbereitungen um 50% schneller auf und halten um 30...300% länger an.','Elite-Haltung. 20...35 Sekunde[n]: Eure Vorbereitungen laden sich um 50% schneller auf und halten um 30...300% länger an.'],
450=>['Wirbelverteidigung','Haltung. 8...20 Sekunde[n] lang habt Ihr eine 75%ige Chance, Angriffe zu blocken. Beim Blocken eines Geschosses auf diese Weise erleiden umstehende Gegner 5...11 Punkt[e] Schaden.','Haltung. 8...20 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken. Richtet jedes Mal 5...11 Punkt[e] Schaden bei umstehenden Feinden an, wenn Ihr einen Geschossangriff blockt.'],
451=>['Melandrus Belastbarkeit','Elite-Haltung. 8...20 Sekunde[n] lang erfreut Ihr Euch für jeden Zustand und jede Verhexung, unter denen Ihr leidet, einer zusätzlichen Lebenspunktregeneration von +4 und einer zusätzlichen Energieregeneration von +1.','Elite-Haltung. 8...20 Sekunde[n]: Ihr habt für jeden Zustand und jede Verhexung auf Euch +4 Lebenspunktregeneration und +1 Energieregeneration.'],
452=>['Dryders Verteidigungen','Haltung. 5...11 Sekunde[n] lang habt Ihr eine 75%ige Chance Angriffe zu blocken und erhaltet 34...60 Rüstung gegen Elementarschaden.','Haltung. 5...11 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken und +34...60 Rüstung gegen Elementarschaden.'],
453=>['Blitzreflexe','Haltung. 5...11 Sekunde[n] lang habt Ihr eine 75%ige Chance, Nahkampf- und Geschossangriffe zu blocken, außerdem ist Eure Angriffsgeschwindigkeit um 33% höher.','Haltung. 5...11 Sekunde[n]: Ihr greift um 33% schneller an und habt eine 75%ige Chance zu blocken.'],
454=>['Wut des Tigers','Haltung. Alle Eure Nicht-Angriffsfertigkeiten werden 5 Sekunden lang deaktiviert. 5...11 Sekunde[n] lang greift Ihr um 25% schneller an.','Haltung. 5...11 Sekunde[n]: Ihr greift um 25% schneller an. Deaktiviert Eure Nicht-Angriffsfertigkeiten (5 Sekunden).'],
455=>['Sturmjäger','Haltung. 8...20 Sekunde[n] bewegt Ihr Euch um 25% schneller und Ihr erhaltet jedes Mal, wenn Ihr Elementarschaden erleidet, 1...5 Energiepunkt[e].','Haltung. 8...20 Sekunde[n]: Ihr bewegt Euch um 25% schneller und gewinnt jedes Mal 1...5 Energiepunkt[e], wenn Ihr Elementarschaden erleidet.'],
456=>['Schlangen-Schnelligkeit','Haltung. 15...30 Sekunde[n] lang ist die Wiederaufladezeit für Eure Fertigkeiten um 33% reduziert. Schlangen-Schnelligkeit endet, wenn Eure Lebenspunkte unter 50% sinken.','Haltung. 15...30 Sekunde[n]: Eure Fertigkeiten laden sich um 33% schneller auf. Endet, wenn Eure Lebenspunkte unter 50% Eurer maximalen Lebenspunkte sinken.'],
457=>['Staubfalle','Falle. Wird Staubfalle aktiviert, fügt sie 5 Sekunden lang allen Gegner in der Nähe 3...8 Sekunde[n] Blindheit und 10...25 Punkt[e] rüstungsignorierenden Erdschaden zu. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden. Staubfalle endet nach 90 Sekunden.','Falle. 90 Sekunden: Betrifft Feinde in der Nähe. Richtet jede Sekunde 10...25 Punkt[e] Schaden an (5 Sekunden). Verursacht jede Sekunde (5 Sekunden) Zustand Blindheit (3...8 Sekunde[n]). Leicht zu unterbrechen.'],
458=>['Stachelfalle','Falle. Wird Stachelfalle aktiviert, erleiden alle Gegner in der Nähe 7...23 Punkt[e] Stichschaden, werden verkrüppelt und leiden 3...25 Sekunde[n] lang unter einer Blutung. Stachelfalle endet nach 90 Sekunden. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunden: Betrifft Feinde in der Nähe. Richtet 7...23 Punkt[e] Stichschaden an. Verursacht Zustände Verkrüppelung und Blutung (3...25 Sekunde[n]). Leicht zu unterbrechen.'],
459=>['Flammenfalle','Falle. Wird Flammenfalle aktiviert, erleiden alle Gegner in der Nähe pro Sekunde (insgesamt 3 Sekunden lang) 5...20 Punkt[e] Flammenschaden und werden 1...3 Sekunde[n] lang in Brand gesetzt. Flammenfalle endet nach 90 Sekunden. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunden: Betrifft Feinde in der Nähe. Richtet jede Sekunde 5...20 Punkt[e] Feuerschaden an (3 Sekunden). Verursacht Zustand Brennen (1...3 Sekunde[n]). Leicht zu unterbrechen.'],
460=>['Heilquelle','Falle. 10 Sekunden lang werden alle umstehenden Verbündeten alle 2 Sekunden um 15...60 Punkt[e] geheilt. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 10 Sekunden: Betrifft umstehende Verbündete. Heilt alle 2 Sekunden um 15...60 Lebenspunkt[e]. Leicht zu unterbrechen.'],
461=>['Dornenfalle','Elite-Falle. Wird Dornenfalle aktiviert, erleiden alle Gegner in der Nähe pro Sekunde (insgesamt 2 Sekunden lang) 10...40 Punkt[e] Stichschaden, werden 3...25 Sekunde[n] lang verkrüppelt und zu Boden geworfen. Dornenfalle endet nach 90 Sekunde[n]. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Elite-Falle. 90 Sekunde[n]: Betrifft Feinde in der Nähe. Diese Falle richtet pro Sekunde (2 Sekunden lang) 10...40 Punkt[e] Stichschaden an, wirft zu Boden und verursacht Zustand Verkrüppelung (3...25 Sekunde[n]). Leicht zu unterbrechen.'],
462=>['Winter','Naturritual. Erstellt einen Geist der Stufe 1...10. Alle Kreaturen in seiner Reichweite erleiden Kälteschaden anstelle von Elementarschaden. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Wandelt Elementarschaden bei allen Kreaturen in Reichweite in Kälteschaden um. Keine Wirkung auf Geister.'],
463=>['Trennung','Naturritual. Erstellt einen Geist der Stufe 1...10. Kreaturen in Reichweite, die keine Geister sind, erleiden, wenn sie physischen Schaden nehmen, 4 Punkte zusätzlichen Schaden. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Erhöht physischen Schaden bei Kreaturen in Reichweite um +4 Punkte. Keine Wirkung auf Geister.'],
464=>['Rand der Auslöschung','Naturritual. Erstellt einen Geist der Stufe 1...10. Wenn eine Kreatur in Reichweite, die kein Geist ist, stirbt, fügt Rand der Auslöschung allen Kreaturen derselben Gattung, deren Lebenspunkte unter 90% liegen und die sich in Reichweite des Geistes befinden, 14...50 Punkt[e] Schaden zu. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Richtet bei Kreaturen in Reichweite jedes Mal 14...50 Punkt[e] Schaden an, wenn eine Kreatur derselben Gattung stirbt. Keine Wirkung auf Geister. Kein Schaden bei Kreaturen, die mehr als 90% ihrer maximalen Lebenspunkte haben.'],
465=>['Großflächenbrand','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10. Alle Kreaturen in seiner Reichweite, die keine Geister sind, erleiden Feuerschaden anstelle von physischem Schaden. Dieser Geist stirbt nach 30...240 Sekunde[n].','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Wandelt physischen Schaden bei allen Kreaturen in Reichweite in Feuerschaden um. Keine Wirkung auf Geister.'],
466=>['Feuersbrunst','Naturritual. Erstellt einen Geist der Stufe 1...10. Alle Pfeiltreffer fügen Kreaturen in seiner Reichweite, die keine Geister sind, Feuerschaden zu. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Für Kreaturen in Reichweite richten alle Pfeile Feuerschaden an. Keine Wirkung auf Geister.'],
467=>['Fruchtbare Jahreszeit','Naturritual. Erstellt einen Geist der Stufe 1...10. Kreaturen in Reichweite, die keine Geister sind, haben +50...150 maximale Lebenspunkte und erhalten +8 Rüstung. Dieser Geist stirbt nach 15...90 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (15...90 Sekunde[n] Lebensdauer). Kreaturen in Reichweite haben +50...150 maximale Lebenspunkte und +8 Rüstung. Keine Wirkung auf Geister.'],
468=>['Symbiose','Naturritual. Erstellt einen Geist der Stufe 1...10. Für jede Verzauberung auf eine Kreatur in Reichweite, die kein Geist ist, hat diese Kreatur +27...150 maximale Lebenspunkte . Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Kreaturen in Reichweite haben für jede Verzauberung auf ihnen +27...150 maximale Lebenspunkte. Keine Wirkung auf Geister.'],
469=>['Urechos','Naturritual. Erstellt einen Geist der Stufe 1...10. Die Verwendung von Siegeln kostet Kreaturen in seiner Reichweite, die keine Geister sind, 10 Energiepunkte. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Siegel kosten Kreaturen in Reichweite 10 Energiepunkte. Keine Wirkung auf Geister.'],
470=>['Jagdsaison','Naturritual. Erstellt einen Geist der Stufe 1...10. Die Heilung aller Kreaturen in seiner Reichweite, die keine Geister sind, ist um 20% reduziert. Wenn Euer Angriff trifft, erhaltet Ihr 5 Lebenspunkte. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Verringert die Wirkung von Heilungen bei Kreaturen in Reichweite um 20%. Kreaturen erhalten für jeden Treffer, den sie mit einem Angriff landen, 5 Lebenspunkte. Keine Wirkung auf Geister.'],
471=>['Eisboden','Naturritual. Erstellt einen Geist der Stufe 1...10. Kreaturen in seiner Reichweite, die keine Geister sind, können keine Wiederbelebungsfertigkeiten aktivieren. Dieser Geist stirbt nach 30...180 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Kreaturen in Reichweite können keine Wiederbelebungsfertigkeiten aktivieren. Keine Wirkung auf Geister.'],
472=>['Günstige Winde','Naturritual. Erstellt einen Geist der Stufe 1...10. Für Kreaturen in seiner Reichweite, die keine Geister sind, bewegen sich Pfeile doppelt so schnell und fügen +6 Punkte Schaden zu. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Bei Kreaturen in Reichweite fliegen Pfeile mit doppelter Geschwindigkeit und richten bei Treffern +6 Punkte Schaden an. Keine Wirkung auf Geister.'],
474=>['Treibwind','Naturritual. Erstellt einen Geist der Stufe 15. Für Kreaturen in seiner Reichweite, die keine Geister sind, kosten alle Fertigkeiten 15 Energiepunkte weniger (minimale Kosten von 10 Energiepunkten) und die Wiederaufladezeit ist um 25% langsamer. Dieser Geist stirbt nach 1...60 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...6 (1...60 Sekunde[n] Lebensdauer). Fertigkeiten kosten Kreaturen in Reichweite 15 Energiepunkte weniger (Mindestkosten 10 Energiepunkte) und laden sich um 25% langsamer auf. Keine Wirkung auf Geister.'],
475=>['Beschleunigender Zephyr','Naturritual. Erstellt einen Geist der Stufe 1...10. Für Kreaturen in seiner Reichweite, die keine Geister sind, werden alle Fertigkeiten doppelt so schnell wieder aufgeladen und benötigen 30% mehr Basisenergie beim Wirken. Dieser Geist stirbt nach 15...90 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (15...90 Sekunde[n] Lebensdauer). Fertigkeiten kosten Kreaturen in Reichweite 30% Energiepunkte mehr und laden sich doppelt so schnell auf. Keine Wirkung auf Geister.'],
476=>['Erneuerung der Natur','Naturritual. Erstellt einen Geist der Stufe 1...10. 30...240 Sekunde[n] lang dauert das Wirken von Verzauberungen und Verhexungen durch Kreaturen, die keine Geister sind, doppelt so lange und das Aufrechterhalten von Verzauberungen benötigt doppelt so viel Energie. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Die Wirkzeit von Verzauberungen und Verhexungen wird bei Kreaturen in Reichweite verdoppelt und es kostet doppelt so viele Energiepunkte, Verzauberungen aufrechtzuerhalten. Keine Wirkung auf Geister.'],
477=>['Schlammiges Terrain','Naturritual. Erstellt einen Geist der Stufe 1...10. Kreaturen in seiner Reichweite, die keine Geister sind, bewegen sich um 10% langsamer und Geschwindigkeitsschübe bleiben wirkungslos. Dieser Geist stirbt nach 30...180 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Kreaturen in Reichweite bewegen sich um 10% langsamer; Geschwindigkeitsschübe bleiben wirkungslos. Keine Wirkung auf Geister.'],
570=>['Zeichen der Unsicherheit','Elite-Verhexung. 5...25 Sekunden lang erleidet der Zielgegner, -1...5 Lebenspunktdegeneration, und Verzauberungen und Haltungen auf diesem Gegner vergehen 20...60 % schneller. Eure Nicht-Assassinen-Fertigkeiten sind 5 Sekunden lang deaktiviert.','Elite-Verhexung. (5...25 Sekunden). Bewirkt -1...5 Lebenspunktdegeneration. Verzauberungen und Haltungen laufen beim anvisierten Gegner um 20...60 % schneller ab. Deaktiviert Eure Nicht-Assassinen-Fertigkeiten (5 Sekunden).'],
571=>['Unterbrechender Dolch','Zauber. Ein Unterbrechender Dolch fliegt auf den Gegner zu und fügt 10...35 Punkt[e] Erdschaden zu. Wenn dieser Gegner eine Fertigkeit aktiviert hat, wird diese unterbrochen. Dieser Zauber hat nur die halbe Reichweite.','Mitteldistanz-Zauber. Geschoss: Richtet 10...35 Punkt[e] Erdschaden an. Unterbricht eine Fertigkeit.'],
572=>['Tödliches Paradoxon','Haltung. Alle Eure Angriffsfertigkeiten werden 10 Sekunde[n] lang deaktiviert. 5...15 Sekunde[n] lang werden Eure Assassinen-Fertigkeiten um 33% schneller aktiviert und aufgeladen.','Haltung. 5...15 Sekunde[n]: Eure Assassinen-Fertigkeiten werden um 33% schneller aktiviert und aufgeladen. Deaktiviert Eure Angriffsfertigkeiten (10 Sekunde[n]).'],
763=>['Neidvoller Blick','Verzauberung. Entfernt eine Verzauberung vom Gegner. Beim Entfernen einer Verzauberung wird 1...20 Sekunde[n] lang Eure nächste Verzauberung 0...1 Sekunde[n] schneller gewirkt und kostet 1...10 Energiepunkt[e] weniger.','Verzauberung. Entfernt eine Verzauberung vom Gegner. Entfernungseffekt: Eure nächste Verzauberung wird 0...1 Sekunde[n] schneller gewirkt und kostet 1...10 Energiepunkt[e] weniger. (1...20 Sekunde[n].)'],
764=>['Schicksalsklage','Elite-Verhexung. 2...6 Sekunde[n] lang werden alle Attribute des Gegners auf 0 gesetzt.','Elite-Verhexung. 2...6 Sekunde[n]: Attribute des Gegners sind 0.'],
766=>['Verächtlicher Blick','Zauber. Wenn der Gegner mehr als 50% seiner Lebenspunkte hat, verliert er alle Verzauberungen.','Zauber. Entfernt Verzauberungen des Gegners. Gegner muss mehr als 50% seiner maximalen Lebenspunkte haben, sonst keine Wirkung.'],
769=>['Verteidigung der Viper','Zauber. Alle umstehenden Feinde leiden 5...20 Sekunde[n] lang an Vergiftung. Schattenschritt zu einer Position in der Nähe, weg vom Gegner.','Zauber. Verursacht Zustand Gift (5...20 Sekunde[n]) bei allen umstehenden Feinden und Ihr unternehmt einen Schattenschritt an eine nahegelegene Position, direkt weg vom Gegner.'],
770=>['Rückkehr','Zauber. Alle umstehenden Gegner werden 3...8 Sekunde[n] lang verkrüppelt. Unternehmt Schattenschritt zur Position des ausgewählten Verbündeten.','Zauber. Verursacht bei allen umstehenden Feinden um Euch Zustand Verkrüppelung (3...8 Sekunde[n]). Ihr unternehmt einen Schattenschritt zur Position des Verbündeten. Sich selbst als Ziel wählen nicht möglich.'],
771=>['Aura der Verschiebung','Elite-Verzauberung. Wenn Ihr Aura der Verschiebung wirkt, macht Ihr einen Schattenschritt zum anvisierten Gegner. Wenn Ihr Aura der Verschiebung nicht länger aufrechterhaltet, kehrt Ihr an Euren ursprünglichen Ort zurück.','Elite-Verzauberung. Unternehmt einen Schattenschritt zum Gegner. Wirkung am Ende: Ihr kehrt zur anfänglichen Position zurück.'],
772=>['Großzügig war Tsungrai','Gegenstandszauber. Haltet Tsungrais Asche bis zu 15...60 Sekunde[n] lang und erhaltet +50...140 Punkt[e] maximale Lebenspunkte. Wenn Ihr seine Asche fallen lasst, erhaltet Ihr 100...280 Lebenspunkt[e].','Gegenstandszauber. 15...60 Sekunde[n]: Ihr habt +50...140 maximale Lebenspunkte. Fallwirkung: Ihr erhaltet 100...280 Lebenspunkt[e].'],
773=>['Mächtig war Vorizun','Gegenstandszauber. Haltet Vorizuns Asche bis zu 15...60 Sekunde[n] lang. Während Ihr seine Asche haltet, erhaltet Ihr +15 Rüstung und +30 Punkte maximale Energie.','Gegenstandszauber. 15...60 Sekunde[n]: Ihr habt +15 Rüstung und +30 maximale Energiepunkte.'],
775=>['Todesblüte','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn Todesblüte erfolgreich ist, erleidet der Gegner +20...45 Punkt[e] Schaden und alle umstehenden Feinde 20...45 Punkt[e] Schaden.','Doppelangriff. Richtet beim Gegner +20...45 Punkt[e] und bei umstehenden Feinden 20...45 Punkt[e] Schaden an. Muss einem Begleithandangriff folgen.'],
776=>['Schlangenzähne','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn Schlangenzähne erfolgreich ist, fügt dieser Angriff +10...20 Punkt[e] Schaden zu und getroffene Feinde leiden 5...20 Sekunde[n] lang unter Blutung und Tiefer Wunde.','Doppelangriff. Richtet +10...20 Punkt[e] Schaden an. Verursacht Zustände Blutung und Tiefe Wunde (5...20 Sekunde[n]). Muss einem Begleithandangriff folgen.'],
777=>['Hörner des Ochsen','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn Hörner des Ochsen erfolgreich ist, fügt dieser Angriff +1...11 Punkt[e] Schaden zu. Falls keine Verbündeten um den getroffenen Feind herumstehen, wird der Feind zu Boden geworfen.','Doppelangriff. Richtet +1...11 Punkt[e] Schaden an. Wirft zu Boden, falls kein Verbündeter des Gegners um ihn herumsteht. Muss einem Begleithandangriff folgen.'],
778=>['Fallende Spinne','Begleithandangriff. Muss einen zu Boden geworfenen Feind treffen. Wenn Fallende Spinne trifft, fügt dieser Angriff +15...35 Punkt[e] Schaden zu und der Feind wird 5...20 Sekunde[n] lang vergiftet.','Begleithandangriff. Richtet +15...35 Punkt[e] Schaden an. Verursacht Zustand Gift (5...20 Sekunde[n]). Gegner muss zu Boden geworfen sein, sonst keine Wirkung.'],
779=>['Schwarzer Lotus-Stoß','Leithandangriff. Wenn Schwarzer Lotus-Stoß erfolgreich ist, fügt er +10...31 Punkt[e] Schaden zu. Wenn der Gegner unter einer Verhexung leidet, erhaltet Ihr 5...13 Energiepunkt[e].','Leithandangriff. Richtet +10...31 Punkt[e] Schaden an. Ihr erhaltet 5...13 Energiepunkt[e], falls Gegner verhext ist.'],
780=>['Reißzähne des Fuchses','Begleithandangriff. Muss einem Leithandangriff folgen. Reißzähne des Fuchses kann nicht geblockt werden und fügt bei einem Treffer +10...35 Punkt[e] Schaden zu.','Begleithandangriff. Richtet +10...35 Punkt[e] Schaden an. Kann nicht geblockt werden. Muss einem Leithandangriff folgen.'],
781=>['Möbiusstoß','Elite-Begleithandangriff. Muss einem Doppelangriff folgen. Wenn Möbiusstoß erfolgreich ist, fügt dieser Angriff +10...35 Punkt[e] Schaden zu. Falls Ihr einen Feind trefft, dessen Lebenspunkte unter 50% sind, werden alle Eure anderen Angriffsfertigkeiten wieder aufgeladen.','Elite-Begleithandangriff. Richtet +10...35 Punkt[e] Schaden an. Lädt Eure anderen Angriffsfertigkeiten auf, falls der Gegner weniger als 50% seiner maximalen Lebenspunkte hat. Muss einem Doppelangriff folgen.'],
782=>['Gezackter Stoß','Leithandangriff. Wenn Gezackter Stoß erfolgreich ist, leidet Euer Ziel 5...20 Sekunde[n] lang unter einer Blutung.','Leithandangriff. Verursacht Zustand Blutung (5...20 Sekunde[n]).'],
783=>['Unvermuteter Stoß','Leithandangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +19...31 Punkt[e] Schaden zu. Falls die Lebenspunkte Eures Ziels höher als 90% sind, fügt Ihr zusätzlich 15...75 Punkt[e] Schaden zu.','Leithandangriff. Richtet +19...31 Punkt[e] Schaden an. Richtet zusätzlich 15...75 Punkt[e] Schaden an, falls der Gegner mehr als 90% seiner maximalen Lebenspunkte hat.'],
784=>['Schlingnatter','Zauber. Schlingnatter muss einem Leithandangriff folgen. Der Gegner wird zu Boden geworfen und leidet 5...20 Sekunde[n] lang unter Vergiftung.','Zauber. Wirft zu Boden. Verursacht Zustand Gift (5...20 Sekunde[n]). Muss einem Leithandangriff folgen.'],
785=>['Zeichen des Todes','Verhexung. 4...10 Sekunde[n] lang erfährt der Gegner um 50% weniger Heilung.','Verhexung. 4...10 Sekunde[n]: Verringert die Wirkung von Heilungen beim Gegner um 50%.'],
786=>['Eiserne Handfläche','Fertigkeit. Der berührte Gegner erleidet 5...50 Punkt[e] Schaden und wird zu Boden geworfen, wenn er unter einer Verhexung oder einem Zustand leidet. Eiserne Handfläche zählt als Leithandangriff.','Berührungs-Fertigkeit. Richtet 5...50 Punkt[e] Schaden an. Wirft den Gegner zu Boden, falls er verhext ist oder einen Zustand hat. Zählt als Leithandangriff.'],
787=>['Unverwüstliche Waffe','Waffenzauber. 3...12 Sekunde[n] lang bekommt der Verbündete (bzw. Ihr selbst) eine Unverwüstliche Waffe. Während er unter einer Verhexung oder einem Zustand leidet, erhält er eine Lebenspunktregeneration von +1...6 und +24 Rüstung.','Waffenzauber. 3...12 Sekunde[n]: +1...6 Lebenspunktregeneration und +24 Rüstung. Der Verbündete (bzw. Ihr selbst) muss verhext sein oder einen Zustand haben, sonst keine Wirkung.'],
788=>['Blind war Mingson','Gegenstandszauber. Haltet Mingsons Asche bis zu 15...60 Sekunde[n] lang. Wenn Ihr seine Asche fallen lasst, werden alle Feinde in der Nähe 3...8 Sekunde[n] lang geblendet.','Gegenstandszauber. 15...60 Sekunde[n]: Fallwirkung: Verursacht bei allen Feinden in der Nähe Zustand Blindheit (3...8 Sekunde[n]).'],
789=>['Erfassend war Kuurong','Elite-Gegenstandszauber. Ihr haltet Kuurongs Asche bis zu 15...60 Sekunden lang empor. Wenn Ihr sie fallen lasst, erleiden alle Gegner im Bereich 15...75 Schaden, und sie werden niedergeschlagen.','Elite-Gegenstandszauber. (15...60 Sekunden.) Abwerfen-Effekt: Fügt allen Gegnern im Bereich 15...75 Schaden zu und schlägt sie nieder.'],
790=>['Nachtragend war Khanhei','Elite-Gegenstandszauber. Haltet Khanheis Asche bis zu 5...11 Sekunde[n] lang. Jedes Mal, wenn ein Feind Euch im Kampf trifft, während Ihr Khanheis Asche haltet, entzieht Ihr diesem Feind 10...45 Lebenspunkt[e].','Elite-Gegenstandszauber. 5...11 Sekunde[n]: Ihr entzieht jedem Feind, der Euch mit einem Angriff trifft, 10...45 Lebenspunkt[e].'],
791=>['Fleisch von meinem Fleisch','Zauber. Verliert die Hälfte Eurer Lebenspunkte. Belebt das Gruppenmitglied mit Euren aktuellen Lebenspunkten und 5...20% der Energiepunkte wieder.','Zauber. Das Gruppenmitglied wird wiederbelebt (Hälfte Eurer aktuellen Lebenspunkte, 5...20% Energiepunkte). Ihr verliert die Hälfte Eurer Lebenspunkte.'],
792=>['Splitterwaffe','Waffenzauber. Ein verbündetes Ziel erhält für eine Dauer von 20 Sekunde[n] eine Splitterwaffe. Die nächsten 1...5 Angriffe des Verbündeten (bzw. Eure eigenen) fügen bis zu 4 umstehenden Feinden 5...50 Punkt[e] Schaden zu.','Waffenzauber. 20 Sekunde[n]: Angriffe richten bei 3 umstehenden Feinden 5...50 Punkt[e] Schaden an. Endet nach 1...5 Angriff[en].'],
793=>['Waffe der Abwehr','Waffenzauber. 3...8 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine Waffe der Abwehr, die ihm eine Lebenspunktregeneration von +2...4 und eine 50%ige Chance zum Blocken gewährt.','Waffenzauber. (3...8 Sekunde[n].) +2...4 Lebenspunktregeneration. 50% Chance zu blocken.'],
794=>['Klagende Waffe','Waffenzauber. 3...14 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine Klagende Waffe. Jedes Mal, wenn diese einen angreifenden Feind trifft, wird dieser unterbrochen.','Waffenzauber. 3...14 Sekunde[n]: Angriffe unterbrechen angreifende Feinde.'],
795=>['Alptraumwaffe','Waffenzauber. Während der nächsten 12 Sekunde[n] hat der Verbündete (bzw. Ihr selbst) eine Alptraumwaffe. Die nächsten 3 Angriffe des Verbündeten (bzw. Eure eigenen) werden um 10...50 Schadenspunkt[e] reduziert und entziehen bis zu 10...50 Lebenspunkt[e].','Waffenzauber. 12 Sekunde[n]: Angriffe des Verbündeten (bzw. von Euch selbst) entziehen 10...50 Lebenspunkt[e], richten aber 10...50 Punkt[e] weniger Schaden an. Endet nach 3 Angriff[en].'],
799=>['Verführerischer Dunst','Elite-Zauber. Ihr unternehmt einen Schattenschritt zum Gegner hin. Dieser leidet 3...9 Sekunde[n] lang unter Benommenheit.','Elite-Zauber. Ihr unternehmt einen Schattenschritt zum Gegner. Verursacht Zustand Benommenheit (3...9 Sekunde[n]).'],
800=>['Dauerhaftes Toxin','Verhexung. 5 Sekunden lang leidet der Gegner unter einer Lebenspunktdegeneration von -1...5. Falls sich der Gegner bewegt, wenn Dauerhaftes Toxin enden sollte, wird es um 5 zusätzliche Sekunden verlängert.','Verhexung. 5 Sekunden: Verursacht -1...5 Lebenspunktdegeneration. Erneuerung: Falls der Gegner sich bewegt, wenn diese Verhexung endet.'],
801=>['Schleier des Schweigens','Elite-Verhexung. Alle Eure Zauber werden 15 Sekunden lang deaktiviert. Der berührte Gegner kann 1...6 Sekunde[n] lang keine Zauber wirken.','Elite-Berührungs-Verhexung. 1...6 Sekunde[n]: Gegner kann keine Zauber wirken. Eure Zauber werden deaktiviert (15 Sekunden).'],
802=>['Verteidigungen aufdecken','Verhexung. 1...11 Sekunde[n] lang kann der Gegner Eure Angriffe nicht blocken.','Verhexung. 1...11 Sekunde[n]: Der Gegner kann Eure Angriffe nicht blocken.'],
803=>['Kraftfresser','Elite-Verhexung. Falls der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird diese Fertigkeit unterbrochen und Ihr entzieht dem Gegner immer, wenn er innerhalb der nächsten 10 Sekunde[n] einen Zauber wirkt, bis zu 5...15 Energiepunkt[e].','Elite-Verhexung. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: Stiehlt 5...15 Energiepunkt[e], wenn der Gegner einen Zauber wirkt (10 Sekunde[n]).'],
804=>['Arkane Schwäche','Elite-Verhexung. 1...10 Sekunden lang führen alle vom Gegner gewirkten Zauber zu 10 Überzaubern.','Elite-Verhexung. (1...10 Sekunden.) Die vom anvisierten Gegner gewirkten Zauber verursachen 10 Überzaubern.'],
805=>['Vampirschreck beleben','Zauber. Der nächste Kadaver wird als Vampirschreck der Stufe 1...17 belebt. Jedes Mal, wenn ein Vampirschreck, den Ihr kontrolliert, Schaden zufügt, erhaltet Ihr dieselbe Menge Lebenspunkte.','Zauber. Erstellt einen Vampirschreck der Stufe 1...17. Ihr erhaltet Lebenspunkte in Höhe des von ihm angerichteten Schadens. Benutzt frischen Kadaver.'],
806=>['Eifer des Sektierers','Elite-Verzauberung. Für 5 Sekunde[n] plus 3 Sekunden pro Rang in Seelensammlung kostet das Wirken Eurer Nekromanten-Zauber 1...6 Energiepunkt[e] weniger, aber Ihr leidet beim Wirken jedes Nekromanten-Zaubers 10 Sekunde[n] lang an einer Blutung.','Elite-Verzauberung. (5 Sekunde[n] plus 3 Sekunden pro Rang in Seelensammlung.) Eure Nekromanten-Zauber kosten 1...6 weniger Energie. Ihr leidet beim Wirken jedes Nekromanten-Zaubers an einer Blutung (10 Sekunde[n]).'],
808=>['Zeichen des Schnitters','Elite-Verhexung. 30 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...5. Wenn er stirbt, während er mit Zeichen des Schnitters verhext ist, erhaltet Ihr 5...15 Energiepunkt[e].','Elite-Verhexung. 30 Sekunde[n]: Verursacht -1...5 Lebenspunktdegeneration. Ihr erhaltet 5...15 Energiepunkt[e], falls der Gegner an dieser Verhexung stirbt.'],
809=>['Trümmerstein','Elite-Verhexung. Der Zielgegner erleidet 25...100 Kälteschaden, bewegt sich 66 % langsamer und ist 3 Sekunden lang mit "Schmetterstein" verhext. Wenn "Schmetterstein" endet, erleiden dieser Gegner und alle Gegner in der Nähe 25...100 Kälteschaden.','Elite-Verhexung. (3 Sekunden.) Anfangseffekt: Verursacht 25...100 Kälteschaden, und Ziel bewegt sich 66 % langsamer. Effekt endet: Fügt dem Ziel und allen Gegnern in der Nähe 25...100 Kälteschaden zu.'],
810=>['Verteidigung des Beschützers','Fertigkeit. 5...11 Sekunde[n] lang haben Euch umstehende Verbündete eine 75%ige Chance, Angriffe zu blocken. Verteidigung des Beschützers endet, wenn Ihr Euch bewegt.','Fertigkeit. 5...11 Sekunde[n]: Euch umstehende Verbündete haben eine 75%ige Chance zu blocken. Endet, wenn Ihr Euch bewegt.'],
811=>['Gemeinsam rennen','Haltung. 5...15 Sekunde[n] lang rennt Ihr und Euer Tiergefährte 25% schneller.','Haltung. 5...15 Sekunde[n]: Ihr und Euer Tiergefährte bewegt Euch um 25% schneller.'],
812=>['Trotzig war Xinrae','Elite-Gegenstandszauber. Haltet Xinraes Asche bis zu 15...60 Sekunde[n] lang. Während Ihr ihre Asche haltet, könnt Ihr durch einen einzelnen Treffer nicht mehr als 20% Eurer maximalen Lebenspunkte verlieren. Wenn Ihr ihre Asche fallen lasst, entzieht Ihr allen Feinden in der Nähe 5...50 Lebenspunkt[e].','Elite-Gegenstandszauber. 15...60 Sekunde[n]: Ihr könnt nicht mehr als 20% Eurer maximalen Lebenspunkte durch einen einzelnen Treffer verlieren. Fallwirkung: Ihr entzieht Feinden in der Nähe 5...50 Lebenspunkt[e].'],
813=>['Lyssas Aura','Elite-Verzauberung. 10 Sekunde[n] lang habt Ihr +0...5 Energieregeneration. Diese Verzauberung wird jedes Mal, wenn Ihr einen Zauber auf einen Feind wirkt, neu aufgetragen.','Elite-Verzauberung. 10 Sekunde[n]: Ihr habt +0...5 Energieregeneration. Erneuerung: Jedes Mal, wenn Ihr einen Zauber auf einen Feind wirkt.'],
814=>['Schattenzuflucht','Verzauberung. 6 Sekunde[n] lang erfreut Ihr Euch einer Lebenspunktregeneration von 5...10. Wenn Schattenzuflucht endet, erhaltet Ihr 40...100 Lebenspunkt[e], wenn Ihr angreift.','Verzauberung. 6 Sekunde[n]: Ihr habt +5...10 Lebenspunktregeneration. Wirkung am Ende: Heilt Euch um 40...100 Lebenspunkt[e], falls Ihr gerade angreift.'],
815=>['Skorpiondraht','Verhexung. Beim nächsten Mal, dass binnen 8...20 Sekunden Ihr und der Zielgegner mehr als 23m voneinander entfernt seid, führt Ihr einen Schattenschritt hin zu diesem Gegner aus, der niedergeschlagen wird. Dieser Zauber hat die halbe normale Reichweite.','Mitteldistanz-Verhexung. (8...20 Sekunden.) Ein Schattenschritt hin zum Zielgegner wird durchgeführt, und dieser Gegner wird niedergeschlagen, wenn er das nächste Mal mehr als 75\' von Euch entfernt ist.'],
816=>['Gespiegelte Haltung','Verhexung. Während der nächsten 10...35 Sekunde[n] nehmt Ihr jedes Mal, wenn der Gegner eine Haltung einnimmt, die gleiche Haltung ein.','Verhexung. 10...35 Sekunde[n]: Ihr nehmt immer die gleiche Haltung ein wie der Gegner.'],
817=>['Zwietracht','Elite-Zauber. Wenn der Gegner unter einem Zustand und den Auswirkungen einer Verhexung oder einer Verzauberung steht, erleidet er 30...110 Punkt[e] Schaden.','Elite-Zauber. Richtet 30...110 Punkt[e] Schaden an. Gegner muss einen Zustand haben und verhext oder verzaubert sein, sonst keine Wirkung.'],
818=>['Brunnen der Müdigkeit','Brunnenzauber. Nutzt die anvisierte Leiche oder opfert 66 % Eurer Lebenspunkte, um für 10...55 Sekunden einen Brunnen der Erschöpfung zu erzeugen. Gegner innerhalb des Brunnens erleiden -1 Energiedegeneration.','Brunnenzauber. (10...55 Sekunden). Gegner in diesem Brunnen haben -1 Energiedegeneration. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
819=>['Vampirgeist','Elite-Verzauberung. Entzieht dem Gegner bis zu 15...60 Lebenspunkt[e]. 10 Sekunde[n] lang habt Ihr +5...10 Lebenspunktregeneration.','Elite-Verzauberung. Entzieht dem Gegner 15...60 Lebenspunkt[e]: Ihr habt +5...10 Lebenspunktdegeneration (10 Sekunde[n]).'],
820=>['Verderbtheit','Elite-Verhexung. Während der nächsten 5...20 Sekunde[n] verlieren immer, wenn der Gegner einen Zauber wirkt, dieser und ein Feind in der Nähe 1...5 Punkt[e] Energie.','Elite-Verhexung. 5...20 Sekunde[n]: Lässt jedes Mal 1...5 Energiepunkt[e] verlieren, wenn der Gegner einen Zauber wirkt. Auch ein Feinde in Eurer Nähe verliert Energie.'],
821=>['Eisadern','Elite-Verhexung. Der Gegner erleidet 10...90 Punkt[e] Kälteschaden. Wenn er innerhalb der nächsten 10...35 Sekunde[n] stirbt, erleiden alle Feinde in der Nähe 20...110 Punkt[e] Kälteschaden.','Elite-Verhexung. 10...35 Sekunde[n]: Richtet bei Feinden in der Nähe 20...110 Punkt[e] Kälteschaden an, wenn der Gegner stirbt. Anfangswirkung: Richtet 10...90 Punkt[e] Kälteschaden an.'],
822=>['Weiche Knie','Elite-Verhexung. 1...16 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...4 und nimmt 5...20 Punkte Schaden, während er in Bewegung ist.','Elite-Verhexung. 1...16 Sekunde[n]: Der Gegner unterliegt einer Lebenspunktdegeneration von -1...4 und nimmt 5...20 Punkte Schaden, während er in Bewegung ist.'],
823=>['Brennende Eile','Verzauberung. 7 Sekunden lang werdet Ihr in Brand gesetzt und bewegt Euch um 30...45% schneller. Wenn Brennende Eile endet, werden alle umstehenden Gegner 3...9 Sekunden lang in Brand gesetzt.','Verzauberung. (7 Sekunden) Ihr bewegt Euch um 30...45% schneller. Ihr beginnt zu brennen (7 Sekunden). Wirkung am Ende: Verursacht Zustand Brennen (3...9 Sekunden bei umstehenden Feinden).'],
824=>['Lavapfeile','Zauber. Lavapfeile fliegen auf bis zu drei Gegner in der Nähe Eures Zieles zu und verursachen bei einem Treffer 20...65 Punkt[e] Feuerschaden.','Zauber. Geschoss: Richtet 20...65 Punkt[e] Feuerschaden an. Bonuswirkung: Schickt Geschosse zu 2 weiteren Feinden in der Nähe des Ziels.'],
825=>['Kohlenbett','Zauber. An der Position des Gegners wird ein Kohlenbett erzeugt. Während der nächsten 5 Sekunden erleiden umstehende Gegner 5...29 Punkte Feuerschaden pro Sekunde. Alle Feinde, die auf dem Kohlenbett zu Boden geworfen werden, werden 3...7 Sekunden lang in Brand gesetzt.','Zauber. Richtet jede Sekunde 5...29 Punkte Feuerschaden an der Position des anvisierten Gegners an (5 Sekunden). Trifft um Euren Zielgegner herum stehende Feinde. Verursacht bei zu Boden geworfenen Gegnern Zustand Brennen (3...7 Sekunden).'],
826=>['Schattenform','Elite-Verzauberung. 5...21 Sekunde[n] lang könnt Ihr nicht zum Ziel von feindlichen Zaubern werden, und Ihr erhaltet eine Schadensreduzierung von 5 Lebenspunkt[en] für jede Assassinen-Verzauberung, die auf Euch liegt. Mit einem einzigen Angriff bzw. einer einzigen Fertigkeit könnt Ihr nicht mehr als 5...25 Punkt[e] Schaden anrichten.','Elite-Verzauberung. (5...21 Sekunde[n].) Ihr könnt nicht zum Ziel von feindlichen Zaubern werden. Ihr erhaltet eine Schadensreduzierung von 5 Lebenspunkt[en] für jede Assassinen-Verzauberung, die auf Euch liegt. Mit einem einzigen Angriff bzw. einer einzigen Fertigkeit könnt Ihr nicht mehr als 5...25 Punkt[e] Schaden anrichten.'],
827=>['Kraft abzapfen','Elite-Verhexung. 5...20 Sekunde[n] lang verursacht der Gegner mit seinen Angriffen -5...50 Schaden und alle Eure Angriffe auf diesen Gegner haben zusätzlich eine 50%ige Wahrscheinlichkeit, kritische Treffer zu sein.','Elite-Verhexung. 5...20 Sekunde[n]: Gegner richtet -5...50 Punkt[e] Angriffsschaden an. Ihr habt bei diesem Gegner +50% zur Chance auf kritische Treffer.'],
828=>['Fauler Gestank','Verhexung. Der Gegner erleidet 10...65 Punkt[e] Kälteschaden. Wenn er an einem Zustand leidet, wird er mit Faulem Gestank verhext und leidet 10 Sekunde[n] lang unter einer Lebenspunktdegeneration von -1...5.','Verhexung. Verursacht -1...5 Lebenspunktdegeneration (10 Sekunde[n]). Anfangswirkung: Richtet 10...65 Punkt[e] Kälteschaden an. Verhexung wird nur auferlegt, wenn der Gegner einen Zustand hat.'],
830=>['Strahl des Urteils','Elite-Zauber. An der aktuellen Position des Gegners wird ein Strahl des Urteils erzeugt. 5 Sekunde[n] erleiden umstehende Feinde um diesen Bereich 10...50 Punkt[e] heiligen Schaden und beginnen für 1...3 Sekunden pro Sekunde zu brennen.','Elite-Zauber. Richtet jede Sekunde 10...50 Punkt[e] heiligen Schaden an und verursacht Brennen (1...3 Sekunde[n]) jede Sekunde (5 Sekunde[n]). Trifft umstehende Feinde um anfängliche Position des Ziels.'],
831=>['Urzorn','Elite-Haltung. 1...9 Sekunden lang greift Ihr 33 % schneller an, und Ihr bewegt Euch 33 % schneller, aber Ihr erleidet 150...125 % Schaden.','Elite-Haltung. (1...9 Sekunden.) Ihr greift 33 % schneller an und bewegt Euch 33 % schneller. Ihr erleidet 150...125 % Schaden.'],
832=>['Fleischgolem beleben','Elite-Zauber. Nutzt die nächstbeste Leiche, um einen Fleischgolem der Stufe 3...25 zu animieren. Der Fleischgolem hinterlässt 1...4 nutzbare Leichen. Ihr könnt immer nur einen Fleischgolem gleichzeitig haben.','Elite-Zauber. Erzeugt einen Fleischgolem der Stufe 3...25, der nach dem Tod 1...4 nutzbare Leichen hinterlässt. Nutzt eine frische Leiche. ihr könnt immer nur einen Fleischgolem gleichzeitig haben.'],
834=>['Rücksichtslose Hast','Verhexung. 6...12 Sekunde[n] lang werden der Gegner und alle umstehenden Feinde mit Rücksichtsloser Hast verhext. Während dieser Zeit greifen sie um 25% schneller an, es besteht jedoch eine 50%ige Chance, dass ihre Angriffe nicht treffen.','Verhexung. Verhext den Gegner und umstehende Feinde (6...12 Sekunde[n]). Die Angriffe der Gegner gehen mit 50%iger Wahrscheinlichkeit daneben, sie greifen jedoch um 25% schneller an.'],
835=>['Blutsbande','Verhexung. 3...12 Sekunde[n] lang werden der Gegner und alle umstehenden Feinde mit Blutsbande verhext. Wenn ein Verbündeter einen dieser Feinde mit einem Angriff trifft, erhält dieser Verbündete 5...20 Lebenspunkt[e]. Wenn einer dieser verhexten Feinde stirbt, werden alle umstehenden Verbündeten für 20...100 Lebenspunkt[e] geheilt.','Verhexung. Verhext den Gegner sowie umstehende Feinde (3...12 Sekunde[n]). Verbündete, die diese Feinde treffen, erhalten 5...20 Lebenspunkt[e]. Wenn einer dieser verhexten Feinde stirbt, werden umstehende Verbündete für 20...100 Lebenspunkt[e] geheilt.'],
836=>['Den Blitz reiten','Elite-Zauber. Der Blitz bringt Euch zum Ziel. Alle umstehenden Feinde werden 1...5 Sekunde[n] lang geblendet. Wenn Euer Ziel ein Gegner ist, erleidet er 10...70 Punkt[e] Blitzschaden. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Elite-Zauber. Richtet 10...70 Punkt[e] Blitzschaden an. 25% Rüstungsdurchdringung. Blendet alle umstehenden Feinde. (1...5 Sekunde[n]). Ihr bewegt Euch sofort zu Eurem Ziel. Das Ziel kann ein Verbündeter sein.'],
837=>['Energiesegen','Elite-Verzauberung. 36...60 Sekunde[n] lang erhöht Energiesegen Eure maximale Gesundheit und die Eures verbündeten Ziels um 1...3 für jeden Punkt Eurer entsprechenden maximalen Energie. Beim Anwenden dieser Verzauberung erhaltet Ihr und Euer Ziel 1...12 Energiepunkt[e]. Ihr erhaltet zudem 1 Energiepunkt pro 2 Punkte, die Ihr in Energiespeicherung habt.','Elite-Verzauberung. (36...60 Sekunde[n].) Eure maximale Gesundheit und die Eures verbündeten Ziels ist für jeden Punkt Eurer maximalen Energie um 1...3 erhöht. Anfangswirkung: Ihr erhaltet beide 1...12 Energiepunkt[e]. Ihr erhaltet +1 Energiepunkt pro 2 Punkte in Energiespeicherung.'],
838=>['Dwaynas Leid','Verzauberung. Während der nächsten 30 Sekunde[n] werden der Verbündete (bzw. Ihr selbst) und alle Verbündeten in der Nähe mit Dwaynas Leid verzaubert. Wenn ein Verbündeter stirbt, während er mit Dwaynas Leid verzaubert ist, wird Eure Gruppe um 5...50 Punkt[e] geheilt.','Verzauberung. Verzaubert Verbündete in der Nähe des Ziels (30 Sekunde[n]). Eure Gruppe wird jedes Mal um 5...50 Lebenspunkt[e] geheilt, wenn einer dieser Verbündeten stirbt.'],
839=>['"Rückzug!"','Schrei. Wenn sich in Hörweite tote Verbündete befinden, bewegt sich Eure Gruppe 5...11 Sekunde[n] lang um 33% schneller.','Schrei. (5...11 Sekunde[n].) Gruppenmitglieder in Hörweite bewegen sich um 33% schneller. Bleibt wirkungslos, wenn sich in Hörweite keine toten Verbündeten befinden.'],
840=>['Vergiftetes Herz','Zauber. Ihr und alle umstehenden Feinde leiden 5...15 Sekunden lang an Vergiftung.','Zauber. Verursacht bei umstehenden Feinden Zustand Gift (5...15 Sekunde[n]). Ihr werdet auch vergiftet.'],
841=>['Stinkender Boden','Zauber. Der Gegner erleidet 15...65 Punkt[e] Kälteschaden. Wenn er am Boden liegt, wird er außerdem 5...20 Sekunde[n] lang vergiftet.','Zauber. Richtet 15...65 Punkt[e] Kälteschaden an. Verursacht Zustand Gift (5...20 Sekunde[n]), falls Gegner zu Boden geworfen ist.'],
842=>['Blitzbogen','Zauber. Der Gegner erleidet 5...40 Punkte Blitzschaden. Wenn Ihr Überzaubert seid, erleidet der Gegner und bis zu zwei andere in der Nähe befindliche Feinde 15...85 Punkte Blitzschaden. Durch Blitzbogen zugefügter Schaden hat eine Rüstungsdurchdringung von 25%.','Zauber. Richtet 5...40 Punkte Blitzschaden an. Verursacht 15...85 Punkte Blitzschaden bei zwei Gegnern in der Nähe, wenn Ihr Überzaubert seid. 25% Rüstungsdurchdringung.'],
843=>['Böe','Elite-Verzauberung. Für 5...11 Sekunden bewegt ihr Euch um 33 % schneller, und der anvisierte Verbündete ebenfalls. Wenn Ihr diesen Zauber wirkt, erleiden alle Gegner um Euch und Euer Ziel herum 15...70 Kälteschaden. Gegner, die von der Böe getroffen werden, während sie angreifen oder sich bewegen, werden niedergeschlagen.','Elite-Verzauberung. (5...11 Sekunden). Ihr und der anvisierte Verbündete bewegt Euch um 33 % schneller. Anfangseffekt: Gegner um Euch und Euer Ziel herum erleiden 15...70 Kälteschaden. Angreifende oder sich bewegende Gegner werden niedergeschlagen.'],
844=>['Aufgeworfene Erde','Zauber. Am Standort des Feindes wird Aufgeworfene Erde erzeugt. In den nächsten 5 Sekunden bewirkt Aufgeworfene Erde pro Sekunde 10...40 Punkt[e] Erdschaden. Jeder Feind, der sich schneller als normal bewegt, wenn er von Aufgeworfene Erde getroffen wird, wird zu Boden geworfen.','Zauber. Richtet 10...40 Punkt[e] Erdschaden pro Sekunde an (5 Sekunden). Trifft Feinde in der Nähe der ursprünglichen Position des Ziels. Wirft Feinde zu Boden, die sich schneller bewegen als normal.'],
845=>['Flüssige Flamme','Zauber. Der Gegner erleidet 7...112 Punkt[e] Feuerschaden. Wenn er angreift oder einen Zauber wirkt, erleiden Feinde in der Nähe ebenfalls 7...112 Punkt[e] Feuerschaden.','Zauber. Richtet 7...112 Punkt[e] Feuerschaden an. Richtet bei Feinden in der Nähe des Gegners 7...112 Punkt[e] Feuerschaden an, falls der Gegner angreift oder zaubert.'],
846=>['Dampf','Zauber. Der Zielgegner erleidet 20...60 Kälteschaden. Wenn der Zielgegner in Flammen steht, blendet Dampf diesen Gegner 5...10 Sekunden lang, und er erleidet zusätzlich 20...60 Feuerschaden.','Zauber. Verursacht 20...60 Kälteschaden und den Zustand "Blindheit" (5...10 Sekunden) sowie 20...60 Feuerschaden, wenn der Zielgegner brennt.'],
847=>['Siegel des Segens','Elite-Siegel. Heilt den Verbündeten (bzw. Euch selbst) um 20...80 Lebenspunkt[e]. Euer nächster auf einen Verbündeten gerichteter Heil- oder Schutzgebet-Zauber heilt zusätzlich um 20...100 Lebenspunkt[e].','Elite-Siegel. Heilt um 20...80. Euer nächster auf einen Verbündeten gerichteter Heil- oder Schutzgebet-Zauber heilt um +20...100 Lebenspunkt[e].'],
848=>['Verhexung umkehren','Verzauberung. Entfernt eine Verhexung vom Verbündeten. Wenn eine Verhexung auf diese Weise entfernt wurde, wird 5...10 Sekunde[n] lang der nächste Schaden, den der Verbündete erleiden würde, um 5...50 Punkt[e] verringert.','Verzauberung. 5...10 Sekunde[n]: Entfernt eine Verhexung vom Verbündeten (bzw. Euch selbst). Der nächste Schaden, den der Verbündete (bzw. Ihr selbst) erleidet, wird um 5...50 Punkt[e] reduziert. Der Verbündete muss verhext sein, sonst keine Wirkung.'],
849=>['Zerfetzender Hieb','Axtangriff. Wenn Zerfetzender Hieb erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Ihr einen Feind am Boden trefft, leidet er 5...20 Sekunde[n] lang unter einer Blutung.','Axtangriff. Richtet +5...20 Punkt[e] Schaden an. Verursacht Zustand Blutung (5...20 Sekunde[n]), falls Gegner zu Boden geworfen ist.'],
850=>['Erbitterter Schlag','Hammerangriff. Wenn Erbitterter Schlag trifft, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn der Gegner an Schwäche leidet, erleidet er außerdem 1...8 Sekunde[n] lang eine Tiefe Wunde.','Hammerangriff. Richtet +5...20 Punkt[e] Schaden an. Verursacht Tiefe Wunde (1...8 Sekunde[n]), falls der Gegner geschwächt ist.'],
851=>['Sonne-Mond-Hieb','Schwertangriff. Ihr greift den Gegner zweimal an. Diese Angriffe können nicht geblockt werden.','Schwertangriff. Ihr greift den Gegner zweimal an. Kann nicht geblockt werden.'],
852=>['Splitterschuss','Bogenangriff. Wenn der Splitterschuss trifft, verursacht Ihr +3...15 Schaden. Wird der Splitterschuss abgeblockt, erleiden alle Gegner im Umkreis Eures Ziels 5...65 Schaden.','Bogenangriff. Verursacht +3...15 Schaden. Fügt Gegnern im Bereich 5...65 Schaden zu, wenn abgeblockt.'],
853=>['Melandrus Schuss','Elite-Bogenangriff. Wenn Melandrus Schuss trifft, leidet Euer Gegner 5...25 Sekunde[n] lang an einer Blutung. Wenn er einen Gegner trifft, der sich bewegt oder zu Boden geworfen wurde, erleidet dieser +10...25 Punkt[e] Schaden und leidet 5...15 Sekunde[n] lang an Verkrüppelung.','Elite-Bogenangriff. Verursacht Blutung (5...25 Sekunde[n]). Richtet +10...25 Punkt[e] Schaden an und verursacht Verkrüppelung (5...15 Sekunde[n]), falls der Gegner sich bewegt oder zu Boden geworfen wurde.'],
854=>['Schlinge','Falle. Wird Schlinge aktiviert, werden alle Gegner in der Nähe 3...15 Sekunde[n] lang verkrüppelt. Schlinge endet nach 90 Sekunden. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunden: Betrifft Feinde in der Nähe. Verursacht Zustand Verkrüppelung (3...15 Sekunde[n]). Leicht zu unterbrechen.'],
858=>['Tanzende Dolche','Zauber. Drei Tanzende Dolche fliegen auf den Gegner zu. Jeder einzelne fügt bei einem Treffer 5...35 Punkt[e] Erdschaden zu. Tanzende Dolche hat nur die halbe Reichweite. Diese Fertigkeit zählt als Leithandangriff','Mitteldistanz-Zauber. Drei Geschosse: Richten je 5...35 Punkt[e] Erdschaden an. Zählt als Leithandangriff.'],
859=>['Alptraum beschwören','Verhexung. 2...16 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -8.','Verhexung. (2...16 Sekunde[n].) Verursacht -8 Lebenspunktdegeneration.'],
860=>['Siegel der Unterbrechung','Siegel. Wenn der Gegner einen Zauber wirkt, wird dieser unterbrochen und der Gegner erleidet 10...51 Punkt[e] Schaden. Ist dieser Gegner verhext, kann Siegel der Unterbrechung beliebige Fertigkeiten unterbrechen, die keine Zauber sind.','Siegel. Unterbricht einen Zauber. Kann eine beliebige Fertigkeit unterbrechen, wenn der Gegner verhext ist. Unterbrechungswirkung: Richtet 10...51 Punkt[e] Schaden an.'],
862=>['Heißhungriger Blick','Elite-Zauber. Fügt dem Gegner und in der Nähe befindlichen Feinden 20...40 Punkt[e] Schaden zu und entzieht diesen 20...40 Lebenspunkt[e].','Elite-Zauber. Fügt dem Gegner und in der Nähe befindlichen Feinden 20...40 Punkt[e] Schaden zu und entzieht diesen 20...40 Lebenspunkt[e].'],
863=>['Orden der Abtrünnigkeit','Elite-Verzauberung. 5 Sekunden lang verliert der Gegner jedes Mal, wenn er von einem Gruppenmitglied mit physischem Schaden getroffen wird, eine Verzauberung. Für jede entfernte Mönch-Verzauberung verliert Ihr 10...3% Eurer maximalen Lebenspunkte.','Elite-Verzauberung. Verzaubert alle Gruppenmitglieder (5 Sekunden). Die Betroffenen entfernen eine Verzauberung, wenn sie physischen Schaden anrichten. Entfernungskosten: Für jede entfernte Mönch-Verzauberung verliert Ihr 10...3% Eurer maximalen Lebenspunkte.'],
864=>['Repressiver Blick','Zauber. Gegner und umstehende Feinde erleiden +10...30 Punkt[e] Schattenschaden. Feinde, die bereits unter einem Zustand leiden, werden 3...12 Sekunde[n] lang vergiftet und geschwächt.','Zauber. Richtet beim Gegner und umstehenden Feinden 10...30 Punkt[e] Schaden an. Verursacht bei unter einem Zustand leidenden Feinden die Zustände Gift und Schwäche (3...12 Sekunde[n]).'],
865=>['Blitzhammer','Zauber. Der Gegner erleidet 10...100 Punkte Blitzschaden und leidet 5...20 Sekunden lang an Beschädigter Rüstung. Blitzhammer hat eine Rüstungsdurchdringung von 25%.','Zauber. Richtet 10...100 Punkte Blitzschaden an. Verursacht Beschädigte Rüstung (5...20 Sekunden). 25% Rüstungsdurchdringung.'],
866=>['Dunstklinge','Zauber. Der Gegner erleidet 15...135 Punkt[e] Kälteschaden. Dunstklinge verursacht nur die halbe Schadensmenge, wenn dieser Gegner mit Verzauberungen belegt ist.','Zauber. Richtet 15...135 Punkt[e] Kälteschaden an. Halber Schaden, falls Gegner verzaubert ist.'],
867=>['Heilendes Licht','Elite-Zauber. Heilt den Verbündeten (bzw. Euch selbst) um 40...120 Lebenspunkt[e]. Wenn Euer Ziel einer Verzauberung unterliegt, erhaltet Ihr 1...3 Energiepunkt[e].','Elite-Zauber. Heilt um 40...120 Lebenspunkt[e]. Ihr erhaltet 1...3 Energiepunkt[e], falls der Verbündete (bzw. Ihr selbst) verzaubert ist.'],
869=>['"Feigling!"','Elite-Schrei. Wenn sich der Gegner bewegt, wird er zu Boden geworfen.','Elite-Schrei. Wirft zu Boden, falls der Gegner sich bewegt.'],
870=>['Pestilenz','Naturritual. Erstellt einen Geist der Stufe 1...10. Wenn eine Kreatur, die kein Geist ist, in seiner Reichweite stirbt, werden alle Zustände, mit denen sie belegt ist, auf alle Kreaturen in dem Bereich verteilt, die bereits an einem Zustand leiden. Dieser Geist stirbt nach 30...180 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Wenn eine Kreatur in Reichweite stirbt, werden die Zustände dieser Kreatur auf alle anderen Kreaturen im Bereich übertragen, die einen Zustand haben. Geister sind nicht betroffen.'],
871=>['Schattengesang','Binderitual. Erstellt einen Geist der Stufe 1...10. Die Angriffe dieses Geistes fügen 5...20 Punkte Schaden zu und führen 1...6 Sekunden lang zu Blindheit. Dieser Geist stirbt nach 30 Sekunden.','Binderitual. Erstellt einen Geist der Stufe 1...10 (30 Sekunden Lebensdauer). Seine Angriffe fügen 5...20 Punkte Schaden zu und verursachen den Zustand Blindheit (1...6 Sekunden).'],
876=>['Siegel der Schatten','Siegel. Der Gegner erleidet 5...35 Punkt[e] Schaden. Wenn Euer Ziel geblendet wurde, erleidet es zusätzlich 15...60 Punkt[e] Schaden.','Siegel. Richtet 5...35 Punkt[e] Schaden an. Richtet zusätzlich 15...60 Punkt[e] Schaden an, falls der Gegner geblendet ist.'],
877=>['Lyssas Ausgleich','Zauber. Der Gegner verliert 1 Verzauberung. Wenn Ihr mehr Verzauberungen als der Gegner habt, hat diese Fertigkeit keine Wirkung.','Zauber. Entfernt beim Gegner eine Verzauberung. Keine Wirkung, falls Ihr mehr Verzauberungen habt als der Gegner.'],
878=>['Visionen des Bedauerns','Elite-Verhexung. 10 Sekunde[n] lang erleiden der Gegner und umstehende Feinde jedes Mal, wenn sie eine Fertigkeit verwenden, 15...45 Punkt[e] Schaden und 5...50 Punkt[e] zusätzlichen Schaden, sofern sie unter keiner weiteren Mesmer-Verhexung leiden.','Elite-Verhexung. Verhext außerdem den Gegner und umstehende Feinde (10 Sekunde[n]). Diese Feinde erleiden 15...45 Punkt[e] Schaden, sobald sie eine Fertigkeit verwenden und 5...50 Punkt[e] zusätzlichen Schaden, wenn sie nicht eine Mesmer- Verhexung erlitten haben.'],
879=>['Illusion der Schmerzen','Verhexung. 8 Sekunden lang unterliegt der Gegner einer Lebenspunktdegeneration von -3...10 und nimmt jede Sekunde 3...10 Punkte Schaden. Wenn Illusion der Schmerzen endet, wird der Gegner für 36...120 Lebenspunkt[e] geheilt.','Verhexung. (8 Sekunden.) Verursacht eine Lebenspunktdegeneration von -3...10 und der Gegner nimmt jede Sekunde 3...10 Punkte Schaden. Wirkung am Ende: Der Gegner wird für 36...120 Punkt[e] geheilt.'],
880=>['Gestohlene Eile','Elite-Verhexung. 1...10 Sekunde[n] lang brauchen der Gegner und alle umstehenden Feinde um 100% länger, um ihre Zauber zu wirken. Das Wirken von Zaubern auf diese Gegner durch Euch oder Eure Verbündeten benötigt um 50% weniger Zeit.','Elite-Verhexung. Verhext außerdem umstehende Feinde (1...10 Sekunde[n]). Verdoppelt die Wirkzeit von Zaubern. Die Wirkzeit von Zaubern, die Ihr oder Eure Verbündeten auf den Gegner wirkt, wird um 50% gesenkt.'],
881=>['Äther-Siegel','Siegel. Wenn Eure Energie unter 5...10 Punkt[en] liegt, erhaltet Ihr 10...20 Energiepunkt[e].','Siegel. Ihr erhaltet 10...20 Energiepunkt[e]. Ihr müsst weniger als 5...10 Energiepunkt[e] haben, sonst keine Wirkung.'],
882=>['Siegel der Entzauberung','Siegel. Ihr verliert Eure gesamte Energie. Der Gegner verliert eine Verzauberung.','Siegel. Entfernt eine Verzauberung. Ihr verliert alle Energiepunkte.'],
883=>['Stimmminderheit','Verhexung. 5...20 Sekunde[n] lang können der Gegner und alle Feinde in der Nähe keine Schreie oder Anfeuerungsrufe verwenden.','Verhexung. Verhext den Gegner und Feinde in der Nähe (5...20 Sekunde[n]). Die Betroffenen können keine Schreie und Anfeuerungsrufe benutzen.'],
884=>['Versengende Flammen','Elite-Zauber. Der Gegner und alle Feinde in der Nähe werden von Versengenden Flammen getroffen. Feinde, die bereits brennen, wenn diese Fertigkeit gewirkt wird, erleiden 10...100 Punkt[e] Feuerschaden. Feinde, die noch nicht in Brand gesetzt sind, brennen 1...7 Sekunde[n] lang.','Elite-Zauber. Trifft Feinde in der Nähe des Ziels. Richtet bei bereits brennenden Feinden 10...100 Punkt[e] Feuerschaden an. Verursacht bei nicht brennenden Feinden Zustand Brennen (1...7 Sekunde[n]).'],
885=>['Schildwächter','Verzauberung. 2...6 Sekunde[n] lang erhalten alle Gruppenmitglieder in Hörweite eine 75%ige Chance, Angriffe zu blocken. Jedes Mal, wenn ein Angriff geblockt wird, werden alle Verbündeten in Hörweite um 10...40 Lebenspunkt[e] geheilt und Schildwächter endet.','Verzauberung. (2...6 Sekunde[n].) Gruppenmitglieder in Hörweite haben eine 75%ige Chance, Angriffe zu blocken. Blockwirkung: Verbündete in Hörweite werden um 10...40 Lebenspunkt[e] geheilt und Schildwächter endet.'],
886=>['Beruhigender Hauch','Verzauberung. 8...18 Sekunde[n] lang erfreut sich der Verbündete (bzw. Ihr selbst) einer Lebenspunktregeneration von +10. Diese Verzauberung endet, wenn der Verbündete angreift oder eine Fertigkeit benutzt.','Verzauberung. 8...18 Sekunde[n]: +10 Lebenspunktregeneration. Endet, wenn der Verbündete (bzw. Ihr selbst) angreift oder eine Fertigkeit benutzt.'],
887=>['Siegel der Verjüngung','Siegel. Heilt Verbündeten (bzw. Euch selbst) um 15...75 Punkt[e] Wenn der Verbündete (bzw. Ihr selbst) einen Zauber wirkt oder angreift, wird er um zusätzlich 15...75 Lebenspunkt[e] geheilt.','Siegel. Heilt um 15...75 Lebenspunkt[e]. Heilt um weitere 15...75 Lebenspunkt[e], falls der Verbündete (bzw. Ihr selbst) gerade einen Zauber wirkt oder angreift.'],
888=>['Wirbelnde Axt','Elite-Axtangriff. Wenn Wirbelnde Axt erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu und jegliche Haltung, die von Eurem Gegner eingenommen wird, endet. Dieser Angriff kann nicht geblockt werden.','Elite-Axtangriff. Richtet +5...20 Punkt[e] Schaden an und entfernt eine Haltung. Kann nicht geblockt werden.'],
889=>['Energischer Schlag','Elite-Hammerangriff. Wenn Energischer Schlag trifft, fügt er +10...30 Punkt[e] Schaden zu und jede Haltung, die der Gegner einsetzt, endet. Der Gegner leidet 5...20 Sekunde[n] lang an Schwäche. Dieser Angriff kann nicht geblockt werden.','Elite-Hammerangriff. Richtet +10...30 Punkt[e] Schaden an. Entfernt jede Haltung des Gegners. Verursacht Zustand Schwäche (5...20 Sekunde[n]). Kann nicht geblockt werden.'],
891=>['"Niemand darf vorbei!"','Schrei. Alle Gegner in der Nähe, die sich bewegen, werden zu Boden geworfen. Diese Fertigkeit wird für jeden zu Boden geworfenen Feind um 1...8 Sekunde[n] schneller wieder aufgeladen (maximal 25 Sekunden).','Schrei. Wirft alle umstehenden Feinde zu Boden, die sich bewegen. Wird für jeden betroffenen Feind um 1...8 Sekunde[n] schneller wieder aufgeladen (maximal 25 Sekunden).'],
892=>['Zitternde Klinge','Elite-Schwertangriff. Wenn Zitternde Klinge erfolgreich ist, fügt Ihr +10...40 Punkt[e] Schaden zu. Wenn dieser Angriff einen sich bewegenden Feind trifft, leidet dieser 10 Sekunde[n] lang an Benommenheit.','Elite-Schwertangriff. Richtet +10...40 Punkt[e] Schaden an. Verursacht Zustand Benommenheit (10 Sekunde[n]), falls der Gegner sich bewegt.'],
893=>['Suchende Pfeile','Vorbereitung. 3...14 Sekunde[n] lang können Eure Pfeile nicht geblockt werden. Suchende Pfeile endet, wenn Ihr nicht trefft.','Vorbereitung. 3...14 Sekunde[n]: Eure Pfeile können nicht geblockt werden. Endet, sobald Ihr nicht trefft.'],
898=>['Überlastung','Verhexung. Für 5 Sekunden erleidet der anvisierte Gegner-1...3 Lebenspunktdegeneration. Wenn er eine Fertigkeit verwendet, erleidet er 15...75 Schaden durch Überlastung, und alle benachbarten Gegner erleiden 75 % dieses Schadens.','Verhexung. (5 Sekunden). Verursacht -1...3 Lebenspunktdegeneration. Wenn der anvisierte Gegner eine Fertigkeit verwendet, erleidet er 15...75 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.'],
899=>['Bilder der Reue','Verhexung. 5...10 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...3. Wenn er mitten im Angriff war, erleidet er 10...52 Punkt[e] Schaden.','Verhexung. 5...10 Sekunde[n]: Verursacht -1...3 Lebenspunktdegeneration. Anfangswirkung: 10...52 Punkt[e] Schaden, falls der Gegner gerade angreift.'],
900=>['Geteilte Bürde','Elite-Verhexung. Der anvisierte Gegner und alle Gegner im Bereich sind für 5...20 Sekunde[n] um 50 % langsamer, wenn sie angreifen, Zauber wirken und sich bewegen.','Elite-Verhexung. Außerdem werden Gegner im Umkreis Eures Ziels verhext (5...20 Sekunde[n]). Ihre Angriffe, gewirkten Zauber und Bewegungen sind um 50 % verlangsamt.'],
901=>['Seelenfessel','Elite-Verhexung. 30 Sekunde[n] lang erleidet der Heiler des Gegners jedes Mal, wenn er den Gegner heilt, 20...80 Punkt[e] Schaden. Diese Verhexung endet, wenn der Gegner mit Peinigungsgebeten belegt ist.','Elite-Verhexung. 30 Sekunde[n]: Der Heiler des Gegners erleidet jedes Mal, wenn er den Gegner heilt, 20...80 Punkt[e] Schaden. Endet, wenn der Gegner mit Peinigungsgebeten belegt ist.'],
902=>['Blut des Aggressoren','Zauber. Entzieht dem Gegner bis zu 5...45 Lebenspunkt[e]. Wenn der Gegner angegriffen hat, leidet er 3...12 Sekunde[n] lang unter Schwäche.','Zauber. Entzieht 5...45 Lebenspunkt[e]. Verursacht Schwäche (3...12 Sekunde[n]), wenn der Gegner angegriffen hat.'],
903=>['Eisprisma','Zauber. Der Gegner erleidet 15...75 Punkte Kälteschaden. Wenn der Gegner unter einer Wassermagie-Verhexung leidet, fügt Eisprisma allen Feinden in der Nähe +15...75 Punkte Kälteschaden zu.','Zauber. Richtet 15...75 Punkte Kälteschaden an. Verursacht 15...75 Punkte Kälteschaden bei allen Feinden in der Nähe, wenn der Gegner unter einer Wassermagie-Verhexung leidet.'],
904=>['Zornige Axt','Axtangriff. Wenn Zornige Axt erfolgreich ist, fügt Ihr +5...35 Punkt[e] Schaden zu. Wenn dieser Angriff geblockt wird, erhaltet Ihr 3 Adrenalinstöße.','Axtangriff. Richtet +5...35 Punkt[e] Schaden an. Ihr erhaltet 3 Adrenalinstöße, falls geblockt.'],
905=>['Günstiger Schlag','Hammerangriff. Wenn Günstiger Schlag trifft, fügt Ihr +5...20 Punkt[e] Schaden zu und erhaltet 3...8 Energiepunkt[e]. Wenn der Gegner unter Schwäche leidet, kann dieser Angriff nicht geblockt werden.','Hammerangriff. Richtet +5...20 Punkt[e] Schaden an. Ihr erhaltet 3...8 Energiepunkt[e]. Kann nicht geblockt werden, wenn der Gegner geschwächt ist.'],
906=>['"Auf Eure Knie!"','Schrei. Alles Adrenalin geht verloren. Wenn ein umstehender Gegner zu Boden geworfen wird, werden alle Eure Haltungen wieder aufgeladen.','Schrei. Lädt alle Eure Haltungen wieder auf, wenn Ihr einen zu Boden geworfenen Feind umsteht. Ihr verliert alles Adrenalin.'],
907=>['Drachenhieb','Elite-Schwertangriff. Wenn Drachenhieb erfolgreich ist, fügt Ihr +10...40 Punkt[e] Schaden zu und erhaltet 1...5 Adrenalinstöße.','Elite-Schwertangriff. Richtet +10...40 Punkt[e] Schaden an. Ihr erhaltet 1...5 Adrenalinstöße, falls Ihr trefft.'],
908=>['Plünderer-Schuss','Bogenangriff. Wenn Plünderer-Schuss erfolgreich ist, fügt Ihr +25...55 Punkt[e] Schaden zu und alle Eure Nichtangriffs-Fertigkeiten werden 5 Sekunde[n] lang deaktiviert.','Bogenangriff. Richtet +25...55 Punkt[e] Schaden an. Eure Nicht-Angriffsfertigkeiten werden deaktiviert (5 Sekunde[n]), falls dieser Angriff trifft.'],
909=>['Scharfschuss','Bogenangriff. This shot moves three times faster, cannot be blocked, and strikes for +10...40 damage but all of your other attack skills are disabled for 8...4 seconds.','Bogenangriff. Deals +10...40 damage. Unblockable. This shot moves three times faster.Your other attack skills are disabled (8...4 seconds).'],
910=>['Geisterriss','Zauber. Öffnet an der Position des Gegners einen Geisterriss. Nach 3 Sekunde[n] erleiden alle umstehenden Feinde 25...125 Punkt[e] Blitzschaden und leiden 1...20 Sekunde[n] lang an Beschädigter Rüstung.','Zauber. Trifft nach 3 Sekunde[n] Feinde in der Nähe der ursprünglichen Position des Gegners. Richtet 25...125 Punkt[e] Blitzschaden an und verursacht Beschädigte Rüstung (1...20 Sekunde[n]).'],
911=>['Vereinigung','Binderitual. Erstellt einen Geist der Stufe 1...12. Jedes Mal, wenn ein Verbündeter in seiner Reichweite, der kein Geist ist, Schaden erleidet oder Lebenspunkte entzogen bekommt, wird dies um 15 Punkt[e] reduziert und der Geist erleidet 15 Punkt[e] Schaden. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...12 (30...60 Sekunde[n] Lebensdauer). Jedes Mal, wenn ein Verbündeter in seiner Reichweite, der kein Geist ist, Schaden erleidet oder Lebenspunkte entzogen bekommt, wird dies um 15 Punkt[e] reduziert und der Geist erleidet 15 Punkt[e] Schaden.'],
913=>['Ruhig war Tanasen','Elite-Gegenstandszauber. Haltet Tanasens Asche bis zu 5...20 Sekunde[n] lang. Während Ihr seine Asche haltet, habt Ihr +10...25 Rüstung und könnt nicht unterbrochen werden.','Elite-Gegenstandszauber. 5...20 Sekunde[n]: Ihr habt +10...25 Rüstung. Ihr könnt nicht unterbrochen werden.'],
914=>['Seele verzehren','Elite-Zauber. Ihr stehlt dem anvisierten Gegner 5...70 Lebenspunkte. Alle feindlichen herbeigerufenen Kreaturen in Hörweite dieses Gegners erleiden 25...125 Schaden.','Elite-Zauber. Stiehlt 5...70 Lebenspunkte. Feindliche herbeigerufene Kreaturen in Hörweite des anvisierten Gegners erleiden 25...125 Schaden.'],
915=>['Geisterlicht','Zauber. Der Verbündete (bzw. Ihr selbst) wird um 60...180 Punkt[e] geheilt. Wenn sich Geister in Hörweite befinden, opfert Ihr keine Lebenspunkte.','Zauber. Heilt um 60...180 Lebenspunkt[e]. Ihr opfert keine Lebenspunkte, falls Ihr Euch in Hörweite von Geistern befindet.'],
916=>['Wehklage','Verhexung. 5...20 Sekunden lang unterliegen der Gegner und alle in der Nähe befindlichen Feinde einer Lebenspunktdegeneration von -0...3. Wenn Ihr Euch beim Wirken dieser Verhexung in Hörweite eines Geistes oder Kadavers befindet, erleiden betroffene Feinde 10...50 Punkt[e] Schaden.','Verhexung. Verhext außerdem den Gegner umstehende Feinde (5...20 Sekunde[n]). Verursacht -0...3 Lebenspunktdegeneration. Anfangswirkung: Verursacht 10...50 Punkt[e] Schaden bei diesen Feinden, wenn Ihr Euch in Hörweite eines Geistes oder Kadavers befindet.'],
917=>['Seele zerreißen','Zauber. Der anvisierte verbündete Geist wird vernichtet. Alle Feinde in dessen Nähe erleiden 50...140 Punkt[e] Blitzschaden und werden 3...12 Sekunde[n] lang geblendet.','Zauber. Vernichtet den verbündeten Geist. Richtet bei Feinden in der Nähe 50...140 Punkt[e] Blitzschaden an und verursacht Zustand Blindheit (3...12 Sekunde[n]).'],
918=>['Geist zu Fleisch','Zauber. Der berührte Geistverbündete wird vernichtet. Alle Verbündeten in der Nähe werden um 30...240 Lebenspunkt[e] geheilt.','Berührungs-Zauber. Vernichtet den berührten verbündeten Geist. Heilt alle Verbündeten in der Nähe um 30...240 Lebenspunkt[e].'],
919=>['Geisterbrand','Zauber. Der Gegner erleidet 5...50 Punkt[e] Blitzschaden. Wenn sich Geister in Hörweite befinden, führt Geisterbrand 1...5 Sekunde[n] lang zu Brennen.','Zauber. Richtet 5...50 Punkt[e] Blitzschaden an. Verursacht Zustand Brennen (1...5 Sekunde[n]), falls Ihr Euch in Hörweite eines Geistes befindet.'],
920=>['Vernichtung','Binderitual. Erstellt einen Geist der Stufe 1...14, der nach 30 Sekunden stirbt. Wenn dieser Geist stirbt, erleiden alle in dem Bereich befindlichen Gegner für jede Sekunde, die der Geist am Leben war, 5...25 Punkt[e] Schaden (maximal 150 Punkte).','Binderitual. Erstellt einen Geist der Stufe 1...14, der nach 30 Sekunden stirbt. Wenn dieser Geist stirbt, erleiden alle in dem Bereich befindlichen Gegner für jede Sekunde, die der Geist am Leben war, 5...25 Punkt[e] Schaden (maximal 150 Punkte).'],
921=>['Missklang','Binderitual. Erstellt einen Geist der Stufe 1...12. Dieser Geist fügt 5...20 Punkt[e] Schaden zu und all jene, die von einem seiner Angriffe getroffen werden, werden unterbrochen. Dieser Geist stirbt nach 10...25 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...12 (10...25 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an und unterbrechen Aktionen.'],
923=>['Entzauberung','Binderitual. Erstellt einen Geist der Stufe 1...12. Dieser Geist fügt 5...20 Punkt[e] Schaden zu und all jene, die von einem seiner Angriffe getroffen werden, verlieren eine Verzauberung. Dieser Geist stirbt nach 10...35 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...12 (10...35 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an und entfernen eine Verzauberung.'],
925=>['Rückruf','Verzauberung. Solange Rückruf aufrecht erhalten wird, passiert nichts. Wenn Rückruf endet, unternehmt Ihr einen Schattenschritt zu dem Verbündeten, den Ihr beim Aktivieren dieser Fertigkeit ausgewählt hattet, und alle Eure Fertigkeiten sind 3 Sekunde[n] lang deaktivert.','Verzauberung. Wirkung am Ende: Unternehmt einen Schattenschritt zum Verbündeten. Sich selbst als Ziel wählen nicht möglich. Deaktiviert am Ende alle Eure Fertigkeiten (3 Sekunde[n]).'],
926=>['Dolche wetzen','Verzauberung. Während der nächsten 5...30 Sekunde[n] führen Eure Dolchangriffe zu einer 5...15 Sekunde[n] langen Blutung.','Verzauberung. (5...30 Sekunde[n].) Eure Dolchangriffe verursachen den Zustand Blutung (5...15 Sekunde[n]).'],
927=>['Schändliche Angst','Verhexung. 10 Sekunde[n] lang bewegt sich der Gegner um 10% schneller als normal. Pro Sekunde, die sich der Gegner bewegt, erleidet er 5...20 Punkt[e] Schaden.','Verhexung. 10 Sekunde[n]: Gegner erleidet jede Sekunde 5...20 Punkt[e] Schaden, wenn er sich bewegt, allerdings bewegt er sich um 10% schneller.'],
928=>['Schattenschleier','Elite-Verhexung. 3...9 Sekunde[n] lang kann der Gegner nicht zum Ziel von Verzauberungen werden.','Elite-Verhexung. 3...9 Sekunde[n]: Der Gegner kann nicht Ziel von Verzauberungen sein.'],
929=>['Schatten der Eile','Haltung. 10...40 Sekunde[n] lang bewegt Ihr Euch um 15% schneller als normal. Wenn Schatten der Eile endet, kehrt Ihr per Schattenschritt zu Eurer ursprünglichen Position zurück.','Haltung. 10...40 Sekunde[n]: Ihr bewegt Euch um 15% schneller. Wirkung am Ende: Ihr kehrt zur anfänglichen Position zurück.'],
930=>['Günstige Beschwörung','Verzauberung. Während der nächsten 20 Sekunde[n] wird der nächste von Euch gewirkte Zauber zusätzlich 10...5 Sekunde[n] lang deaktiviert und Ihr erhaltet 110...200% der Energiekosten dieses Zaubers.','Verzauberung. 20 Sekunde[n]: Ihr erhaltet bei Eurem nächsten Zauber 110...200% der Energiekosten zurück. +10...5 Sekunde[n] zur Aufladezeit des Zaubers.'],
931=>['Kraftrevanche','Zauber. Wenn der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird dieser unterbrochen und der Gegner gewinnt 10...5 Energiepunkt[e].','Zauber. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: Gegner gewinnt 10...5 Energiepunkt[e].'],
932=>['Erschweren','Zauber. Falls der Gegner eine Fertigkeit aktiviert hat, wird diese unterbrochen und zusätzlich bei diesem und allen Feinden im Bereich 5...12 Sekunde[n] lang deaktiviert.','Zauber. Unterbricht eine Fertigkeit. Unterbrechungswirkung: Deaktiviert unterbrochene Fertigkeit (+5...12 Sekunde[n]) beim Gegner und allen Feinden im Bereich.'],
933=>['Sturm zerschlagen','Elite-Zauber. Der Gegner verliert alle Verzauberungen. Für jede Verzauberung, die auf diese Art entfernt wird, wird Sturm zerschlagen zusätzlich 7 Sekunde[n] lang deaktiviert.','Elite-Zauber. Entfernt alle Verzauberungen. Entfernungskosten: Sturm zerschlagen wird für jede entfernte Verzauberung für +7 Sekunde[n] deaktiviert.'],
934=>['Unnatürliches Siegel','Siegel. Der Gegner erleidet 15...75 Punkt[e] Schaden. Unterliegt der Gegner einer Verzauberung oder Verhexung, erleiden umstehende Feinde 5...50 Punkt[e] Schaden.','Siegel. Richtet 15...75 Punkt[e] Schaden an. Richtet bei anderen umstehenden Feinden 5...50 Punkt[e] Schaden an, falls der Gegner verhext oder verzaubert ist.'],
935=>['Hochkommende Galle','Verhexung. 20 Sekunden lang bewirkt diese Verhexung gar nichts. Wenn Hochkommende Galle endet, erleiden der Gegner und alle Feinde in dem Bereich für jede Sekunde, die Hochkommende Galle aktiv war, 1...6 Punkt[e] Schaden.','Verhexung. 20 Sekunden: Wirkung am Ende: Richtet für jede Sekunde, die Hochkommende Galle aktiv war, 1...6 Punkt[e] Schaden an. Schädigt den Gegner und andere Feinde im Bereich.'],
936=>['Verzauberungen vergiften','Zauber. Der Gegner verliert eine Verzauberung. Für jede verbleibende Verzauberung wird der Gegner 3...10 Sekunde[n] lang vergiftet.','Zauber. Entfernt eine Verzauberung vom Gegner. Verursacht Zustand Gift (3...10 Sekunde[n] pro verbleibender Verzauberung auf dem Gegner).'],
937=>['Stoßwelle','Elite-Zauber. Alle Feinde im Bereich erleiden 15...60 Punkt[e] Erdschaden und sind 1...10 Sekunde[n] lang geschwächt. In der Nähe befindliche Feinde erleiden ebenfalls +15...60 Punkt[e] Erdschaden und leiden 1...10 Sekunde[n] lang an Beschädigter Rüstung. Umstehende Feinde, die bereits unter diesen Effekten leiden, erleiden +15...60 Punkt[e] Erdschaden und werden 1...10 Sekunde[n] lang geblendet.','Elite-Zauber. Feinde im Bereich erleiden 15...60 Punkt[e] Erdschaden und leiden unter Schwäche (1...10 Sekunde[n]). In der Nähe befindliche Feinde erleiden ebenfalls +15...60 Punkt[e] Erdschaden und leiden an Beschädigter Rüstung (1...10 Sekunde[n]). Umstehende Feinde erleiden ebenfalls +15...60 Punkt[e] Erdschaden und leiden an Blindheit (1...10 Sekunde[n]).'],
938=>['Kreis der Stabilität','Abwehrzauber. Erstellt an Eurer aktuellen Position einen Kreis der Stabilität. 10...25 Sekunde[n] lang können Verbündete, die keine Geister sind, nicht zu Boden geworfen werden.','Abwehrzauber. (10...25 Sekunde[n].) Verbündete in dieser Abwehr können nicht zu Boden geworfen werden. Verbündete Geister sind nicht betroffen.'],
939=>['Eisfesseln','Elite-Verhexung. 1...10 Sekunde[n] lang ist die Bewegungsgeschwindigkeit des Gegners um 66% reduziert. Wenn er unter den Auswirkungen einer Verzauberung steht, sind die Bewegungen dieses Gegners um 90% reduziert.','Elite-Verhexung. (1...10 Sekunde[n].) Gegner bewegt sich um 66% langsamer. Gegner bewegt sich um 90% langsamer, falls er verzaubert ist.'],
941=>['Gesegnetes Licht','Elite-Zauber. Heilt den Verbündeten (bzw. Euch selbst) um 10...120 Lebenspunkt[e] und entfernt einen Zustand und eine Verhexung.','Elite-Zauber. Heilt um 10...120 Lebenspunkt[e]. Entfernt einen Zustand und eine Verhexung.'],
942=>['Verhexungen zurücknehmen','Elite-Zauber. Entfernt alle Verhexungen vom Zielverbündeten und allen benachbarten Verbündeten. Dieser Zauber braucht 2 Sekunden länger, um aufzuladen, für jede Verhexung, die so entfernt wurde. (50 % Chance auf Fehlschlag, wenn Gunst der Götter 4 oder weniger.)','Elite-Zauber. Entfernt alle Verhexungen. Betrifft auch benachbarte Verbündete Entfernungskosten: +2 Sekunden pro entfernte Verhexung. 50 % Chance auf Fehlschlag, wenn Gunst der Götter nicht mindestens 5 beträgt.'],
943=>['Löschen','Zauber. Entfernt einen Zustand von jedem Gruppenmitglied. Gruppenmitglieder, von denen Brennen entfernt wurde, werden um 10...100 Lebenspunkt[e] geheilt.','Zauber. Wirkt auf die gesamte Gruppe. Entfernt einen Zustand. Gruppenmitglieder, von denen Brennen entfernt wurde, werden um 10...100 Lebenspunkt[e] geheilt.'],
944=>['Siegel der Stärke','Siegel. Eure nächsten 1...16 Angriffe fügen +5 Punkt[e] Schaden zu.','Siegel. Eure Angriffe richten +5 Punkt[e] Schaden an. Endet nach 1...16 Angriff[en].'],
946=>['Fokus des Fallenstellers','Elite-Vorbereitung. 12...36 Sekunde[n] lang können Eure Fallen-Fertigkeiten nicht leicht unterbrochen werden und Euer Attribut Überleben in der Wildnis ist um 0...4 erhöht.','Elite-Vorbereitung. 12...36 Sekunde[n]: Eure Fallen-Fertigkeiten können nicht länger leicht unterbrochen werden. Ihr erhaltet +0...4 bei Eurem Attribut Überleben in der Wildnis.'],
947=>['Dornenranken','Naturritual. Erstellt einen Geist der Stufe 1...10. Kreaturen, die keine Geister sind und in seiner Reichweite zu Boden geworfen werden, erleiden 5 Schadenspunkte und leiden 5...20 Sekunde[n] lang an einer Blutung. Dieser Geist stirbt nach 30...240 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Zu Boden geworfene Kreaturen erleiden 5 Punkte Schaden und beginnen zu bluten (5...20 Sekunde[n]). Keine Wirkung auf Geister.'],
948=>['Verzweifelter Stoß','Leithandangriff. Wenn Ihr weniger als 50...80% Eurer Lebenspunkte habt, fügt Ihr +15...60 Punkt[e] Schaden zu.','Leithandangriff. Richtet +15...60 Punkt[e] Schaden an, falls Ihr weniger als 50...80% Eurer maximalen Lebenspunkte habt.'],
949=>['Weg des Fuchses','Verzauberung. 10...35 Sekunde[n] lang ist ein Blocken bei Euren nächsten 1...6 Angriffen nicht möglich.','Verzauberung. 10...35 Sekunde[n]: Eure Angriffe können nicht geblockt werden. Endet nach 1...6 Angriff[en].'],
950=>['Schattenbürde','Verhexung. 3...15 Sekunde[n] lang bewegt sich der Gegner um 25% langsamer und während er keine anderen Verhexungen hat, hat er 20...30 weniger Rüstung gegen Eure Angriffe.','Verhexung. 3...15 Sekunde[n]: Gegner bewegt sich um 25% langsamer und besitzt -20...30 Rüstung gegen Eure Angriffe. Rüstungsreduzierung betrifft den Gegner nur, solange er keine anderen Verhexungen hat.'],
951=>['Geschwindigkeitsentzug','Verhexung. 5...15 Sekunden lang bewegt sich der Zielgegner 33 % langsamer, und Ihr bewegt Euch 33 % schneller. Dieser Zauber lädt sich 50 % schneller auf, wenn er auf einen Gegner gewirkt wird, der sich bewegt.','Verhexung. (5...15 Sekunden.) Der Zielgegner bewegt sich 33 % langsamer, und Ihr bewegt Euch 33 % schneller. Lädt sich 50 % schneller auf, wenn er auf einen Gegner gewirkt wird, der sich bewegt.'],
952=>['Angriff des Todes','Zauber. Schattenschritt, um den Gegner auszuwählen. Wenn dieser Gegner mehr Lebenspunkte als Ihr hat, werdet Ihr um 65...200 Punkt[e] geheilt.','Zauber. Ihr unternehmt einen Schattenschritt zum Gegner. Ihr werdet um 65...200 Lebenspunkt[e] geheilt, falls der Gegner mehr Lebenspunkte hat als Ihr.'],
953=>['Kraftfluss','Elite-Verhexung. Falls der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird diese Fertigkeit unterbrochen und der Gegner unterliegt 4...10 Sekunde[n] lang einer Energiedegeneration von -2.','Elite-Verhexung. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: -2 Energiepunktdegeneration (4...10 Sekunde[n]).'],
954=>['Verhexungen vertreiben','Elite-Zauber. Entfernt bis zu 2 Verhexungen vom Verbündeten (bzw. Euch selbst).','Elite-Zauber. Entfernt beim Verbündeten (bzw. Euch selbst) 2 Verhexungen.'],
955=>['Verzauberung zerreißen','Zauber. Entfernt 1 Verzauberung[en] vom Gegner. Wenn eine Verzauberung entfernt wurde, leidet er 5...25 Sekunde[n] lang an einer Blutung.','Zauber. Entfernt 1 Verzauberung[en]. Entfernungswirkung: Verursacht Blutung (5...25 Sekunde[n]).'],
957=>['Zauberschild','Verzauberung. 5...20 Sekunde[n] lang könnt Ihr beim Wirken von Zaubern nicht zum Ziel von Zaubern Eurer Gegner werden. Wenn Zauberschild endet, werden alle Eure Fertigkeiten 8...4 Sekunde[n] lang deaktiviert.','Verzauberung. 5...20 Sekunde[n]: Während Ihr Zauber wirkt, könnt Ihr nicht zum Ziel von Zaubern werden. Wirkung am Ende: Eure Fertigkeiten werden deaktiviert (8...4 Sekunde[n]).'],
958=>['Heilendes Geflüster','Zauber. Der Verbündete wird um 40...100 Punkt[e] geheilt. Dieser Zauber hat nur die Hälfte der normalen Reichweite.','Mitteldistanz-Zauber. Heilt um 40...100 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
959=>['Ätherisches Licht','Zauber. Der Verbündete (bzw. Ihr selbst) wird um 25...100 Punkt[e] geheilt. Dieser Zauber kann leicht unterbrochen werden.','Zauber. Heilt um 25...100 Lebenspunkt[e]. Leicht zu unterbrechen.'],
960=>['Verzauberungen freisetzen','Zauber. Alle Verzauberungen gehen verloren. Jedes Gruppenmitglied wird pro verlorene Mönchs-Verzauberung um 5...35 Lebenspunkt[e] geheilt.','Zauber. Entfernt alle Eure Verzauberungen. Heilt alle Gruppenmitglieder für jede entfernte Mönch-Verzauberung um 5...35 Lebenspunkt[e].'],
961=>['Zerfetzen','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10. Blutende Kreaturen in seiner Reichweite erleiden eine Lebenspunktdegeneration von -2. Wenn dieser Geist stirbt, leiden alle Kreaturen in seiner Reichweite, die keine Geister sind, und deren Lebenspunkte unter 90% liegen, 5...25 Sekunde[n] lang an einer Blutung. Dieser Geist stirbt nach 30...240 Sekunde[n].','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunde[n] Lebensdauer). Blutende Kreaturen in Reichweite haben -2 Lebenspunktdegeneration. Wirkung am Ende: Verursacht bei Kreaturen in Reichweite, die weniger als 90% ihrer maximalen Lebenspunkte haben, Zustand Blutung (5...25 Sekunde[n]). Keine Wirkung auf Geister.'],
962=>['Geistübertragung','Zauber. Der Geist, der Euch am nächsten ist, verliert 5...50 Lebenspunkt[e]. Der Verbündete (bzw. Ihr selbst) wird für jeden verlorenen Lebenspunkt um 5 Punkt[e] geheilt.','Zauber. Der am nächsten zu Euch befindliche Geist verliert 5...50 Lebenspunkt[e]. Heilt den Verbündeten (bzw. Euch selbst) für jeden verlorenen Lebenspunkt um 5 Lebenspunkt[e].'],
963=>['Wiederherstellung','Binderitual. Erstellt einen Geist der Stufe 1...14. Wenn dieser Geist stirbt, werden alle Gruppenmitglieder in dem Bereich mit 5...50% ihrer Lebenspunkte und 0 Energiepunkten wieder belebt. Dieser Geist stirbt nach 30 Sekunden.','Binderitual. Erstellt einen Geist der Stufe 1...14 (30 Sekunde[n] Lebensdauer). Wirkung am Ende: Gruppenmitglieder im Bereich werden wiederbelebt (5...50% Lebenspunkte, 0 Energiepunkte).'],
964=>['Rachsüchtige Waffe','Waffenzauber. Wenn der Verbündete innerhalb der nächsten 8 Sekunde[n] das nächste Mal durch einen Gegner Schaden erleidet oder Lebenspunkte entzogen bekommt, entzieht er diesem Gegner bis zu 15...60 Lebenspunkt[e].','Waffenzauber. (8 Sekunde[n].) Entzieht dem nächsten Feind, der Schaden beim Verbündeten anrichtet, 15...60 Lebenspunkt[e].'],
973=>['Blendpulver','Zauber. Muss einem Begleithandangriff folgen. Der Gegner und alle umstehenden Feinde werden 3...15 Sekunde[n] lang geblendet.','Zauber. Verursacht beim Gegner und umstehenden Feinden Zustand Blindheit (3...15 Sekunde[n]). Muss einem Begleithandangriff folgen.'],
974=>['Berührung der Fangschrecke','Fertigkeit. Der Zielgegner wird 5...20 Sekunden lang verkrüppelt. Diese Fertigkeit zählt als Begleithandangriff.','Fertigkeit. Verursacht den Zustand Verkrüppelung (5...20 Sekunden). Diese Fertigkeit zählt als Begleithandangriff.'],
975=>['Ermüdender Angriff','Doppelangriff. Muss einem Leithandangriff folgen. Die Aktion des Gegners wurde unterbrochen. Wenn diese Aktion ein Zauber war, dann erleidet der Gegner 10 Überzaubern.','Doppelangriff. Unterbricht eine Aktion. Verursacht 10 Überzaubern, wenn die unterbrochene Aktion ein Zauber war. Muss einem Leithandangriff folgen.'],
976=>['Wiederholender Schlag','Begleithandangriff. Muss einem Begleithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt er +10...30 Punkt[e] Schaden zu. Wenn er sein Ziel verfehlt, benötigt er zusätzlich 15 Sekunden zum Wiederaufladen.','Begleithandangriff. Richtet +10...30 Punkt[e] Schaden an. +15 Sekunden zur Aufladezeit dieser Fertigkeit, falls Ihr verfehlt. Muss einem Begleithandangriff folgen.'],
977=>['Weg des Lotus','Verzauberung. Wenn Ihr innerhalb der nächsten 20 Sekunde[n] das nächste Mal mit einer Doppelangriff-Fertigkeit trefft, erhaltet Ihr 5...20 Energiepunkt[e].','Verzauberung. 20 Sekunde[n]: Ihr erhaltet 5...20 Energiepunkt[e], wenn Ihr das nächste Mal mit einem Doppelangriff trefft.'],
978=>['Zeichen der Unbeständigkeit','Verhexung. Während der nächsten 20 Sekunde[n] wird der Feind das nächste Mal, wenn Ihr ihn mit einer Doppelangriffs-Fertigkeit trefft, zu Boden geworfen.','Verhexung. 20 Sekunde[n]: Wirft den Gegner zu Boden, wenn Ihr ihn das nächste Mal mit einem Doppelangriff trefft.'],
979=>['Argwohn','Verhexung. Für 6 Sekunden schlägt der nächste Zauber, den der anvisierte Gegner auf einen Eurer Verbündeten wirkt, fehl und verursacht bei diesem Gegner 10...80 Schaden, sowie 75 % dieses Schadens bei allen benachbarten Gegnern.','Verhexung. (6 Sekunden). Der nächste Zauber, den der anvisierte Gegner auf einen Eurer Verbündeten wirkt, schlägt fehl und verursacht bei diesem Gegner 10...80 Schaden, sowie 75 % dieses Schadens bei allen benachbarten Gegnern.'],
980=>['Schmaus der Seelen','Zauber. Vernichtet die Geister aller Verbündeten in der Nähe. Für jeden Geist, der auf diese Art vernichtet wurde, werden alle Gruppenmitglieder um 50...100 Lebenspunkt[e] geheilt.','Zauber. Heilt alle Gruppenmitglieder für jeden verbündeten Geist in der Nähe um 50...100 Lebenspunkt[e]. Alle verbündeten Geister in der Nähe werden vernichtet.'],
981=>['Erholung','Binderitual. Erstellt einen Geist der Stufe 1...14. Verbündete in seiner Reichweite, die keine Geister sind, erfreuen sich einer Lebenspunktregeneration von +1...3. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...14 (15...45 Sekunde[n] Lebensdauer). Verbündete in Reichweite, die keine Geister sind, haben +1...3 Lebenspunktregeneration.'],
982=>['Unterschlupf','Binderitual. Erstellt einen Geist der Stufe 1...12. Verbündete in seiner Reichweite, die keine Geister sind, können bei einem einzelnen Angriff nicht mehr als maximal 10% ihrer Lebenspunkte verlieren. Wenn dieser Geist Schaden verhindert, verliert er 75...45 Lebenspunkt[e]. Dieser Geist besteht 30...60 Sekunde[n] lang.','Binderitual. Erstellt einen Geist der Stufe 1...12 (30...60 Sekunde[n] Lebensdauer). Verbündete in Reichweite, die keine Geister sind, können durch einen einzelnen Angriff nicht mehr als 10% ihrer maximalen Lebenspunkte verlieren. Schadensverhinderungskosten: Der Geist verliert 75...45 Lebenspunkt[e].'],
983=>['Schattenwaffe','Waffenzauber. Ein verbündetes Ziel erhält für eine Dauer von 1...7 Sekunde[n] eine Schattenwaffe. Jedes Mal, wenn der Verbündete getroffen wird, wird der Angreifer für 1...7 Sekunde[n] geblendet. Die nächsten 1...3 Mal, wenn ein Angriff dieses Verbündeten trifft, wird sein Ziel 5 Sekunde[n] lang geblendet.','Waffenzauber. (1...7 Sekunde[n].) Verursacht bei jedem, der den Verbündeten (bzw. Euch selbst) angreift, den Zustand Blindheit (5 Sekunde[n]). Die nächsten 1...3 Angriffe des Ziels verursachen Blindheit (5 Sekunde[n]), wenn sie treffen.'],
985=>['Trittnägel','Zauber. Target foe and all foes adjacent to your target are Crippled and Bleeding for 5...15 seconds. Caltrops has half the normal range.','Mitteldistanz-Zauber. Inflicts Crippled and Bleeding conditions (5...15 seconds) on target and adjacent foes.'],
986=>['Neunschwänziger Stoß','Doppelangriff. Muss einem Begleithandangriff folgen. Neunschwänziger Stoß kann nicht geblockt werden und fügt bei einem Treffer +15...40 Punkt[e] Schaden zu.','Doppelangriff. Richtet +15...40 Punkt[e] Schaden an. Kann nicht geblockt werden. Muss einem Begleithandangriff folgen.'],
987=>['Weg der leeren Handfläche','Elite-Verzauberung. Für 5...15 Sekunden kosten Begleithand- und Doppelangriffe keine Energie und werden um 25...50 % schneller aufgeladen.','Elite-Verzauberung. (5...15 Sekunden). Begleithand- und Doppelangriffe kosten keine Energie und werden um 25...50 % schneller aufgeladen.'],
988=>['Schläfenstoß','Elite-Begleithandangriff. Muss einem Leithandangriff folgen. Wenn dieser Angriff erfolgreich ist, leidet der Gegner 1...10 Sekunde[n] lang unter Benommenheit und Blindheit und wenn er einen Zauber wirkt, wird er dabei unterbrochen.','Elite-Begleithandangriff. Unterbricht einen Zauber. Verursacht Zustände Benommenheit und Blindheit (1...10 Sekunde[n]). Muss einem Leithandangriff folgen.'],
989=>['Goldener Phönix-Stoß','Begleithandangriff. Wenn Ihr nicht verzaubert seid, trifft diese Fertigkeit nicht. Wenn Goldener Phönix-Stoß erfolgreich ist, fügt er dem Gegner +10...30 Punkt[e] Schaden und allen umstehenden Feinden 10...30 Punkt[e] Schaden zu.','Begleithandangriff. Fügt dem Gegner +10...30 und umstehenden Feinden 10...30 Punkt[e] Schaden zu. Schlägt fehl, falls Ihr nicht verzaubert seid.'],
990=>['Verzauberungen ausmerzen','Fertigkeit. Der Gegner verliert 1 Verzauberung. Alle anderen Nicht-Angriffsfertigkeiten werden 8...4 Sekunde[n] lang deaktiviert. Für jede Fertigkeit, die auf diese Weise deaktiviert wird, verliert der berührte Gegner 1 weitere Verzauberung.','Berührungs-Fertigkeit. Entfernt für jede Eurer Nicht-Angriffsfertigkeiten eine Verzauberung. Alle Eure Nicht-Angriffsfertigkeiten werden deaktiviert (8...4 Sekunde[n]).'],
991=>['Verhexungen zurückweisen','Zauber. Entfernt eine Verhexung vom Verbündeten und eine weitere für jede wieder aufladende Gunst-der-Götter-Fertigkeit, die Ihr habt.','Zauber. Entfernt eine Verhexung vom Verbündeten und eine weitere für jede wieder aufladende Gunst-der-Götter-Fertigkeit, die Ihr habt.'],
992=>['Dreifachhieb','Elite-Axtangriff. Greift den Gegner und umstehende Feinde an. Jeder erfolgreiche Angriff fügt +10...40 Punkt[e] Schaden zu.','Elite-Axtangriff. Richtet +10...40 Punkt[e] Schaden an. Trifft den Gegner und umstehende Feinde.'],
993=>['Erzürnter Schlag','Elite-Hammerangriff. Wenn Erzürnter Schlag erfolgreich ist, erhaltet Ihr 1...4 Adrenalinstöße. Wenn Ihr einen sich bewegenden Feind trefft, erleidet dieser +10...40 Schaden und wird zu Boden geworfen.','Elite-Hammerangriff. Gibt Euch 1...4 Adrenalinstöße, wenn Ihr trefft. Richtet +10...40 Schaden an und wirft den Gegner zu Boden, wenn er sich bewegt hat.'],
994=>['Erneuernder Schlag','Hammerangriff. Wenn Erneuernder Schlag trifft, fügt er +10...40 Punkt[e] Schaden zu. Wenn Ihr einen zu Boden geworfenen Feind trefft, erhaltet Ihr 3 Energiepunkt[e] und dieser Angriff wird sofort wieder aufgeladen.','Hammerangriff. Richtet +10...40 Punkt[e] Schaden an. Ihr erhaltet 3 Energiepunkt[e] und dieser Angriff wird sofort wieder aufgeladen, wenn der Gegner zu Boden geworfen wurde.'],
995=>['Tigerhaltung','Haltung. 4...10 Sekunde[n] lang sind Eure Angriffe um 33% schneller. Tigerhaltung endet, sobald einer Eurer Angriffe nicht trifft.','Haltung. 4...10 Sekunde[n]: Ihr greift um 33% schneller an. Endet, sobald Ihr nicht trefft.'],
996=>['Stehender Hieb','Schwertangriff. Wenn Stehender Hieb erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu sowie zusätzlich 5...20 Punkt[e] Schaden, wenn Ihr eine Haltung einnehmt.','Schwertangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet zusätzlich 5...20 Punkt[e] Schaden an, falls Ihr eine Haltung einnehmt.'],
997=>['Hungersnot','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10. Jedes Mal, wenn die Energiepunkte eine Kreatur in seiner Reichweite, die kein Geist ist, auf 0 sinken, erleidet diese Kreatur 20...70 Punkt[e] Schaden. Dieser Geist stirbt nach 30...180 Sekunde[n].','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Richtet bei Kreaturen in Reichweite, deren Energiepunkte auf 0 sinken, 20...70 Punkt[e] Schaden an. Keine Wirkung auf Geister.'],
1018=>['Kritisches Auge','Fertigkeit. 10...35 Sekunde[n] lang habt Ihr zusätzlich eine 3...15% höhere Chance, bei einem Angriff einen kritischen Treffer zu erzielen. Ihr erhaltet 1 Energiepunkt[e] für jeden kritischen Treffer.','Fertigkeit. 10...35 Sekunde[n]: Ihr habt +3...15% zur Chance auf kritische Treffer. Ihr erhaltet jedes Mal 1 Energiepunkt[e], wenn Ihr einen kritischen Treffer landet.'],
1019=>['Kritischer Stoß','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt er +10...30 Punkt[e] Schaden zu, führt zu einem kritischen Treffer und Ihr erhaltet 1...3 Energiepunkt[e].','Doppelangriff. Richtet +10...30 Punkt[e] Schaden an. Immer ein kritischer Treffer. Ihr erhaltet 1...3 Energiepunkt[e]. Muss einem Begleithandangriff folgen.'],
1020=>['Stahlklingen','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt er für jeden wieder aufzuladenden Dolchangriff +5...16 Punkt[e] Schaden (maximaler Bonus 60) zu.','Doppelangriff. Richtet für jeden sich aufladenden Dolchangriff +5...16 Punkt[e] Schaden an (maximal 60). Muss einem Begleithandangriff folgen.'],
1021=>['Dschungelschlag','Begleithandangriff. Muss auf einen Startangriff folgen. Wenn er trifft, verursacht dieser Angriff +10...25 Schaden. Trifft er einen verkrüppelten Gegner, so nehmen dieser und alle benachbarten Gegner 1...31 Schaden.','Begleithandangriff. Verursacht +10...25 Schaden. Wenn der anvisierte Gegner verkrüppelt ist, erleiden er und benachbarte Gegner 1...31 Schaden. Muss auf einen Startangriff folgen.'],
1022=>['Wilder Stoß','Begleithandangriff. Muss einem Leithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt er +10...35 Punkt[e] Schaden zu und jede Haltung, die der Gegner einsetzt, endet. Dieser Angriff kann nicht geblockt werden.','Begleithandangriff. Richtet +10...35 Punkt[e] Schaden an. Entfernt Haltung des Gegners. Kann nicht geblockt werden. Muss einem Leithandangriff folgen.'],
1023=>['Stich der springenden Mantis','Leithandangriff. Wenn Stich der Mantis erfolgreich ist, erleidet der Gegner +5...15 Punkt[e] Schaden. Wenn dieser Angriff einen sich bewegenden Gegner trifft, wird dieser 3...15 Sekunde[n] lang verkrüppelt.','Leithandangriff. Richtet +5...15 Punkt[e] Schaden an. Verursacht Zustand Verkrüppelung (3...15 Sekunde[n]), falls der Gegner sich bewegt.'],
1024=>['Stoß der schwarzen Mantis','Leithandangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +8...20 Punkt[e] Schaden zu. Wenn Euer Gegner unter einer Verhexung leidet, wird er 3...15 Sekunde[n] lang verkrüppelt.','Leithandangriff. Richtet +8...20 Punkt[e] Schaden an. Verursacht Zustand Verkrüppelung (3...15 Sekunde[n]), falls der Gegner verhext ist.'],
1025=>['Unterbrechender Dolchstoß','Leithandangriff. Wenn dieser Angriff erfolgreich ist, unterbricht er die Aktion des Gegners. Wenn diese Aktion ein Zauber war, wird er 3...10 Sekunden[n] lang deaktiviert.','Leithandangriff. Unterbricht eine Aktion. Falls die unterbrochene Aktion ein Zauber war, wird er deaktiviert (3...10 Sekunde[n]).'],
1026=>['Goldener Lotus-Stoß','Leithandangriff. Wenn dieser Angriff erfolgreich ist, fügt er +5...20 Punkt[e] Schaden zu. Wenn Ihr unter den Auswirkungen einer Verzauberung leidet, erhaltet Ihr 5...8 Energiepunkt[e].','Leithandangriff. Richtet +5...20 Punkt[e] Schaden an. Ihr erhaltet 5...8 Energiepunkt[e], falls Ihr verzaubert seid.'],
1027=>['Kritische Verteidigungen','Verzauberung. 4...10 Sekunde[n] lang habt Ihr eine 75%ige Chance zum Blocken. Kritische Verteidigungen wird bei jedem kritischen Treffer, den Ihr landet, aktualisiert.','Verzauberung. 4...10 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken. Erneuerung: Mit jedem Eurer kritischen Treffer.'],
1028=>['Weg der Perfektion','Verzauberung. Während der nächsten 60 Sekunde[n] erhaltet Ihr jedes Mal, wenn Ihr erfolgreich einen kritischen Treffer landet, 10...40 Lebenspunkt[e].','Verzauberung. (60 Sekunden.) Eure kritischen Treffer heilen Euch um 10...40 Lebenspunkt[e].'],
1029=>['Dunkle Abtrünnigkeit','Elite-Verzauberung. Während der nächsten 3...17 Sekunde[n] entfernt Ihr jedes Mal, wenn Ihr erfolgreich einen kritischen Treffer landet, eine Verzauberung von Eurem Ziel. Wenn Ihr eine Verzauberung auf diese Weise entfernt, verliert Ihr 10...3 Energiepunkt[e] oder Dunkle Abtrünnigkeit endet.','Elite-Verzauberung. 3...17 Sekunde[n]: Eure kritischen Treffer entfernen eine Verzauberung. Entfernungskosten: Ihr verliert 10...3 Energiepunkt[e] oder Dunkle Abtrünnigkeit endet.'],
1030=>['Wut der Heuschrecke','Elite-Verzauberung. 10...35 Sekunde[n] lang habt Ihr zusätzlich eine 50%ige Chance auf einen Doppeltreffer, wenn Ihr Dolche verwendet.','Elite-Verzauberung. 10...35 Sekunde[n]: Ihr habt +50% zur Chance auf Doppeltreffer. Keine Wirkung, falls Ihr keine Dolche benutzt.'],
1031=>['Schleier des Kummers','Verzauberung. 30...60 Sekunden lang habt Ihr +3...8 Lebenspunktregeneration und eine 75%ige Chance Angriffe zu blocken, wenn Eure Lebenspunkte unter 50% liegen.','Verzauberung. (30...60 Sekunden.) Ihr habt +3...8 Lebenspunktregeneration und eine 75%ige Chance, zu blocken. Eure Lebenspunkte müssen unter 50% liegen, sonst keine Wirkung.'],
1032=>['Herz der Schatten','Zauber. Ihr werdet um 30...150 Lebenspunkt[e] geheilt. Schattenschritt zu einer Position in der Nähe, weg vom Gegner.','Zauber. Ihr werdet um 30...150 Lebenspunkt[e] geheilt und unternehmt einen Schattenschritt zu einer Position in der Nähe, weg vom Gegner.'],
1033=>['Aufspießen','Fertigkeit. Muss einem Doppelangriff folgen. Der Gegner erleidet 25...100 Punkt[e] Erdschaden und leidet 5...20 Sekunde[n] lang an einer Tiefe Wunde.','Fertigkeit. Richtet 25...100 Punkt[e] Erdschaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]). Muss einem Doppelangriff folgen.'],
1034=>['Eiternde Wunde','Elite-Verhexung. For 1...7 seconds, target foe moves 33% slower. That foe takes 5...25 damage each second while suffering from a condition.','Elite-Verhexung. (1...7 Sekunde[n].) Gegner bewegt sich um 33% langsamer. Falls dieser Gegner an einem Zustand leidet, erleidet er außerdem 5...25 Punkt[e] Schaden pro Sekunde.'],
1035=>['Versprechen des Assassinen','Elite-Verhexung. Wenn der Gegner innerhalb der nächsten 5...15 Sekunde[n] stirbt, erhaltet Ihr 5...20 Energiepunkt[e], und alle Eure Fertigkeiten werden wieder aufgeladen.','Elite-Verhexung. 5...15 Sekunde[n]: Wenn der Gegner stirbt, erhaltet Ihr 5...20 Energiepunkt[e] und alle Eure Fertigkeiten werden aufgeladen.'],
1036=>['Siegel der Bosheit','Siegel. Für jeden Zustand unter dem der Gegner leidet, verliert Ihr einen Zustand.','Siegel. Für jeden Zustand des Gegners verliert Ihr einen Zustand.'],
1037=>['Dunkle Flucht','Haltung. 5...15 Sekunde[n] lang bewegt Ihr Euch um 25% schneller und erleidet nur den halben Schaden. Dunkle Flucht endet, wenn Ihr mit einem Angriff erfolgreich trefft.','Haltung. 5...15 Sekunde[n]: Ihr bewegt Euch um 25% schneller und nehmt nur halben Schaden. Endet, wenn Ihr mit einem Angriff trefft.'],
1038=>['Verkrüppelnder Dolch','Zauber. Ein Verkrüppelnder Dolch fliegt auf den Gegner zu. Verkrüppelnder Dolch fügt bei einem Treffer 15...60 Punkt[e] Erdschaden zu und verkrüppelt sich bewegende Feinde 3...15 Sekunde[n] lang. Dieser Zauber hat nur die halbe Reichweite.','Mitteldistanz-Zauber. Geschoss: Richtet 15...60 Punkt[e] Erdschaden an. Verursacht Zustand Verkrüppelung (3...15 Sekunde[n]), falls der Gegner sich bewegt.'],
1040=>['Geistermarsch','Zauber. Schattenschritt zu Zielgeist.','Zauber. Schattenschritt zum ausgewählten Geist.'],
1041=>['Unsichtbare Wut','Haltung. Alle umstehenden Feinde werden 3...10 Sekunden lang geblendet. Während der nächsten 10...30 Sekunden könnt Ihr von geblendeten Gegnern nicht geblockt werden.','Haltung. Verursacht bei umstehenden Feinden Zustand Blindheit (3...10 Sekunde[n]). Geblendete Feinde können Eure Angriffe nicht blocken (10...30 Sekunde[n]).'],
1042=>['Blitzende Klingen','Elite-Haltung. 5...30 Sekunde[n] lang habt Ihr eine 75%ige Chance, Angriffe zu blocken, während Ihr selbst angreift. Wenn Ihr einen Angriff auf diese Weise blockt, erleidet Euer Angreifer 5...20 Punkt[e] Schaden.','Elite-Haltung. 5...30 Sekunde[n]: 75%ige Chance beim Angreifen zu blocken. Blockwirkung: 5...20 Punkt[e] Schaden für Euren Angreifer.'],
1043=>['Preschen','Haltung. 3 Sekunde[n] lang lauft Ihr um 50% schneller.','Haltung. 3 Sekunde[n]: Ihr bewegt Euch um 50% schneller.'],
1044=>['Dunkles Gefängnis','Verhexung. Schattenschritt zum Gegner. 1...6 Sekunde[n] lang bewegt sich dieser Gegner um 33% langsamer.','Verhexung. Unternehmt einen Schattenschritt zum Gegner. Der Gegner bewegt sich um 33% langsamer (1...6 Sekunde[n]).'],
1045=>['Handflächenschlag','Elite-Fertigkeit. Der berührte Gegner erleidet 10...65 Punkt[e] Schaden und wird 1...5 Sekunde[n] lang verkrüppelt. Diese Fertigkeit zählt als Begleithandangriff.','Elite-Berührungs-Fertigkeit. Richtet +10...65 Punkt[e] Schaden an und verursacht Zustand Verkrüppelung (1...5 Sekunde[n]). Dieser Angriff zählt als Begleithandangriff.'],
1048=>['Enthüllte Verzauberung','Zauber. Eine Verzauberung wird vom Gegner entfernt und Ihr und erhaltet 3...15 Energiepunkt[e]. Enthüllte Verzauberung wird 20 Sekunden lang durch die dem Gegner genommene Verzauberung ersetzt.','Zauber. Entfernt beim Gegner eine Verzauberung. Entfernungswirkungen: Ihr erhaltet 3...15 Energiepunkt[e]; dieser Zauber wird durch die entfernte Verzauberung ersetzt (20 Sekunden).'],
1049=>['Enthüllte Verhexung','Zauber. Eine Verhexung wird von einem Verbündeten (bzw. Euch selbst) entfernt und Ihr erhaltet 4...10 Energiepunkt[e]. Enthüllte Verhexung wird 20 Sekunden lang durch die entfernte Verhexung ersetzt.','Zauber. Entfernt beim Verbündeten (bzw. Euch selbst) eine Verhexung. Entfernungswirkungen: Ihr erhaltet 4...10 Energiepunkt[e]; dieser Zauber wird durch die entfernte Verhexung ersetzt (20 Sekunden).'],
1052=>['Angehäufter Schmerz','Zauber. Der Gegner erleidet 15...75 Punkt[e] Schaden. Wenn der Gegner unter 2 oder mehr Verhexungen leidet, erleidet er 5...20 Sekunde[n] lang eine Tiefe Wunde.','Zauber. Richtet 15...75 Punkt[e] Schaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls der Gegner 2 oder mehr Verhexungen hat.'],
1053=>['Übernatürliche Ablenkung','Elite-Zauber. Alle anderen Eurer Fertigkeiten werden 8 Sekunde[n] lang deaktiviert. Falls der Gegner eine Fertigkeit aktiviert, wird diese unterbrochen und zusätzlich 5...12 Sekunde[n] lang deaktiviert.','Elite-Zauber. Unterbricht eine Fertigkeit. Unterbrechungswirkung: Deaktiviert unterbrochene Fertigkeit (+5...12 Sekunde[n]). Eure anderen Fertigkeiten werden deaktiviert (8 Sekunde[n]).'],
1054=>['Antlitz des Ahnen','Verzauberung. 4...10 Sekunde[n] lang verlieren alle umstehenden Feinde jedes Mal, wenn der Verbündete (bzw. Ihr selbst) im Nahkampf getroffen wird, sämtliches Adrenalin sowie drei Energiepunkte.','Verzauberung. 4...10 Sekunde[n]: Alle umstehenden Feinde verlieren jedes Mal alles Adrenalin und 3 Energiepunkte, wenn ein Nahkampfangriff den Verbündeten (bzw. Euch selbst) trifft.'],
1055=>['Wiederkehrende Unsicherheit','Elite-Verhexung. 5 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...6. Hat dieser Gegner eine weitere Verhexung, wenn Wiederkehrende Unsicherheit enden würde, wird sie erneut angewendet.','Elite-Verhexung. (5 Sekunde[n].) Verursacht -1...6 Lebenspunktdegeneration. Erneuerung: Falls der Gegner eine andere Verhexung hat, wenn Wiederkehrende Unsicherheit enden würde.'],
1056=>['Kitahs Bürde','Verhexung. 6...12 Sekunden lang bewegt sich der Gegner um 50% langsamer. Wenn Kitahs Bürde endet, erhaltet Ihr 10...18 Energiepunkt[e].','Verhexung. 6...12 Sekunden: Gegner bewegt sich um 50% langsamer. Wirkung am Ende: Ihr erhaltet 10...18 Energiepunkt[e].'],
1057=>['Übernatürliche Labilität','Elite-Zauber. Unterbricht die Aktion des Gegners. Handelt es sich bei der Aktion um eine Fertigkeit, werden der Gegner und alle Gegner in der Nähe 2...4 Sekunden lang zu Boden geworfen. (Bei Schnellwirkung von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Elite-Zauber. Unterbricht die Aktion des gegners. Handelt es sich bei der Aktion um eine Fertigkeit, werden der Gegner und und alle Feinde in der Nähe 2...4 Sekunden lang zu Boden geworfen. Bei Schnellwirkung von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.'],
1059=>['Verhexungsfresser-Siegel','Siegel. Der berührte Verbündete und bis zu 2...5 umstehende Verbündete verlieren jeweils eine Verhexung. Ihr erhaltet für jede Verhexung, die auf diese Art entfernt wird, 1...4 Energiepunkt[e].','Berührungs-Siegel. Entfernt beim Ziel und 2...5 umstehenden Verbündeten eine Verhexung. Entfernungswirkung: Ihr erhaltet für jede entfernte Verhexung 1...4 Energiepunkt[e].'],
1061=>['Reaktion','Zauber. Der Gegner verliert eine Verzauberung. Wenn eine Verzauberung auf diese Art entfernt wird, verliert der Gegner 4...10 Energiepunkt[e].','Zauber. Entfernt eine Verzauberung. Entfernungswirkung: Gegner verliert 4...10 Energiepunkt[e].'],
1062=>['Arkane Entwendung','Zauber. 5...35 Sekunde[n] lang wird ein zufällig gewählter Zauber des Gegners deaktiviert und Arkane Entwendung wird durch diesen Zauber ersetzt.','Zauber. 5...35 Sekunde[n]: Deaktiviert einen willkürlichen Zauber. Diese Fertigkeit wird zum betreffenden Zauber.'],
1066=>['Sieger plündern','Elite-Verhexung. Während der nächsten 3...15 Sekunde[n] verliert der Gegner jedes Mal, wenn er eine Kreatur mit weniger Lebenspunkten angreift oder einen Zauber auf sie wirkt, 25...100 Lebenspunkt[e].','Elite-Verhexung. 3...15 Sekunde[n]: Lässt den Gegner jedes Mal 25...100 Lebenspunkt[e] verlieren, wenn er eine Kreatur mit weniger Lebenspunkten angreift oder einen Zauber auf eine solche Kreatur wirkt.'],
1067=>['Lebensfluchstoß','Zauber. Der Gegner erleidet 12...48 Punkt[e] Schattenschaden. Sind seine Lebenspunkte über 50%, entzieht Ihr ihm bis zu 12...48 Lebenspunkt[e].','Zauber. Richtet 12...48 Punkt[e] Schaden an. Entzieht 12...48 Lebenspunkt[e], falls der Gegner mehr als 50% seiner maximalen Lebenspunkte hat.'],
1068=>['Bitterkalt','Zauber. Der Gegner erleidet 15...60 Punkt[e] Kälteschaden. Wenn dieser Gegner mehr Lebenspunkte als Ihr hat, wird Bitterkalt sofort wieder aufgeladen.','Zauber. Richtet 15...60 Punkt[e] Kälteschaden an. Lädt sich sofort wieder auf, falls der Gegner mehr Lebenspunkte hatte als Ihr.'],
1069=>['Geschmack der Schmerzen','Zauber. Wenn die Lebenspunkte des Gegners unter 50% liegen, erhaltet Ihr 30...150 Lebenspunkt[e].','Zauber. Heilt Euch um 30...150 Lebenspunkt[e]. Der Gegner muss weniger als 50% seiner maximalen Lebenspunkte haben, sonst keine Wirkung.'],
1070=>['Verzauberungen schänden','Zauber. Der Zielgegner und alle in seiner Nähe befindlichen Gegner erleiden 6...60 Punkt[e] Schattenschaden sowie zusätzlich 4...20 Punkt[e] Schattenschaden für jede auf ihnen liegende Verzauberung.','Zauber. Richtet beim Gegner und Feinden in der Nähe 6...60 Punkt[e] Schaden an. Richtet zusätzlich 4...20 Punkt[e] Schaden für jede auf ihnen liegende Verzauberung an.'],
1071=>['Angstschauer','Verhexung. 10...40 Sekunde[n] lang wird der Gegner jedes Mal, wenn er beim Anwenden einer Fertigkeit mit Kälteschaden getroffen wird, unterbrochen und Ihr verliert 8...3 Energiepunkt[e] oder Angstschauer endet.','Verhexung. 10...40 Sekunde[n]: Kälteschaden unterbricht die Fertigkeiten des Gegners. Unterbrechungskosten: Ihr verliert 8...3 Energiepunkt[e] oder diese Verhexung endet.'],
1075=>['Vampirschwarm','Zauber. Vampirschwarm entzieht bis zu drei Gegnern in dem Bereich bis zu 15...60 Lebenspunkt[e].','Zauber. Entzieht 15...60 Lebenspunkt[e]. Trifft 2 zwei weitere Gegner in dem Bereich.'],
1076=>['Bluttrinker','Zauber. Wenn Eure Lebenspunkte über 90% liegen, leidet Ihr 6 Sekunde[n] lang an einer Blutung. Entzieht dem Gegner bis zu 20...65 Lebenspunkt[e].','Zauber. Entzieht 20...65 Lebenspunkt[e]. Ihr beginnt zu bluten (6 Sekunde[n]), falls Ihr mehr als 90% Eurer maximalen Lebenspunkte habt.'],
1077=>['Vampirbiss','Fertigkeit. Entzieht dem Gegner durch die Berührung 29...74 Lebenspunkt[e].','Berührungs-Fertigkeit. Entzieht 29...74 Lebenspunkt[e].'],
1078=>['Suhlerbiss','Fertigkeit. Der berührte Gegner erleidet 20...58 Punkt[e] Schattenschaden.','Berührungs-Fertigkeit. Richtet 20...58 Punkt[e] Schaden an.'],
1079=>['Schwächende Berührung','Fertigkeit. Der berührte Gegner verliert 5...65 Lebenspunkt[e] und leidet 5...20 Sekunde[n] lang an Schwäche.','Berührungs-Fertigkeit. Lässt 5...65 Lebenspunkt[e] verlieren. Verursacht Zustand Schwäche (5...20 Sekunde[n]).'],
1081=>['Teinais Wind','Zauber. Gegner und umstehende Feinde erleiden 10...40 Punkte Kälteschaden. Brennende Feinde, die durch Teinais Wind getroffen werden, erleiden zusätzlich 40...80 Punkte Schaden und werden unterbrochen.','Zauber. Richtet 10...40 Punkte Kälteschaden an. Brennende Feinde erleiden +40...80 Punkte Schaden und werden unterbrochen. Trifft auch umstehende Gegner.'],
1082=>['Schockpfeil','Zauber. Sendet einen Schockpfeil aus, der schnell auf den Gegner zufliegt und ihm 5...50 Punkte Blitzschaden zufügt. Wenn Schockpfeil einen Gegner mit Beschädigter Rüstung trifft, erhaltet Ihr 5 Energiepunkte sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung. Schockpfeil hat eine Rüstungsdurchdringung von 25%.','Zauber. Rasantes Geschoss: Richtet 5...50 Punkte Blitzschaden an. Ihr erhaltet 5 Energiepunkte sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung, wenn Ihr einen Feind mit Beschädigter Rüstung trefft. 25% Rüstungsdurchdringung.'],
1083=>['Schwankender Boden','Elite-Zauber. Am Standort des Feindes wird ein Schwankender Boden erzeugt. In den nächsten 5 Sekunde[n] erleiden Gegner in der Nähe 10...40 Punkt[e] Erdschaden pro Sekunde. Angreifende Gegner, die von Schwankender Boden getroffen werden, werden zu Boden geworfen.','Elite-Zauber. Richtet jede Sekunde 10...40 Punkt[e] Erdschaden an (5 Sekunde[n]) und wirft angreifende Gegner zu Boden. Trifft Feinde in der Nähe der ursprünglichen Position des Ziels.'],
1084=>['Splitter-Rüstung','Verzauberung. 5...11 Sekunde[n] lang habt Ihr eine 25...50%ige Chance, Angriffe zu blocken, und jedes Mal, wenn Ihr das Ziel eines feindlichen Zaubers oder Angriffs seid, erleidet ein Gegner in der Nähe 5...35 Punkt[e] Erdschaden.','Verzauberung. (5...11 Sekunde[n].) Ihr habt eine 25...50%ige Chance zu blocken. Richtet jedes Mal bei einem Gegner in der Nähe 5...35 Punkt[e] Erdschaden an, wenn Ihr Ziel eines feindlichen Zaubers oder Angriffs seid.'],
1085=>['Aschenexplosion','Verhexung. Umstehende Feinde erleiden 35...65 Punkte Erdschaden. Brennende Feinde, die durch Aschenexplosion getroffen werden, werden für 5 Sekunden verhext und haben eine 20...75%ige Wahrscheinlichkeit, ihr Ziel zu verfehlen.','Verhexung. Richtet 35...65 Punkte Erdschaden an. Brennende Feinde sind für 5 Sekunden verhext und verfehlen 20...75% ihrer Angriffe. Trifft auch umstehende Gegner.'],
1086=>['Drachenstampfer','Zauber. An der Position des Gegners wird ein Drachenstampfer beschworen. Alle Gegner in diesem Gebiet werden zu Boden geworfen und erleiden 26...100 Punkt[e] Erdschaden.','Zauber. Richtet 26...100 Punkt[e] Erdschaden an. Wirft zu Boden. Trifft auch Feinde in der Nähe des Gegners.'],
1088=>['Zweite Chance','Elite-Zauber. Ihr erhaltet für jeden Eurer Energiepunkte, der durch Überzaubern eingeschränkt ist, 1 Energiepunkte und 5 Punkte Gesundheit. Ihr verliert alle Verzauberungen.','Elite-Zauber. Ihr erhaltet für jeden Punkt Überzaubern 1 Energiepunkte und 5 Punkte Gesundheit. Ihr verliert alle Verzauberungen.'],
1090=>['Glühende Kohle','Verhexung. Der Gegner erleidet 10...70 Punkte Feuerschaden. Wenn Ihr Überzaubert seid, wird dieser Gegner für 3 Sekunden mit Glühenden Kohlen verhext und erleidet zusätzlich jede Sekunde 5...25 Feuerschaden.','Verhexung. Fügt dem Gegner 10...70 Punkte Feuerschaden zu. Wenn Ihr Überzaubert seid, wird dieser Gegner für 3 Sekunden verhext und erleidet jede Sekunde 5...25 Feuerschaden.'],
1091=>['Doppeldrache','Elite-Verzauberung. Ihr beschwört die Macht des Drachen. 8 Sekunde[n] lang werden ein Verbündeter und Ihr mit Doppeldrache verzaubert. Umstehende Feinde erleiden pro Sekunde 10...40 Punkt[e] Feuerschaden. Wenn Ihr oder Euer Verbündeter Fertigkeiten auf einen Feind anwenden, wird dieser Feind zudem 1...4 Sekunde[n] lang in Brand gesetzt.','Elite-Verzauberung. (8 Sekunde[n].) Verzaubert Euch und Euren Verbündeten. Umstehende Feinde erleiden pro Sekunde 10...40 Punkt[e] Feuerschaden. Fertigkeiten gegen einen Feind verursachen zusätzlich Brennen (1...4 Sekunde[n]).'],
1093=>['Teinais Hitze','Abwehrzauber. Erstellt für 10...15 Sekunden eine Abwehr von Teinais Hitze an Eurer Position Feinde im Bereich haben 2...5 Lebenspunktdegeneration. Die Angriffe geschwächter Feinde sind um 33% verlangsamt. Diese Fertigkeit wird 20 Sekunden lang deaktiviert.','Abwehrzauber. (10...15 Sekunden) Verursacht -2...5 Lebenspunktdegeneration. Angriffe geschwächter Feinde im Bereich sind um 33% verlangsamt. Für 20 Sekunden deaktiviert.'],
1094=>['Feueratem','Zauber. An der aktuellen Position des Gegners wird Feueratem erzeugt. Während der nächsten 5 Sekunde[n] erleiden umstehende Gegner 10...40 Punkt[e] Feuerschaden pro Sekunde.','Zauber. Richtet jede Sekunde 10...40 Punkt[e] Feuerschaden an (5 Sekunde[n]). Trifft umstehende Feinde um anfängliche Position des Ziels.'],
1095=>['Sternenexplosion','Elite-Zauber. Der berührte Gegner und alle Feinde im Bereich erleiden 7...112 Punkt[e] Feuerschaden und werden 1...4 Sekunde[n] lang in Brand gesetzt. Ihr erhaltet für jeden getroffenen Feind 2 Energiepunkte.','Elite-Berührungs-Zauber. Richtet 7...112 Punkt[e] Feuerschaden an. Verursacht Zustand Brennen (1...4 Sekunde[n]). Ihr erhaltet für jeden getroffenen Feind 2 Energiepunkte. Trifft auch Feinde im Bereich.'],
1096=>['Glyphe der Essenz','Glyphe. 15 Sekunde[n] lang wird Euer nächster Zauber sofort gewirkt, führt aber dazu, dass Ihr Eure gesamte Energie verliert.','Glyphe. (15 Sekunde[n].) Euer nächster Zauber kann sofort gewirkt werden. Ihr verliert alle Energiepunkte.'],
1097=>['Teinais Gefängnis','Verhexung. 1...8 Sekunden lang werden die Beine des Gegners von Eis umschlossen, wodurch seine Bewegungen um 66% langsamer werden. Wenn der Gegner an Beschädigter Rüstung leidet, sickert die Kälte durch und verursacht 5...9 Lebenspunktdegeneration.','Verhexung. (1...8 Sekunden.) Gegner bewegt sich um 66% langsamer. Gegner mit Beschädigter Rüstung haben 5...9 Lebenspunktdegeneration.'],
1098=>['Eisspiegel','Elite-Verhexung. Zerbricht einen Eisspiegel. Alle Feinde in Eurer Nähe und das verbündete Ziel erleiden 15...70 Punkt[e] Kälteschaden und bewegen sich 2...6 Sekunde[n] lang um 66% langsamer. Wenn Ihr einen Gegner trefft, der mit Wassermagie verhext ist, lädt Eisspiegel um 50% schneller wieder auf.','Elite-Verhexung. Richtet 15...70 Punkt[e] Kälteschaden an und verlangsamt Feinde um 66% (2...6 Sekunde[n]). Trifft Feinde in Eurer Nähe und Euren Verbündeten. Lädt um 50% schneller wieder auf, falls ein getroffener Gegner mit Wassermagie verhext ist.'],
1099=>['Teinais Kristalle','Zauber. Der Gegner erleidet 20...40 Punkte Schaden. Wenn der Gegner unter einer Wassermagie-Verhexung leidet, richtet dieser Zauber beim Gegner und Feinden in der Nähe zusätzlich 20...40 Punkte Schaden an, und Feinde in der Nähe erleiden Beschädigte Rüstung für 5...15 Sekunden.','Zauber. Fügt dem Gegner 20...40 Punkte Schaden zu. Verursacht +20...40 mehr Schaden und verursacht Beschädigte Rüstung (5...15 Sekunden) bei Feinden in der Nähe, die unter einer Wasserverhexung leiden.'],
1113=>['Kirins Zorn','Zauber. 5 Sekunden lang erleiden umstehende Gegner am Wirkungsort des Zaubers 8...32 Punkt[e] heiligen Schaden pro Sekunde.','Zauber. Richtet jede Sekunde 8...32 Punkt[e] heiligen Schaden an (5 Sekunden). Trifft umstehende Feinde um Eure anfängliche Position.'],
1114=>['Geisterbindung','Verzauberung. Während der nächsten 8 Sekunde[n] wird der Verbündete (bzw. Ihr selbst), immer, wenn er mehr als 50 Punkt[e] Schaden durch die nächsten 10 Angriffe oder Zauber erleidet, um 30...90 Lebenspunkt[e] geheilt.','Verzauberung. 8 Sekunde[n]: Heilt jedes Mal um 30...90 Lebenspunkt[e], wenn der Verbündete (bzw. Ihr selbst) mehr als 50 Punkt[e] Schaden erleidet. Endet, nachdem der Verbündete Schaden durch 10 Angriffe oder Zauber erlitten hat.'],
1115=>['Flair der Verzauberung','Elite-Verzauberung. 4...10 Sekunde[n] lang kosten Verzauberungen, die auf diesen Verbündeten gewirkt werden, 10 Energiepunkt[e] weniger (mindestens 1 Energiepunkt[e]).','Elite-Verzauberung. 4...10 Sekunde[n]: Auf den Verbündeten gewirkte Verzauberungen kosten 10 Energiepunkt[e] weniger (mindestens 1 Energiepunkt[e]). Sich selbst als Ziel wählen nicht möglich.'],
1117=>['Himmlische Wonne','Zauber. Heilt Euch und Gruppenmitglieder in Hörweite um 15...60 Punkt[e].','Zauber. Heilt Euch selbst und Gruppenmitglieder in Hörweite um 15...60 Punkt[e].'],
1118=>['Heilsalve','Elite-Zauber. Der Verbündete (bzw. Ihr selbst) wird um 20...120 Lebenspunkt[e] geheilt. Alle Gruppenmitglieder in Hörweite Eures Ziels erhalten Lebenspunkte entsprechend dem mit diesem Zauber verbundenen Gunst-der-Götter-Bonus. Eure Peinigungsgebete werden 20 Sekunden lang deaktiviert.','Elite-Zauber. Heilt um 20...120 Lebenspunkt[e]. Gruppenmitglieder in Hörweite Eures Ziels erhalten Lebenspunkte entsprechend dem Gunst-der-Götter-Bonus. <c x="SkillDull">Deaktiviert Eure Peinigungsgebete (20 Sekunden).'],
1119=>['Kareis Heilkreis','Zauber. Heilt Euch selbst und alle umstehenden Geschöpfe um 30...180 Punkt[e].','Zauber. Heilt Euch um 30...180 Lebenspunkt[e]. Heilt auch umstehende Kreaturen.'],
1120=>['Jameis Starren','Zauber. Heilt Verbündeten für 35...180 Lebenspunkt[e].','Zauber. Heilt um 35...180 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
1121=>['Geschenk des Lebens','Zauber. Alle Eure anderen Heilgebete werden 10...5 Sekunde[n] lang deaktiviert. Der Verbündete wird um 15...150 Lebenspunkt[e] geheilt.','Zauber. Heilt um 15...150 Lebenspunkt[e]. Eure anderen Heilgebete-Fertigkeiten werden deaktiviert (10...5 Sekunde[n]). Sich selbst als Ziel wählen nicht möglich.'],
1123=>['Lebensmantel','Elite-Verzauberung. Entfernt beim Verbündeten 0...2 Zustände. 8 Sekunde[n] lang erhält der Verbündete, wenn er das nächste Mal Schaden erleiden oder Lebenspunkte entzogen bekommen würde, stattdessen den entsprechenden Wert als Lebenspunkte (maximal 20...100).','Elite-Verzauberung. (8 Sekunde[n].) Wandelt den nächsten erlittenen Schaden bzw. die nächsten entzogenen Lebenspunkte (maximal 20...100 Punkt[e]) in Heilung um. Anfangswirkung: Entfernt 0...2 Zustände.'],
1126=>['Ausdrückliche Entfernung','Elite-Zauber. Ihr und der Verbündete verlieren 1 Zustand und 1 Verhexung und werden um 50 Lebenspunkt[e] geheilt.','Elite-Zauber. Entfernt einen Zustand und eine Verhexung vom Verbündeten und Euch selbst und heilt um 50 Punkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
1128=>['Gesang der Wiederbelebung','Zauber. Ein Gruppenmitglied wird mit höchstens der Anzahl Eurer Lebenspunkte und 5...35% der Energiepunkte wiederbelebt. Die Reichweite dieses Zaubers ist nur halb so groß wie gewöhnlich.','Mitteldistanz-Zauber. Das Gruppenmitglied wird wiederbelebt (Eure aktuellen Lebenspunkte, 5...35% Energiepunkte).'],
1129=>['Wort des Tadels','Elite-Zauber. Der anvisierte Gegner nimmt 30...130 heiligen Schaden. Falls Euer Ziel weniger als 50 % Lebenspunkte hatte, braucht "Wort der Zensur" 20 zusätzliche Sekunde[n] zur Wiederaufladung.','Elite-Zauber. Verursacht 30...130 heiligen Schaden. +20 Wiederaufladezeit, wenn der anvisierte Gegner weniger als 50 % Lebenspunkte hat.'],
1130=>['Speer des Lichts','Zauber. Speer des Lichts fliegt auf den Gegner zu und fügt ihm, falls er trifft, 26...56 Punkt[e] heiligen Schaden zu. Speer des Lichts fügt +15...60 Punkt[e] Schaden zu, wenn er einen angreifenden Gegner trifft.','Zauber. Geschoss: Richtet 26...56 Punkt[e] heiligen Schaden an. Richtet zusätzlich 15...60 Punkt[e] Schaden an, falls der Gegner gerade angreift.'],
1131=>['Steinseelenschlag','Fertigkeit. Der berührte Gegner erleidet 10...55 Punkt[e] heiligen Schaden. Wenn Euer Ziel zu Boden geworfen wurde, erleidet es zusätzlich 10...55 Punkt[e] heiligen Schaden.','Berührungs-Fertigkeit. Richtet 10...55 Punkt[e] heiligen Schaden an. Richtet zusätzlich 10...55 Punkt[e] heiligen Schaden an, falls Gegner zu Boden geworfen ist.'],
1133=>['Betrunkener Schlag','Nahkampfangriff. Wenn dieser Angriff trifft, fügt Ihr +10...40 Punkt[e] Schaden zu und Euer Ziel leidet unter einem der folgenden Zustände: Tiefe Wunde (20 Sekunden lang), Schwäche (20 Sekunden lang), Blutung (25 Sekunden lang) oder Verkrüppelung (15 Sekunden lang). Nachdem Ihr einen Betrunkenen Schlag ausgeführt habt, werdet Ihr zu Boden geworfen.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an. Verursacht willkürlich einen der folgenden Zustände: Tiefe Wunde (20 Sekunden), Schwäche (20 Sekunden), Blutung (25 Sekunden) oder Verkrüppelung (15 Sekunden). Ihr werdet zu Boden geworfen.'],
1134=>['Leviathanschlag','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn dieser Angriff geblockt wird, wird Euer Ziel zu Boden geworfen und erleidet 10...34 Punkt[e] Schaden.','Nahkampfangriff. Richtet +5...20 Punkt[e] Schaden an. Wirft zu Boden und richtet 10...34 Punkt[e] Schaden an, falls geblockt.'],
1135=>['Jaizhenjuschlag','Schwertangriff. Wenn Jaizhenjuschlag trifft, fügt Ihr +1...30 Punkt[e] Schaden zu. Wenn Ihr keine Haltung einnehmt, ist ein Blocken bei Jaizhenjuschlag nicht möglich.','Schwertangriff. Richtet +1...30 Punkt[e] Schaden an. Kann nicht geblockt werden, es sei denn, Ihr nehmt eine Haltung ein.'],
1136=>['Durchdringender Hieb','Axtangriff. Wenn dieser Angriff erfolgreich ist, trefft Ihr für 10...25 Punkt[e] zusätzlichen Schaden. Dieser Axtangriff hat eine Rüstungsdurchdringung von 20%.','Axtangriff. Richtet +10...25 Punkt[e] Schaden an. 20% Rüstungsdurchdringung.'],
1137=>['Yetischlag','Hammerangriff. Alles Adrenalin geht verloren. Greift alle umstehenden Feinde an. Wenn dieser Angriff einen Gegner trifft, der unter einem Zustand leidet, wird dieser zu Boden geworfen. (Bei einer Hammerbeherrschung von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Hammerangriff. Greift alle umstehenden Feinde an. Feinde, die unter einem Zustand leiden, werden zu Boden geworfen. Ihr verliert alles Adrenalin. Mindestens Hammerbeherrschung 5, sonst 50%ige Chance auf Misserfolg.'],
1141=>['"Ihr werdet sterben!"','Schrei. Sind die Lebenspunkte des anvisierten Gegners unter 90 %, so erhaltet Ihr 1...3 Adrenalinschläge.','Schrei. Ihr erhaltet 1...3 Adrenalinschläge. Kein Effekt, solange der anvisierte Gegner nicht unter 90 % Lebenspunkte besitzt.'],
1142=>['Günstige Abwehr','Elite-Haltung. 8 Sekunde[n] lang wird der nächste Angriff gegen Euch geblockt. Ihr erhaltet 1...4 Adrenalinstöße, wenn diese Haltung endet.','Elite-Haltung. (8 Sekunde[n].) Blockt einen Angriff. Wirkung am Ende: Ihr erhaltet 1...4 Adrenalinstöße.'],
1144=>['Silberflügel-Hieb','Schwertangriff. Bei einem Treffer fügt dieser Angriff +1...40 Punkte Schaden zu.','Schwertangriff. Richtet +1...40 Punkt[e] Schaden an.'],
1146=>['Schubs','Elite-Fertigkeit. Der berührte Zielgegner erleidet 15...75 Schaden, seine Haltung endet, und er wird niedergeschlagen.','Elite-Berührungs-Fertigkeit. Der berührte Zielgegner erleidet 15...75 Schaden, seine Haltung endet, und er wird niedergeschlagen.'],
1191=>['Trennender Angriff','Bogenangriff. Wenn Trennender Angriff trifft, fügt Ihr fügt Ihr +5...25 Punkt[e] Schaden zu. Dieser Angriff hat eine Rüstungsdurchdringung von 10%.','Bogenangriff. Richtet +5...25 Punkt[e] Schaden an. 10% Rüstungsdurchdringung.'],
1192=>['Zojuns Schuss','Bogenangriff. Ein Pfeil wird abgeschossen, der nur die halbe Reichweite zurücklegt, aber dafür +10...40 Punkt[e] Schaden zufügt.','Mitteldistanz-Bogenangriff. Richtet +10...40 Punkt[e] Schaden an.'],
1194=>['Raubtierverbindung','Schrei. Während der nächsten 5...20 Sekunde[n] greift Euer Tiergefährte um 25% schneller an und Ihr werdet bei jedem erfolgreichen Angriff um 1...31 Punkt[e] geheilt.','Schrei. (5...20 Sekunde[n].) Euer Tiergefährte greift um 25% schneller an und Ihr erhaltet bei jedem erfolgreichen Angriff Eures Tiergefährten 1...31 Lebenspunkt[e].'],
1195=>['Gemeinsame Heilung','Elite-Fertigkeit. Euer Tiergefährte entzieht 15 Sekunde[n] lang jedes Mal 1...20 Lebenspunkt[e], wenn er mit einem Angriff trifft. Sowohl Ihr als auch Euer Tiergefährte werdet für 20...104 Lebenspunkt[e] geheilt. Wenn Euer Gefährte tot ist, wird er mit 50% der Lebenspunkte wiederbelebt. Wenn Ihr diese Fertigkeit benutzt, reist Euer Tiergefährte mit Euch.','Elite-Fertigkeit. (15 Sekunde[n].) Die Angriffe Eures Tiergefährten entziehen 20...104 Lebenspunkt[e]. Anfangswirkung: Heilt Euch und Euren Tiergefährten für 20...104 Lebenspunkt[e]. Falls Euer Tiergefährte tot ist, wird er wiederbelebt (50% Lebenspunkte) Wenn Ihr diese Fertigkeit benutzt, reist Euer Tiergefährte mit Euch.'],
1196=>['Zojuns Eile','Haltung. 5...11 Sekunde[n] lang bewegt Ihr Euch um 33% schneller und habt eine 27...75%ige Chance, Geschosse zu blocken. Zojuns Eile endet, wenn Ihr angreift.','Haltung. 5...11 Sekunde[n]: Ihr bewegt Euch um 33% schneller und habt eine 27...75%ige Chance, Geschosse zu blocken. Endet, sobald Ihr angreift.'],
1197=>['Nadelschuss','Bogenangriff. Wenn Nadelschuss erfolgreich ist, fügt er nur 10...30 Schaden zu. Der Pfeil bewegt sich schneller als normal. Wenn Nadelschuss einen Feind trifft, dessen Lebenspunkte unter 50% sind, wird er sofort wieder aufgeladen. Eure anderen Angriffs-Fertigkeiten werden 2 Sekunden lang deaktiviert.','Bogenangriff. Schneller Pfeil. Richtet 10...30 Punkt[e] Schaden an. Lädt sich sofort wieder auf, falls der Gegner weniger als 50% seiner maximalen Lebenspunkte hat. Deaktiviert Eure anderen Angriffsfertigkeiten (2 Sekunden).'],
1198=>['Stahlspitzenpfeil','Elite-Bogenangriff. Ihr schießt einen Stahlspitzenpfeil ab, der sich langsamer als normal bewegt. Wenn er trifft, leidet der Gegner 5...20 Sekunde[n] lang unter Benommenheit und falls er einen Zauber wirkt, wird dieser unterbrochen.','Elite-Bogenangriff. Langsamer Pfeil. Unterbricht einen Zauber. Verursacht Zustand Benommenheit (5...20 Sekunde[n]).'],
1199=>['Glaspfeile','Elite-Vorbereitung. Während der nächsten 10...35 Sekunde[n] fügen Eure Pfeile bei einem Treffer +6...20 Punkt[e] Schaden zu, und führen 10...20 Sekunde[n] lang zu einer Blutung, wenn sie geblockt werden.','Elite-Vorbereitung. 10...35 Sekunde[n]: Eure Pfeile richten +6...20 Punkt[e] Schaden an. Verursacht Zustand Blutung (10...20 Sekunde[n]), falls geblockt.'],
1200=>['Siegel des Bogenschützen','Elite-Siegel. 1...24 Sekunde[n] lang dauern alle von Euch zugefügten Zustände, während Ihr einen Bogen führt, um 150% länger an.','Elite-Siegel. 1...24 Sekunde[n]. Von Euch zugefügte Zustände, während Ihr einen Bogen führt, dauern um 150% länger an.'],
1201=>['Wilder Sprung','Tiergefährtenangriff. Euer Tiergefährte führt einen Wilden Sprung aus, der +5...20 Punkt[e] Schaden zufügt. Trifft dieser Angriff einen Gegner, der einen Zauber wirkt, wird er zu Boden geworfen.','Tiergefährtenangriff. Richtet +5...20 Punkt[e] Schaden an. Wirft zu Boden, falls der Gegner einen Zauber wirkt.'],
1202=>['Erzürnter Ausfall','Elite-Tiergefährtenangriff. Euer Tiergefährte greift mit einem Erzürnten Ausfall an, der dem Gegner 5...20 Sekunden lang eine Tiefe Wunde und +10...50 Punkt[e] Schaden zufügt.','Elite-Tiergefährtenangriff. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]) und fügt +10...50 Punkt[e] Schaden zu.'],
1203=>['Bestienattacke','Tiergefährtenangriff. Euer Tiergefährte greift mit einer Bestienattacke an, die +5...20 Punkt[e] Schaden zufügt. Trifft dieser Angriff einen Gegner am Boden, leidet dieser 4...10 Sekunde[n] lang an Benommenheit.','Tiergefährtenangriff. Richtet +5...20 Punkt[e] Schaden an. Verursacht Zustand Benommenheit (4...10 Sekunde[n]), falls Gegner zu Boden geworfen ist.'],
1205=>['Giftbiss','Tiergefährtenangriff. Euer Tiergefährte greift mit einem Giftbiss an, der den Gegner 5...20 Sekunde[n] lang vergiftet.','Tiergefährtenangriff. Verursacht Zustand Gift (5...20 Sekunde[n]).'],
1206=>['Sprung','Tiergefährtenangriff. Der nächste Angriff Eures Tiergefährten ist ein Sprung, der +5...20 Punkt[e] Schaden zufügt. Trifft dieser Angriff einen Gegner, der sich bewegt, wird dieser zu Boden geworfen.','Tiergefährtenangriff. Richtet +5...20 Punkt[e] Schaden an. Wirft zu Boden, falls der Gegner sich bewegt.'],
1209=>['Bestienwut','Haltung. Alle Eure Nicht-Angriffsfertigkeiten werden 5 Sekunden lang deaktiviert. 5...11 Sekunde[n] lang greift Ihr um 25% schneller an.','Haltung. 5...11 Sekunde[n]: Ihr greift um 25% schneller an. Eure Nicht-Angriffsfertigkeiten werden deaktiviert (5 Sekunden).'],
1211=>['Vipernnest','Falle. Erzeugt ein Vipernnest. Wenn es ausgelöst wird, erleiden alle getroffenen Gegner in der Nähe 5...35 Punkt[e] Stichschaden und werden 5...20 Sekunde[n] lang vergiftet. Vipernnest endet nach 90 Sekunde[n]. Diese Falle kann leicht unterbrochen werden.','Falle. 90 Sekunde[n]: Betrifft Feinde in der Nähe. Richtet 5...35 Punkt[e] Stichschaden an. Verursacht Zustand Gift (5...20 Sekunde[n]). Leicht zu unterbrechen.'],
1212=>['Tagundnachtgleiche','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10. In seiner Reichweite gewirkte Zauber, die Überzaubern hervorrufen, verursachen zusätzlich 10 Überzaubern. Dieser Geist stirbt nach 30...240 Sekunden.','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10 (30...240 Sekunden Lebensdauer). Überzaubern verursachende Zauber, die in seiner Reichweite gewirkt werden, verursachen zusätzlich 10 Überzaubern.'],
1213=>['Ruhe','Naturritual. Erstellt einen Geist der Stufe 1...10. Von Kreaturen in seiner Reichweite, die keine Geister sind, gewirkte Verzauberungen enden 20...50% schneller. Dieser Geist stirbt nach 15...120 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (15...120 Sekunde[n] Lebensdauer). Verzauberungen enden bei Kreaturen in Reichweite um 20...50% schneller. Keine Wirkung auf Geister.'],
1215=>['Gezeter der Seelen','Elite-Zauber. Der Gegner und alle Feinde in der Nähe erleiden 10...65 Punkt[e] Blitzschaden. Wenn Ihr Euch in Hörweite eines Geistes befindet oder einen gebündelten Gegenstand haltet, erhaltet Ihr 10 Energiepunkt[e].','Elite-Zauber. Richtet beim Gegner und bei Feinden in der Nähe 10...65 Blitzschaden an. Ihr erhaltet 10 Energie, wenn Ihr in Hörweite eines Geistes seid oder einen gebündelten Gegenstand haltet.'],
1217=>['Herr der Rituale','Elite-Fertigkeit. 5...35 Sekunde[n] lang erhalten Eure Ritualisten-Attribute einen Schub von 2...4 für Eure nächste Fertigkeit. Wenn diese Fertigkeit ein Binderitual ist, wird sie um 10...60% schneller wieder aufgeladen und Herr der Rituale lädt sich sofort wieder auf.','Elite-Fertigkeit. (5...35 Sekunde[n].) Ihr erhaltet +2...4 auf alle Ritualisten-Attribute für Eure nächste Fertigkeit. Wenn diese Fertigkeit ein Binderitual ist, wird sie um 10...60% schneller wieder aufgeladen und Herr der Rituale lädt sich sofort wieder auf.'],
1218=>['Grausam war Daoshen','Gegenstandszauber. Haltet Daoshens Asche bis zu 15...60 Sekunde[n] lang. Während Ihr seine Asche haltet, haben alle Ritualisten-Fertigkeiten eine Rüstungsdurchdringung von 10%. Wenn Ihr seine Asche fallen lasst, erleiden alle Feinde in der Nähe 15...85 Punkt[e] Blitzschaden.','Gegenstandszauber. (15...60 Sekunde[n].) Eure Ritualisten-Fertigkeiten haben eine Rüstungsdurchdringung von 10%. Fallwirkung: Richtet bei allen Feinden in der Nähe 15...85 Punkt[e] Blitzschaden an.'],
1219=>['Schützend war Kaolai','Gegenstandszauber. Haltet Kaolais Asche bis zu 15...60 Sekunde[n] lang. Während Ihr seine Asche haltet, erhaltet Ihr 20 Rüstung. Wenn Ihr seine Asche fallen lasst, werden alle Gruppenmitglieder um 20...95 Lebenspunkt[e] geheilt.','Gegenstandszauber. 15...60 Sekunde[n]: Ihr habt +20 Rüstung. Fallwirkung: Alle Gruppenmitglieder werden um 20...95 Lebenspunkt[e] geheilt.'],
1220=>['Eingestimmt war Songkai','Elite-Gegenstandszauber. Haltet Songkais Asche bis zu 45 Sekunde[n] lang. Während Ihr ihre Asche haltet, kostet das Wirken Eurer Zauber und Binderituale bis zu -5...50% weniger Basisenergie.','Elite-Gegenstandszauber. 45 Sekunde[n]: Das Wirken Eurer Zauber und Binderituale kostet 5...50% der Basis-Energiekosten weniger.'],
1221=>['Unverwüstlich war Xiko','Gegenstandszauber. Haltet Xikos Asche bis zu 5...20 Sekunde[n] lang. Für jede Verhexung und jeden Zustand, unter der bzw. dem Ihr leidet, solange Ihr die Asche haltet, erhaltet Ihr +3 Lebenspunktregeneration. Wenn Ihr die Asche fallen lasst, verliert Ihr 1...4 Zustände.','Gegenstandszauber. 5...20 Sekunde[n]: Für jede Verhexung und jeden Zustand auf Euch habt Ihr +3 Lebenspunktregeneration. Fallwirkung: Ihr verliert 1...4 Zustände.'],
1222=>['Lebhaft war Naomei','Gegenstandszauber. Haltet Naomeis Asche bis zu 45 Sekunde[n] lang. Wenn Ihr ihre Asche fallen lasst, werden alle Gruppenmitglieder in dem Bereich mit 15...75% ihrer Lebenspunkte und 0 Energie wiederbelebt.','Gegenstandszauber. 45 Sekunde[n]: Fallwirkung: Gruppenmitglieder im Bereich werden wiederbelebt (15...75% Lebenspunkte, 0 Energiepunkte).'],
1223=>['Gequält war Lingwah','Gegenstandszauber. Haltet Lingwahs Asche bis zu 10...60 Sekunde[n] lang. Während Ihr ihre Asche haltet, kosten Eure Ritualisten-Verhexungen 1...5 weniger Energiepunkt[e] und halten um 50% länger an. Wenn Ihr ihre Asche fallen lasst, werden alle Eure Ritualisten-Verhexungen wieder aufgeladen.','Gegenstandszauber. (10...60 Sekunde[n].) Eure Ritualisten-Verhexungen kosten 1...5 weniger Energiepunkt[e] und halten um 50% länger an. Fallwirkung: Alle Eure Ritualisten-Verhexungen werden wieder aufgeladen.'],
1224=>['Geist entziehen','Zauber. Teleportiert den verbündeten Geist an Eure Position.','Zauber. Teleportiert den verbündeten Geist an Eure Position.'],
1225=>['Gelenkter Schlag','Zauber. Der Gegner erleidet 5...95 Punkt[e] Blitzschaden. Dieser Gegner erleidet zusätzlich 5...35 Punkt[e] Blitzschaden, wenn Ihr einen Gegenstand haltet.','Zauber. Richtet 5...95 Punkt[e] Blitzschaden an. Richtet zusätzlich 5...35 Punkt[e] Blitzschaden an, falls Ihr einen Gegenstand haltet.'],
1226=>['Geistersegenstoß','Zauber. Der Gegner erleidet 20...65 Punkt[e] Blitzschaden und alle von Euch kontrollierten Geister in Hörweite erhalten 20...65 Lebenspunkt[e].','Zauber. Richtet 20...65 Punkt[e] Blitzschaden an. Von Euch kontrollierte Geister in Hörweite erhalten 20...65 Lebenspunkt[e].'],
1227=>['Essenzschlag','Zauber. Der Gegner erleidet 15...60 Punkt[e] Blitzschaden. Wenn sich Geister in Hörweite befinden, erhaltet Ihr 1...9 Energiepunkt[e].','Zauber. Richtet 15...60 Punkt[e] Blitzschaden an. Ihr erhaltet 1...9 Energiepunkt[e], falls sich Geister in Hörweite befinden.'],
1228=>['Geist abzapfen','Zauber. Der Euch am nächsten stehende Geist verliert seine gesamte Energie. Ihr erhaltet 30...60% dieser Energie.','Zauber. Der Euch am nächsten stehende Geist verliert seine gesamte Energie. Ihr erhaltet 30...60% dieser Energie.'],
1229=>['Explosives Wachstum','Verzauberung. Während der nächsten 15...60 Sekunde[n] erleiden jedes Mal, wenn Ihr eine Kreatur erschafft, bis zu 5 Gegner neben dieser Kreatur 20...65 Punkt[e] Blitzschaden.','Verzauberung. 15...60 Sekunde[n]: Richtet jedes Mal, wenn Ihr eine Kreatur erstellt, bei 5 Feind[en] in deren Nähe 20...65 Punkt[e] Blitzschaden an.'],
1230=>['Segen der Schöpfung','Verzauberung. 15...60 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn Ihr eine Kreatur erschafft, 5...50 Lebenspunkt[e] und 1...6 Energiepunkt[e].','Verzauberung. 15...60 Sekunde[n]: Ihr erhaltet jedes Mal 5...50 Lebenspunkt[e] und 1...6 Energiepunkt[e], wenn Ihr eine Kreatur erstellt.'],
1231=>['Geisterlenkung','Elite-Verzauberung. 12 Sekunde[n] lang habt Ihr +1...6 Energieregeneration. Wenn Ihr Euch beim Wirken dieses Zaubers in Hörweite eines Geistes befindet, erhaltet Ihr 3...12 Energiepunkt[e].','Elite-Verzauberung. (12 Sekunde[n].) Ihr habt +1...6 Energieregeneration. Anfangswirkung: Ihr erhaltet 3...12 Energiepunkt[e], wenn Ihr Euch in Hörweite eines Geistes befindet.'],
1232=>['Rüstung der Gefühllosigkeit','Fertigkeit. 10...35 Sekunde[n] lang verringert sich der von Euren Geistern in Hörweite erlittene Schaden um 50% und sie sind gegen kritische Treffer gefeit.','Fertigkeit. (10...35 Sekunde[n].) Eure Geister in Hörweite erleiden 50% weniger Schaden und sind gegen kritische Treffer gefeit.'],
1233=>['Beruhigende Erinnerungen','Zauber. Der Verbündete (bzw. Ihr selbst) wird um 10...100 Lebenspunkt[e] geheilt. Wenn Ihr einen Gegenstand haltet, erhaltet Ihr 3 Energiepunkt[e].','Zauber. Heilt um 10...100 Lebenspunkt[e]. Ihr erhaltet 3 Energiepunkt[e], falls Ihr einen Gegenstand haltet.'],
1234=>['Körper und Seele heilen','Zauber. Heilt Verbündeten (bzw. Euch selbst) um 20...115 Lebenspunkt[e]. Der betreffende Verbündete verliert für jeden verbündten Geist in Hörweite einen Zustand.','Zauber. Heilt um 20...115 Lebenspunkt[e]. Entfernt für jeden Geist in Hörweite einen Zustand.'],
1235=>['Stumpfe Waffe','Verhexung. 5...20 Sekunde[n] lang können der Gegner und alle umstehenden Feinde in der Nähe keine kritischen Treffer landen und verursachen 3...20 Punkt[e] weniger Schaden.','Verhexung. Verhext den Gegner sowie umstehende Feinde (5...20 Sekunde[n]). Entfernt die Fähigkeit, kritische Treffer zu landen. Reduziert den Schaden um 3...20 Punkt[e].'],
1236=>['Fesselnde Ketten','Verhexung. Während der nächsten 3 Sekunde[n] bewegen sich der Gegner und alle umstehenden Feinde um 90% langsamer und erleiden 1...30 Punkt[e] Schaden pro Sekunde, solange sie in Bewegung sind.','Verhexung. Verhext außerdem den Gegner umstehende Feinde (3 Sekunde[n]). Diese Gegner bewegen sich um 90% langsamer und erleiden jede Sekunde 1...30 Punkt[e] Schaden, solange sie in Bewegung sind.'],
1237=>['Schmerzhafte Bindung','Verhexung. 10...20 Sekunde[n] lang werden der Gegner und alle Feinde in der Nähe mit Schmerzhafte Bindung verhext und erleiden jedes Mal, wenn sie von einem Geisterangriff getroffen werden, 8...20 Punkt[e] Schaden.','Verhexung. Verhext den Gegner und Feinde in der Nähe (10...20 Sekunde[n]). Geister richten bei den Betroffenen +8...20 Punkt[e] Schaden an.'],
1238=>['Siegel der Schöpfung','Siegel. Ihr erhaltet 4 Energiepunkt[e] für jede von Euch kontrollierte herbeigerufene Kreatur in Hörweite (maximal 3...12 Energiepunkte).','Siegel. Ihr erhaltet 4 Energiepunkt[e] für jede von Euch kontrollierte herbeigerufene Kreatur in Hörweite (maximal 3...12 Energiepunkte).'],
1239=>['Siegel der Geister','Elite-Siegel. Erstellt 3 Geister der Stufe 1...12. Diese Geister fügen mit Angriffen 5...20 Punkt[e] Schaden zu und sterben nach 60 Sekunde[n].','Elite-Siegel. Erstellt 3 Geister der Stufe 1...12 (60 Sekunde[n] Lebensdauer). Diese Geister fügen mit Angriffen 5...20 Punkt[e] Schaden zu.'],
1240=>['Seelenverflechtung','Elite-Fertigkeit. 5...45 Sekunde[n] lang kosten Eure Binderituale 15 weniger Energiepunkte (mindestens 5) und laden sich sofort wieder auf. Seelenverflechtung endet nach 1...3 Binderitual[en].','Elite-Fertigkeit. (5...45 Sekunde[n].) Eure Binderituale 15 kosten weniger Energiepunkte (mindestens 5) und laden sich sofort wieder auf. Endet nach 1...3 Binderitual[en].'],
1244=>['Geisterhafte Eile','Verzauberung. Während der nächsten 5...30 Sekunde[n] werden in Hörweite eines Geistes von Euch gewirkte Zauber um 25% schneller wieder aufgeladen.','Verzauberung. 5...30 Sekunde[n]: Von Euch gewirkte Zauber laden sich um 25% schneller wieder auf. Ihr müsst Euch in Hörweite eines Geistes befinden, sonst keine Wirkung.'],
1245=>['Blick aus dem Jenseits','Zauber. Der Gegner erleidet 20...65 Punkte Blitzschaden. Wenn Ihr Euch in Hörweite eines Geistes befindet, wird der Gegner 2...6 Sekunde[n] lang geblendet.','Zauber. Richtet 20...65 Punkt[e] Blitzschaden an. Verursacht den Zustand Blindheit (2...6 Sekunde[n]), falls Ihr Euch in Hörweite eines Geistes befindet.'],
1246=>['Wut der Vorfahren','Fertigkeit. 1 Sekunde[n] lang geschieht nichts. Wenn diese Fertigkeit endet, erleiden alle den Verbündeten (bzw. Euch selbst) umstehenden Feinde 5...110 Punkt[e] Blitzschaden.','Fertigkeit. 1 Sekunde[n]: Wirkung am Ende: Richtet bei umstehenden Feinden um den Verbündeten (bzw. Euch selbst) 5...110 Punkt[e] Blitzschaden an.'],
1247=>['Schmerzen','Binderitual. Erstellt einen Geist der Stufe 1...12. Die Angriffe dieses Geistes fügen 5...30 Punkt[e] Schaden zu. Dieser Geist stirbt nach 30...150 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...12 (30...150 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...30 Punkt[e] Schaden an.'],
1249=>['Verschiebung','Binderitual. Erstellt einen Geist der Stufe 1...14. Alle Verbündeten in seiner Reichweite, die keine Geister sind, haben eine 75%ige Chance, Angriffe zu blocken. Jedes Mal, wenn ein Angriff auf diese Weise geblockt wird, erleidet dieser Geist 60 Punkt[e] Schaden. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...14 (30...60 Sekunde[n] Lebensdauer). Verbündete in Reichweite, die keine Geister sind, haben eine 75%ige Chance zu blocken. Blockwirkung: Der Geist erleidet 60 Punkt[e] Schaden.'],
1250=>['Erhaltung','Elite-Binderitual. Erstellt einen Geist der Stufe 1...14. Dieser Geist heilt alle 4 Sekunden einen Verbündeten in dem Bereich, der kein Geist ist, um 10...115 Lebenspunkt[e]. Dieser Geist stirbt nach 90 Sekunde[n].','Elite-Binderitual. Erstellt einen Geist der Stufe 1...14 (90 Sekunde[n] Lebensdauer). Alle 4 Sekunden heilt der Geist einen Verbündeten, der kein Geist ist, um 10...115 Lebenspunkt[e].'],
1251=>['Leben','Binderitual. Erstellt einen Geist der Stufe 1...14. Wenn dieser Geist stirbt, werden alle Verbündeten in seiner Reichweite, die keine Geister sind, pro Sekunde, die der Geist am Leben war, um 1...7 Lebenspunkt[e] geheilt. Dieser Geist stirbt nach 20 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...14 (20 Sekunde[n] Lebensdauer). Betrifft Verbündete in Reichweite, die keine Geister sind. Wirkung am Ende: Heilt pro Sekunde, die der Geist am Leben war, um 1...7 Lebenspunkt[e].'],
1252=>['Erdbindung','Binderitual. Erstellt einen Geist der Stufe 1...14. Alle Gegner, die keine Geister sind, die in seiner Reichweite zu Boden geworfen werden, bleiben mindestens 3 Sekunden lang am Boden. Jedes Mal, wenn dies geschieht, verliert der Geist 50...25 Lebenspunkt[e]. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...14 (15...45 Sekunde[n] Lebensdauer). Feinde in Reichweite, die keine Geister sind und zu Boden geworfen werden, bleiben mindestens 3 Sekunden lang am Boden. Bodenwurfkosten: Der Geist verliert 50...25 Lebenspunkt[e].'],
1253=>['Blutgesang','Binderitual. Erstellt einen Geist der Stufe 1...12, der nach 30...150 Sekunde[n] stirbt. Angriffe durch diesen Geist entziehen bis zu 5...25 Lebenspunkt[e]','Binderitual. Erstellt einen Geist der Stufe 1...12 (30...150 Sekunde[n] Lebensdauer). Seine Angriffe entziehen 5...25 Lebenspunkt[e].'],
1255=>['Fernweh','Elite-Binderitual. Erstellt einen Geist der Stufe 1...12. Jedes Mal, wenn ein Angriff dieses Geistes einen Gegner trifft, der sich nicht bewegt, wird dieser zu Boden geworfen und der Geist verliert 70...50 Lebenspunkt[e]. Dieser Geist stirbt nach 30...60 Sekunde[n].','Elite-Binderitual. Erstellt einen Geist der Stufe 1...12 (30...60 Sekunde[n] Lebensdauer). Seine Angriffe werfen Feinde, die sich nicht bewegen, zu Boden. Bodenwurfkosten: Der Geist verliert 70...50 Lebenspunkt[e].'],
1257=>['Geisterlichtwaffe','Elite-Waffenzauber. Während der nächsten 10 Sekunde[n] erhält der Verbündete (bzw. Ihr selbst) pro Sekunde 5...25 Lebenspunkt[e] sowie zusätzlich 5...25 Lebenspunkt[e] pro Sekunde, wenn dieser Verbündete sich in Hörweite eines Geistes befindet.','Elite-Waffenzauber. (10 Sekunde[n].) Der Verbündete erhält 5...25 Lebenspunkt[e] pro Sekunde. 5...25 weitere Lebenspunkte in Hörweite eines Geistes.'],
1258=>['Grausame Waffe','Waffenzauber. Gebt dem Verbündeten (bzw. Euch selbst) 10...40 Sekunde[n] lang eine Grausame Waffe. Solange der Träger mit keiner Verzauberung belegt ist, fügt die Waffe +5...15 Punkt[e] Schaden zu.','Waffenzauber. 10...40 Sekunde[n]: Angriffe richten +5...15 Punkt[e] Schaden an. Keine Wirkung, während der Verbündete (bzw. Ihr selbst) verzaubert ist.'],
1259=>['Gelenkte Waffe','Waffenzauber. 4...10 Sekunde[n] lang können die Angriffe des Verbündeten (bzw. Eure eigenen) nicht geblockt werden.','Waffenzauber. 4...10 Sekunde[n]: Angriffe können nicht geblockt werden.'],
1260=>['Sanftmut','Verhexung. Während der nächsten 5...30 Sekunde[n] greifen der Gegner und alle Feinde in dem Bereich um 50% langsamer an.','Verhexung. Verhext Feinde im Bereich des Gegners (5...30 Sekunde[n]). Die Betroffenen greifen um 50% langsamer an.'],
1261=>['Kalte Rüstung','Verzauberung. 10...25 Sekunde[n] lang habt Ihr +10...40 Rüstung gegen physischen Schaden und könnt nicht in Brand gesetzt werden.','Verzauberung. (10...25 Sekunde[n].) Ihr habt +10...40 Rüstung gegen physischen Schaden und seid immun gegen Brennen.'],
1262=>['Heilring','Zauber. Heilt umstehende Kreaturen um 30...180 Lebenspunkt[e]. Der Wirker wird nicht geheilt.','Zauber. Heilt umstehende Verbündete und Feinde um 30...180 Lebenspunkt[e]. Der Wirker wird nicht geheilt.'],
1263=>['Leben verlängern','Zauber. Belebt das berührte tote Gruppenmitglied mit 50% seiner Lebenspunkte und 5...20% seiner Energie wieder. Das Gruppenmitglied und alle Verbündeten in Hörweite werden um 55...130 Lebenspunkt[e] geheilt.','Berührungs-Zauber. Das Gruppenmitglied wird wiederbelebt (50% Lebenspunkte, 5...20% Energiepunkte). Heilt Verbündete in Hörweite um 55...130 Lebenspunkt[e].'],
1264=>['Untergang','Zauber. Der Gegner erleidet für jedes Binderitual, das Ihr habt und das wieder aufgeladen wird, 10...60 Punkt[e] Blitzschaden (maximal 135).','Zauber. Richtet für jedes Eurer sich aufladenden Binderituale 10...60 Punkt[e] Blitzschaden an (maximal 135).'],
1265=>['Segen des Ausübers','Zauber. Heilt Verbündeten (bzw. Euch selbst) um 15...60 Punkt[e]. Wenn dieser Verbündete unter den Auswirkungen eines Waffenzaubers leidet, heilt ihn Segen des Ausübers zusätzlich für 15...75 Lebenspunkt[e].','Zauber. Heilt um 15...60 Lebenspunkt[e]. Heilt um weitere 15...75 Lebenspunkt[e], falls der Verbündete (bzw. Ihr selbst) unter dem Einfluss eines Waffenzaubers steht.'],
1266=>['Beruhigung','Binderitual. Erstellt einen Geist der Stufe 1...12. Alle Feinde in seiner Reichweite benötigen doppelt so lange, um Adrenalin aufzuladen. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...12 (15...45 Sekunde[n] Lebensdauer). Das Aufladen von Adrenalin dauert bei Feinden in Reichweite doppelt so lange.'],
1267=>['Wesentliche Waffe','Waffenzauber. 5...30 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine Wesentliche Waffe und +40...175 maximale Lebenspunkte.','Waffenzauber. 5...30 Sekunde[n]: +40...175 maximale Lebenspunkte.'],
1268=>['Waffe der Beschleunigung','Elite-Waffenzauber. 5...25 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine Waffe der Beschleunigung und Zauber und Binderituale werden um 33% schneller wieder aufgeladen.','Elite-Waffenzauber. 5...25 Sekunde[n]: Zauber und Binderituale laden sich um 33% schneller wieder auf.'],
1269=>['Siegel der Wut','Siegel. Der Gegner erleidet 5...50 Punkt[e] heiligen Schaden und +5...10 Punkt[e] heiligen Schaden für jede Adrenalinfertigkeit des Gegners.','Siegel. Richtet 5...50 Punkt[e] heiligen Schaden an. Richtet für jede Adrenalinfertigkeit des Gegners zusätzlich 5...10 Punkt[e] heiligen Schaden an.'],
1333=>['Zustände ausweiten','Elite-Zauber. Verteilt alle Zustände vom Gegner auf alle Feinde in der Nähe Eures Gegners. Die Dauer der Zustände ist um 5...100% verlängert (maximal 30 Sekunden).','Elite-Zauber. Verteilt alle Zustände vom Gegner auf alle Feinde in der Nähe Eures Gegners. Die Dauer dieser Zustände ist um 5...100% verlängert (maximal 30 Sekunden).'],
1334=>['Hypochondrie','Zauber. Alle Zustände von allen Gegnern im Bereich werden auf den Zielgegner übertragen.','Zauber. Alle Zustände von Gegnern im Bereich werden auf den Zielgegner übertragen.'],
1335=>['Ableben des Verschwenders','Verhexung. 5 Sekunde[n] lang wird der Gegner mit Ableben des Verschwenders verhext. Jede Sekunde unter der Verhexung erleidet der Gegner und alle umstehenden Gegner 1...10 Punkte Schaden und zusätzlich für jede Sekunde der aktiven Zeit des Spruchs 1...10 Punkte Schaden. Diese Verhexung endet vorzeitig, wenn der Gegner eine Fertigkeit einsetzt.','Verhexung. (5 Sekunde[n].) Jede Sekunde unter dieser Verhexung erleiden der Gegner und alle umstehende Feinde 1...10 Punkt[e] Schaden. Für jede Sekunde der Wirkungszeit dieser Verhexung nehmen Gegner weitere 1...10 Punkte Schaden. Endet vorzeitig, wenn der Gegner eine Fertigkeit einsetzt.'],
1336=>['Geisterschmerz','Zauber. Der Gegner erleidet 15...75 Punkt[e] Schaden. Alle gegnerischen herbeigerufenen Kreaturen im Bereich des Gegners erleiden 25...125 Punkt[e] Schaden.','Zauber. Richtet 15...75 Punkt[e] Schaden an. Richtet bei allen gegnerischen herbeigerufenen Kreaturen im Bereich des Gegners 25...125 Punkt[e] Schaden an.'],
1337=>['Täuschungen entziehen','Zauber. Entfernt eine Mesmer-Verhexung vom Gegner. Wenn eine Verhexung auf diese Weise entfernt wurde, verliert der Gegner 1...5 Energiepunkt[e] und Ihr erhaltet für jeden verlorenen Punkt 4 Energiepunkt[e].','Zauber. Entfernt beim Gegner eine Mesmer-Verhexung. Lässt 1...5 Energiepunkt[e] verlieren. Ihr erhaltet für jeden verlorenen Energiepunkt 4 Energiepunkt[e]. Keine Wirkung, falls keine Verhexung entfernt wird.'],
1338=>['Beharrliche Erinnerungen','Verzauberung. Während der nächsten 5...20 Sekunde[n] wird jeder von Euch gewirkte Zauber, der unterbrochen wird, sofort wieder aufgeladen.','Verzauberung. 5...20 Sekunde[n]: Eure unterbrochenen Zauber laden sich sofort wieder auf.'],
1339=>['Symbole der Inspiration','Elite-Fertigkeit. 6...40 Sekunden lang wird diese Fertigkeit zur Elite-Fertigkeit eines Zielgegners. Elite-Fertigkeiten, die Ihr wirkt, verwenden Euer Wirken-Attribut anstelle ihrer eigentlichen Attribute.','Elite-Fertigkeit. (6...40 Sekunden.) Diese Fertigkeit wird zur Elite-Fertigkeit eines Zielgegners. Elite-Fertigkeiten, die Ihr wirkt, verwenden Euer Wirken-Attribut anstelle ihrer eigentlichen Attribute.'],
1340=>['Symbolische Schnelligkeit','Verzauberung. 36...60 Sekunde[n] lang verwenden alle Eure Siegel Euer Attribut "Schnellwirkung" statt der normalen Attribute.','Verzauberung. (36...60 Sekunde[n].) Eure Siegel verwenden das Attribut "Schnellwirkung".'],
1341=>['Frustration','Verhexung. Während der nächsten 5...20 Sekunde[n] wirkt der Gegner seine Zauber um 50% langsamer und erleidet jedes Mal, wenn er unterbrochen wird, 5...50 Punkt[e] Schaden. Wird eine Fertigkeit unterbrochen, richtet Frustration doppelten Schaden an.','Verhexung. (5...20 Sekunde[n].) Verlangsamt die Wirkungszeit von Zaubern um 50%. Der Gegner erleidet 5...50 Punkt[e] Schaden, wenn er unterbrochen wird. Richtet doppelten Schaden bei unterbrochenen Fertigkeiten an.'],
1342=>['Reizen','Elite-Zauber. Falls der Gegner eine Fertigkeit verwendet, werden er selbst sowie alle Gegner im Bereich unterbrochen und Ihr entzieht allen unterbrochenen Gegnern im Bereich 0...5 Energiepunkt[e].','Elite-Zauber. Unterbricht eine Fertigkeit. Unterbrechungswirkung: Unterbricht außerdem andere Gegner im Bereich und Ihr entzieht allen Gegnern im Bereich 0...5 Energiepunkte.'],
1343=>['Äther-Phantom','Verhexung. 10 Sekunden lang unterliegt der Gegner einer Energiedegeneration von -1. Wenn diese Verhexung vorzeitig entfernt wird, verliert dieser Gegner 1...5 Energiepunkt[e].','Verhexung. 10 Sekunden: Verursacht -1 Energiedegeneration. Lässt 1...5 Energiepunkt[e] verlieren, falls diese Verhexung vorzeitig endet.'],
1344=>['Netz der Störung','Verhexung. Unterbrecht den Gegner. 10 Sekunde[n] lang ist der Gegner mit Netz der Störung verhext. Wenn diese Verhexung endet, wird der Gegner wieder unterbrochen.','Verhexung. 10 Sekunde[n]: Anfangswirkung: Unterbricht eine Fertigkeit. Wirkung am Ende: Unterbricht eine Fertigkeit.'],
1345=>['Rätsel des Verzauberers','Elite-Verhexung. Für 10 Sekunden wirkt der anvisierte Gegner Verzauberungen um 100...200 % langsamer. Steht der anvisierte Gegner nicht unter dem Einfluss einer Verzauberung, wenn ihm diese Verhexung zugefügt wird, nimmt er 10...100 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.','Elite-Verhexung. Verursacht um 100...200 % langsameres Wirken von Zaubern (10 Sekunden). Anfangseffekt: Ist der anvisierte Gegner nicht verzaubert, so nimmt er 10...100 Schaden, und benachbarte Gegner erleiden 75 % dieses Schadens.'],
1346=>['Siegel der Illusionen','Elite-Siegel. Eure nächsten 1...3 Nicht-Illusionszauber verwenden Euer Illusions-Attribut anstelle seiner normalen Attribute.','Elite-Siegel. Eure nächsten 1...3 Nicht-Illusionszauber verwenden Euer Illusions-Attribut anstelle seiner normalen Attribute.'],
1347=>['Verzauberung entlassen','Zauber. Entfernt eine Verzauberung vom Gegner. Wenn der Gegner verhext ist, wird diese Fertigkeit um 20...50% schneller wieder aufgeladen.','Zauber. Entfernt eine Verzauberung vom Gegner. Um 20...50% schnellere Aufladung, falls der Gegner verhext ist.'],
1348=>['Verhexungsfresser-Strudel','Elite-Zauber. Entfernt eine Verhexung vom anvisierten Verbündeten. Gleichzeitig erleiden Gegner in Reichweite des Verbündeten 30...90 Schaden und verlieren eine Verzauberung.','Elite-Zauber. Entfernt eine Verhexung vom anvisierten Verbündeten. Entfernen-Effekt: Verursacht 30...90 Schaden und entfernt eine Verzauberung von Gegnern im Umkreis dieses Verbündeten.'],
1349=>['Spiegel der Entzauberung','Zauber. Entfernt eine Verzauberung vom Gegner. Alle Mitglieder in der Gruppe dieses Gegner verlieren ebenfalls eine Verzauberung.','Zauber. Entfernt eine Verzauberung vom Gegner. Gruppenmitglieder des Gegners verlieren diese Verzauberung ebenfalls.'],
1350=>['Simpler Diebstahl','Elite-Zauber. Unterbricht die Aktion des Gegners. Falls diese Aktion eine Fertigkeit war, wird diese 5...20 Sekunde[n] lang deaktiviert und Simpler Diebstahl durch die Fertigkeit ersetzt.','Elite-Zauber. Unterbricht eine Aktion. Unterbrechungswirkung: Falls eine Fertigkeit unterbrochen wurde, wird diese deaktiviert und Simpler Diebstahl wird zu dieser Fertigkeit (5...20 Sekunde[n]).'],
1351=>['Schlurfschreck beleben','Zauber. Der nächste Kadaver wird als Schlurfschreck der Stufe 1...17 belebt. Wenn der Schlurfschreck stirbt, wird er durch einen Splitterschreck der Stufe 0...15 ersetzt, der bei jedem seiner Angriffe eine Blutung hervorruft.','Zauber. Erstellt einen Schlurfschreck der Stufe 1...17. Wenn der Schlurfschreck stirbt, wird er durch einen Splitterschreck der Stufe 0...15 ersetzt, der bei jedem seiner Angriffe eine Blutung hervorruft. Benutzt frischen Kadaver.'],
1352=>['Orden der Untoten','Elite-Zauber. 5 Sekunde[n] lang richten Eure Diener +3...16 Punkt[e] Schaden an, Ihr verliert jedoch jedes Mal, wenn einer Eurer Diener einen erfolgreichen Angriff durchführt, 2% Eurer maximalen Lebenspunkte.','Elite-Zauber. 5 Sekunde[n]: Eure Diener richten +3...16 Schaden an. Diener-Trefferwirkung: Ihr verliert 2% Eurer maximalen Lebenspunkte.'],
1353=>['Verwesendes Fleisch','Zauber. Vernichtet einen Eurer anvisierten belebten untoten Diener. Alle Feinde in der Nähe dieser Kreatur erkranken 5...15 Sekunde[n] lang.','Zauber. Vernichtet einen Eurer untoten Diener. Verursacht bei Feinden in der Nähe des Dieners Zustand Krankheit (5...15 Sekunde[n]).'],
1354=>['Fest für die Toten','Zauber. Vernichtet den anvisierten belebten untoten Verbündeten. Alle Eure anderen belebten untoten Verbündeten werden um 10...100 Lebenspunkt[e] geheilt.','Zauber. Vernichtet einen Eurer untoten Diener. Heilt Eure Diener um 10...100 Lebenspunkt[e].'],
1355=>['Versplitterte Knochen','Elite-Verzauberung. 60 Sekunde[n] lang wird jedes Mal, wenn der von Euch anvisierte untote Diener stirbt, dieser durch einen Splitterschreck der Stufe 0...15 ersetzt, der bei jedem seiner Angriffe eine Blutung hervorruft.','Elite-Verzauberung. 60 Sekunde[n]: Wenn der untote Diener stirbt, wird er durch einen Splitterschreck der Stufe 0...15 ersetzt, der bei jedem seiner Angriffe eine Blutung hervorruft.'],
1356=>['Erkrankung','Elite-Verzauberung. 60 Sekunde[n] lang leiden jedes Mal, wenn Ihr unter einem neuen Zustand leidet, alle Gegner in dem Bereich unter demselben Zustand und Ihr opfert 10...5% maximale Lebenspunkte.','Elite-Verzauberung. 60 Sekunde[n]: Immer wenn Ihr einen Zustand erhaltet, erhalten ihn auch alle Feinde in dem Bereich. Ihr opfert jedes Mal 10...5% Eurer maximalen Lebenspunkte, wenn dies geschieht.'],
1358=>['Geschwürige Lungen','Verhexung. 10...30 Sekunde[n] lang unterliegen der Gegner und alle in der Nähe befindlichen Feinde einer Lebenspunktdegeneration von -4, wenn sie bluten und erleiden jedes Mal, wenn sie einen Schrei oder Anfeuerungsruf anwenden, 5...20 Sekunde[n] lang eine Blutung.','Verhexung. Verhext den Gegner und Feinde in der Nähe (10...30 Sekunde[n]). Verursacht bei allen Betroffenen, die bluten, -4 Lebenspunktdegeneration. Verursacht jedes mal eine Blutung (5...20 Sekunde[n]), wenn einer der Betroffenen einen Schrei oder Anfeuerungsruf benutzt.'],
1359=>['Schmerz der Entzauberung','Elite-Zauber. Der Gegner verliert 1...3 Verzauberung[en]. Wenn eine Verzauberung auf diese Art entfernt wird, verlieren der Gegner und alle umstehenden Feinde 10...100 Lebenspunkt[e].','Elite-Zauber. Der Gegner verliert 1...3 Verzauberung[en]. Entfernungswirkung: Der Gegner und alle umstehenden Feinde verlieren 10...100 Lebenspunkt[e].'],
1360=>['Zeichen der Wut','Verhexung. 5 Sekunde[n] lang erhalten Verbündete, die den Gegner treffen, 0...2 Adrenalinstöße. Wenn diese Verhexung endet, leidet der Gegner 1...15 Sekunde[n] lang an Beschädigter Rüstung.','Verhexung. (5 Sekunde[n].) Verbündete, die den Gegner treffen, erhalten 0...2 Adrenalinstöße. Wirkung am Ende: Verursacht Beschädigte Rüstung (1...15 Sekunde[n]).'],
1362=>['Verzauberung verderben','Elite-Verhexung. Entfernt eine Verzauberung vom Gegner. Beim Entfernen einer Verzauberung auf diese Weise erleidet der Gegner 10 Sekunden lang eine Lebenspunktdegeneration von -1...8.','Elite-Verhexung. Entfernt eine Verzauberung vom Gegner. Entfernungswirkung: -1...8 Lebenspunktdegeneration (10 Sekunden).'],
1363=>['Siegel des Kummers','Siegel. Der Gegner erleidet 15...75 Punkt[e] Schaden. Wenn dieser Gegner sich in der Nähe eines Kadavers befindet oder einen toten Tiergefährten hat, wird diese Fertigkeit sofort wieder aufgeladen.','Siegel. Richtet 15...75 Punkt[e] Schaden an. Lädt sich sofort wieder auf, falls der Gegner in der Nähe eines Kadavers ist oder einen toten Tiergefährten hat.'],
1364=>['Siegel des Leidens','Elite-Siegel. Ihr leidet 6 Sekunde[n] lang unter einer Blutung. Die nächste Nekromanten-Fertigkeit, die einen Gegner trifft, verursacht 2...16 Sekunde[n] lang eine Blutung.','Elite-Siegel. Ihr leidet 6 Sekunde[n] lang unter einer Blutung. Das Ziel Eurer nächsten Nekromanten-Fertigkeit erleidet eine Blutung (2...16 Sekunde[n]).'],
1365=>['Siegel der verlorenen Seelen','Siegel. Wenn die Lebenspunkte des Gegners unter 50% liegen, erhaltet Ihr 10...100 Lebenspunkt[e] und 1...10 Energiepunkt[e].','Siegel. Ihr erhaltet 10...100 Lebenspunkt[e] und 1...10 Energiepunkt[e], falls der Gegner weniger als 50% seiner maximalen Lebenspunkte hat.'],
1366=>['Brunnen der Dunkelheit','Brunnenzauber. Nutzt die nächstbeste Leiche oder opfert 66 % Eurer Lebenspunkte, um für 5...50 Sekunden einen Brunnen der Dunkelheit zu erzeugen. Verhexte Gegner innerhalb des Brunnens verfehlen 50 % der Zeit ihr Ziel.','Brunnenzauber. (5...50 Sekunden). Verhexte Gegner in diesem Brunnen haben eine Chance von 50 % auf einen Fehlschlag. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
1367=>['Blendende Welle','Elite-Zauber. Der Gegner erleidet 5...50 Punkt[e] Blitzschaden. Der Gegner und alle umstehenden Feinde werden 3...8 Sekunde[n] lang geblendet. Dieser Zauber hat eine Rüstungsdurchdringung von 25%. Wenn dieser Zauber einen angreifenden Gegner trifft, werden alle umstehenden Feinde ebenfalls getroffen und dieser Zauber richtet 50% mehr Schaden an.','Elite-Zauber. Richtet 5...50 Punkt[e] Blitzschaden an. Verursacht Blindheit beim Gegner und allen umstehenden Feinden (3...8 Sekunde[n]). 25% Rüstungsdurchdringung. Falls der Gegner gerade angreift, werden auch umstehende Feinde getroffen und dieser Zauber richtet 50% mehr Schaden an.'],
1368=>['Kühle Winde','Verhexung. Der anvisierte Gegner erleidet gemeinsam mit allen umstehenden Feinden 30...60 Punkte Kälteschaden. Für 10 Sekunden hält die nächste auf den verhexten Gegner gerichtete Wassermagie-Verhexung um 25...100% länger an.','Verhexung. (10 Sekunden.) Die nächste Wasser-Verhexung auf dem Gegner hält um 25...100% länger an. Anfangswirkung: Richtet 30...60 Punkte Kälteschaden an. Trifft auch umstehende Gegner.'],
1369=>['Blitzstrahl','Zauber. Sendet einen Blitzstrahl aus, der, falls er trifft, 5...50 Punkt[e] Blitzschaden zufügt. Falls Blitzstrahl einen angreifenden Gegner trifft, erleidet dieser 5...50 Punkt[e] zusätzlichen Blitzschaden. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Zauber. Geschoss: Richtet 5...50 Punkt[e] Blitzschaden an. Richtet zusätzlich 5...50 Punkt[e] Blitzschaden an, falls der Gegner sich bewegt. 25% Rüstungsdurchdringung.'],
1370=>['Eile des Sturm-Dschinn','Verzauberung. 10...25 Sekunde[n] lang bewegt Ihr Euch um 25% schneller. Ihr verliert pro Sekunde, die Ihr Euch bewegt, 1 Energiepunkt[e].','Verzauberung. (10...25 Sekunde[n].) Ihr bewegt Euch um 25% schneller. Ihr verliert pro Sekunde, die Ihr Euch bewegt, 1 Energiepunkt[e].'],
1371=>['Steinschläger','Verzauberung. Während der nächsten 5...30 Sekunde[n] wird jeder Elementar- oder physische Schaden, den Ihr nehmt oder zufügt, in Erdschaden umgewandelt.','Verzauberung. (5...30 Sekunde[n].) Wandelt von Euch erlittenen oder angerichteten physischen und Elementarschaden in Erdschaden um.'],
1372=>['Sandsturm','Elite-Zauber. An der Position des Gegners wird ein Sandsturm erzeugt. In den nächsten 10 Sekunde[n] werden Gegner in der Nähe mit 20...40 Punkt[en] Erdschaden pro Sekunde getroffen. Angreifende Feinde werden pro Sekunde zusätzlich mit 10...30 Punkt[en] Erdschaden getroffen.','Elite-Zauber. Richtet jede Sekunde 20...40 Punkt[e] Erdschaden an (10 Sekunde[n]). Trifft Feinde in der Nähe der anfänglichen Position des Gegners. Richtet bei angreifenden Feinden zusätzlich 10...30 Punkt[e] Erdschaden pro Sekunde an.'],
1373=>['Steinmantel','Elite-Verzauberung. 5...20 Sekunde[n] lang habt Ihr und ein Verbündeter +1...30 Rüstung und seid gegen kritische Treffer immun. Wenn Ihr diesen Zauber wirkt, erleiden alle Feinde in Eurer Nähe und in der Nähe Eures Ziels 15...70 Punkt[e] Erdschaden und sind 5...20 Sekunde[n] lang geschwächt.','Elite-Verzauberung. (5...20 Sekunde[n].) Ihr und ein Verbündeter habt +1...30 Rüstung und seid gegen kritische Treffer immun. Anfangswirkung: Feinde in Eurer Nähe und in der Nähe Eures Ziels erleiden 15...70 Punkt[e] Erdschaden und leiden unter Schwäche (5...20 Sekunde[n]).'],
1374=>['Ebonfalke','Zauber. Sendet ein Geschoss aus, das dem Gegner 10...85 Punkt[e] Erdschaden zufügt und 5...15 Sekunde[n] lang Schwäche verursacht, wenn es trifft.','Zauber. Geschoss: Richtet 10...85 Punkt[e] Erdschaden an und verursacht Zustand Schwäche (5...15 Sekunde[n]).'],
1375=>['Steinfleisch-Aura','Verzauberung. 5...15 Sekunde[n] lang wird der Schaden, den Ihr erleidet um 1...31 Punkt[e] reduziert und Ihr seid immun gegen kritische Angriffe.','Verzauberung. (5...15 Sekunde[n].) Reduziert von Euch erlittenen Schaden um 1...31 Punkt[e] und Ihr seid gegen kritische Treffer immun.'],
1376=>['Glyphe der Wiederherstellung','Glyphe. 15 Sekunden lang heilen Euch Eure nächsten 2 Zauber um 30...105 Lebenspunkt[e] und Ihr erfahrt Heilung in Höhe von 150...400% der Energiekosten dieser Zauber.','Glyphe. (15 Sekunden.) Eure nächsten 2 Zauber heilen Euch um 30...105 Lebenspunkt[e]. Zusätzlich werdet Ihr um 150...400% der Energiekosten dieser Zauber geheilt.'],
1377=>['Ätherprisma','Elite-Fertigkeit. 3 Sekunde[n] lang wird der Schaden, den Ihr erleidet, um 75% reduziert. Wenn Ätherprisma endet, erhaltet Ihr 5...20 Energiepunkt[e].','Elite-Fertigkeit. (3 Sekunde[n].) Sämtlicher Schaden, den Ihr erleidet, wird um 75% reduziert. Wirkung am Ende: Erhaltet 5...20 Energiepunkt[e].'],
1378=>['Meister der Magie','Elite-Verzauberung. 1...61 Sekunden lang werden alle Eure Elementarattribute auf 8...14 gesetzt, und Eure Elementarzauber geben 1 Energie plus 30 % ihrer Kosten zurück.','Elite-Verzauberung. (1...61 Sekunden.) Eure Elementarattribute werden auf 8...14 gesetzt, Elementarzauber geben 1 Energie plus 30 % ihrer Kosten zurück.'],
1379=>['Glühender Blick','Zauber. Der Gegner erleidet 5...50 Punkt[e] Feuerschaden. Wenn er in Flammen steht, erhaltet Ihr 5 Energiepunkt[e] sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung.','Zauber. Richtet 5...50 Punkt[e] Feuerschaden an. Ihr erhaltet 5 Energiepunkt[e] sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung, wenn der Gegner brennt.'],
1380=>['Hitze der Savanne','Elite-Zauber. An der Position des Gegners wird Hitze der Savanne erzeugt. In den nächsten 5 Sekunde[n] erleiden alle Gegner in der Nähe 5...20 Punkt[e] Feuerschaden pro Sekunde der Wirkzeit des Zaubers.','Elite-Zauber. Richtet pro Sekunde ab dem Wirken des Spruchs (5 Sekunde[n]) 5...20 Punkt[e] Feuerschaden an. Trifft Feinde in der Nähe der ursprünglichen Position des Ziels.'],
1381=>['Eile des Flammen-Dschinn','Verzauberung. Alle umstehenden Feinde erleiden 15...120 Punkt[e] Feuerschaden. Ihr bewegt Euch 8...14 Sekunde[n] lang um 25% schneller. Eile des Flammen-Dschinn wird um 50% schneller wieder aufgeladen, wenn ein Gegner von einem Zauber getroffen wird.','Verzauberung. (8...14 Sekunde[n].) Ihr bewegt Euch um 25% schneller. Anfangswirkung: Richtet bei umstehenden Feinden 15...120 Punkt[e] Feuerschaden an. Falls Ihr einen Feind mit diesem Zauber schädigt, wird er um 50% schneller wieder aufgeladen.'],
1382=>['Gefrierende Böe','Verhexung. Wenn der Gegner an den Auswirkungen einer Wassermagie-Verhexung leidet, erleidet er 20...80 Punkt[e] Kälteschaden. Ansonsten bewegt er sich 1...5 Sekunde[n] lang um 66% langsamer.','Verhexung. Richtet 20...80 Punkt[e] Kälteschaden an, falls der Gegner mit Wassermagie verhext ist. Ansonsten bewegt er sich um 66% langsamer (1...5 Sekunde[n]).'],
1390=>['Intervention des Richters','Verzauberung. 10 Sekunden lang wird das nächste Mal, wenn der Verbündete (oder Ihr selbst) Schaden erleidet, der tödlich wäre, dieser Schaden aufgehoben und ein Feind in der Nähe erleidet 30...180 Punkt[e] heiligen Schaden.','Verzauberung. 10 Sekunden: Hebt den nächsten Schaden auf, der zum Tod führen würde. Aufhebungswirkung: Richtet bei einem Feind in der Nähe des Verbündeten (bzw. Euch selbst) 30...180 Punkt[e] heiligen Schaden an.'],
1391=>['Unterstützender Geist','Verzauberung. 5...23 Sekunde[n] lang wird der Verbündete (bzw. Ihr selbst) jedes Mal, wenn er Schaden erleidet, während er am Boden liegt, um 5...50 Lebenspunkt[e] geheilt.','Verzauberung. 5...23 Sekunde[n]: Heilt jedes Mal um 5...50 Lebenspunkt[e], wenn der Verbündete (bzw. Ihr selbst) Schaden erleidet, während er zu Boden geworfen ist.'],
1392=>['Wachsame Heilung','Verzauberung. 10 Sekunden lang erhält der Verbündete (bzw. Ihr selbst) eine Lebenspunktregeneration von +1...4. Wenn diese Fertigkeit vorzeitig endet, erhält dieser Verbündete 30...120 Lebenspunkt[e].','Verzauberung. 10 Sekunden: Der Verbündete (bzw. Ihr selbst) hat +1...4 Lebenspunktregeneration und erhält 30...120 Lebenspunkt[e], falls diese Verzauberung vorzeitig endet.'],
1393=>['Segen des Heilers','Elite-Verzauberung. 10...55 Sekunde[n] lang werden Heilgebet-Zauber um 50% schneller gewirkt und heilen um 50% mehr Lebenspunkte.','Elite-Verzauberung. 10...55 Sekunde[n]: Ihr könnt Eure Heilgebet-Zauber um 50% schneller wirken. Erhöht ihre Heilwirkung um 50%.'],
1394=>['Verpflichtung des Heilers','Elite-Verzauberung. Während Ihr diese Verzauberung aufrechterhaltet, heilen Eure Heilgebet-Zauber um 20% weniger Lebenspunkte, kosten dafür aber -1...4 Energiepunkt[e].','Elite-Verzauberung. Eure Heilgebet-Zauber kosten 1...4 Energiepunkt[e] weniger. Verringert ihre Heilwirkung um 20%.'],
1395=>['Balthasars Pendel','Elite-Verzauberung. 5...25 Sekunde[n] lang wird das nächste Mal, wenn der Verbündete (bzw. Ihr selbst) durch einen Gegner zu Boden geworfen würde, stattdessen dieser Gegner zu Boden geworfen.','Elite-Verzauberung. 5...25 Sekunde[n]: Wirft den nächsten Feind zu Boden, der versucht, den Verbündeten (bzw. Euch selbst) zu Boden zu werfen.'],
1396=>['Tröstende Worte','Zauber. Der Verbündete wird um 20...65 Lebenspunkt[e] geheilt und zusätzlich um 20...50 Lebenspunkt[e], wenn er unter einem Zustand leidet.','Zauber. Heilt um 20...65 Lebenspunkt[e]. Heilt um weitere 20...50 Lebenspunkt[e], falls der Verbündete (bzw. Ihr selbst) einen Zustand hat.'],
1397=>['Licht der Erlösung','Elite-Zauber. Alle Gruppenmitglieder werden um 5...70 Lebenspunkt[e] geheilt.','Elite-Zauber. Heilt die gesamte Gruppe um 5...70 Lebenspunkt[e].'],
1398=>['Geißelverzauberung','Verhexung. 30 Sekunde[n] lang erleidet der Wirker dieser Verzauberung jedes Mal, wenn der Gegner Ziel einer Verzauberung ist, 15...75 Punkt[e] Schaden.','Verhexung. 30 Sekunde[n]: Richtet bei jedem, der eine Verzauberung auf den Gegner wirkt, 15...75 Punkt[e] Schaden an.'],
1399=>['Schild der Absorption','Verzauberung. 3...7 Sekunde[n] lang ist Schaden, den der Verbündete (bzw. Ihr selbst) erleidet, für jeden Treffer, den dieser Verbündete erleidet, während er unter dieser Verzauberung steht, um 5 Punkt[e] reduziert.','Verzauberung. 3...7 Sekunde[n]: Reduziert erlittenen Schaden jedes Mal um 5 Punkt[e], wenn der Verbündete (bzw. Ihr selbst) Schaden erleidet.'],
1400=>['Umkehrung des Schadens','Verzauberung. 8 Sekunden lang erleidet das nächste Mal, wenn der Verbündete (bzw. Ihr selbst) Schaden erleiden würde, der Feind, der den Schaden zufügt, ihn stattdessen selbst (maximal 5...75 Punkt[e].','Verzauberung. 8 Sekunden: Hebt den nächsten Schaden auf und trifft den Verursacher für dieselbe Punktzahl (maximal 5...75).'],
1401=>['Genesungsberührung','Zauber. Der berührte Verbündete verliert zwei Zustände und wird für jeden Zustand, der auf diese Weise entfernt wird, um 15...60 Lebenspunkt[e] geheilt.','Berührungs-Zauber. Entfernt zwei Zustände. Heilt für jeden entfernten Zustand um 15...60 Lebenspunkt[e].'],
1402=>['Kritischer Hieb','Axtangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn dieser Angriff zu einen kritischen Treffer führt, wird der Gegner unterbrochen.','Axtangriff. Richtet +5...20 Punkt[e] Schaden an. Unterbricht eine Aktion, falls Ihr einen kritischen Treffer landet.'],
1403=>['Qualvoller Hieb','Axtangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Euer Gegner an einer Tiefen Wunde leidet, unterbrecht Ihr seine Aktion.','Axtangriff. Richtet +5...20 Punkt[e] Schaden an. Unterbricht eine Aktion, falls Gegner eine Tiefe Wunde hat.'],
1404=>['Dreschen','Haltung. 1...15 Sekunde[n] lang greift Ihr um 33% schneller an, bewegt Euch aber um 33% langsamer.','Haltung. 1...15 Sekunde[n]: Ihr greift um 33% schneller an. Ihr bewegt Euch um 33% langsamer.'],
1405=>['Angreifender Schlag','Elite-Haltung. 1...10 Sekunde[n] lang lauft Ihr um 33% schneller. Euer nächster erfolgreicher Nahkampftreffer fügt +10...90 Punkt[e] Schaden zu und diese Haltung endet. Diese Haltung endet, wenn Ihr eine Fertigkeit verwendet.','Elite-Haltung. 1...10 Sekunde[n]: Ihr bewegt Euch um 33% schneller und richtet mit Eurem nächsten Nahkampftreffer +10...90 Punkt[e] Schaden an. Endet, wenn Ihr trefft oder eine Fertigkeit benutzt.'],
1406=>['Kopfstoß','Elite-Fertigkeit. Der berührte Gegner erleidet 40...100 Punkt[e] Schaden. Ihr leidet 10 Sekunde[n] lang unter Benommenheit.','Elite-Berührungs-Fertigkeit. Richtet 40...100 Punkt[e] Schaden an. Ihr seid benommen (10 Sekunde[n]).'],
1407=>['Trost des Löwen','Fertigkeit. Alle Eure Siegel werden 12 Sekunden lang deaktiviert. Ihr werdet um 50...110 Lebenspunkt[e] geheilt und erhaltet 0...3 Adrenalinstöße.','Fertigkeit. Ihr werdet um 50...110 Lebenspunkt[e] geheilt und erhaltet 0...3 Adrenalinstöße. Deaktiviert Eure Siegel (12 Sekunden).'],
1408=>['Wut des Ntouka','Elite-Fertigkeit. Erhaltet 1...7 Adrenalinstöße. Während der nächsten 8 Sekunde[n] wird jedes Mal, wenn Ihr eine Adrenalinfertigkeit verwendet, diese 3 Sekunde[n] lang wieder aufgeladen.','Elite-Fertigkeit. Ihr erhaltet 1...7 Adrenalinstöße. Adrenalinfertigkeiten laden sich nach Benutzung innerhalb von 3 Sekunde[n] wieder auf (8 Sekunde[n]).'],
1409=>['Mokele-Schlag','Hammerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu und erhaltet 2 Adrenalinstöße.','Hammerangriff. Richtet +5...20 Punkt[e] Schaden an und Ihr erhaltet 2 Adrenalinstöße.'],
1410=>['Anmaßender Schlag','Hammerangriff. Wenn dieser Angriff erfolgreich ist, verursacht Ihr +1...20 Punkt[e] Schaden. Wenn der Gegner zu Boden geworfen wird, leidet er 1...8 Sekunde[n] lang an Benommenheit.','Hammerangriff. Fügt +1...20 Punkt[e] Schaden zu. Wenn der Gegner zu Boden geworfen wird, leidet er 1...8 Sekunde[n] lang an Benommenheit.'],
1411=>['Siegel der Ausdauer','Siegel. Ihr verfügt über +50...300 Lebenspunkt[e]. Dieses Siegel endet, wenn Ihr einen erfolgreichen Angriff durchführt.','Siegel. Ihr habt +50...300 maximale Lebenspunkte. Endet, wenn Ihr mit einem Angriff trefft.'],
1412=>['"Ihr seid ganz allein!"','Elite-Schrei. Wenn sich der Gegner nicht in der Nähe eines Verbündeten befindet, leidet er 8 Sekunde[n] lang an einer Verkrüppelung und an Schwäche.','Elite-Schrei. Verursacht Zustände Verkrüppelung und Schwäche (8 Sekunde[n]). Keine Wirkung, falls der Gegner in der Nähe eines seiner Verbündeten ist.'],
1413=>['Aggressiver Ausbruch','Haltung. 2...10 Sekunde[n] lang greift Ihr um 33% schneller an. Wenn diese Haltung endet, verliert Ihr Euer gesamtes Adrenalin.','Haltung. 2...10 Sekunde[n]: Ihr greift um 33% schneller an. Wirkung am Ende: Ihr verliert alles Adrenalin.'],
1414=>['Wütender Angriff','Haltung. 5...15 Sekunde[n] lang bewegt Ihr Euch um 25% schneller. Wütender Angriff endet, wenn Ihr ein Ziel erfolgreich trefft. Dabei erhaltet Ihr 0...3 Adrenalinstöße, sofern Ihr mit einem Nahkampfangriff trefft.','Haltung. (5...15 Sekunde[n].) Ihr bewegt Euch um 25% schneller. Erhaltet bei Eurem nächsten Nahkampfangriff +0...3 Adrenalin. <c x="SkillDull">Endet nach Eurem nächsten Treffer.'],
1415=>['Verkrüppelnder Hieb','Elite-Schwertangriff. Wenn dieser Angriff erfolgreich ist, wird der Gegner 5...15 Sekunde[n] lang verkrüppelt und leidet 10...25 Sekunde[n] lang an einer Blutung.','Elite-Schwertangriff. Verursacht Zustand Verkrüppelung (5...15 Sekunde[n]) und Zustand Blutung (10...25 Sekunde[n]).'],
1416=>['Barbarischer Schnitt','Schwertangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...30 Punkt[e] Schaden zu. Wenn Ihr gegenwärtig keine Haltung einnehmt, fügt Ihr auch 5...15 Sekunde[n] lang eine Blutung zu.','Schwertangriff. Richtet +5...30 Punkt[e] Schaden an. Verursacht Zustand Blutung (5...15 Sekunde[n]), falls Ihr keine Haltung einnehmt.'],
1465=>['Vorbereiteter Schuss','Elite-Bogenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...25 Punkt[e] Schaden zu. Wenn Ihr unter den Auswirkungen einer Vorbereitung steht, erhaltet Ihr 1...9 Energiepunkt[e].','Elite-Bogenangriff. Richtet +10...25 Punkt[e] Schaden an. Ihr erhaltet 1...9 Energiepunkt[e], falls Ihr eine aktive Vorbereitung habt.'],
1466=>['Brennender Pfeil','Elite-Bogenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...30 Punkt[e] Schaden zu und verursacht 2...8 Sekunde[n] lang Brennen.','Elite-Bogenangriff. Richtet +10...30 Punkt[e] Schaden an. Verursacht Zustand Brennen (2...8 Sekunde[n]).'],
1467=>['Bogenschuss','Bogenangriff. Wenn dieser Pfeil trifft, fügt er +10...35 Punkt[e] Schaden zu. Dieser Pfeil kann nicht geblockt werden, doch er bewegt sich um 50% langsamer.','Bogenangriff. Richtet +10...35 Punkt[e] Schaden an. Kann nicht geblockt werden. Dieser Pfeil bewegt sich um 50% langsamer.'],
1468=>['Gemeinsam zuschlagen','Elite-Schrei. Euer Tiergefährte bewegt sich sofort zu Eurem Ziel hin und verursacht 5...15 Sekunde[n] lang mit seinem nächsten Angriff eine Blutung. Wenn Ihr das nächste Mal mit einem Eurer Angriffe trefft, wird der Gegner 5...15 Sekunde[n] lang verkrüppelt.','Elite-Schrei. Euer Tiergefährte bewegt sich sofort zu Eurem Ziel hin und verursacht mit seinem nächsten Angriff Blutung (5...15 Sekunde[n]). Das nächste Mal, wenn einer Eurer Angriffe trifft, verursacht Ihr Zustand Verkrüppelung (5...15 Sekunde[n]).'],
1469=>['Kreuzfeuer','Bogenangriff. Wenn dieser Angriff den Gegner trifft, fügt er +5...20 Punkt[e] Schaden zu. Wenn dieser Gegner sich in der Nähe Eurer Verbündeten befindet, kann dieser Angriff nicht geblockt werden.','Bogenangriff. Richtet +5...20 Punkt[e] Schaden an. Kann nicht geblockt werden, falls der Gegner in der Nähe eines Eurer Verbündeten ist.'],
1470=>['Stachelpfeile','Vorbereitung. 24 Sekunde[n] lang führen Eure Pfeile zu einer Blutung, die 3...15 Sekunde[n] lang anhält. Beim Aktivieren dieser Fertigkeit habt Ihr -40 Rüstung.','Vorbereitung. 24 Sekunde[n]: Eure Pfeile verursachen den Zustand Blutung (3...15 Sekunde[n]). Beim Aktivieren dieser Fertigkeit habt Ihr -40 Rüstung.'],
1471=>['Fokus des Plünderers','Elite-Fertigkeit. 10 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn Ihr einen Feind trefft, der an einem Zustand leidet, 3...12 Energiepunkt[e].','Elite-Fertigkeit. 10 Sekunde[n]: Ihr erhaltet 3...12 Energiepunkt[e], wenn Ihr einen mit einem Zustand belegten Feind trefft.'],
1472=>['Giftigkeit','Naturritual. Erstellt einen Geist der Stufe 1...10. Vergiftete oder erkrankte Kreaturen in seiner Reichweite erleiden eine Lebenspunktdegeneration von -2. Dieser Geist stirbt nach 30...180 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Vergiftete und kranke Kreaturen in Reichweite haben -2 Lebenspunktdegeneration.'],
1473=>['Treibsand','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10. Alle Kreaturen in seiner Reichweite, die keine Geister sind, verlieren jedes Mal, wenn sie angreifen oder eine Fertigkeit verwenden, 1 Energiepunkt. Dieser Geist stirbt nach 30...180 Sekunde[n].','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Kreaturen verlieren jedes Mal 1 Energiepunkt, wenn sie angreifen oder eine Fertigkeit einsetzen. Keine Wirkung auf Geister.'],
1474=>['Umarmung des Sturms','Haltung. 10 Sekunden lang bewegt Ihr Euch um 25% schneller. Diese Haltung wird jedes Mal, wenn Ihr Elementarschaden erleidet, erneuert.','Haltung. 10 Sekunden: Ihr bewegt Euch um 25% schneller. Erneuerung: Jedes Mal, wenn Ihr Elementarschaden erleidet.'],
1475=>['Geschwindigkeit des Fallenstellers','Haltung. 5...30 Sekunde[n] lang werden Eure Fallen um 25% schneller aufgeladen und um 25% schneller aktiviert. Diese Haltung endet, wenn einer Eurer Angriffe trifft.','Haltung. 5...30 Sekunde[n]: Eure Fallen laden sich um 25% schneller auf und werden um 25% schneller aktiviert. Endet, wenn Ihr mit einem Angriff trefft.'],
1476=>['Stolperdraht','Falle. Wird Stolperdraht aktiviert, erleiden alle Feinde in der Nähe 5...20 Punkt[e] Stichschaden. Alle verkrüppelten Feinde werden zu Boden geworfen. Stolperdraht endet nach 90 Sekunden. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunden: Richtet bei Feinden in der Nähe 5...20 Punkt[e] Stichschaden an. Wirft verkrüppelte Feinde zu Boden. Leicht zu unterbrechen.'],
1478=>['Erneuernde Welle','Verhexung. 8 Sekunde[n] lang erleidet der Gegner 2...12 Punkt[e] Schaden pro Sekunde. Wenn diese Verhexung endet, erhaltet Ihr 1...8 Energiepunkt[e].','Verhexung. (8 Sekunde[n].) Richtet 2...12 Punkt[e] Schaden pro Sekunde an. Wirkung am Ende: Ihr erhaltet 1...8 Energiepunkt[e].'],
1479=>['Opfer des Geistes','Elite-Zauber. Erhaltet 8...17 Energiepunkt[e]. Wenn sich Geister in Hörweite befinden, opfert Ihr keine Lebenspunkte.','Elite-Zauber. Ihr erhaltet 8...17 Energiepunkt[e]. Ihr opfert keine Lebenspunkte, falls Geister in Hörweite sind.'],
1480=>['Geschenk des Geistes','Verzauberung. Jedes Mal, wenn Ihr während der nächsten 60 Sekunde[n] eine Kreatur erschafft, erhalten alle Verbündeten in der Nähe dieser Kreatur 5...50 Lebenspunkt[e] und verlieren 1 Zustand.','Verzauberung. 60 Sekunde[n]: Jedes Mal, wenn Ihr eine Kreatur erstellt, erhalten alle Verbündeten in der Nähe 5...50 Lebenspunkt[e] und verlieren einen Zustand.'],
1481=>['Todespakt-Siegel','Siegel. Belebt das Gruppenmitglied mit Euren aktuellen Lebenspunkten und 15...100% maximaler Energie wieder. Wenn dieser Verbündete das nächste Mal innerhalb von 120 Sekunde[n] stirbt, sterbt Ihr auch.','Siegel. Das Gruppenmitglied wird wiederbelebt (Eure aktuellen Lebenspunkte, 15...100% maximale Energie). 120 Sekunde[n]: Ihr sterbt, wenn dieses Gruppenmitglied das nächste Mal stirbt.'],
1482=>['Essenz zurückfordern','Elite-Zauber. All Eure Geister sterben. Ihr erhaltet 5...20 Energiepunkt[e] und all Eure Binderituale werden wieder aufgeladen, wenn ein Geist auf diese Weise stirbt.','Elite-Zauber. All Eure Geister sterben. Wenn ein Geist auf diese Weise stirbt, erhaltet Ihr 5...20 Energiepunkt[e] und all Eure Binderituale werden wieder aufgeladen.'],
1483=>['Bannstoß','Nahkampfangriff. Wenn der Angriff erfolgreich ist, fügt er 10...60 Punkt[e] heiligen Schaden zu. Fügt herbeigerufenen Kreaturen doppelten Schaden zu.','Nahkampfangriff. Richtet 10...60 Punkt[e] heiligen Schaden an. Fügt herbeigerufenen Kreaturen doppelten Schaden zu.'],
1484=>['Mystischer Schwung','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, verursacht Ihr +3...12 Punkt[e] Schaden. Wenn Ihr verzaubert seid, fügt dieser Angriff zusätzlich +3...12 Punkt[e] Schaden zu.','Nahkampfangriff. Richtet +3...12 Punkt[e] Schaden an. Richtet zusätzlich +3...12 Punkt[e] Schaden an, wenn Ihr verzaubert seid.'],
1485=>['Angriff des Eremiten','Sensenangriff. Wenn der Angriff erfolgreich ist, fügt er +1...10 Punkt[e] Schaden zu und entfernt eine Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wird, fügt Ihr zusätzlich +1...10 Punkt[e] Schaden zu und trefft alle umstehenden Feinde.','Sensenangriff. Richtet +1...10 Punkt[e] Schaden an und entfernt eine Derwisch-Verzauberung. Entfernungseffekt: Richtet +1...10 Punkt[e] Schaden an und trifft alle umstehenden Feinde.'],
1486=>['Unreinheiten ausnutzen','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, verursacht Ihr +3...15 Punkt[e] Schaden. Jeder getroffene Feind verliert 1 Zustand. Für jeden Feind, der einen Zustand verliert, erleiden alle in der Nähe des Gegners befindlichen Feinde 10...40 Punkt[e] heiligen Schaden.','Nahkampfangriff. Richtet +3...15 Punkt[e] Schaden an. Getroffene Feinde verlieren 1 Zustand. Entfernungseffekt: In der Nähe der getroffenen Gegner befindliche Feinde erleiden 10...40 Punkt[e] heiligen Schaden.'],
1487=>['Doppelter Mondschwung','Nahkampfangriff. Ihr verliert 1 Derwisch-Verzauberung und erhaltet 10...50 Lebenspunkt[e]. Wenn eine Verzauberung auf diese Weise entfernt wird, könnt Ihr nicht geblockt werden, trefft zweimal und erhaltet zusätzlich 10...70 Lebenspunkt[e].','Nahkampfangriff. Entfernt 1 Eurer Derwisch-Verzauberungen. Ihr erhaltet 10...50 Energiepunkt[e]. Entfernungseffekt: Unblockbar, zwei Angriffe und 10...70 Lebenspunkt[e] zusätzlich.'],
1488=>['Siegreicher Schwung','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, verursacht Ihr +5...25 Punkt[e] Schaden. Wenn der Gegner weniger Lebenspunkte hat als Ihr, erhaltet Ihr 30...80 Lebenspunkt[e].','Nahkampfangriff. Richtet +5...25 Punkt[e] Schaden an. Ihr erhaltet 30...80 Lebenspunkt[e] für jeden getroffenen Gegner, der weniger Lebenspunkte hat als Ihr.'],
1489=>['Unwiderstehlicher Schwung','Sensenangriff. Richtet +3...15 Punkt[e] Schaden an und verliert 1 Derwisch-Verzauberung. Wenn Ihr eine Verzauberung auf diese Weise verliert, kann Unwiderstehlicher Schwung nicht geblockt werden, eine Haltung wird entfernt und der Angriff richtet zusätzlich +3...15 Punkt[e] Schaden an.','Sensenangriff. Richtet +3...15 Punkt[e] Schaden an. Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Unblockbar, entfernt eine Haltung, richtet zusätzlich +3...15 Punkt[e] Schaden an.'],
1490=>['Frommer Angriff','Nahkampfangriff. Wenn der Angriff erfolgreich ist, fügt er +10...20 Punkt[e] Schaden zu und entfernt 1 Derwisch-Verzauberung. Wenn eine Derwisch-Verzauberung entfernt wurde, lädt diese Fertigkeit 75% schneller wieder auf und alle umstehenden Feinde erleiden 15...40 Punkt[e] Schaden,','Nahkampfangriff. Richtet +10...20 Punkt[e] Schaden an. Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Fertigkeit lädt 75% schneller wieder auf und alle umstehenden Feinde erleiden 15...40 Punkt[e] Schaden,'],
1491=>['Mystischer Wirbelsturm','Zauber. Richtet bei allen Feinden in der Nähe 10...60 Punkt[e] Kälteschaden an. Wenn Ihr verzaubert seid, verursacht dieser Zauber zusätzlich 10...60 Punkt[e] Kälteschaden.','Zauber. Richtet bei allen Feinden in der Nähe 10...60 Punkt[e] Kälteschaden an. Richtet 10...60 Punkt[e] Kälteschaden zusätzlich an, wenn Ihr verzaubert seid.'],
1493=>['Grenths Finger','Blitzverzauberung. Alle in der Nähe befindlichen Feinde erleiden 10...40 Punkt[e] Kälteschaden. 30 Sekunde[n] lang fügen Eure Angriffe Kälteschaden zu. Wenn diese Verzauberung endet, übertragt Ihr 1...2 Zustände an alle umstehenden Feinde.','Blitzverzauberung. (30 Sekunde[n].) Eure Angriffe fügen Kälteschaden zu. Anfangswirkung: In der Nähe befindliche Feinde erleiden 10...40 Punkt[e] Kälteschaden. Wirkung am Ende: Überträgt 1...2 Zustände auf alle umstehenden Feinde.'],
1495=>['Dornenaura','Blitzverzauberung. Alle Feinde in der Nähe leiden 5...15 Sekunde[n] an einer Blutung. 30 Sekunde[n] lang bewirkt diese Verzauberung nichts. Wenn diese Verzauberung endet, werden alle in der Nähe befindliche Feinde 3...8 Sekunde[n] lang verkrüppelt.','Blitzverzauberung. (30 Sekunde[n].) Anfangswirkung: Verursacht bei in der Nähe befindlichen Feinden den Zustand Blutung (5...15 Sekunde[n]). Wirkung am Ende: Verursacht bei in der Nähe befindlichen Feinden den Zustand Verkrüppelung (3...8 Sekunde[n]).'],
1496=>['Balthasars Wut','Blitzverzauberung. Alle in der Nähe befindliche Feinde werden 1...3 Sekunde[n] lang in Brand gesetzt. 20 Sekunde[n] danach bewirkt diese Verzauberung nichts Wenn diese Verzauberung endet, erhaltet Ihr 1...2 Adrenalinstöße, wenn sich Feinde in Hörweite befinden.','Blitzverzauberung. (20 Sekunde[n].) Anfangswirkung: Verursacht bei in der Nähe befindlichen Feinden Brennen (1...3 Sekunde[n]). Wirkung am Ende: Ihr erhaltet 1...2 Adrenalinstöße, wenn sich Feinde in Hörweite befinden.'],
1497=>['Staubdecke','Blitzverzauberung. Alle in der Nähe befindlichen Feinde erleiden 10...40 Punkt[e] Erdschaden. 30 Sekunde[n] lang fügen Eure Angriffe Erdschaden zu. Wenn diese Verzauberung endet, werden alle in der Nähe befindliche Feinde 1...4 Sekunde[n] lang geblendet.','Blitzverzauberung. (30 Sekunde[n].) Eure Angriffe fügen Erdschaden zu. Anfangswirkung: Richtet bei in der Nähe befindlichen Feinden 10...40 Punkt[e] Erdschaden an. Wirkung am Ende: Verursacht bei in der Nähe befindlichen Feinden Zustand Blindheit (1...4 Sekunde[n]).'],
1498=>['Umwerfende Gewalt','Blitzverzauberung. Alle in der Nähe befindlichen Feinde erleiden 10...40 Punkt[e] Erdschaden. 30 Sekunde[n] lang fügen Eure Angriffe Erdschaden zu. Wenn diese Verzauberung endet, leiden alle in der Nähe befindlichen Feinde 1...10 Sekunde[n] unter "Beschädigte Rüstung".','Blitzverzauberung. (30 Sekunde[n].) Eure Angriffe fügen Erdschaden zu. Anfangswirkung: Richtet bei in der Nähe befindlichen Feinden 10...40 Punkt[e] Erdschaden an. Wirkung am Ende: Fügt in der Nähe befindlichen Feinden "Beschädigte Rüstung" (1...10 Sekunde[n]) zu.'],
1499=>['Fromme Erneuerung','Elite-Blitzverzauberung. 8 Sekunde[n] lang geschieht nichts. Wenn diese Verzauberung endet, wird Fromme Erneuerung wieder aufgeladen und Ihr erhaltet 0...5 Energiepunkt[e] und 0...30 Lebenspunkt[e].','Elite-Blitzverzauberung. (8 Sekunde[n].) Wirkung am Ende: Lädt wieder auf und Ihr erhaltet 0...5 Energie- und 0...30 Lebenspunkt[e].'],
1500=>['Trugbild-Umhang','Blitzverzauberung. 20 Sekunden lang habt Ihr eine Chance von 40 %, zu blocken plus 4...10 % für jede zusätzliche Verzauberung (max. 80 %). Alle Gegner in der Nähe erleiden jedes Mal 10...40 Erdschaden, wenn eine Derwisch-Verzauberung von Euch entfernt wird.','Blitzverzauberung. (20 Sekunden.) Chance von 40 %, zu blocken plus 4...10 % für jede zusätzliche Verzauberung. Gegner in der Nähe erleiden 10...40 Erdschaden, wenn Ihre eine Derwisch-Verzauberung verliert.'],
1502=>['Arkaner Eifer','Elite-Verzauberung. 10 Sekunde[n] lang bekommt Ihr jedes Mal, wenn Ihr einen Zauber wirkt, für jede Verzauberung, die auf Euch liegt, 2 Energiepunkt[e] (maximal 2...7 Energiepunkt[e]).','Elite-Verzauberung. (10 Sekunde[n].) Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr für jede Verzauberung auf Euch 2 Energiepunkt[e] (maximal 2...7).'],
1503=>['Mystische Vitalität','Verzauberung. 20 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn einer Eurer Angriffe erfolgreich ist, für jede Verzauberung, die auf Euch liegt, 3...15 Lebenspunkt[e] (maximal 25 Lebenspunkt[e]).','Verzauberung. 20 Sekunde[n]: Jedes Mal, wenn ein Angriff von Euch trifft, erhaltet Ihr für jede Verzauberung auf Euch 3...15 Lebenspunkt[e] (maximal 25).'],
1504=>['Wachsame Intervention','Verzauberung. 60 Sekunde[n] lang wird der Verbündete (bzw. Ihr selbst) das nächste Mal, wenn er Schaden erleidet und seine Lebenspunkte dadurch unter 25% sinken, um 50...200 Lebenspunkt[e] geheilt.','Verzauberung. 60 Sekunde[n]: Heilt um 50...200 Lebenspunkt[e], wenn Schaden die Lebenspunkte des Verbündeten (bzw. von Euch selbst) das nächste Mal unter 25% seiner maximalen Lebenspunkte senkt.'],
1505=>['Gelübde der Frömmigkeit','Verzauberung. 20 Sekunde[n] lang habt Ihr +24 Rüstung und eine Lebenspunktregeneration von +1...4. Das Gelübde der Frömmigkeit erneuert sich jedes Mal, wenn eine Verzauberung, mit der Ihr belegt seid, endet.','Verzauberung. (20 Sekunde[n].) +24 Rüstung und +1...4 Lebenspunktregeneration. Erneuerung: jedes Mal, wenn eine Verzauberung, mit der Ihr belegt seid, endet.'],
1506=>['Wesentliche Wohltat','Verzauberung. 20 Sekunde[n] lang habt Ihr +40...100 maximale Lebenspunk[e]. Wenn diese Verzauberung endet, werdet Ihr um 75...200 Lebenspunkt[e] geheilt.','Verzauberung. 20 Sekunde[n]: Ihr habt +40...100 maximale Lebenspunkte. Wirkung am Ende: Heilt Euch um 75...200 Lebenspunkt[e].'],
1507=>['Herz der heiligen Flamme','Blitzverzauberung. Alle in der Nähe befindlichen Gegner erleiden 5...30 Punkt[e] heiligen Schaden. 30 Sekunde[n] danach fügen Eure Angriffe heiligen Schaden zu. Wenn diese Verzauberung endet, werden alle in der Nähe befindliche Feinde 2...5 Sekunde[n] lang in Brand gesetzt.','Blitzverzauberung. (30 Sekunde[n].) Eure Angriffe fügen heiligen Schaden zu. Anfangswirkung: Richtet bei in der Nähe befindlichen Feinden 5...30 Punkt[e] heiligen Schaden an. Wirkung am Ende: Verursacht bei in der Nähe befindlichen Feinden Zustand Brennen (2...5 Sekunde[n]).'],
1508=>['Verzauberungen ausweiten','Fertigkeit. 10 Sekunde[n] lang wirkt Eure nächste Derwisch-Verzauberung 10...150% länger.','Fertigkeit. (10 Sekunde[n]) Eure nächste Derwisch-Verzauberung wirkt 10...150% länger.'],
1509=>['Vertrauensvolle Intervention','Verzauberung. Wenn Schaden Eure Lebenspunkte auf unter 50% fallen lässt, endet Vertrauensvolle Intervention. Wenn Vertrauensvolle Intervention endet, werdet Ihr um 30...150 Lebenspunkt[e] geheilt.','Verzauberung. Ihr erhaltet 30...150 Lebenspunkt[e], wenn Eure Lebenspunkte das nächste Mal durch Schaden unter 50% Eurer maximalen Lebenspunkte gebracht werden.'],
1510=>['Sandscherben','Blitzverzauberung. 30 Sekunden lang erleiden bei Euren nächsten 1...5 Treffern mit der Sense alle Gegner 10...60 Erdschaden.','Blitzverzauberung. (30 Sekunden.) Fügt allen anderen Gegnern in der Nähe 10...60 Erdschaden zu, wenn Ihr mit Eurer Sense trefft. Endet nach 1...5 Treffern.'],
1512=>['Lyssas Eile','Blitzverzauberung. 3...15 Sekunde[n] lang werden Eure Derwisch-Verzauberungen um 33% schneller wieder aufgeladen. Wenn Ihr diese Verzauberung aktiviert, werden alle Aktionen umstehender Feinde unterbrochen. Wenn diese Verzauberung endet, werden alle Aktionen umstehender Feinde unterbrochen. Bei Windgebeten von 5 oder höher, sonst besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.','Blitzverzauberung. (3...15 Sekunde[n].) Eure Derwisch-Verzauberungen werden um 33% schneller wieder aufgeladen. Anfangswirkung: Unterbricht alle Aktionen umstehender Feinde. Wirkung am Ende: Unterbricht alle Aktionen umstehender Feinde. (Bei Windgebeten von 5 oder höher, sonst besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)'],
1513=>['Lenkende Hände','Verzauberung. 20 Sekunde[n] lang ist ein Blocken bei Euren nächsten 0...3 Angriffen nicht möglich. Bei Aktivierung entfernt diese Fertigkeit den Zustand "Blindheit".','Verzauberung. (20 Sekunde[n].) Eure nächsten 0...3 Angriff[e] können nicht geblockt werden. Anfangswirkung: Entfernt "Blindheit".'],
1514=>['Flüchtige Stabilität','Blitzverzauberung. Während der nächsten 4...10 Sekunde[n] könnt Ihr nicht zu Boden geworfen werden und bewegt Euch um 25% schneller. Diese Verzauberung endet vorzeitig, wenn sie verhindert, dass Ihr zu Boden geworfen werdet.','Blitzverzauberung. (4...10 Sekunde[n].) Ihr könnt nicht zu Boden geworfen werden und bewegt Euch um 25% schneller. Endet, wenn sie verhindert, dass Ihr zu Boden geworfen werdet.'],
1515=>['Rüstung der Heiligkeit','Verzauberung. Alle umstehenden Feinde leiden 5...15 Sekunde[n] lang am Zustand Schwäche. 15 Sekunde[n] lang erleidet Ihr 5...20 Punkt[e] weniger Schaden von Feinden, die an einem Zustand leiden.','Verzauberung. Verursacht Zustand Schwäche bei allen umstehenden Feinden (5...15 Sekunden). Feinde mit einem Zustand richten bei Euch 5...20 Punkt[e] weniger Schaden an (15 Sekunden).'],
1516=>['Mystische Regeneration','Verzauberung. 5...20 Sekunde[n] lang habt Ihr für jede Verzauberung auf Euch (maximal 8) +1...4 Lebenspunktregeneration.','Verzauberung. (5...20 Sekunde[n].) Ihr habt für jede Verzauberung auf Euch (maximal 8) +1...4 Lebenspunktregeneration.'],
1517=>['Schweigegelübde','Elite-Verzauberung. 5...10 Sekunde[n] lang könnt Ihr nicht zum Ziel von Zaubern werden und selbst keine Zauber wirken.','Elite-Verzauberung. (5...10 Sekunde[n].) Ihr könnt nicht zum Ziel von Zaubern werden. Ihr könnt keine Zauber wirken.'],
1518=>['Balthasars Avatar','Elite-Form. 10...90 Sekunde[n] lang erhaltet Ihr +20 Rüstung gegen körperlichen Schaden, gewinnt Adrenalin um 25% schneller, Eure Angriffe fügen heiligen Schaden zu und immer wenn Ihr eine Derwisch-Verzauberung verliert, werden Feinde in der Nähe 1...3 Sekunden lang in Brand gesetzt. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunde[n].) Ihr erhaltet +20 Rüstung gegen körperlichen Schaden, gewinnt Adrenalin um 25% schneller, Eure Angriffe fügen heiligen Schaden zu und immer wenn Ihr eine Derwisch-Verzauberung verliert, werden Feinde in der Nähe in Brand gesetzt (1...3 Sekunden). Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
1519=>['Dwaynas Avatar','Elite-Form. 10...90 Sekunden lang fügen Eure Angriffe heiligen Schaden zu. Immer wenn Ihr eine Derwisch-Angriffsfähigkeit einsetzt, verliert Ihr 1 Verhexung. Immer wenn Ihr eine Derwisch-Verzauberung verliert, werden alle Verbündeten in Hörweite um 5...50 Lebenspunkte geheilt. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunden.) Richtet heiligen Schaden an. Immer wenn Ihr eine Derwisch-Angriffsfähigkeit einsetzt, verliert Ihr 1 Verhexung. Immer wenn Ihr eine Derwisch-Verzauberung verliert, werden Verbündete in Hörweite um 5...50 Lebenspunkte geheilt. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
1520=>['Grenths Avatar','Elite-Form. 10...90 Sekunde[n] lang fügen Eure Sensenangriffe Dunkelschaden zu und stehlen 0...12 Lebenspunkt[e]. Ihr seid immun gegen Krankheit und fügt allen umstehenden Feinden 3 Sekunde[n] lang Krankheit zu, wenn Ihr eine Derwisch-Verzauberung verliert. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunde[n].) Eure Sensenangriffe fügen Dunkelschaden zu und stehlen 0...12 Lebenspunkt[e]. Ihr seid immun gegen Krankheit. Ihr fügt allen umstehenden Feinden Krankheit zu (3 Sekunde[n] lang), wenn Ihr eine Derwisch-Verzauberung verliert. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
1521=>['Lyssas Avatar','Elite-Form. 10...90 Sekunde[n] lang werden Eure Derwisch-Verzauberungen um 50% schneller wieder aufgeladen und Eure Angriffe fügen Chaosschaden zu. Immer wenn Ihr eine Derwisch-Verzauberung verliert, entzieht Ihr allen umstehenden Feinden 1 Energiepunkt[e]. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunde[n].) Eure Derwisch-Verzauberungen laden 50% schneller wieder auf und fügen bei Angriffen Chaosschaden zu. Wenn Ihr eine Derwisch-Verzauberung verliert, entzieht Ihr umstehenden Feinden 1 Energiepunkt[e]. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
1522=>['Melandrus Avatar','Elite-Form. 10...90 Sekunde[n] lang habt Ihr +150 Lebenspunkt[e], +30 Elementarrüstung und Eure Angriffe fügen Erdschaden zu. Immer wenn Ihr eine Derwisch-Verzauberung verliert, verlieren alle Gruppenmitglieder in Hörweite 1 Zustand. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunde[n].) Ihr habt +150 maximale Lebenspunkt[e], +30 Elementarrüstung und Eure Angriffe fügen Erdschaden zu. Immer wenn Ihr eine Derwisch-Verzauberung verliert, verlieren alle Gruppenmitglieder in Hörweite 1 Zustand. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
1523=>['Meditation','Verzauberung. Alles Adrenalin geht verloren. 20 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn eine auf Euch wirkende Verzauberung endet, 1...4 Energiepunkt[e].','Verzauberung. (20 Sekunde[n].) Alles Adrenalin geht verloren. Ihr erhaltet jedes Mal 1...4 Energiepunkt[e], wenn eine auf Euch wirkende Verzauberung endet.'],
1524=>['Eifer des Eremiten','Verzauberung. Ihr erhaltet für jeden Feind in der Nähe 1...3 Energiepunkt[e] (maximal 8 Energiepunkte). 10 Sekunde[n] danach bewirkt diese Verzauberung nichts Wenn diese Verzauberung endet, erhaltet Ihr 1...3 Energiepunkt[e] für jeden umstehenden Gegner (maximal 8 Energiepunkt[e]).','Verzauberung. (10 Sekunde[n].) Anfangswirkung: Ihr erhaltet für jeden Feind in der Nähe 1...3 Energiepunkt[e] (maximal 8). Wirkung am Ende: Ihr erhaltet für jeden Feind in der Nähe 1...3 Energiepunkt[e] (maximal 8).'],
1525=>['Natürliche Heilung','Zauber. Ihr werdet um 50...170 Lebenspunkt[e] geheilt. Wenn Ihr nicht verzaubert seid, wird dieser Zauber 50% schneller aktiviert.','Zauber. Heilt Euch um 50...170 Lebenspunkt[e]. Wenn Ihr nicht verzaubert seid, wird dieser Zauber 50% schneller aktiviert.'],
1526=>['Mit Leben durchdringen','Zauber. Der Verbündete wird um 5...50% Eurer aktuellen Lebenspunkte (maximal 300 Lebenspunkt[e]) geheilt.','Zauber. Heilt um 5...50% Eurer aktuellen Lebenspunkte (maximal 300 Punkt[e]). Sich selbst als Ziel wählen nicht möglich.'],
1527=>['Mystische Heilung','Zauber. Ihr werdet um 5...65 Lebenspunkt[e] geheilt. Heilt zudem alle verzauberten Gruppenmitglieder um 5...65 Lebenspunkt[e].','Zauber. Heilt Euch um 5...65 Lebenspunkt[e]. Heilt alle verzauberten Gruppenmitglieder um 5...65 Lebenspunkt[e].'],
1528=>['Dwaynas Berührung','Zauber. Der berührte Verbündete wird pro Verzauberung, mit der Ihr belegt seid (maximal 60...240), um 60 Lebenspunkt[e] geheilt.','Berührungs-Zauber. Heilt für jede Verzauberung auf Euch um 60 Lebenspunkt[e] (maximal 60...240).'],
1529=>['Fromme Wiederherstellung','Zauber. Ihr erhaltet 80...150 Lebenspunkt[e] und entfernt 1 Derwisch-Verzauberung. Wenn eine Verzauberung auf diese Weise entfernt wurde, verliert Ihr außerdem 1...3 Verhexungen.','Zauber. Ihr erhaltet 80...150 Lebenspunkt[e] und entfernt 1 Derwisch-Verzauberung. Entfernungseffekt: Ihr verliert 1...3 Verhexungen.'],
1530=>['Siegel des frommen Lichts','Siegel. Entfernt 1 Derwisch-Verzauberung. Heilt Verbündeten (bzw. Euch selbst) um 30...150 Lebenspunkt[e]. Wenn eine Verzauberung auf diese Weise entfernt wird, lädt dieses Siegel 75% schneller wieder auf.','Siegel. Heilt 30...150 Lebenspunkt[e]. Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Lädt 75% schneller wieder auf.'],
1531=>['Einschüchternde Aura','Verzauberung. 60 Sekunde[n] lang habt Ihr zusätzlich +40...100 Lebenspunkt[e] und erleidet 1...10 Punkt[e] weniger Schaden von Feinden mit weniger Lebenspunkten als Ihr.','Verzauberung. (60 Sekunde[n].) Ihr habt zusätzlich +40...100 Lebenspunkt[e] und erleidet -1...10 Punkt[e] Schaden von Feinden mit weniger Lebenspunkten als Ihr.'],
1532=>['Mystischer Sandsturm','Zauber. An der Eurer Position wird ein Sandsturm erzeugt, der 3 Sekunde[n] lang anhält. Feinde in der Nähe Eurer ursprünglichen Position erleiden pro Sekunde 10...40 Punkt[e] Erdschaden. Angreifende Feinde erleiden zusätzlich 10...20 Punkt[e] Schaden. Wenn Ihr beim Wirken dieses Zaubers verzaubert seid, hält die Wirkung doppelt so lange an.','Zauber. (3 Sekunde[n].) Richtet 10...40 Punkt[e] Erdschaden pro Sekunde an. Richtet bei angreifenden Feinden zusätzlich 10...20 Punkt[e] Schaden an. Trifft Feinde in der Nähe Eurer ursprünglichen Position. Die Wirkung hält doppelt so lange an, wenn Ihr verzaubert seid.'],
1533=>['Wind der Entzauberung','Zauber. Entfernt 1 Eurer Derwisch-Verzauberungen. Wird eine Verzauberung entfernt, verlieren alle Feinde in der Nähe 1 Verzauberung und erleiden 20...80 Punkt[e] Kälteschaden.','Zauber. Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Alle Feinde in der Nähe verlieren 1 Verzauberung und erleiden 20...80 Punkt[e] Kälteschaden.'],
1534=>['Zerfetzende Berührung','Zauber. Fügt dem Zielgegner 15...65 Kälteschaden zu. Ihr verliert 1 Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wurde, verliert der Zielgegner 1 Verzauberung und Ihr erhaltet 2 Adrenalinschlag(pl:"Adrenalinschläge").','Berührungs-Zauber. Verursacht 15...65 Kälteschaden. Ihr verliert 1 Derwisch-Verzauberung. Entfernen-Effekt: Zielgegner verliert 1 Verzauberung, Ihr erhaltet 2 Adrenalinschlag(pl:"Adrenalinschläge").'],
1535=>['Verkrüppelnder Schwung','Sensenangriff. Trifft dieser Angriff einen Gegner, wird dieser 3...12 Sekunde[n] lang verkrüppelt. Diese Fertigkeit verursacht +3...15 Punkt[e] Schaden zusätzlich, wenn der Feind sich bewegt.','Sensenangriff. (3...12 Sekunde[n].) Verursacht Verkrüppelung. Richtet bei sich bewegenden Feinden +3...15 Punkt[e] Schaden an.'],
1536=>['Verwundender Schlag','Elite-Sensenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu, der Gegner leidet 5...20 Sekunde[n] lang an einer Blutung und Ihr verliert 1 Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wurde, erleidet der Gegner außerdem 5...20 Sekunde[n] lang eine Tiefe Wunde.','Elite-Sensenangriff. Richtet +5...20 Punkt[e] Schaden an und verursacht Zustand Blutung (5...20 Sekunde[n]). Entfernt 1 Derwisch-Verzauberung. Entfernungseffekt: Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]).'],
1537=>['Ermüdender Schlag','Sensenangriff. Ihr entfernt 1 Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wurde, erleidet der Gegner 3...10 Sekunde[n] lang eine Tiefe Wunde. Wenn keine Verzauberung entfernt, leidet Ihr 10 Sekunden lang unter "Schwäche".','Sensenangriff. Entfernt 1 Derwisch-Verzauberung. Entfernungseffekt: Verursacht Zustand Tiefe Wunde (3...10 Sekunde[n]). Wenn keine Verzauberung entfernt wird, leidet Ihr unter "Schwäche" (10 Sekunden).'],
1538=>['Lyssas Angriff','Sensenangriff. Wenn dieser Angriff trifft, unterbricht er eine Aktion. Falls Ihr verzaubert seid, wird jeder von Euch unterbrochene Zauber zudem 1...10 Sekunde[n] lang deaktiviert. Dieser Angriff fügt 50% des normalem Schadens zu.','Sensenangriff. Unterbricht eine Aktion. Falls Ihr verzaubert seid, wird der unterbrochene Zauber zudem 1...10 Sekunde[n] lang deaktiviert. Dieser Angriff fügt 50% des normalem Schadens zu.'],
1539=>['Kühler Sieg','Sensenangriff. Wenn dieser Angriff erfolgreich ist, werden dem Gegner +3...15 Punkt[e] Schaden zugefügt. Wenn Ihr einen Feind trefft, dessen Lebenspunkte niedriger als Eure eigenen sind, erleiden der Gegner und alle umstehenden Feinde 10...30 Punkt[e] Kälteschaden.','Sensenangriff. Richtet +3...15 Punkt[e] Schaden an. Fügt jedem Feind, dessen Lebenspunkte niedriger als Eure eigenen sind, und allen umstehenden Feinden 10...30 Punkt[e] Kälteschaden zu.'],
1540=>['Überzeugung','Blitzverzauberung. Wenn Ihr unter einem Zustand leidet, erhaltet Ihr 10 Sekunde[n] lang +10 Rüstung und 1...3 Lebenspunktregeneration für jeden Zustand, unter dem Ihr leidet. Wenn diese Verzauberung endet, werdet Ihr von 1...2 Zuständen geheilt.','Blitzverzauberung. (10 Sekunde[n].) Ihr erhaltet +10 Rüstung, wenn Ihr unter einem Zustand leidet. Ihr erhaltet 1...3 Lebenspunktregeneration für jeden Zustand, unter dem Ihr leidet. Wirkung am Ende: Entfernt 1...2 Zustände.'],
1541=>['Verzauberte Eile','Blitzverzauberung. 7 Sekunde[n] lang bewegt Ihr Euch um 25% schneller. Wenn diese Verzauberung vorzeitig endet, verliert Ihr 1 Zustände.','Blitzverzauberung. (7 Sekunde[n].) Ihr bewegt Euch um 25% schneller. Wenn diese Verzauberung vorzeitig endet, verliert Ihr 1 Zustände.'],
1542=>['Fromme Konzentration','Haltung. Ihr könnt 5...20 Sekunde[n] lang nicht unterbrochen werden, aber jedes Mal, wenn Ihr normalerweise unterbrochen würdet, verliert Ihr 1 Derwisch-Verzauberung oder Fromme Konzentration endet.','Haltung. (5...20 Sekunde[n].) Verhindert Unterbrechungen. Verhinderungskosten: Ihr verliert 1 Derwisch-Verzauberung oder Fromme Konzentration endet.'],
1543=>['Fromme Eile','Haltung. Ihr entfernt 1 Derwisch-Verzauberung und bewegt Euch 1...7 Sekunde[n] lang 25% schneller. Wenn eine Verzauberung entfernt wird, rennt Ihr stattdessen 50% schneller.','Haltung. (1...7 Sekunde[n].) Ihr verliert 1 Derwisch-Verzauberung und bewegt Euch 25% schneller. Entfernungseffekt: Rennt stattdessen 50% schneller.'],
1544=>['Wirbelangriff','Blitzverzauberung. 1...6 Sekunde[n] lang bewegt Ihr Euch um 33% schneller als gewöhnlich. Das nächste Mal, wenn Ihr einen Feind trefft, erleiden alle anderen Feinde in der Nähe 10...60 Kälteschaden und diese Verzauberung endet.','Blitzverzauberung. (1...6 Sekunde[n].) Ihr bewegt Euch um 33% schneller. Fügt das nächste Mal, wenn Ihr einen Feind trefft, allen anderen Feinden in der Nähe 10...60 Kälteschaden zu und die Verzauberung endet.'],
1545=>['Glaubensprüfung','Zauber. Fügt 15...75 Punkt[e] Kälteschaden zu und entfernt 1 Verzauberung vom Gegner. Wenn der Gegner nicht verzaubert war, leidet er 2...6 Sekunde[n] lang unter Benommenheit.','Berührungs-Zauber. Fügt 15...75 Punkt[e] Kälteschaden zu und entfernt 1 Verzauberung vom Gegner. Wenn der Gegner nicht verzaubert war, leidet er 2...6 Sekunde[n] lang unter Benommenheit.'],
1546=>['Lodernder Speer','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt er +5...25 Punkt[e] Schaden zu und setzt den Gegner 1...3 Sekunde[n] lang in Brand.','Speerangriff. Richtet +5...25 Punkt[e] Schaden an. Verursacht Zustand Brennen (1...3 Sekunde[n]).'],
1547=>['Mächtiger Wurf','Speerangriff. Euer Speer bewegt sich dreimal so schnell. Wenn er trifft, fügt Ihr +10...40 Punkt[e] Schaden zu.','Speerangriff. Richtet +10...40 Punkt[e] Schaden an. Dieser Speer bewegt sich mit dreifacher Geschwindigkeit.'],
1548=>['Grausamer Speer','Elite-Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...50 Punkt[e] Schaden zu. Wenn Ihr ein Ziel trefft, das sich nicht bewegt, fügt Ihr 5...20 Sekunde[n] lang eine Tiefe Wunde zu.','Elite-Speerangriff. Richtet +10...50 Punkt[e] Schaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls der Gegner sich nicht bewegt.'],
1549=>['Wurf des Läufers','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn dieser Angriff einen sich bewegenden Feind trifft, fügt Ihr zusätzlich 5...40 Punkt[e] Schaden zu.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet zusätzlich 5...40 Punkt[e] Schaden an, falls der Gegner sich bewegt.'],
1550=>['Unblockbarer Wurf','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...40 Punkt[e] Schaden zu. Dieser Angriff kann nicht geblockt werden.','Speerangriff. Richtet +10...40 Punkt[e] Schaden an. Kann nicht geblockt werden.'],
1551=>['Speer des Blitzes','Speerangriff. Greift alle Gegner zwischen Euch und Eurem Ziel an. Wenn dieser Angriff trifft, verursacht er +10...20 Blitzschaden. Dieser Angriff hat 25 % Rüstungsdurchdringung.','Speerangriff. Verursacht +10...20 Blitzschaden. 25 % Rüstungsdurchdringung. Greift alle Gegner zwischen Euch und Eurem Ziel an.'],
1552=>['Ermüdender Speer','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...40 Punkt[e] Schaden zu. Ihr seid 5 Sekunde[n] lang geschwächt.','Speerangriff. Richtet +10...40 Punkt[e] Schaden an. Ihr seid geschwächt (5 Sekunde[n]).'],
1553=>['Hymne der Wut','Elite-Anfeuerungsruf. 10 Sekunde[n] erhalten alle Gruppenmitglieder in Hörweite bei der nächsten Verwendung einer Angriffsfertigkeit 2...5 Adrenalinstöße.','Elite-Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten bei Benutzung ihrer nächsten Angriffsfertigkeit 2...5 Adrenalin.'],
1554=>['Verkrüppelungs-Hymne','Elite-Anfeuerungsruf. 10 Sekunde[n] lang führt die nächste Angriffsfertigkeit von jedem Verbündeten in Hörweite 5...15 Sekunde[n] lang zu Verkrüppelung.','Elite-Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite verursachen mit ihrer nächsten Angriffsfertigkeit den Zustand Verkrüppelung (5...15 Sekunde[n]).'],
1555=>['Verteidigungshymne','Elite-Anfeuerungsruf. 4...10 Sekunde[n] lang hat jedes Gruppenmitglied in Hörweite eine 50%ige Chance, Angriffe zu blocken. Dieser Anfeuerungsruf endet, wenn das Gruppenmitglied mit einer Angriffsfertigkeit trifft.','Elite-Anfeuerungsruf. 4...10 Sekunde[n]: Gruppenmitglieder in Hörweite haben eine 50%ige Chance zu blocken. Endet bei einem Treffer mit einer Angriffsfertigkeit.'],
1556=>['Gute Reise','Schrei. 5...20 Sekunde[n] bewegen sich alle Verbündeten in Hörweite um 25% schneller, wenn sie verzaubert sind.','Schrei. 5...20 Sekunde[n]: Verbündete in Hörweite bewegen sich um 25% schneller, solange sie verzaubert sind.'],
1557=>['Hymne der Flamme','Anfeuerungsruf. 10 Sekunde[n] lang führt die nächste Angriffsfertigkeit von jedem Gruppenmitglied in Hörweite auch 1...5 Sekunde[n] lang zu Brennen.','Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite verursachen mit ihrer nächsten Angriffsfertigkeit den Zustand Brennen (1...5 Sekunde[n]).'],
1558=>['"Zielt auf die Augen!"','Schrei. 10 Sekunde[n] lang hat der nächste Angriff jedes Verbündeten in Hörweite zusätzlich eine 30...100%ige Chance, ein kritischen Treffer zu sein.','Schrei. 10 Sekunde[n]: Verbündete in Hörweite haben mit ihrem nächsten Angriff +30...100% zur Chance auf kritische Treffer.'],
1559=>['Hymne des Neids','Anfeuerungsruf. 10 Sekunde[n] lang führt die nächste Angriffsfertigkeit von jedem Verbündeten in Hörweite bei Feinden mit mehr als 50% Lebenspunkten zu +10...25 Punkt[en] Schaden.','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite richten mit ihrer nächsten Angriffsfertigkeit +10...25 Punkt[e] Schaden an. Schadensbonus gilt nur bei Feinden mit mehr als 50% ihrer maximalen Lebenspunkte.'],
1560=>['Machtgesang','Anfeuerungsruf. 5...20 Sekunde[n] lang erfreut sich jeder Verbündete in Hörweite einer Energieregeneration von 4, bis er eine Fertigkeit verwendet.','Anfeuerungsruf. 5...20 Sekunde[n]: Verbündete in Hörweite erhalten +4 Energieregeneration. Endet bei Benutzung einer Fertigkeit.'],
1561=>['Eifrige Hymne','Anfeuerungsruf. 10 Sekunde[n] lang erhält jeder Verbündete in Hörweite, wenn er das nächste Mal eine Angriffsfertigkeit verwendet, 1...8 Energiepunkt[e].','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite erhalten bei Benutzung ihrer nächsten Angriffsfertigkeit 1...8 Energiepunkt[e].'],
1562=>['Arie des Eifers','Anfeuerungsruf. 10 Sekunde[n] lang erhält jeder Verbündete in Hörweite bei der nächsten Verwendung einer Fertigkeit 1...6 Energiepunkt[e].','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite erhalten bei Benutzung ihres nächsten Zaubers 1...6 Energiepunkt[e].'],
1563=>['Lyrik des Eifers','Anfeuerungsruf. 10 Sekunde[n] lang erhält jeder Verbündete in Hörweite bei der nächsten Verwendung eines Siegels 1...8 Energiepunkt[e].','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite erhalten bei Benutzung ihres nächsten Siegels 1...8 Energiepunkt[e].'],
1564=>['Ballade der Wiederherstellung','Anfeuerungsruf. 10 Sekunde[n] lang erhält jedes Gruppenmitglied in Hörweite, wenn es das nächste Mal Schaden erleidet, 15...75 Lebenspunkt[e].','Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten 15...75 Lebenspunkt[e], wenn sie das nächste Mal Schaden erleiden.'],
1565=>['Chor der Wiederherstellung','Anfeuerungsruf. 10 Sekunde[n] lang wird jeder Verbündete in Hörweite, wenn er das nächste Mal einen Schrei oder Anfeuerungsruf verwendet, um 30...90 Lebenspunkt[e] geheilt.','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite werden bei Benutzung ihres nächsten Schreis oder Anfeuerungsrufs um 30...90 Lebenspunkt[e] geheilt.'],
1566=>['Arie der Wiederherstellung','Anfeuerungsruf. 10 Sekunde[n] lang erhält jedes Gruppenmitglied in Hörweite, wenn es das nächste Mal einen Zauber wirkt, 30...90 Lebenspunkt[e].','Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten bei Benutzung ihres nächsten Zaubers 30...90 Lebenspunkt[e].'],
1567=>['Lied der Konzentration','Anfeuerungsruf. 10 Sekunde[n] lang kann der nächste potenzielle Treffer mittels einer Angriffsfertigkeit eines Verbündeten in Hörweite nicht unterbrochen werden.','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite können bei ihrer nächsten Fertigkeit nicht unterbrochen werden.'],
1568=>['Hymne der Führung','Elite-Anfeuerungsruf. 10 Sekunde[n] lang kann die nächste Fertigkeit, die jedes Gruppenmitglied in Hörweite verwendet, nicht geblockt werden.','Elite-Anfeuerungsruf. 10 Sekunde[n]: Die nächste Angriffsfertigkeit von Gruppenmitgliedern in Hörweite kann nicht geblockt werden.'],
1569=>['Energie bringender Chor','Anfeuerungsruf. 10 Sekunde[n] lang kostet der nächste Schrei oder Anfeuerungsruf von jedem Verbündeten in Hörweite 3...7 Energiepunkt[e] weniger.','Anfeuerungsruf. 10 Sekunde[n]: Der nächste Schrei oder Anfeuerungsruf kostet Verbündete in Hörweite 3...7 Energiepunkt[e] weniger.'],
1570=>['Lied der Läuterung','Elite-Anfeuerungsruf. 20 Sekunde[n] lang entfernen die nächsten 1...6 Fertigkeiten, die jeder Verbündete in Hörweite verwendet, 1 Zustand von diesem Verbündeten.','Elite-Anfeuerungsruf. 20 Sekunde[n]: Verbündete in Hörweite verlieren bei Benutzung ihrer nächsten 1...6 Fertigkeit[en] einen Zustand.'],
1571=>['Verhexungsbrech-Arie','Anfeuerungsruf. 10 Sekunde[n] lang verliert jeder Verbündete in Hörweite beim nächsten Wirken eines Zaubers 1 Verhexung.','Anfeuerungsruf. 10 Sekunde[n]: Verbündete in Hörweite verlieren bei Benutzung ihres nächsten Zaubers eine Verhexung.'],
1572=>['"Seid vorbereitet!"','Schrei. 5...15 Sekunde[n] lang erleiden das nächste Mal, wenn der Verbündete zu Boden geworfen würde, alle Feinde in der Nähe stattdessen 15...75 Punkt[e] Schaden.','Schrei. (5...15 Sekunde[n].) Verhindert den nächsten Bodenwurf und richtet bei allen Feinden in der Nähe des Verbündeten 15...75 Punkt[e] Schaden an. Sich selbst als Ziel wählen nicht möglich.'],
1573=>['Ehrfurcht','Fertigkeit. Wenn diese Fertigkeit einen niedergeschlagenen Gegner trifft, macht es ihn 5...15 Sekunden lang benommen.','Fertigkeit. Verursacht Zustand Benommenheit (5...15 Sekunde[n]). Ziel muss zu Boden geworfen sein, sonst keine Wirkung.'],
1574=>['Dauerhafte Harmonie','Echo. 10...35 Sekunde[n] lang dauern Anfeuerungsrufe und Schreie, die auf den Nicht-Geister-Verbündeten (bzw. Euch selbst) gerichtet sind, um 50% länger.','Echo. 10...35 Sekunde[n]: Schreie und Anfeuerungsrufe halten beim Verbündeten (bzw. Euch selbst) um 50% länger an. Nicht auf Geister anwendbar.'],
1575=>['Loderndes Finale','Echo. 10...35 Sekunde[n] lang werden jedes Mal, wenn ein auf einen Nicht-Geister-Verbündeten gerichteter Anfeuerungsruf oder Schrei endet, alle diesen Verbündeten umstehenden Feinde 1...7 Sekunde[n] lang in Brand gesetzt.','Echo. 10...35 Sekunde[n]: Verursacht bei umstehenden Feinden jedes Mal Zustand Brennen (1...7 Sekunde[n]), wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten (bzw. Euch selbst) endet. Nicht auf Geister anwendbar.'],
1576=>['Brennender Refrain','Echo. Wenn der Nicht-Geister-Verbündete während der nächsten 20 Sekunde[n] einen Feind trifft, der über mehr Lebenspunkte als er selbst verfügt, wird dieser Feind 1...3 Sekunde[n] lang in Brand gesetzt. Dieses Echo wird jedes Mal wiederholt, wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet.','Echo. 20 Sekunde[n]: Verursacht Zustand Brennen (1...3 Sekunde[n]), wenn der Verbündete (bzw. Ihr selbst) einen Feind mit mehr Lebenspunkten trifft. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten endet. Nicht auf Geister anwendbar.'],
1577=>['Finale der Wiederherstellung','Echo. 10...35 Sekunde[n] lang wird der Nicht-Geister-Verbündete jedes Mal, wenn ein auf ihn gerichteter Anfeuerungsruf oder Schrei endet, um 15...75 Lebenspunkt[e] geheilt.','Echo. (10...35 Sekunde[n].) Verbündeter (bzw. Ihr selbst) erhält 15...75 Lebenspunkte, immer wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet. Nicht auf Geister anwendbar.'],
1578=>['Genesungsrefrain','Echo. 15 Sekunde[n] lang erfreut sich der Nicht-Geister-Verbündete einer Lebenspunktregeneration von +2...3. Dieses Echo wird jedes Mal wiederholt, wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet.','Echo. 15 Sekunde[n]: Der Verbündete (bzw. Ihr selbst) hat +2...3 Lebenspunktregeneration. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten endet. Nicht auf Geister anwendbar.'],
1579=>['Reinigendes Finale','Echo. 10...35 Sekunde[n] lang verliert der Nicht-Geister-Verbündete jedes Mal, wenn ein auf ihn gerichteter Anfeuerungsruf oder Schrei endet, 1 Zustand.','Echo. 10...35 Sekunde[n]: Der Verbündete (bzw. Ihr selbst) verliert jedes Mal einen Zustand, wenn ein Schrei oder Anfeuerungsruf auf ihm endet. Nicht auf Geister anwendbar.'],
1580=>['Klingenumkehr-Refrain','Echo. 20 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst), der kein Geist ist, eine 5...20%ige Chance, Angriffe zu blocken. Dieses Echo wird jedes Mal wiederholt, wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet.','Echo. (20 Sekunde[n].) Der Verbündete (bzw. Ihr selbst) hat eine 5...20%ige Chance, Angriffe zu blocken. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten endet. Nicht auf Geister anwendbar.'],
1581=>['Glühendes Siegel','Siegel. Wenn der Gegner brennt, erhaltet Ihr 5...15 Energiepunkt[e].','Siegel. Ihr erhaltet 5...15 Energiepunkt[e], falls der Gegner brennt.'],
1583=>['Eifer des Anführers','Fertigkeit. Ihr erhaltet für jeden Verbündeten in der Nähe 2...4 Energiepunkt[e] (maximal 8...12 Energiepunkt[e]).','Fertigkeit. Ihr erhaltet für jeden Verbündeten in der Nähe 2...4 Energiepunkt[e] (maximal 8...12).'],
1584=>['Trost des Anführers','Fertigkeit. Ihr erhaltet 30...75 Lebenspunkt[e]. Ihr erhaltet auch für jeden Verbündeten in Hörweite +10...20 Lebenspunkt[e] (maximal 140 Punkte).','Fertigkeit. Ihr erhaltet 30...75 Lebenspunkt[e]. Zusätzlich erhaltet Ihr für jeden Verbündeten in Hörweite 10...20 Lebenspunkt[e] (maximal 140).'],
1585=>['Siegel der Synergie','Siegel. Der Verbündete wird um 40...100 Lebenspunkt[e] geheilt. Wenn Ihr nicht unter den Auswirkungen einer Verzauberung leidet, werdet Ihr um 40...100 Lebenspunkt[e] geheilt.','Siegel. Heilt den Verbündeten um 40...100 Lebenspunkt[e]. Außerdem werdet Ihr um 40...100 Lebenspunkt[e] geheilt, falls Ihr nicht verzaubert seid. Sich selbst als Ziel wählen nicht möglich.'],
1586=>['Engelsschutz','Fertigkeit. 10 Sekunde[n] lang wird der Verbündete jedes Mal, wenn er mehr als 250...80 Punkt[e] Schaden pro Sekunde erleidet, um die Schadensmenge über diesem Betrag geheilt.','Fertigkeit. 10 Sekunde[n]: In jeder Sekunde, in welcher der Verbündete (bzw. Ihr selbst) Schaden von mehr als 250...80 Punkt[en] erleidet, wird bei ihm jeglicher Schaden über dieser Menge geheilt. Sich selbst als Ziel wählen nicht möglich.'],
1587=>['Engelsbindung','Elite-Fertigkeit. 10 Sekunde[n] lang wird das nächste Mal, wenn ein Verbündeter in Hörweite tödlichen Schaden erleiden würde, dieser Schaden aufgehoben und der Verbündete um 20...200 Lebenspunkt[e] geheilt. Engelsbindung endet bei allen anderen Verbündeten.','Elite-Fertigkeit. 10 Sekunde[n]: Das nächste Mal, wenn ein Verbündeter in Hörweite tödlichen Schaden erleiden würde, wird dieser Schaden aufgehoben und der Verbündete um 20...200 geheilt. Endet bei allen anderen Verbündeten.'],
1588=>['Siegel der Verätzung','Elite-Siegel. Alle Gruppenmitglieder verlieren alle Zustände. Ihr werdet für jeden Zustand, der auf diese Weise entfernt wird, 1 Sekunde lang in Brand gesetzt.','Elite-Siegel. Alle Gruppenmitglieder verlieren alle Zustände. Ihr beginnt zu brennen (1 Sekunde pro entferntem Zustand).'],
1589=>['"Haltet Eure Stellung!"','Schrei. 5...20 Sekunde[n] lang erhalten alle Gruppenmitglieder in Hörweite +24 Rüstung, wenn sie sich nicht bewegen.','Schrei. 5...20 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten +24 Rüstung, wenn sie sich nicht bewegen.'],
1590=>['"Geht voran!"','Schrei. Der Verbündete (bzw. Ihr selbst) bewegt sich pro Verbündeten in Hörweite 1...5 Sekunde[n] lang um 25% schneller (maximal 30 Sekunde[n] lang).','Schrei. 1...5 Sekunde[n] pro Verbündetem in Hörweite (maximal 30 Sekunde[n]): Der Verbündete (bzw. Ihr selbst) bewegt sich um 25% schneller.'],
1591=>['"Beeilt Euch!"','Schrei. 5...20 Sekunde[n] lang bewegt sich der Verbündete um 33% schneller. Diese Fertigkeit endet, wenn der Verbündete erfolgreich angreift.','Schrei. 5...20 Sekunde[n]: Der Verbündete bewegt sich um 33% schneller. Endet, sobald der Verbündete mit einem Angriff trifft. Sich selbst als Ziel wählen nicht möglich.'],
1592=>['"Wir kommen wieder!"','Schrei. Alle Gruppenmitglieder in Hörweite werden mit 25...50% Lebenspunkten und 5...20% Energiepunkten wiederbelebt.','Schrei. Alle Gruppenmitglieder in Hörweite werden wiederbelebt (25...50% Lebenspunkte, 5...20% Energiepunkte).'],
1593=>['"Gebt nicht auf!"','Schrei. alle Verbündeten in Hörweite, deren Lebenspunkte unter 75% liegen, erhalten 1...10 Energiepunkt[e].','Schrei. Verbündete in Hörweite erhalten 1...10 Energiepunkt[e]. Betrifft nur Verbündete, die weniger als 75% ihrer maximalen Lebenspunkte haben.'],
1594=>['"Hilfe!"','Schrei. Der Zielverbündete, der kein Geist ist, erhält 15...90 Lebenspunkte. 1...10 Sekunden werden Zauber anderer Verbündeter, die diesen Verbündeten zum Ziel haben, 50 % schneller gewirkt.','Schrei. (1...10 Sekunden) Der Zielverbündete, der kein Geist ist, erhält 15...90 Lebenspunkte. Zauber anderer Verbündeter, die diesen Verbündeten zum Ziel haben, werden 50 % schneller gewirkt.'],
1595=>['"Zieht Euch zurück!"','Schrei. 4...10 Sekunde[n] erhalten alle Verbündeten in Hörweite 5...15 Lebenspunkt[e] pro Sekunde, wenn sie sich bewegen und bewegen sich um 33% schneller. "Zurückweichen!" endet bei einem Verbündeten, der von diesem Schrei betroffen ist, wenn er erfolgreich angreift.','Schrei. 4...10 Sekunde[n]: Verbündete in Hörweite erhalten 5...15 Lebenspunkt[e] pro Sekunde, wenn sie sich bewegen. Sie bewegen sich um 33% schneller. Endet für einen Verbündeten, wenn er mit einem Angriff trifft.'],
1596=>['"Schon unterwegs!"','Elite-Schrei. 4...10 Sekunden lang bewegen sich alle Verbündeten in Hörweite um 33% schneller und gewinnen 5...15 Lebenspunkte pro Sekunde, während sie in Bewegung sind.','Elite-Schrei. (4...10 Sekunden.) Verbündete in Hörweite bewegen sich 33% schneller und gewinnen 5...15 Lebenspunkte pro Sekunde, solange sie in Bewegung sind.'],
1597=>['"Sie brennen!"','Schrei. 10 Sekunde[n] lang erleiden Gruppenmitglieder in Hörweite 5...35% weniger Schaden von Feinden, die brennen.','Schrei. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erleiden von brennenden Feinden 5...35% weniger Schaden.'],
1598=>['"Ergebt Euch nicht!"','Schrei. 15 Sekunde[n] lang erfreuen sich alle Gruppenmitglieder in Hörweite, deren Lebenspunkte unter 75% liegen, einer Lebenspunktregeneration von +1...5.','Schrei. 15 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten +1...5 Lebenspunktregeneration. Betrifft nur Gruppenmitglieder, die weniger als 75% ihrer maximalen Lebenspunkte haben.'],
1599=>['Es ist nur eine Fleischwunde.','Elite-Schrei. Der Verbündete verliert alle Zustände. Wenn ein Zustand auf diese Weise entfernt wird, bewegt sich dieser Verbündete 1...10 Sekunde[n] lang um 25% schneller.','Elite-Schrei. Entfernt alle Zustände vom Verbündeten. Dieser Verbündete bewegt sich um 25% schneller (1...10 Sekunde[n]), wenn ein Zustand entfernt wurde. Sich selbst als Ziel auswählen ist nicht möglich.'],
1600=>['Stachelspeer','Speerangriff. Wenn dieser Angriff erfolgreich ist, leidet Euer Gegner 5...20 Sekunde[n] lang an einer Blutung.','Speerangriff. Verursacht Zustand Blutung (5...20 Sekunde[n]).'],
1601=>['Bösartiger Angriff','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Ihr mit diesem Angriff einen kritischen Treffer landet, leidet der Gegner 5...15 Sekunde[n] lang an einer Tiefen Wunde.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Verursacht mit einem kritischen Treffer Zustand Tiefe Wunde (5...15 Sekunde[n]).'],
1602=>['Betäubender Schlag','Elite-Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...50 Punkt[e] Schaden zu. Wenn er einen Feind trifft, der unter einem Zustand leidet, wird dieser 4...10 Sekunde[n] lang betäubt.','Elite-Speerangriff. Richtet +10...50 Punkt[e] Schaden an. Verursacht Zustand Benommenheit (4...10 Sekunde[n]), falls der Gegner einen Zustand hat.'],
1603=>['Unbarmherziger Speer','Speerangriff. Wenn dieser Angriff einen Gegner trifft, dessen Lebenspunkte unter 50% liegen, leidet dieser 5...20 Sekunde[n] lang an einer Tiefen Wunde.','Speerangriff. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]). Gegner muss weniger als 50% seiner maximalen Lebenspunkte haben, sonst keine Wirkung.'],
1604=>['Unterbrechender Wurf','Speerangriff. Wenn dieser Angriff einen Gegner trifft, der unter einem Zustand leidet, wird er unterbrochen.','Speerangriff. Unterbricht Aktionen. Gegner muss einen Zustand haben, sonst keine Wirkung.'],
1605=>['Wilder Wurf','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt er +5...20 Punkt[e] Schaden zu und jegliche Haltung, die von Eurem Gegner eingenommen wird, endet. Dieser Angriff kann nicht geblockt werden. Alle Eure Angriffsfertigkeiten, die nicht auf Speeren beruhen, werden 3 Sekunde[n] lang deaktiviert.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Kann nicht geblockt werden. Beendet die Haltung des Gegners.Eure Angriffsfertigkeiten, die nicht auf Speeren beruhen, werden 3 Sekunde[n] lang deaktiviert.'],
1633=>['Böswilliger Stoß','Nahkampfangriff. Wenn dieser Angriff einen Gegner trifft, der an einem Zustand leidet, fügt Ihr +10...30 Punkt[e] Schaden zu und der Angriff führt zu einem kritischen Treffer.','Nahkampfangriff. Dieser Angriff richtet +10...30 Punkt[e] Schaden an und ist ein kritischer Treffer, falls der Gegner einen Zustand hat.'],
1634=>['Vernichtender Angriff','Elite-Doppelangriff. Muss einem Begleithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt Ihr 5...50 Punkt[e] Schaden zu und der Gegner verliert eine Verzauberung. Dieser Angriff kann nicht geblockt werden.','Elite-Doppelangriff. Richtet 5...50 Punkt[e] Schaden an. Entfernt eine Verzauberung. Kann nicht geblockt werden. Muss einem Begleithandangriff folgen.'],
1635=>['Goldener Schädel-Stoß','Elite-Begleithandangriff. Wenn Ihr mit einer Verzauberung belegt seid und dieser Angriff trifft, leidet der Gegner 1...12 Sekunde[n] lang an Benommenheit.','Elite-Begleithandangriff. Verursacht Zustand Benommenheit (1...12 Sekunde[n]). Ihr müsst verzaubert sein, sonst keine Wirkung.'],
1636=>['Schwarzer Spinnen-Stoß','Begleithandangriff. Muss einen verhexten Feind treffen. Wenn er trifft, fügt dieser Angriff +5...20 Punkt[e] Schaden zu und der Feind wird 5...20 Sekunde[n] lang vergiftet.','Begleithandangriff. Richtet +5...20 Punkt[e] Schaden an. Verursacht Zustand Gift (5...20 Sekunde[n]). Muss einen verhexten Feind treffen.'],
1637=>['Goldener Fuchs-Stoß','Leithandangriff. Wenn dieser Angriff erfolgreich ist, erleidet der Gegner +10...30 Punkt[e] Schaden. Wenn Ihr unter dem Einfluss einer Verzauberung steht, kann der Angriff nicht geblockt werden.','Leithandangriff. Richtet +10...30 Punkt[e] Schaden an. Kann nicht geblockt werden, falls Ihr verzaubert seid.'],
1638=>['Tödliche Eile','Verzauberung. 10...35 Sekunde[n] lang werden Zauber mit halber Reichweite um 5...50% schneller gewirkt und um 5...60% schneller wieder aufgeladen.','Verzauberung. 10...35 Sekunde[n]: Ihr könnt Eure Zauber mit halber Reichweite um 5...50% schneller wirken und sie laden sich um 5...60% schneller wieder auf.'],
1639=>['Mittel des Assassinen','Verzauberung. Während der nächsten 30 Sekunde[n] entfernen Eure nächsten 1...10 Angriffsfertigkeiten einen Zustand.','Verzauberung. 30 Sekunde[n]: Eure nächsten 1...10 Angriffsfertigkeit[en] entfernen je einen Zustand.'],
1640=>['Versprechen des Fuchses','Elite-Verzauberung. 5...20 Sekunde[n] lang können Eure Dolchangriffe nicht geblockt werden. Diese Verzauberung endet, wenn Ihr das nächste Mal nicht trefft.','Elite-Verzauberung. 5...20 Sekunde[n]: Eure Dolchangriffe können nicht geblockt werden. Endet, sobald Ihr nicht trefft.'],
1641=>['Vorgetäuschte Neutralität','Verzauberung. 4...10 Sekunde[n] lang erfreut Ihr Euch einer Lebenspunktregeneration von +7 und +80 Rüstung. Diese Verzauberung endet, wenn Ihr mit einem Angriff erfolgreich trefft oder eine Fertigkeit verwendet.','Verzauberung. 4...10 Sekunde[n]: Ihr habt +7 Lebenspunktregeneration und +80 Rüstung. Endet, wenn Ihr mit einem Angriff trefft oder eine Fertigkeit benutzt.'],
1642=>['Versteckte Trittnägel','Elite-Verhexung. Eure Nicht-Assassinen-Fertigkeiten sind 3 Sekunden lang deaktiviert. Für 1...10 Sekunden bewegt sich der anvisierte Gegner um 50 % langsamer. Wenn die Verhexung endet, wird dieser Gegner für 1...15 Sekunden verkrüppelt.','Elite-Verhexung. (1...10 Sekunde[n].) Bewirkt eine 50%ige Verlangsamung der Bewegung. Wirkung am Ende: Verursacht Zustand Verkrüppelung (1...15 Sekunde[n]). Eure Nicht-Assassinen-Fertigkeiten sind 10 Sekunden lang deaktiviert.'],
1643=>['Verzauberungen angreifen','Elite-Fertigkeit. Muss einem Doppelangriff folgen. Der Gegner verliert alle Verzauberungen.','Elite-Fertigkeit. Entfernt alle Verzauberungen. Muss einem Doppelangriff folgen.'],
1644=>['Verfall des Verschwenders','Elite-Fertigkeit. Ihr unternehmt einen Schattenschritt zum Gegner hin. Wenn dieser keine Fertigkeit benutzt, wird er zu Boden geworfen. Alle Eure Angriffsfertigkeiten, die nicht auf Dolchen beruhen, sind 10 Sekunde[n] lang deaktiviert.','Elite-Fertigkeit. Unternehmt einen Schattenschritt zum Gegner. Gegner wird zu Boden geworfen, wenn er keine Fertigkeit benutzt. Deaktiviert Eure Angriffsfertigkeiten, die nicht auf Dolchen beruhen (10 Sekunde[n]).'],
1645=>['Verzauberung lösen','Fertigkeit. Wenn der berührte Gegner am Boden liegt, verliert er eine Verzauberung.','Berührungs-Fertigkeit. Entfernt eine Verzauberung. Gegner muss zu Boden geworfen sein, sonst keine Wirkung.'],
1646=>['Todesomen','Verhexung. Während der nächsten 5...35 Sekunde[n] fügt Ihr das nächste Mal, wenn die Lebenspunkte des Gegners durch hinzugefügten Schaden auf weniger als 50% fallen, 5...20 Sekunde[n] lang eine Tiefe Wunde zu und unternehmt einen Schattenschritt zu diesem Gegner hin. Dieser Zauber hat nur die halbe Reichweite.','Mitteldistanz-Verhexung. 5...35 Sekunde[n]: Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]) und unternimmt einen Schattenschritt zum Gegner, wenn Schaden seine Lebenspunkte das nächste Mal unter 50% seiner maximalen Lebenspunkte bringen würde.'],
1647=>['Siegel des toxischen Schocks','Siegel. Wenn der Gegner vergiftet ist, erleidet er 10...100 Punkt[e] Schaden.','Siegel. Richtet 10...100 Punkt[e] Schaden an. Gegner muss vergiftet sein, sonst keine Wirkung.'],
1648=>['Siegel des Zwielichts','Siegel. Pro Verhexung, mit der der Gegner belegt ist, verliert dieser eine Verzauberung.','Siegel. Entfernt eine Verzauberung pro Verhexung auf dem Gegner.'],
1649=>['Weg des Assassinen','Elite-Haltung. 20 Sekunde[n] lang greift Ihr, während Ihr Dolche führt, um 5...20% schneller an und habt eine +5...35%ige Chance, ein kritischen Treffer zu erzielen.','Elite-Haltung. 20 Sekunde[n]: Ihr greift, während Ihr Dolche führt, Ihr um 5...20% schneller an und habt eine +5...35%ige Chance, ein kritischen Treffer zu erzielen.'],
1650=>['Schattenmarsch','Haltung. Schattenschritt zum Gegner. 15 Sekunde[n] lang geschieht nichts. Eure Angriffsfertigkeiten sind 1 Sekunde lang deaktiviert und Eure Haltungen und Verzauberungen sind 10 Sekunden lang deaktiviert. Wenn diese Haltung endet, kehrt Ihr zu Eurem Ausgangsort zurück.','Haltung. (15 Sekunde[n].) Schattenschritt zum Gegner. Wirkung am Ende: Ihr kehrt zu Eurem Ausgangsort zurück. Deaktiviert Eure Angriffsfertigkeiten 1 Sekunde lang. Deaktiviert Eure Verzauberungen und Haltungen 10 Sekunden lang.'],
1651=>['Rückzug des Todes','Zauber. Schattenschritt zum Verbündeten. Wenn Ihr weniger Lebenspunkte als dieser Verbündete habt, erhaltet Ihr 40...130 Lebenspunkt[e].','Zauber. Ihr erhaltet 40...130 Lebenspunkt[e], falls Ihr weniger Lebenspunkte habt als der Verbündete. Anfangswirkung: Unternehmt einen Schattenschritt zum Verbündeten. Sich selbst als Ziel wählen nicht möglich.'],
1652=>['Schattengefängnis','Elite-Verhexung. Schattenschritt zum Gegner. 1...7 Sekunde[n] lang bewegt sich dieser Gegner um 66% langsamer.','Elite-Verhexung. Unternehmt einen Schattenschritt zum Gegner. Der Gegner bewegt sich um 66% langsamer (1...7 Sekunde[n]).'],
1653=>['Tauschen','Zauber. Ihr und die herbeigerufene Kreatur macht einen Schattenschritt zum Standort des jeweils anderen.','Zauber. Ihr und die herbeigerufene Kreatur macht einen Schattenschritt zum Standort des jeweils anderen.'],
1654=>['Schattenverschmelzung','Elite-Verzauberung. Ihr unternehmt einen Schattenschritt zum Verbündeten hin. Wenn Ihr diese Verzauberung nicht länger aufrechterhaltet, kehrt Ihr an Euren ursprünglichen Ort zurück.','Elite-Verzauberung. Unternehmt einen Schattenschritt zum Verbündeten. Wirkung am Ende: Ihr kehrt zur anfänglichen Position zurück. Sich selbst als Ziel wählen nicht möglich.'],
1655=>['Preis des Stolzes','Verhexung. Während der nächsten 5 Sekunde[n] verliert der Gegner bei der nächsten Verwendung einer Elite-Fertigkeit 3...15 Energiepunkt[e].','Verhexung. 5 Sekunde[n]: Lässt den Gegner 3...15 Energiepunkt[e] verlieren, wenn er das nächste Mal eine Elite-Fertigkeit benutzt.'],
1656=>['Flair der Entzauberung','Elite-Verhexung. Entfernt eine Verzauberung vom Gegner und allen Feinden in der Nähe. 5...20 Sekunde[n] lang enden Verzauberungen auf diesen Feinden um 150...300% schneller.','Elite-Verhexung. Verhext auch Feinde in der Nähe Eures Gegners (5...20 Sekunde[n]). Entfernt eine Verzauberung vom Gegner und allen Feinden in der Nähe. Verzauberungen auf diesen Feinden enden um 150...300% schneller.'],
1657=>['Siegel der Unbeholfenheit','Siegel. Wenn der Gegner angreift, werden er und alle umstehenden Feinde unterbrochen und erleiden 15...60 Punkt[e] Schaden. Gegner, die Angriffsfertigkeiten verwenden, werden zu Boden geworfen.','Siegel. Unterbricht einen Angriff des Gegners und aller umstehenden Feinde. Unterbrechungswirkung: Richtet 15...60 Punkt[e] Schaden an und wirft Gegner, die Angriffsfertigkeiten verwenden, zu Boden.'],
1658=>['Symbolische Haltung','Haltung. 5...20 Sekunde[n] lang wird das nächste Siegel, das Ihr aktiviert, um 20...80% schneller aufgeladen.','Haltung. 5...20 Sekunde[n]: Euer nächstes Siegel lädt sich um 20...80% schneller wieder auf.'],
1659=>['Toxische Kälte','Elite-Zauber. Der Gegner erleidet 15...75 Punkt[e] Kälteschaden. Falls er mit einer Verhexung oder Verzauberung belegt ist, leidet er 10...25 Sekunde[n] lang an einer Vergiftung.','Elite-Zauber. Richtet 15...75 Punkt[e] Kälteschaden an. Verursacht Zustand Gift (10...25 Sekunde[n]), falls der Gegner verhext oder verzaubert ist.'],
1660=>['Brunnen der Stille','Brunnenzauber. Nutzt die anvisierte Leiche oder opfert 66 % Eurer Lebenspunkte, um für 10...30 Sekunden einen Brunnen der Stille zu erzeugen. Gegner innerhalb des Brunnens können keine Kampfschreie oder Gesänge verwenden und erleiden -1...4 Lebenspunktdegeneration.','Brunnenzauber. (10...30 Sekunden). Gegner in diesem Brunnen können keine Kampfschreie oder Gesänge verwenden und haben -1...4 Lebenspunktregeneration. Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
1661=>['Leuchtstein','Zauber. Sendet ein Geschoss aus, das dem Gegner 5...50 Punkt[e] Erdschaden zufügt, wenn es trifft. Wenn dieser Zauber einen geschwächten Gegner trifft, erhaltet Ihr 5 Energiepunkt[e] sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung.','Zauber. Geschoss: Richtet 5...50 Punkt[e] Erdschaden an. Ihr erhaltet 5 Energiepunkt[e] sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung, wenn der Gegner unter Schwäche leidet.'],
1662=>['Geistige Explosion','Elite-Zauber. Der Gegner erleidet 15...60 Punkt[e] Feuerschaden. Wenn Ihr mehr Energie als dieser Gegner habt, erhaltet Ihr 1...8 Energiepunkt[e].','Elite-Zauber. Richtet 15...60 Punkt[e] Feuerschaden an. Ihr erhaltet 1...8 Energiepunkt[e], falls Ihr mehr Energie habt als der Gegner.'],
1663=>['Elementare Flamme','Verzauberung. Während der nächsten 10...35 Sekunden wird der Gegner jedes Mal, wenn auf ihn eine Elementar-Verhexung gerichtet wird, 1...5 Sekunden lang in Brand gesetzt.','Verzauberung. (10...35 Sekunden.) Verursacht jedes Mal den Zustand Brennen (1...5 Sekunden), wenn eine Elementar-Verhexung auf den Gegner gerichtet wird.'],
1664=>['Blitz herbeirufen','Elite-Zauber. Der Gegner und bis zu zwei andere in der Nähe befindliche Feinde erleiden 10...90 Punkt[e] Blitzschaden. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Elite-Zauber. Richtet 10...90 Punkt[e] Blitzschaden an. Trifft zwei Feinde in der Nähe des Ziels. 25% Rüstungsdurchdringung.'],
1683=>['Nachdenklicher Wächter','Verzauberung. 5...11 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine 50%ige Chance Angriffe von verzauberten Gegnern zu blocken.','Verzauberung. 5...11 Sekunde[n]: 50%ige Chance, Angriffe verzauberter Gegner zu blocken.'],
1684=>['Einblick des Schreibers','Elite-Verzauberung. Während der nächsten 10...35 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn Ihr ein Siegel benutzt, 3 Energiepunkt[e].','Elite-Verzauberung. 10...35 Sekunde[n]: Ihr erhaltet jedes Mal 3 Energiepunkt[e], wenn Ihr ein Siegel benutzt.'],
1685=>['Heilige Eile','Verzauberung. 1...60 Sekunde[n] lang werden Eure Heilgebet-Zauber um 50% schneller gewirkt. Diese Verzauberung endet, wenn Ihr eine andere Verzauberung wirkt.','Verzauberung. 1...60 Sekunde[n]: Ihr könnt Eure Heilgebet-Zauber um 50% schneller wirken. Endet, wenn Ihr eine Verzauberung wirkt.'],
1686=>['Lichtschimmer','Elite-Zauber. Heilt Verbündeten (bzw. Euch selbst) um 10...115 Lebenspunkt[e].','Elite-Zauber. Heilt um 10...115 Lebenspunkt[e].'],
1687=>['Eifrige Segnung','Elite-Zauber. Heilt den Verbündeten (bzw. Euch selbst) um 30...180 Lebenspunkt[e]. Wenn seine Lebenspunkte unter 50% lagen, erhaltet Ihr 7 Energiepunkt[e].','Elite-Zauber. Heilt um 30...180 Lebenspunkt[e]. Ihr erhaltet 7 Energiepunkt[e], falls der Verbündete (bzw. Ihr selbst) weniger als 50% seiner maximalen Lebenspunkte hatte.'],
1688=>[' Eifer des Verteidigers','Elite-Verhexung. 10...30 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn der Gegner einen erfolgreichen Angriff landet, 2 Energiepunkt[e].','Elite-Verhexung. 10...30 Sekunde[n]: Ihr erhaltet jedes Mal 2 Energiepunkt[e], wenn ein Angriff des Gegners trifft.'],
1689=>['Siegel des mystischen Zorns','Siegel. Der Gegner erleidet für jede Verzauberung, mit der Ihr belegt seid, 25 Punkt[e] heiligen Schaden (maximal 30...120 Punkt[e] heiligen Schaden).','Siegel. Richtet für jede Verzauberung auf Euch 25 Punkt[e] heiligen Schaden an (maximal 30...120).'],
1690=>['Siegel der Entfernung','Elite-Siegel. Wenn der Verbündete (bzw. Ihr selbst) unter dem Einfluss einer Verzauberung steht, verliert er eine Verhexung und einen Zustand.','Elite-Siegel. Entfernt eine Verhexung und einen Zustand. Der Verbündete (bzw. Ihr selbst) muss verzaubert sein, sonst keine Wirkung.'],
1691=>['Zustand aufheben','Zauber. Entfernt einen Zustand vom Verbündeten (bzw. Euch selbst). Wenn dieser Verbündete unter den den Auswirkungen einer Verzauberung leidet, wird er um 15...75 Lebenspunkt[e] geheilt.','Zauber. Entfernt einen Zustand. Heilt um 15...75 Lebenspunkt[e], falls der Verbündete (bzw. Ihr selbst) verzaubert ist.'],
1692=>['Verhexungen umleiten','Elite-Zauber. Entfernt bis zu 1...3 Verhexung[en] vom Verbündeten. Für jede Verhexung, die auf diese Weise entfernt wird, verliert der Verbündete einen Zustand und erhält 15...75 Lebenspunkt[e].','Elite-Zauber. Entfernt 1...3 Verhexung[en]. Für jede entfernte Verhexung verliert der Verbündete (bzw. Ihr selbst) einen Zustand und erhält 15...75 Lebenspunkt[e].'],
1693=>['Gegenangriff','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...35 Punkt[e] Schaden zu. Wenn Ihr einen angreifenden Gegner trefft, erhaltet Ihr 2...6 Energiepunkt[e].','Nahkampfangriff. Richtet +5...35 Punkt[e] Schaden an. Ihr erhaltet 2...6 Energiepunkt[e], falls der Gegner gerade angreift.'],
1694=>['Magierschlag','Elite-Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt er +7...25 Punkt[e] Schaden zu. Wenn Euer Gegner unter dem Einfluss einer Verzauberung steht, kann der Angriff nicht geblockt werden.','Elite-Nahkampfangriff. Richtet +7...25 Punkt[e] Schaden an. Kann nicht geblockt werden, falls Gegner verzaubert ist.'],
1695=>['Soldatenstoß','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...40 Punkt[e] mehr Schaden zu. Wenn Ihr mit einem Anfeuerungsruf oder Schrei belegt seid, kann dieser Angriff nicht geblockt werden.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an. Kann nicht geblockt werden, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht.'],
1696=>['Köpfen','Elite-Axtangriff. You lose all adrenaline and all Energy. This attack is unblockable, you deal +5...80 damage, and cause a Deep Wound for 5...20 seconds. This attack is always critical and if foe is killed, nearby foes are Weakened for 8 seconds.','Elite-Axtangriff. Deals +5...80 damage. Inflicts Deep Wound condition (5...20 seconds). Automatic critical hit. If foe is killed, nearby foes are Weakened (8 seconds). You lose all adrenaline and Energy.'],
1697=>['Magiejägerschmetterer','Elite-Hammerangriff. Wenn dieser Angriff erfolgreich ist, wird der Gegner zu Boden geworfen. Wenn Euer Gegner unter dem Einfluss einer Verzauberung steht, kann der Angriff nicht geblockt werden.','Elite-Hammerangriff. Wirft zu Boden. Kann nicht geblockt werden, wenn Gegner verzaubert ist.'],
1698=>['Soldaten-Haltung','Elite-Haltung. 5...15 Sekunde[n] lang habt Ihr eine 75%ige Chance zu blocken. Ihr greift um 33% schneller an, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht.','Elite-Haltung. (5...15 Sekunde[n].) Ihr habt eine 75%ige Chance zu blocken. Ihr greift um 33% schneller an, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht.'],
1699=>['Soldaten-Verteidigung','Haltung. 1...6 Sekunde[n] lang habt Ihr eine 75%ige Chance, Angriffe zu blocken, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht. Für jeden geblockten Angriff erhaltet Ihr 1 Adrenalinstoß.','Haltung. (1...6 Sekunde[n].) Ihr habt eine 75%ige Chance zu blocken, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht. Blockwirkung: Ihr erhaltet 1 Adrenalinstoß.'],
1700=>['Fieberhafte Verteidigung','Haltung. 8 Sekunde[n] lang habt Ihr eine 75%ige Chance Angriffe zu blocken, dafür erleidet Ihr aber doppelten Schaden.','Haltung. 8 Sekunde[n]: Ihr habt eine 75%ige Chance zu blocken. Ihr erleidet doppelten Schaden.'],
1701=>['Ruhige Haltung','Elite-Haltung. 10 Sekunde[n] lang erhaltet Ihr das nächste Mal, wenn Ihr zu Boden geworfen würdet, stattdessen 1...4 Adrenalinstöße und 1...7 Energiepunkt[e].','Elite-Haltung. 10 Sekunde[n]: Das nächste Mal, wenn Ihr zu Boden geworfen würdet, erhaltet Ihr stattdessen 1...4 Adrenalinstöße und 1...7 Energiepunkt[e].'],
1702=>['Hieb des stählernen Fangzahns','Schwertangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +1...31 Punkt[e] Schaden zu. Wenn Ihr einen Gegner trefft, der zu Boden geworfen wurde, erhaltet Ihr 1...5 Adrenalin.','Schwertangriff. Richtet +1...31 Punkt[e] Schaden an. Ihr erhaltet 1...5 Adrenalinstöße, falls Gegner zu Boden geworfen ist.'],
1719=>['Schreischuss','Bogenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +10...25 Punkt[e] Schaden zu. Wenn Euer Gegner in Hörweite ist, leidet er 5...20 Sekunde[n] lang an einer Blutung.','Bogenangriff. Richtet +10...25 Punkt[e] Schaden an. Verursacht Zustand Blutung (5...20 Sekunde[n]), falls der Gegner in Hörweite ist.'],
1720=>['Scharfer Pfeil','Bogenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Falls Ihr einen kritischen Treffer landet, fügt Ihr zusätzlich 5...25 Punkt[e] Schaden zu.','Bogenangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet zusätzlich +5...25 Punkt[e] Schaden an, falls Ihr einen kritischen Treffer landet.'],
1721=>['Gemeinsam toben','Elite-Fertigkeit. 3...15 Sekunde[n] lang greift Ihr und Euer Tiergefährte um 33% schneller an und lauft um 25% schneller.','Elite-Fertigkeit. 3...15 Sekunde[n]: Ihr und Euer Tiergefährte greift um 33% schneller an und bewegt Euch um 25% schneller. Euer Tiergefährte muss am Leben sein, sonst keine Wirkung.'],
1722=>['Gegabelter Pfeil','Bogenangriff. Schießt zwei Pfeile gleichzeitig auf den Gegner ab. Wenn Ihr mit einer Verzauberung oder Verhexung belegt seid, schießt Ihr nur einen Pfeil ab.','Bogenangriff. Ihr feuert zwei Pfeile gleichzeitig ab. Ihr feuert nur einen Pfeil ab, falls Ihr verzaubert oder verhext seid.'],
1723=>['Unterbrechende Genauigkeit','Vorbereitung. Während der nächsten 36 Sekunde[n] unterbrechen Eure Pfeile bei jedem kritischen Treffer auch Euer Ziel.','Vorbereitung. 36 Sekunde[n]: Unterbricht jedes Mal eine Aktion, wenn Ihr mit einem Pfeil einen kritischen Treffer landet.'],
1724=>['Gewandtheit des Profis','Elite-Haltung. 1...20 Sekunde[n] lang greift Ihr um 33% schneller an und Euer Attribut Treffsicherheit ist um 2 erhöht.','Elite-Haltung. 1...20 Sekunde[n]: Ihr greift um 33% schneller an und Euer Attribut Treffsicherheit wird um +2 erhöht.'],
1725=>['Tosender Wind','Naturritual. Erstellt einen Geist der Stufe 1...10. Anfeuerungsrufe und Schreie kosten 1...5 Punkt[e] mehr Energie. Dieser Geist stirbt nach 30...180 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (30...180 Sekunde[n] Lebensdauer). Schreie und Anfeuerungsrufe kosten Kreaturen in Reichweite +1...5 Energiepunkt[e].'],
1726=>['Verderben des Magiers-Schuss','Elite-Bogenangriff. Wenn dieser Angriff erfolgreich ist, unterbricht er die Aktion des Gegners. Wenn diese Aktion ein Zauber war, wird er zusätzlich 10 Sekunden[n] lang deaktiviert. Dieser Angriff kann nicht geblockt werden.','Elite-Bogenangriff. Unterbricht eine Aktion. Unterbrechungswirkung: Unterbrochener Zauber ist +10 Sekunde[n] lang deaktivert. Kann nicht geblockt werden.'],
1727=>['Natürlicher Schwung','Haltung. 1...8 Sekunde[n] lang lauft Ihr um 33% schneller und habt eine 50%ige Chance, Angriffe zu blocken. Natürlicher Schwung endet, wenn Ihr verhext oder verzaubert werdet.','Haltung. 1...8 Sekunde[n]: Ihr bewegt Euch um 33% schneller und habt eine 50%ige Chance zu blocken. Endet, sobald Ihr verhext oder verzaubert werdet.'],
1728=>['Heket-Toben','Haltung. 5...11 Sekunde[n] lang sind Eure Angriffe um 33% schneller. Diese Haltung endet, sobald Ihr eine Angriffsfertigkeit verwendet.','Haltung. 5...11 Sekunde[n]: Ihr greift um 33% schneller an. Endet, sobald Ihr eine Angriffsfertigkeit verwendet.'],
1729=>['Rauchfalle','Elite-Falle. Wenn die Rauchfalle ausgelöst wird, werden Gegner im Bereich 5...10 Sekunden lang geblendet und benommen. Die Rauchfalle endet nach 90 Sekunden. Beim Aktivieren dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Elite-Falle. (90 Sekunden.) Fügt Gegnern im Bereich die Zustände Geblendet und Benommen zu (5...10 Sekunden). Leicht zu unterbrechen.'],
1730=>['Irritierende Hitze','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10. Kreaturen in seiner Reichweite, die keine Geister sind, erhalten Adrenalin doppelt so schnell. Dieser Geist stirbt nach 30...120 Sekunde[n].','Elite-Naturritual. Erstellt einen Geist der Stufe 1...10 (30...120 Sekunde[n] Lebensdauer). Verdoppelt für Kreaturen in Reichweite die erhaltene Adrenalinmenge.'],
1731=>['Lautstark war Sogolon','Gegenstandszauber. 60 Sekunde[n] lang dauern alle von Euch verwendeten Schreie und Anfeuerungsrufe um 20...50% länger an.','Gegenstandszauber. 60 Sekunde[n]: Eure Schreie und Anfeuerungsrufe halten um 20...50% länger an.'],
1732=>['Vernichtend war Glaive','Elite-Gegenstandszauber. Haltet Glaives Asche bis zu 30...60 Sekunde[n] lang. Während Ihr ihre Asche haltet, haben alle Ritualisten-Fertigkeiten eine Rüstungsdurchdringung von 20%. Wenn Ihr ihre Asche fallen lasst, erleiden alle Feinde in dem Bereich 15...85 Punkt[e] Blitzschaden.','Elite-Gegenstandszauber. (30...60 Sekunde[n].) Eure Ritualisten-Fertigkeiten haben eine Rüstungsdurchdringung von 20%. Fallwirkung: Richtet bei allen Feinden im Bereich 15...85 Punkt[e] Blitzschaden an.'],
1733=>['Stoß des Ausübers','Zauber. Der Gegner erleidet 10...60 Punkte Blitzschaden. Wenn Ihr unter dem Einfluss eines Waffenzaubers steht, fügt Ihr zusätzlich 10...50 Punkt[e] Blitzschaden zu.','Zauber. Richtet 10...60 Punkt[e] Blitzschaden an. Richtet zusätzlich 10...50 Punkt[e] Blitzschaden an, falls Ihr unter dem Einfluss eines Waffenzaubers steht.'],
1734=>['Wütendes Starren','Binderitual. Vernichtet den anvisierten Geist und erstellt einen Geist der Wut der Stufe 1...14. Die Angriffe dieses Geistes fügen 5...20 Punkt[e] Schaden zu. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Vernichtet einen Geist. Erstellt einen Geist der Stufe 1...14 (30...60 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an.'],
1736=>['Geistesstärke','Elite-Verzauberung. 15...60 Sekunde[n] lang fügen Eure Angriffe 5...35 Punkt[e] mehr Schaden zu, wenn Ihr unter den Auswirkungen eines Waffenzaubers steht.','Elite-Verzauberung. 15...60 Sekunde[n]: Eure Angriffe richten +5...35 Punkt[e] Schaden an, falls Ihr unter dem Einfluss eines Waffenzaubers steht.'],
1737=>['Eifer des Ausübers','Elite-Verzauberung. 10...40 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn Ihr einen Waffenzauber auf einen Verbündeten wirkt, 1...5 Energiepunkt[e].','Elite-Verzauberung. 10...40 Sekunde[n]: Ihr erhaltet jedes Mal 1...5 Energiepunkt[e], wenn Ihr einen Waffenzauber wirkt.'],
1738=>['Sicht jenseits der Sicht','Verzauberung. Ihr könnt 8...20 Sekunde[n] lang nicht geblendet werden.','Verzauberung. 8...20 Sekunde[n]: Ihr seid immun gegen Blindheit.'],
1739=>['Erneuernde Erinnerungen','Verzauberung. 5...20 Sekunde[n] lang kostet Euch beim Halten eines Gegenstandes das Wirken aller Waffen- und Gegenstandszauber um 5...35% weniger Energie.','Verzauberung. 5...20 Sekunde[n]: Eure Waffen- und Gegenstandszauber kosten 5...35% weniger Energie. Ihr müsst einen Gegenstand halten, sonst keine Wirkung.'],
1740=>['Mittel des Ausübers','Verzauberung. 10...30 Sekunden lang verliert ein Verbündeter jedes Mal 2 Zustände, wenn Ihr einen Waffenzauber auf ihn wirkt.','Verzauberung. (10...30 Sekunde[n]) Ein Verbündeter verliert jedes Mal 2 Zustände, wenn Ihr einen Waffenzauber auf ihn wirkt.'],
1741=>['Geisterspiegel-Licht','Zauber. Der Verbündete wird um 15...90 Lebenspunkt[e] geheilt. Wenn Ihr Euch in Hörweite eines Geistes befindet, werdet Ihr ebenfalls um 15...90 Lebenspunkt[e] geheilt.','Zauber. Heilt um 15...90 Lebenspunkt[e]. Ihr erhaltet 15...90 Lebenspunkt[e], falls Ihr Euch in Hörweite eines Geistes befindet. Sich selbst als Ziel wählen nicht möglich.'],
1742=>['Siegel der Macht der Geister','Elite-Siegel. 5...20 Sekunde[n] lang greifen alle von Euch kontrollierten Geister in Hörweite um 33% schneller an und richten um +5...10 Punkte mehr Schaden an.','Elite-Siegel. 5...20 Sekunde[n]: Alle von Euch kontrollierten Geister in Hörweite greifen um 33% schneller an und richten um +5...10 Punkte mehr Schaden an.'],
1743=>['Siegel der Bindung','Siegel. Ihr verliert 200...50 Lebenspunkt[e] und übernehmt die Kontrolle über den vom Gegner kontrollierten Geist. (Bei einer Macht des Herbeirufens von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Siegel. Ihr verliert 200...50 Lebenspunkt[e]. Übernehmt die Kontrolle über den vom Gegner kontrollierten Geist. <c x="SkillDull">Mindestens Macht des Herbeirufens 5, sonst 50%ige Chance auf Misserfolg.'],
1744=>['Angriff des Verwalters','Elite-Zauber. Der Gegner erleidet 20...85 Punkt[e] Blitzschaden. Wenn Ihr einen Gegenstand haltet, erhaltet Ihr 7 Energiepunkte und 5...50 Lebenspunkt[e].','Elite-Zauber. Richtet 20...85 Punkt[e] Blitzschaden an. Ihr erhaltet 7 Energiepunkte und 5...50 Lebenspunkt[e], falls Ihr einen Gegenstand haltet.'],
1745=>['Qual','Binderitual. Erstellt einen Geist der Stufe 1...11. Die Angriffe dieses Geistes fügen 5...20 Punkt[e] Schaden zu und verursachen bei verhexten Feinden doppelten Schaden. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...11 (15...45 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an. Doppelter Schaden bei verhexten Feinden.'],
1747=>['Ermächtigung','Binderitual. Erstellt einen Geist der Stufe 1...14. Alle Verbündeten in seiner Reichweite, die einen Gegenstand halten, erhalten 15...45 maximale Lebenspunkt[e] und 10 maximale Energiepunkte. Dieser Geist stirbt nach 15...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...14 (15...60 Sekunde[n] Lebensdauer). Verbündete in Reichweite erhalten +15...45 maximale Lebenspunkte und +10 maximale Energiepunkte, falls sie einen Gegenstand halten.'],
1748=>['Gesundung','Binderitual. Erstellt einen Geist der Stufe 1...14. Zustände, mit denen Verbündeten in Reichweite dieses Geistes belegt sind, enden um 20...50% schneller. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...14 (30...60 Sekunde[n] Lebensdauer). Zustände auf Verbündeten in Reichweite enden um 20...50% früher.'],
1749=>['Waffe der Wut','Elite-Waffenzauber. 5...20 Sekunde[n] lang erhält der Verbündete (bzw. Ihr selbst) bei jedem erfolgreichen Treffer mit einem Angriff um 100% mehr Adrenalin und 1 Energiepunkt.','Elite-Waffenzauber. 5...20 Sekunde[n]: +100% zur erhaltenen Adrenalinmenge und +1 Energiepunkt, wenn ein Angriff des Verbündeten (bzw. von Euch selbst) trifft.'],
1750=>['Xinraes Waffe','Elite-Waffenzauber. Wenn der Verbündete (bzw. Ihr selbst) innerhalb der nächsten 8 Sekunde[n] das nächste Mal Schaden durch einen Feind erleidet, ist dieser Schaden auf 5% der maximalen Lebenspunkte des Verbündeten begrenzt und er entzieht dem Gegner bis zu 20...80 Lebenspunkt[e].','Elite-Waffenzauber. 8 Sekunde[n]: Wenn der Verbündete (bzw. Ihr selbst) das nächste Mal Schaden durch einen Feind erleidet, ist dieser Schaden auf 5% der maximalen Lebenspunkte des Verbündeten begrenzt und er entzieht dem Feind bis zu 20...80 Lebenspunkt[e].'],
1751=>['Waffe des Kriegshetzers','Waffenzauber. Während der nächsten 3...13 Sekunde[n] wird jedes Mal, wenn der Verbündete einen Feind angreift, der selbst nicht angreift, dieser Feind unterbrochen.','Waffenzauber. 3...13 Sekunde[n]: Angriffe unterbrechen eine Aktion. Unterbricht angreifende Feinde nicht.'],
1752=>['Waffe der Behebung','Elite-Waffenzauber. 8 Sekunden lang stiehlt der Zielverbündete das nächste Mal, wenn ein Gegner ihm Schaden oder Lebensentzug zufügt, diesem Gegner bis zu 20...80 Lebenspunkte, und er verliert 2 Zustände.','Elite-Waffenzauber. (8 Sekunden) Der Zielverbündete stiehlt das nächste Mal, wenn ein Gegner ihm Schaden oder Lebensentzug zufügt, diesem Gegner bis zu 20...80 Lebenspunkte, und er verliert 2 Zustände.'],
1753=>['Zerreißender Schwung','Sensenangriff. Ihr richtet +5...20 Punkt[e] Schaden an und verliert 1 Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wird, entfernt Ihr eine Verzauberung von jedem Feind, den Ihr trefft.','Sensenangriff. Richtet +5...20 Punkt[e] Schaden an. Ihr verliert 1 Derwisch-Verzauberung. Entfernungseffekt: Getroffene Feinde verlieren eine Verzauberung.'],
1754=>['Attacke','Elite-Blitzverzauberung. 3...15 Sekunde[n] lang erfolgen Eure Angriffe, Bewegungen und Euer Adrenalingewinn um 25% schneller.','Elite-Blitzverzauberung. (3...15 Sekunde[n].) Eure Angriffe, Bewegungen und Euer Adranalingewinn erfolgen um 25% schneller.'],
1755=>['Mystische Verdorbenheit','Blitzverzauberung. Alle umstehenden Feinde leiden 1...10 Sekunde[n] lang an Krankheit. 20 Sekunde[n] lang geschieht nichts. Wenn Ihr verzaubert seid, während Ihr diese Fertigkeit aktiviert, wird die Dauer von Krankheit verdoppelt. Wenn diese Verzauberung endet, werden alle Gruppenmitglieder in Hörweite von Krankheit geheilt.','Blitzverzauberung. (20 Sekunde[n].) Anfangswirkung: Alle umstehenden Feinde leiden unter Krankheit. (1...10 Sekunde[n]). Doppelte Dauer, wenn Ihr bereits verzaubert seid. Wirkung am Ende: Gruppenmitglieder in Hörweite werden von Krankheit geheilt.'],
1756=>['Grenths Griff','Elite-Blitzverzauberung. For 20 seconds, your attack skills also Cripple that foe for 1...11 seconds and you transfer 1...3 conditions from yourself to that foe.','Elite-Blitzverzauberung. (20 seconds.) Inflict Cripple (1...11 seconds) with your attack skills and transfer 1...3 conditions.'],
1757=>['Dornenschleier','Blitzverzauberung. Wenn Ihr Verzauberung wirkt, erleiden alle Feinde in der Nähe 5...50 Punkt[e] Stichschaden. 5...25 Sekunde[n] lang erleidet Ihr von Zaubern 5...35% weniger Schaden.','Blitzverzauberung. (5...25 Sekunde[n].) Zauberschaden um 5...35% verringert. Anfangswirkung: In der Nähe befindliche Feinde erleiden 5...50 Punkt[e] Stichschaden.'],
1758=>['Griff des Läufers','Blitzverzauberung. Während der nächsten 5...20 Sekunde[n] fügen Angriffe gegen Feinde, die sich bewegen, dem Feind 2...9 Sekunde[n] "Verkrüppelung" zu. Wenn Ihr diese Verzauberung wirkt, werden Verkrüppelung und 1 weiterer Zustand von Euch entfernt. Diese Verzauberung endet, wenn Ihr 1...3 Mal Verkrüppelung zugefügt habt.','Blitzverzauberung. (5...20 Sekunde[n].) Angriffe auf sich bewegende Feinde fügen zusätzlich "Verkrüppelung" zu. Anfangswirkung: Ihr verliert "Verkrüppelung" und 1 weiteren Zustand. Endet, wenn Ihr 1...3 Mal Verkrüppelung zugefügt habt.'],
1759=>['Gelübde der Stärke','Elite-Verzauberung. Wenn Ihr einen Gegner mit Eurer Sense angreift, fügt Ihr 15 Sekunde[n] lang allen umstehenden Gegnern 10...25 Punkt[e] Hiebschaden zu.','Elite-Verzauberung. (15 Sekunde[n].) Angriffe mit einer Sense fügen allen umstehenden Feinden 10...25 Punkt[e] Hiebschaden zu.'],
1760=>['Ebon-Staubaura','Elite-Blitzverzauberung. Wenn Ihr diese Verzauberung wirkt, werden alle Feinde in der Nähe 1...7 Sekunde[n] lang geblendet. 30 Sekunde[n] fügen Eure Nahkampfangriffe +3...30 Punkt[e] Erdschaden zu, wenn Ihr eine Erdwaffe führt. Wenn diese Verzauberung endet, werdet Ihr von Blindheit geheilt.','Elite-Blitzverzauberung. (30 Sekunde[n].) Eure Nahkampfangriffe fügen +3...30 Punkt[e] Erdschaden zu. Anfangswirkung: Blendet Feine in der Nähe 1...7 Sekunde[n] lang. Wirkung am Ende: Entfernt Blindheit. Keine Wirkung, falls Ihr keine Erdwaffe benutzt.'],
1761=>['Eifriges Gelübde','Elite-Verzauberung. 20 Sekunde[n] lang beträgt Eure Energieregeneration -2 und Ihr bekommt jedes Mal, wenn einer Eurer Angriffe trifft, 1...6 Energiepunkt[e].','Elite-Verzauberung. 20 Sekunde[n]: Ihr erhaltet jedes Mal 1...6 Energiepunkt[e], wenn ein Angriff von Euch trifft. Ihr habt -2 Energieregeneration.'],
1762=>['Herz der Wut','Haltung. 2...10 Sekunde[n] lang sind Eure Angriffe um 25% schneller.','Haltung. (2...10 Sekunde[n].) Ihr greift um 25% schneller an.'],
1763=>['Eifrige Erneuerung','Blitzverzauberung. Alle in der Nähe befindlichen Gegner erleiden 5...30 Punkt[e] heiligen Schaden. 5...25 Sekunde[n] lang beträgt Eure Energieregeneration -1 und Ihr bekommt jedes Mal, wenn einer Eurer Angriffe trifft, 1 Energiepunkt. Wenn diese Verzauberung vorzeitig endet, erhaltet Ihr 1...5 Energiepunkt[e].','Blitzverzauberung. (5...25 Sekunde[n].) Anfangswirkung: Richtet bei in der Nähe befindlichen Feinden 5...30 Punkt[e] heiligen Schaden an. Eure Energieregeneration beträgt -1 und Ihr bekommt jedes Mal, wenn einer Eurer Angriffe trifft, 1 Energiepunkt. Wenn diese Verzauberung vorzeitig endet, erhaltet Ihr 1...5 Energiepunkt[e].'],
1764=>['Einblick des Angreifers','Blitzverzauberung. 3...10 Sekunde[n] lang habt Ihr eine Chance von 50%, beim Angreifen zu blocken. Wenn diese Verzauberung endet, fügt Ihr allen umstehenden Feinden 3...15 Sekunde[n] lang Schwäche zu.','Blitzverzauberung. (3...10 Sekunde[n].) Gewährt eine Chance von 50%, beim Angreifen zu blocken. Wirkung am Ende: Fügt umstehenden Feinden 3...15 Sekunde[n] lang Schwäche zu.'],
1765=>['Zerreißende Aura','Blitzverzauberung. Wenn Ihr diese Verzauberung wirkt, erleiden alle Feinde in der Nähe 10...40 Punkt[e] Kälteschaden. 30 Sekunde[n] lang entfernen Eure Angriffsfertigkeiten Verzauberungen von zu Boden geworfenen Feinden. Wenn diese Verzauberung endet, leiden in der Nähe befindliche Feinde 1...10 Sekunde[n] unter "Beschädigte Rüstung".','Blitzverzauberung. (30 Sekunde[n].) Eure Angriffsfertigkeiten entfernen Verzauberungen von zu Boden geworfenen Feinden. Anfangswirkung: Richtet bei allen Feinden in der Nähe 10...40 Punkt[e] Kälteschaden an. Wirkung am Ende: In der Nähe befindliche Feinde leiden 1...10 Sekunde[n] lang an Beschädigter Rüstung.'],
1766=>['Anmut des Federfußes','Verzauberung. 5...20 Sekunde[n] lang bewegt Ihr Euch um 25% schneller und Zustände enden um 50% schneller.','Verzauberung. 5...20 Sekunde[n]: Ihr bewegt Euch um 25% schneller und Zustände auf Euch enden um 50% früher.'],
1767=>['Schwung des Schnitters','Elite-Sensenangriff. Wenn dieser Angriff erfolgreich ist, leidet Euer Gegner 3...15 Sekunde[n] lang an Verkrüppelung. Ihr verliert 1 Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wurde, wirft dieser Angriff 2...3 Sekunde[n] lang zu Boden,','Elite-Sensenangriff. (3...15 Sekunde[n].) Verursacht Verkrüppelung. Ihr verliert 1 Derwisch-Verzauberung. Entfernungseffekt: Wirft 2...3 Sekunde[n] lang zu Boden.'],
1768=>['Eile des Läufers','Blitzverzauberung. 2...8 Sekunde[n] lang bewegt Ihr Euch um 25% schneller und fügt Feinden, die sich bewegen, +3...12 Punkt[e] mehr Schaden zu.','Blitzverzauberung. (2...8 Sekunde[n].) Ihr bewegt Euch um 25% schneller und richtet bei Feinden, die sich bewegen, +3...12 Punkt[e] Schaden an.'],
1769=>['Konzentrierter Zorn','Elite-Fertigkeit. 45 Sekunde[n] lang erhaltet Ihr um 0...150% mehr Adrenalin.','Elite-Fertigkeit. 45 Sekunde[n]: Ihr erhaltet 0...150% mehr Adrenalin.'],
1770=>['Natürliche Laune','Fertigkeit. 4...15 Sekunde[n] lang erhaltet Ihr um 33% mehr Adrenalin, wenn Ihr nicht mit einer Verzauberung belegt seid.','Fertigkeit. 4...15 Sekunde[n]: Ihr erhaltet 33% mehr Adrenalin. Keine Wirkung, falls Ihr verzaubert seid.'],
1771=>['Gesang der Wiederherstellung','Elite-Anfeuerungsruf. 10 Sekunde[n] lang erhält jedes Gruppenmitglied in Hörweite, wenn es das nächste Mal eine Fertigkeit einsetzt, 45...110 Lebenspunkt[e].','Elite-Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten bei Benutzung ihrer nächsten Fertigkeit 45...110 Lebenspunkt[e].'],
1772=>['Lyrik der Läuterung','Anfeuerungsruf. Während der nächsten 5...20 Sekunde[n] lang verliert jeder Verbündete in Hörweite bei der nächsten Verwendung eines Siegels 1 Zustand.','Anfeuerungsruf. 5...20 Sekunde[n]: Verbündete in Hörweite verlieren bei Benutzung ihres nächsten Siegels einen Zustand.'],
1773=>['Wut des Soldaten','Elite-Echo. 10...35 Sekunde[n] lang greift Ihr um 33% schneller an und erhaltet um 33% mehr Adrenalin, wenn Ihr mit einem Anfeuerungsruf oder Schrei belegt seid, allerdings habt Ihr -20 Rüstung.','Elite-Echo. (10...35 Sekunde[n].) Ihr greift um 33% schneller an und erhaltet um 33% mehr Adrenalin, falls Ihr unter dem Einfluss eines Schreis oder Anfeuerungsrufs steht. Ihr habt -20 Rüstung.'],
1774=>['Aggressiver Refrain','Echo. 5...25 Sekunde[n] lang sind Eure Angriffe um 25% schneller, aber Ihr habt -20 Rüstung. Dieses Echo wird jedes Mal wiederholt, wenn ein auf Euch gerichteter Anfeuerungsruf oder Schrei endet.','Echo. (5...25 Sekunde[n].) Ihr greift um 25% schneller an. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf Euch endet. Ihr habt -20 Rüstung.'],
1775=>['Energie bringendes Finale','Echo. 10...35 Sekunde[n] lang erhält der Nicht-Geister-Verbündete jedes Mal, wenn ein auf ihn gerichteter Anfeuerungsruf oder Schrei endet, 1...2 Energiepunkt[e].','Echo. 10...35 Sekunde[n]: Der Verbündete (bzw. Ihr selbst) erhält jedes Mal 1...2 Energiepunkt[e], wenn ein Schrei oder Anfeuerungsruf auf ihm endet. Nicht auf Geister anwendbar.'],
1776=>['Siegel der Aggression','Siegel. Wenn Ihr mit einem Schrei oder Anfeuerungsruf belegt seid, erhaltet Ihr 2 Adrenalinstöße.','Siegel. Ihr erhaltet 2 Adrenalinstöße, falls Ihr unter dem Einfluss eines Schreis oder Anfeuerungsrufs steht.'],
1777=>['Heilmittel-Siegel','Siegel. Ihr verliert 1 Zustand.','Siegel. Ihr verliert einen Zustand.'],
1778=>['Siegel der Wiederkehr','Siegel. Belebt das ausgewählte Gruppenmitglied mit 5...20% seiner Lebens- und 1...4% seiner Energiepunkte pro Gruppenmitglied in Hörweite.','Siegel. Das Gruppenmitglied wird wiederbelebt (5...20% Lebenspunkte und 1...4% Energiepunkte pro Gruppenmitglied in Hörweite).'],
1779=>['"Nehmt Euch Zeit!"','Schrei. Ihr erhaltet 2 Adrenalinschläge für jedes Gruppenmitglied in Hörweite (maximal 1...8 Adrenalin).','Schrei. Ihr erhaltet 2 Adrenalin (maximal 1...8) für jedes Gruppenmitglied in Hörweite.'],
1780=>['"Darf nicht angerührt werden!"','Schrei. Während der nächsten 20 Sekunde[n] scheitern der nächste[n] gegen Verbündete in Hörweite gerichtete[n] 1...5 Berührungs-Fertigkeit[en].','Schrei. (20 Sekunde[n].) Der nächste[n] gegen Verbündete in Hörweite gerichtete[n] 1...5 Berührungs-Fertigkeit[en] scheitern.'],
1781=>['"Findet ihren Schwachpunkt!"','Schrei. 5...20 Sekunden[n] lang verursacht der nächste Angriff des Verbündeten +5...50 Schaden sowie 5...20 Sekunde[n] lang eine Tiefe Wunde.','Schrei. (5...20 Sekunde[n].) Dieser Verbündete verursacht mit dem nächsten Angriff +5...50 Schaden sowie (5...20 Sekunde[n]) den Zustand Tiefe Wunde.'],
1782=>['"Die Macht ist Euer!"','Elite-Schrei. 2...4 Sekunde[n] lang erhalten alle Verbündeten in Hörweite 1...2 Energieregeneration.','Elite-Schrei. 2...4 Sekunde[n]: Verbündete in Hörweite erhalten 1...2 Energieregeneration.'],
1783=>['Speer des Würgers','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...25 Punkt[e] Schaden zu. Wenn der Gegner mehr Lebenspunkte als Ihr hat, leidet er 5...20 Sekunde[n] lang an einer Tiefen Wunde.','Speerangriff. Richtet +5...25 Punkt[e] Schaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls der Gegner mehr Lebenspunkte hat als Ihr.'],
1784=>['Schneller Speer','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Ihr mit einer Verzauberung belegt seid, fliegt dieser Speer doppelt so schnell und kann nicht geblockt werden.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Dieser Speer bewegt sich mit doppelter Geschwindigkeit und kann nicht geblockt werden, falls Ihr verzaubert seid.'],
1814=>['Blick des Lichtbringers','Fertigkeit. Der ausgewählte dämonische Diener Abaddons erleidet 100 Punkt[e] heiligen Schaden und wird unterbrochen. Diese Fertigkeit trifft pro Rang, den Ihr bei Lichtbringer erworben habt, einen zusätzlichen Feind in dem Bereich. Diese Fertigkeit wird nach ihrer Verwendung 15 Sekunden lang deaktiviert.','Fertigkeit. Der ausgewählte dämonische Diener Abaddons erleidet 100 Punkt[e] heiligen Schaden und wird unterbrochen. Trifft pro Rang, den Ihr bei Lichtbringer erworben habt, einen zusätzlichen Feind im Bereich. Diese Fertigkeit wird deaktiviert (15 Sekunden).'],
1815=>['Lichtbringer-Siegel','Siegel. Wenn Ihr Euch im Bereich eines dämonischen Dieners Abaddons befindet, erhaltet Ihr 3...5 Adrenalinstöße und 16...24 Energiepunkt[e].','Siegel. Ihr erhaltet 3...5 Adrenalinstöße und 16...24 Energiepunkt[e], wenn Ihr Euch im Bereich eines dämonischen Dieners Abaddons befindet.'],
1816=>['Sonnenspeer-Wiedergeburtssiegel','Siegel. Das tote Gruppenmitglied wird an Eurer Position mit vollen Lebenspunkten und 10% Energiepunkte pro Sonnenspeer-Rang, den Ihr erreicht habt, wiederbelebt. Das Siegel kann nur einmal pro Mission verwendet werden, es sei denn, es wird durch einen Moralschub aufgeladen.','Siegel. Das tote Gruppenmitglied wird an Eurer Position wiederbelebt (volle Lebenspunkte, 10% Energiepunkte pro Sonnenspeer-Rang, den Ihr erreicht habt). Das Siegel wird erst aufgeladen, wenn Ihr einen Moralschub erhalten habt.'],
1948=>['Schattenzuflucht','Verzauberung. Ihr seid 5 Sekunde[n] lang geblendet. 10 Sekunde[n] lang erhaltet Ihr +7...10 Lebenspunktregeneration und +40 Rüstung.','Verzauberung. 10 Sekunde[n]: Ihr erhaltet +7...10 Lebenspunktregeneration und +40 Rüstung. Ihr seid geblendet (5 Sekunde[n]).'],
1949=>['Äther-Alptraum','Verhexung. Der Gegner verliert 5...8 Energiepunkt[e]. Der Gegner und alle Feinde in dem Bereich erleiden 10 Sekunde[n] lang eine Lebenspunktdegeneration in Höhe der verlorenen Energiepunkte.','Verhexung. Lässt 5...8 Energiepunkt[e] verlieren. Der Gegner und Feinde im Gebiet haben -1 Lebenspunktdegeneration pro verlorenem Energiepunkt (10 Sekunde[n]).'],
1950=>['Siegel der Verdorbenheit','Siegel. Der Gegner und alle Feinde in der Nähe erleiden 20...30 Punkte Schaden. Pro betroffenen Feind, der unter einem Zustand oder einer Verhexung leidet, erhaltet Ihr 2 Punkt[e] Energie (maximal 12...20 Punkt[e]).','Siegel. Richtet beim Gegner und Feinden in der Nähe 20...30 Punkt[e] Schaden an. Ihr erhaltet für jeden dieser Gegner mit einem Zustand oder einer Verhexung 2 Energiepunkt[e] (maximal 12...20).'],
1951=>['Elementarlord','Verzauberung. 40...60 Sekunde[n] lang erhalten Eure Elementarattribute einen Schub von 1. Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr 1 Energiepunkt pro 10 Ränge in Energiespeicherung und werdet um 100...300% der Energiekosten dieses Zaubers geheilt.','Verzauberung. (40...60 Sekunde[n].) Eure Elementarattribute erhalten einen Schub von 1. Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr 1 Energiepunkt pro 10 Ränge in Energiespeicherung und werdet um 100...300% der Energiekosten dieses Zaubers geheilt.'],
1952=>['Selbstloser Geist','Verzauberung. 15...20 Sekunde[n] lang kosten von Euch auf einen weiteren Verbündeten gewirkte Zauber 3 Punkt[e] weniger Energie.','Verzauberung. (15...20 Sekunde[n].) Zauber, die Ihr auf einen weiteren Verbündeten wirkt, kosten 3 Punkt[e] weniger Energie.'],
1953=>['Dreifachschuss','Bogenangriff. 3 Pfeile werden gleichzeitig auf den Gegner abgefeuert. Diese Pfeile fügen 40...25% weniger Schaden zu.','Bogenangriff. Ihr feuert drei Pfeile gleichzeitig auf den Gegner ab. Diese Pfeile richten 40...25% weniger Schaden an.'],
1954=>['"Rettet Euch selbst!"','Schrei. 4...6 Sekunden lang erhalten alle anderen Gruppenmitglieder +100 Rüstung.','Schrei. 4...6 Sekunde[n]: Alle anderen Gruppenmitglieder erhalten +100 Rüstung.'],
1955=>['Aura der Heiligen Macht','Verzauberung. Wenn Ihr eine Derwisch-Verzauberung verliert, fügt Ihr 45 Sekunde[n] lang allen umstehenden Feinden 20...25 Punkt[e] heiligen Schaden zu.','Verzauberung. (45 Sekunde[n].) Immer wenn Ihr eine Derwisch-Verzauberung verliert, erleiden alle umstehenden Feinde 20...25 Punkt[e] heiligen Schaden.'],
1957=>['Speer der Wut','Speerangriff. Dieser Angriff fügt +30...40 Punkt[e] Schaden zu. Wenn er einen Feind trifft, der an einem Zustand leidet, erhaltet Ihr 3...6 Adrenalinstöße.','Speerangriff. Richtet +30...40 Punkt[e] Schaden an. Ihr erhaltet 3...6 Adrenalinstöße, falls Ihr einen Feind mit einem Zustand trefft.'],
1986=>['Vampirangriff','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn dieser Angriff erfolgreich ist, entzieht Ihr 10...40 Lebenspunkt[e].','Doppelangriff. Entzieht 10...40 Lebenspunkt[e], falls dieser Angriff trifft. Muss einem Begleithandangriff folgen.'],
1987=>['Lotus-Stoß','Begleithandangriff. Muss einem Leithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt er +10...25 Punkt[e] Schaden zu und Ihr erhaltet 5...20 Energiepunkt[e].','Begleithandangriff. Richtet +10...25 Punkt[e] Schaden an; Ihr erhaltet 5...20 Energiepunkt[e]. Muss einem Leithandangriff folgen.'],
1988=>['Goldfangstoß','Begleithandangriff. Muss einem Leithandangriff folgen. Wenn Ihr verzaubert seid und dieser Angriff einen Treffer landet, leidet der Gegner 5...20 Sekunde[n] lang an einer Tiefen Wunde.','Begleithandangriff. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls Ihr verzaubert seid. Muss einem Leithandangriff folgen.'],
1990=>['Fallender Lotus-Stoß','Begleithandangriff. Muss einen zu Boden geworfenen Gegner treffen. Wenn Ihr erfolgreich seid, fügt Ihr +15...35 Punkt[e] Schaden zu und erhaltet 1...12 Energiepunkt[e].','Begleithandangriff. Richtet +15...35 Punkt[e] Schaden an; Ihr erhaltet 1...12 Energiepunkt[e]. Gegner muss zu Boden geworfen sein, sonst keine Wirkung.'],
1991=>['Siegel des Sadisten','Siegel. Ihr erhaltet pro Zustand auf dem Gegner 10...45 Lebenspunkt[e].','Siegel. Ihr erhaltet pro Zustand auf dem Gegner 10...45 Lebenspunkt[e].'],
1992=>['Siegel der Ablenkung','Siegel. Falls der Gegner einen Zauber wirkt, wird dieser unterbrochen und pro Siegel, das Ihr ausgerüstet habt, 1...5 Sekunde[n] lang deaktiviert.','Siegel. Unterbricht einen Zauber. Unterbrechungswirkung: Der Zauber des Gegners wird deaktiviert (1...5 Sekunde[n] für jedes Siegel, das Ihr ausgerüstet habt).'],
1993=>['Siegel der Zurückrufung','Siegel. 6 Sekunde[n] lang beträgt Eure Energieregeneration -4. Wenn dieser Effekt endet, erhaltet Ihr 13...20 Energiepunkt[e].','Siegel. 6 Sekunde[n]: Ihr habt -4 Energieregeneration. Wirkung am Ende: Ihr erhaltet 13...20 Energiepunkt[e].'],
1994=>['Kraftsperre','Zauber. Falls der Gegner einen Zauber oder Anfeuerungsruf wirkt, wird dieser unterbrochen und zusätzlich 5...13 Sekunde[n] lang deaktiviert.','Zauber. Unterbricht einen Zauber oder Anfeuerungsruf. Unterbrechungswirkung: unterbrochener Zauber oder Anfeuerungsruf wird zusätzlich 5...13 Sekunde[n] lang deaktiviert.'],
1995=>['Spare in der Zeit ...','Zauber. Wenn der Gegner keinen Zauber wirkt oder angreift, erhaltet Ihr 8...13 Energiepunkt[e].','Zauber. Ihr erhaltet 8...13 Energiepunkt[e], falls der Gegner gerade nicht angreift oder einen Zauber wirkt.'],
1996=>['Summe aller Ängste','Verhexung. 4...12 Sekunde[n] lang sind die Bewegungen, Angriffe und Wirkgeschwindigkeit von Zaubern des Gegners um 33% langsamer.','Verhexung. 4...12 Sekunde[n]: Bewegung, Angriffe und das Wirken von Zaubern sind beim Gegner um 33% verlangsamt.'],
1997=>['Verkümmernde Aura','Verzauberung. 5...20 Sekunde[n] lang verursachen die Nahkampfangriffe des Verbündeten (bzw. Eure eigenen) 5...20 Sekunde[n] lang Schwäche.','Verzauberung. 5...20 Sekunde[n]: Die Nahkampfangriffe des Verbündeten (bzw. von Euch selbst) verursachen den Zustand Schwäche (5...20 Sekunde[n]).'],
1998=>['Kakophonie','Verhexung. 15 Sekunde[n] lang erleidet der Gegner jedes Mal, wenn er einen Schrei oder Anfeuerungsruf benutzt, 30...105 Punkt[e] Schaden.','Verhexung. 15 Sekunde[n]: Richtet jedes Mal 30...105 Punkt[e] Schaden an, wenn der Gegner einen Schrei oder Anfeuerungsruf benutzt.'],
1999=>['Umarmung des Winters','Verhexung. Während der nächsten 2...6 Sekunde[n] bewegt sich der Gegner um 66% langsamer und erleidet 5...15 Punkt[e] Schaden, während er sich bewegt.','Verhexung. (2...6 Sekunde[n].) Der Gegner bewegt sich um 66% langsamer und erleidet 5...15 Punkt[e] Schaden, während er sich bewegt.'],
2000=>['Irdene Fesseln','Verhexung. 3 Sekunden lang bewegen sich der Gegner und alle Feinde in der Nähe um 90% langsamer. Wenn Irdene Fesseln endet, verursacht es Schwäche für 5...20 Sekunden','Verhexung. (3 Sekunden.) Der Gegner und alle umstehenden Feinde bewegen sich um 90% langsamer. Verursacht Schwäche für 5...20 Sekunden, wenn es endet.'],
2001=>['Kreis der Schwäche','Abwehrzauber. Erzeugt an Eurer gegenwärtigen Position einen Kreis der Schwäche. 5...20 Sekunde[n] lang werden Feinde in diesem Bereich jedes Mal, wenn sie Elementarschaden erleiden, für 5...20 Sekunde[n] geschwächt.','Abwehrzauber. (5...20 Sekunde[n].) Verursacht bei allen Feinden in dieser Abwehr, die Elementarschaden erleiden, den Zustand Schwäche (5...20 Sekunde[n]).'],
2002=>['Glyphe der Schnelligkeit','Glyphe. 15 Sekunde[n] lang werden Eure nächsten 1...5 Zauber um 25% schneller wieder aufgeladen und Geschosse von ihnen bewegen sich um 200% schneller.','Glyphe. (15 Sekunde[n].) Eure nächsten 1...5 Zauber laden sich um 25% schneller auf und mit ihnen abgefeuerte Geschosse bewegen sich um 200% schneller.'],
2003=>['Verhexung heilen','Zauber. Entfernt eine Verhexung vom Verbündeten (bzw. Euch selbst). Wenn eine Verhexung entfernt wurde, wird der Verbündete um 30...100 Lebenspunkt[e] geheilt.','Zauber. Entfernt eine Verhexung. Entfernungswirkung: Heilt um 30...100 Lebenspunkt[e].'],
2004=>['Zustand zerschlagen','Zauber. Entfernt einen Zustand vom Verbündeten (bzw. Euch selbst). Wenn ein Zustand entfernt wurde, erleiden Gegner in dem Bereich 10...60 Punkt[e] heiligen Schaden.','Zauber. Entfernt einen Zustand. Entfernungswirkung: Richtet bei Feinden im Bereich des Verbündeten (bzw. von Euch selbst) 10...60 Punkt[e] heiligen Schaden an.'],
2005=>['Segen des Peinigers','Verzauberung. 30 Sekunde[n] lang haben Eure Peinigungsgebete den doppelten Gunst-der-Götter-Bonus.','Verzauberung. 30 Sekunde[n]: Eure Peinigungsgebete haben den doppelten Gunst-der-Götter-Heilbonus.'],
2006=>['Geißelungs-Siegel','Siegel. Der Gegner erleidet 26...56 Punkt[e] heiligen Schaden. Falls er angegriffen hat, erhaltet Ihr 4...14 Energiepunkt[e].','Siegel. Richtet 26...56 Punkt[e] heiligen Schaden an. Ihr erhaltet 4...14 Energiepunkt[e], falls der Gegner gerade angreift.'],
2007=>['Reinigender Schleier','Verzauberung. Während Ihr diese Verzauberung aufrechterhaltet, enden Zustände auf den Verbündeten (bzw. Euch selbst) um 5...50% schneller. Wenn diese Verzauberung endet, wird ein Zustand vom Verbündeten entfernt.','Verzauberung. Zustände auf dem Verbündeten (bzw. Euch selbst) enden um 5...50% früher. Wirkung am Ende: Entfernt einen Zustand.'],
2008=>['Zermalmender Schlag','Hammerangriff. Wenn Ihr einen Gegner trefft, der zu Boden geworfen wurde, leidet dieser 5...20 Sekunde[n] lang an Schwäche und an einer Tiefen Wunde.','Hammerangriff. Verursacht die Zustände Schwäche und Tiefe Wunde (5...20 Sekunde[n]), falls Gegner zu Boden geworfen ist.'],
2009=>['Verwegener Hieb','Axtangriff. Wenn er erfolgreich ist, führt dieser Angriff immer zu einem kritischen Treffer.','Axtangriff. Immer ein kritischer Treffer.'],
2010=>['Knieschneider','Schwertangriff. Wenn dieser Angriff einen verkrüppelten Feind trifft, erhaltet Ihr 2...7 Energiepunkt[e] und 1...3 Adrenalinstöße.','Schwertangriff. Ihr erhaltet 2...7 Energiepunkt[e] und 1...3 Adrenalinstöße, falls der Gegner verkrüppelt ist.'],
2011=>['Raufen','Fertigkeit. Der berührte Gegner und Ihr werden zu Boden geworfen. Ihr verliert Eure aktuelle Haltung.','Berührungs-Fertigkeit. Wirft den Gegner zu Boden. Ihr werdet ebenfalls zu Boden geworfen. Eure aktuelle Haltung endet.'],
2012=>['Strahlende Sense','Sensenangriff. Dieser Angriff verursacht pro Energiepunkt, den Ihr momentan habt, +1 Punkt Schaden (maximal 5...30 Punkt[e] Schaden). Wenn dieser Angriff trifft, erhaltet Ihr 1...7 Energiepunkt[e].','Sensenangriff. Richtet für jeden Eurer Energiepunkte +1 Punkt Schaden an (maximal 5...30). Ihr erhaltet 1...7 Energiepunkt[e].'],
2013=>['Grenths Aura','Blitzverzauberung. 20 Sekunde[n] lang fügt Ihr 5...25 Punkt[e] weniger Schaden zu und stehlt 5...25 Lebenspunkt[e], wenn Ihr mit einer Sense trefft. Wenn Ihr Verzauberung wirkt, stehlt Ihr 5...25 Lebenspunkt[e] von allen umstehenden Feinden.','Blitzverzauberung. (20 Sekunde[n].) Ihr fügt 5...25 Punkt[e] weniger Schaden zu und stehlt 5...25 Lebenspunkt[e], wenn Ihr mit einer Sense trefft. Anfangswirkung: Stiehlt 5...25 Lebenspunkt[e] von allen umstehenden Feinden.'],
2014=>['Siegel der frommen Zurückhaltung','Siegel. Entfernt 1 Derwisch-Verzauberung. Der anvisierte Gegner erhält 5...15 Sekunde[n] lang Verkrüppelung. Wenn eine Verzauberung entfernt wurde, erhalten alle Gegner im Umkreis Eures Ziels ebenfalls Verkrüppelung, und dieses Siegel wird um 75 % schneller wieder aufgeladen.','Siegel. Verursacht den Zustand "Verkrüppelung" (5...15 Sekunde[n]). Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernen-Effekt: verursacht auch Verkrüppelung bei Gegnern im Umkreis Eures Ziels und wird um 75 % schneller wieder aufgeladen.'],
2015=>['Sense des Bauern','Sensenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Ihr mehr als einen Feind trefft, wird dieser Angriff sofort wieder aufgeladen.','Sensenangriff. Richtet +5...20 Punkt[e] Schaden an. Wird sofort wieder aufgeladen, falls Ihr mehr als einen Feind trefft.'],
2016=>['Energisch war Lee Sa','Gegenstandszauber. Haltet Lee Sas Asche 5...15 Sekunde[n] lang. Während Ihr ihre Asche haltet, erhaltet Ihr +2 Energieregeneration. Wenn Ihr ihre Asche fallen lasst, erhaltet Ihr +1...10 Energiepunkt[e].','Gegenstandszauber. 5...15 Sekunde[n]: Ihr habt +2 Energieregeneration. Fallwirkung: Ihr erhaltet +1...10 Energiepunkt[e].'],
2017=>['Hymne der Müdigkeit','Anfeuerungsruf. 8 Sekunde[n] lang führt die nächste Angriffsfertigkeit von jedem Verbündeten in Hörweite auch 1...16 Sekunde[n] lang zu Schwäche.','Anfeuerungsruf. 8 Sekunde[n]: Verbündete in Hörweite verursachen bei Benutzung ihrer nächsten Angriffsfertigkeit Schwäche (1...16 Sekunde[n]).'],
2018=>['Hymne der Störung','Anfeuerungsruf. 1...10 Sekunde[n] lang unterbricht die nächste Angriffsfertigkeit jedes Verbündeten in Hörweite außerdem eine Aktion.','Anfeuerungsruf. 1...10 Sekunde[n]: Verbündete in Hörweite unterbrechen bei Benutzung ihrer nächsten Angriffsfertigkeit eine Aktion.'],
2051=>['Geister herbeirufen','Zauber. Alle von Euch kontrollierten Geister unternehmen einen Schattenschritt zu Eurer Position und erhalten 60...100 Lebenspunkte.','Zauber. Von Euch kontrollierte Geister machen einen Schattenschritt zu Eurer Position und erhalten 60...100 Lebenspunkt[e].'],
2052=>['Schattenfangzahn','Verhexung. Ihr unternehmt einen Schattenschritt zum Gegner hin. 10 Sekunde[n] lang macht diese Verhexung nichts. Wenn sie endet, kehrt Ihr zu Eurer ursprünglichen Position zurück und der Gegner leidet 5...20 Sekunde[n] lang an einer Tiefen Wunde.','Verhexung. Unternehmt einen Schattenschritt zum Gegner. Wirkung am Ende (nach 10 Sekunde[n]): Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]); Ihr kehrt zur anfänglichen Position zurück.'],
2053=>['Kalkuliertes Risiko','Verhexung. 3...24 Sekunde[n] lang fügen Angriffe des Gegners +10 Punkte Schaden zu, aber es gibt bei jedem Angriff eine Chance von 50%, dass der Schaden stattdessen dem Gegner zugefügt wird. (Maximal 15...100 Punkt[e] Schaden)','Verhexung. (3...24 Sekunde[n].) Angriffe des Gegners richten +10 Punkte Schaden an. Bei jedem Angriff besteht eine Chance von 50%, dass der Schaden (maximal 15...100 Punkt[e]) stattdessen dem Gegner zugefügt wird.'],
2054=>['Schrumpfende Rüstung','Verhexung. 10 Sekunde[n] lang leidet der Gegner an einer Lebenspunktdegeneration von -1...4. Wenn diese Verhexung endet, hat der Gegner 5...20 Sekunde[n] lang eine Beschädigte Rüstung.','Verhexung. 10 Sekunde[n]: Verursacht -1...4 Lebenspunktdegeneration. Wirkung am Ende: Verursacht Zustand Beschädigte Rüstung (5...20 Sekunde[n]).'],
2055=>['Aneurysma','Zauber. Gegner erhält alle Energiepunkte zurück. Pro Energiepunkt, der auf diese Weise gewonnen wurde, erleidet der Gegner 1...3 Punkt[e] Schaden und alle umstehenden Gegner verlieren einen Energiepunkt. (Maximalverlust: 1...30 Energiepunkt[e])','Zauber. Gegner erhält alle Energiepunkte zurück. Pro gewonnenen Energiepunkt erleidet der Gegner 1...3 Punkt[e] Schaden und alle umstehenden Gegner verlieren einen Energiepunkt (maximal 1...30).'],
2056=>['Wanderndes Auge','Verhexung. 4 Sekunde[n] lang wird der nächste Angriff des Gegners, falls dieser anzugreifen versucht, unterbrochen und alle Feinde in der Nähe erleiden 30...110 Punkt[e] Schaden.','Verhexung. 4 Sekunde[n]: Unterbricht den nächsten Angriff des Gegners. Unterbrechungswirkung: 30...110 Punkt[e] Schaden bei Feinden in der Nähe.'],
2057=>['Widerliches Gelage','Zauber. Alle Zustände werden vom Verbündeten auf Euch übertragen. Für jeden auf diese Weise erhaltenen Zustand erhaltet Ihr 0...45 Lebenspunkte und 2...4 Energiepunkte. Diese Fertigkeit lädt doppelt so schnell auf, wenn Ihr "Krankheit" von Eurem Ziel entfernt.','Zauber. Alle Zustände werden vom Verbündeten auf Euch übertragen. Ihr erhaltet für jeden übertragenen Zustand 0...45 Lebenspunkt[e] und 2...4 Energiepunkt[e]. Die Wiederaufladezeit wird halbiert, wenn Ihr "Krankheit" entfernt. Sich selbst als Ziel wählen nicht möglich.'],
2058=>['Verwesende Galle','Verhexung. 5...25 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...3. Wenn er stirbt, während er mit dieser Verhexung belegt ist, erleiden alle Feinde in der Nähe 25...85 Punkt[e] Schaden.','Verhexung. 5...25 Sekunde[n]: Verursacht -1...3 Lebenspunktdegeneration. Richtet bei allen Feinden in der Nähe 25...85 Punkt[e] Schaden an, falls der Gegner stirbt.'],
2059=>['Kriegsneurose','Zauber. Der Gegner erleidet 10...30 Punkte Blitzschaden und leidet 5...20 Sekunden lang an Beschädigter Rüstung. Dieser Zauber hat eine Rüstungsdurchdringung von 25%. Wenn Ihr Überzaubert seid, trifft dieser Zauber umstehende Feinde.','Zauber. Richtet 10...30 Punkte Blitzschaden an. Verursacht den Zustand Beschädigte Rüstung (5...20 Sekunden). 25% Rüstungsdurchdringung. Wenn Überzaubert, werden auch umstehende Gegner getroffen.'],
2060=>['Glyphe der Aufopferung','Glyphe. 15 Sekunde[n] lang führen Eure nächsten 1...4 Zauber, die einen Gegner anvisieren, außerdem 1...4 Sekunde[n] lang zu Brennen.','Glyphe. (15 Sekunde[n].) Eure nächsten 1...4 auf Feinde gerichteten Zauber verursachen zusätzlich den Zustand Brennen (1...4 Sekunde[n]).'],
2061=>['Geduldiger Geist','Verzauberung. 2 Sekunde[n] lang wird ein Verbündeter mit Geduldiger Geist verzaubert. Sofern diese Verzauberung nicht vorzeitig beendet wird, wird dieser Verbündete um 30...120 Lebenspunkt[e] geheilt, wenn diese Verzauberung endet.','Verzauberung. (2 Sekunde[n].) Wirkung am Ende: Heilt 30...120 Lebenspunkt[e]. Keine Wirkung bei vorzeitiger Beendigung.'],
2062=>['Heilendes Band','Zauber. Der Verbündete wird um 20...110 Lebenspunkt[e] geheilt. Bis zu 2 zusätzliche Verbündete in der Nähe des Ziels werden um 10...100 Lebenspunkt[e] geheilt.','Zauber. Heilt um 20...110 Lebenspunkt[e]. Heilt zwei weitere Verbündete in der Nähe des Verbündeten um 10...100 Lebenspunkt[e]. Sich selbst als Ziel wählen nicht möglich.'],
2063=>['Aura der Stabilität','Verzauberung. 3...8 Sekunde[n] lang kann der Verbündete nicht zu Boden geworfen werden.','Verzauberung. 3...8 Sekunde[n]: Der Verbündete kann nicht zu Boden geworfen werden. Sich selbst als Ziel wählen nicht möglich.'],
2064=>['Makelloser Verstand','Verzauberung. 1...15 Sekunde[n] lang verliert der Verbündete alle 5 Sekunde[n] lang eine Verhexung.','Verzauberung. 1...15 Sekunde[n]: Entfernt nach je 5 Sekunde[n] eine Verhexung. Sich selbst als Ziel wählen nicht möglich.'],
2065=>['Makellose Seele','Verzauberung. 1...15 Sekunde[n] lang verliert der Verbündete alle 3 Sekunde[n] lang einen Zustand.','Verzauberung. 1...15 Sekunde[n]: Entfernt nach je 3 Sekunde[n] einen Zustand. Sich selbst als Ziel wählen nicht möglich.'],
2066=>['Entwaffnen','Schwertangriff. Unterbricht die Aktion des Gegners. Falls diese Aktion ein Angriff war, werden alle Angriffsfertigkeiten des Gegners 0...3 Sekunde[n] lang deaktiviert.','Schwertangriff. Unterbricht den Gegner. Unterbrechungswirkung: Deaktiviert die Angriffsfertigkeiten des Gegners (0...3 Sekunde[n]), falls die unterbrochene Aktion ein Angriff war.'],
2067=>['"Das war Absicht!"','Schrei. Wenn Ihr zu Boden geworfen wurdet, erhaltet Ihr 1...6 Adrenalinstöße.','Schrei. Ihr erhaltet 1...6 Adrenalinstöße, falls Ihr zu Boden geworfen werdet.'],
2068=>['Schnellfeuer','Vorbereitung. 5...25 Sekunde[n] lang sind Eure Angriffe um 33% schneller, wenn Ihr einen Bogen einsetzt.','Vorbereitung. 5...25 Sekunde[n]: Eure Angriffe sind um 33% schneller, wenn Ihr einen Bogen einsetzt.'],
2069=>['Schuss des Faultierjägers','Bogenangriff. Wenn dieser Angriff erfolgreich ist, erleidet der Gegner +10...25 Punkt[e] Schaden. Wenn er keine Fertigkeit verwendet, fügt Schuss des Faultierjägers zusätzlich 10...35 Punkt[e] Schaden zu.','Bogenangriff. Richtet +10...25 Punkt[e] Schaden an. Richtet zusätzlich +10...35 Punkt[e] Schaden an, falls der Gegner gerade keine Fertigkeit benutzt.'],
2070=>['Auraschneider','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, leidet Euer Gegner 5...15 Sekunde[n] lang an einer Blutung. Falls Ihr verzaubert seid, fügt Ihr außerdem 1...10 Sekunde[n] lang Beschädigte Rüstung zu.','Nahkampfangriff. (5...15 Sekunde[n].) Verursacht bei stehenden Feinden "Blutung". Verursacht ebenfalls Beschädigte Rüstung (1...10 Sekunde[n]), falls Ihr verzaubert seid.'],
2071=>['Eifriger Schwung','Sensenangriff. Wenn dieser Angriff erfolgreich ist, verursacht Ihr +5...20 Punkt[e] Schaden. Ihr erhaltet für jeden getroffenen Feind 3 Energiepunkt[e] und 1 Adrenalinstoß.','Sensenangriff. Richtet 5...20 Punkt[e] Schaden an. Ihr erhaltet für jeden getroffenen Feind 3 Energiepunkt[e] und 1 Adrenalinstoß.'],
2072=>['Rein war Li Ming','Gegenstandszauber. Haltet Li Mings Asche 5...20 Sekunde[n] lang. Während Ihr ihre Asche haltet, enden Zustände, mit denen Ihr belegt seid, um 10...50% schneller. Wenn Ihr ihre Asche fallen lasst, verlieren alle Verbündeten in Hörweite 1...4 Zustände.','Gegenstandszauber. 5...20 Sekunde[n]: Zustände auf Euch enden um 10...50% früher. Fallwirkung: Entfernt bei Verbündeten in Hörweite 1...4 Zustände.'],
2073=>['Waffe der Aggression','Waffenzauber. 5...15 Sekunde[n] lang sind Eure Angriffe um 25% schneller.','Waffenzauber. 5...15 Sekunde[n]: Ihr greift um 25% schneller an.'],
2074=>['Brusttrommler','Speerangriff. Wenn dieser Angriff einen Feind mit Beschädigter Rüstung trifft, leidet dieser 5...20 Sekunde[n] lang an einer Tiefen Wunde.','Speerangriff. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls Gegner Beschädigte Rüstung hat.'],
2075=>['Hastiger Refrain','Echo. 8...20 Sekunde[n] lang bewegt sich der Verbündete (bzw. Ihr selbst) um 25% schneller. Dieses Echo wird jedes Mal wiederholt, wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet.','Echo. 8...20 Sekunde[n]: Der Verbündete (bzw. Ihr selbst) bewegt sich um 25% schneller. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten (bzw. Euch selbst) endet.'],
2091=>['Schattenzuflucht','Verzauberung. Ihr seid 5 Sekunde[n] lang geblendet. 10 Sekunde[n] lang erhaltet Ihr +7...10 Lebenspunktregeneration und +40 Rüstung.','Verzauberung. 10 Sekunde[n]: Ihr erhaltet +7...10 Lebenspunktregeneration und +40 Rüstung. Ihr seid geblendet (5 Sekunde[n]).'],
2092=>['Äther-Alptraum','Verhexung. Der Gegner verliert 5...8 Energiepunkt[e]. Der Gegner und alle Feinde in dem Bereich erleiden 10 Sekunde[n] lang eine Lebenspunktdegeneration in Höhe der verlorenen Energiepunkte.','Verhexung. Lässt 5...8 Energiepunkt[e] verlieren. Der Gegner und Feinde im Gebiet haben -1 Lebenspunktdegeneration pro verlorenem Energiepunkt (10 Sekunde[n]).'],
2093=>['Siegel der Verdorbenheit','Siegel. Der Gegner und alle Feinde in der Nähe erleiden 20...30 Punkte Schaden. Pro betroffenen Feind, der unter einem Zustand oder einer Verhexung leidet, erhaltet Ihr 2 Punkt[e] Energie (maximal 12...20 Punkt[e]).','Siegel. Richtet beim Gegner und Feinden in der Nähe 20...30 Punkt[e] Schaden an. Ihr erhaltet für jeden dieser Gegner mit einem Zustand oder einer Verhexung 2 Energiepunkt[e] (maximal 12...20).'],
2094=>['Elementarlord','Verzauberung. 40...60 Sekunde[n] lang erhalten Eure Elementarattribute einen Schub von 1. Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr 1 Energiepunkt pro 10 Ränge in Energiespeicherung und werdet um 100...300% der Energiekosten dieses Zaubers geheilt.','Verzauberung. (40...60 Sekunde[n].) Eure Elementarattribute erhalten einen Schub von 1. Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr 1 Energiepunkt pro 10 Ränge in Energiespeicherung und werdet um 100...300% der Energiekosten dieses Zaubers geheilt.'],
2095=>['Selbstloser Geist','Verzauberung. 15...20 Sekunde[n] lang kosten von Euch auf einen weiteren Verbündeten gewirkte Zauber 3 Punkt[e] weniger Energie.','Verzauberung. (15...20 Sekunde[n].) Zauber, die Ihr auf einen weiteren Verbündeten wirkt, kosten 3 Punkt[e] weniger Energie.'],
2096=>['Dreifachschuss','Bogenangriff. 3 Pfeile werden gleichzeitig auf den Gegner abgefeuert. Diese Pfeile fügen 40...25% weniger Schaden zu.','Bogenangriff. Ihr feuert drei Pfeile gleichzeitig auf den Gegner ab. Diese Pfeile richten 40...25% weniger Schaden an.'],
2097=>['"Rettet Euch selbst!"','Schrei. 4...6 Sekunde[n] lang erhalten alle anderen Gruppenmitglieder +100 Rüstung.','Schrei. 4...6 Sekunde[n]: Alle anderen Gruppenmitglieder erhalten +100 Rüstung.'],
2098=>['Aura der Heiligen Macht','Verzauberung. Wenn Ihr eine Derwisch-Verzauberung verliert, fügt Ihr 45 Sekunde[n] lang allen umstehenden Feinden 20...25 Punkt[e] heiligen Schaden zu.','Verzauberung. (45 Sekunde[n].) Immer wenn Ihr eine Derwisch-Verzauberung verliert, erleiden alle umstehenden Feinde 20...25 Punkt[e] heiligen Schaden.'],
2099=>['Speer der Wut','Speerangriff. Dieser Angriff fügt +30...40 Punkt[e] Schaden zu. Wenn er einen Feind trifft, der an einem Zustand leidet, erhaltet Ihr 3...6 Adrenalinstöße.','Speerangriff. Richtet +30...40 Punkt[e] Schaden an. Ihr erhaltet 3...6 Adrenalinstöße, falls Ihr einen Feind mit einem Zustand trefft.'],
2100=>['Geister herbeirufen','Zauber. Alle von Euch kontrollierten Geister unternehmen einen Schattenschritt zu Eurer Position und erhalten 60...100 Lebenspunkte.','Zauber. Von Euch kontrollierte Geister machen einen Schattenschritt zu Eurer Position und erhalten 60...100 Lebenspunkt[e].'],
2101=>['Kritische Beweglichkeit','Verzauberung. 4 Sekunde[n] und 1 extra Sekunde pro Rang bei Kritischen Stößen lang greift Ihr um 33% schneller an und erhaltet +15...25 Rüstung. Diese Fertigkeit wiederholt sich jedes Mal, wenn Ihr einen kritischen Treffer landet.','Verzauberung. (4 Sekunde[n] plus 1 Sekunde für jeden Rang bei Kritischen Stößen.) Ihr greift um 33% schneller an und erhaltet +15...25 Rüstung. Erneuerung: Jedes Mal, wenn Ihr einen kritischen Treffer landet.'],
2102=>['Schmerzensschrei','Zauber. Unterbrecht die Fertigkeit des Gegners. Wenn dieser Gegner unter einer Mesmer-Verhexung gelitten hat, nehmen dieser Gegner und alle Feinde in dem Bereich 25...50 Punkt[e] Schaden und 10 Sekunden lang eine Lebenspunktedegeneration von 3...5.','Zauber. Unterbricht eine Fähigkeit. Wenn Gegner eine Mesmer-Verhexung erlitten hat, werden 25...50 Punkt[e] Schaden beim Gegner und Feinden in dem Bereich angerichtet und 10 Sekunden lang ist eine Lebenspunktedegeneration von -3...5 wirksam.'],
2103=>['Nekrose','Fertigkeit. Wenn der Gegner unter einem Zustand oder einer Verhexung leidet, erleidet er 60...90 Punkt[e] Schaden.','Fertigkeit. Richtet 60...90 Punkt[e] Schaden an, falls Gegner einen Zustand oder eine Verhexung hat.'],
2104=>['Intensität','Fertigkeit. 10 Sekunden lang fügt Ihr das nächste Mal, wenn Ihr einem Gegner mit einem Zauber Elementarschaden zufügt, 60...70% dieses Schadens allen Feinden in dem Bereich zu.','Fertigkeit. (10 Sekunden.) Das nächste Mal, wenn Ihr Elementarschaden mit einem Zauber zufügt, erleiden andere Feinde in dem Bereich 60...70% dieses Schadens.'],
2105=>['Lebenssaat','Verzauberung. Während der nächsten 2...5 Sekunden werden jedes Mal, wenn der Verbündete Schaden erleidet, alle Gruppenmitglieder pro Rang in Gunst der Götter um 2 Lebenspunkt[e] geheilt.','Verzauberung. (2...5 Sekunden.) Heilt alle Gruppenmitglieder jedes Mal, wenn das Ziel Schaden erleidet, um 2 Lebenspunkt[e] pro Rang in Gunst der Götter. Sich selbst als Ziel wählen nicht möglich.'],
2107=>['Wirbelsturmangriff','Nahkampfangriff. Greift den Gegner und umstehende Feinde an. Jeder erfolgreiche Angriff fügt +13...20 Punkt[e] Schaden zu.','Nahkampfangriff. Greift Gegner und umstehende Feinde an und richtet +13...20 Punkt[e] Schaden an.'],
2108=>['Tobt niemals allein','Fertigkeit. 18...25 Sekunde[n] lang greifen Ihr und Euer Tiergefährte um 25% schneller und erfreuen sich einer Lebenspunktregeneration von +1...3.','Fertigkeit. 18...25 Sekunde[n]: Ihr und Euer Tiergefährte greift um 25% schneller an und habt +1...3 Lebenspunktregeneration.'],
2109=>['Ewige Aura','Verzauberung. Ihr habt +100 maximale Lebenspunkte. Wenn diese Verzauberung endet werden alle Gruppenmitglieder im Bereich mit 40...50% Lebenspunkt[en] und 20...30% Energiepunkt[en] wiederbelebt.','Verzauberung. Ihr habt +100 maximale Lebenspunkte. Wirkung am Ende: Alle Gruppenmitglieder im Bereich werden mit 40...50% Lebenspunkt[en] und 20...30% Energiepunkt[en] wiederbelebt.'],
2110=>['Vampirismus','Binderitual. Erstellt einen Geist der Stufe 4...14, der nach 75...150 Sekunde[n] stirbt. Angriffe durch diesen Geist entziehen bis zu 10...20 Lebenspunkt[e] und Ihr werdet um 10...20 Lebenspunkt[e] geheilt.','Binderitual. Erstellt einen Geist der Stufe 4...14 (75...150 Sekunde[n] Lebensdauer). Seine Angriffe entziehen 10...20 Lebenspunkt[e] und Ihr werdet um 10...20 Lebenspunkt[e] geheilt.'],
2112=>['"Es gibt nichts zu befürchten!"','Schrei. 4 Sekunde[n] und 1 Sekunde pro 2 Ränge bei Führung lang erleiden alle Gruppenmitglieder in Hörweite um 20...35% weniger Schaden. Betroffene Gruppenmitglieder werden um 35...60 Lebenspunkt[e] geheilt, wenn dieser Schrei endet.','Schrei. (4 Sekunde[n] plus 1 Sekunde für alle 2 Ränge bei Führung.) Reduziert Schaden für Gruppenmitglieder in Hörweite um 20...35%. Wirkung am Ende: Heilt um 35...60 Lebenspunkt[e].'],
2116=>['Überraschungsangriff','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, wird der Gegner 5...8 Sekunde[n] lang geblendet. Dieser Angriff zählt als Leithandangriff.','Nahkampfangriff. Verursacht Blindheit (5...8 Sekunde[n]). Zählt als Leithandangriff.'],
2135=>['Trampelnder Ochse','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn Ihr erfolgreich seid, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Ihr einen verkrüppelten Feind trefft, wird dieser zu Boden geworfen.','Doppelangriff. Richtet +5...20 Punkt[e] Schaden an; wirft den Gegner zu Boden, falls er verkrüppelt ist. Muss einem Begleithandangriff folgen.'],
2136=>['Rauchpulver-Verteidigung','Haltung. 8 Sekunde[n] lang erleidet Ihr beim nächsten Treffer nur den halben Schaden und alle umstehenden Feinde werden 2...6 Sekunde[n] lang geblendet.','Haltung. (8 Sekunde[n].) Das nächste Mal, wenn Ihr getroffen werdet, erleidet Ihr nur halben Schaden und verursacht bei umstehenden Feinden den Zustand Blindheit (2...6 Sekunde[n]).'],
2137=>['Verwirrende Bilder','Verhexung. 2...10 Sekunden lang benötigt der Gegner doppelt so lange, um Nicht-Angriffsfertigkeiten zu aktivieren.','Verhexung. (2...10 Sekunden.) Der Gegner benötigt doppelt so lange, um Nicht-Angriffsfertigkeiten zu aktivieren.'],
2138=>['Lebenskraft des Verhexers','Verzauberung. 10 Sekunde[n] lang habt Ihr +1...8 Lebenspunktregeneration. Lebenskraft des Verhexers endet, wenn Ihr eine Fertigkeit benutzt, die keine Verhexung ist.','Verzauberung. (10 Sekunde[n].) Ihr habt +1...8 Lebenspunktregeneration. Endet, sobald Ihr eine Fertigkeit benutzt, die keine Verhexung ist.'],
2139=>['Masochismus','Verzauberung. 10...40 Sekunden lang sind Eure Todesmagie- und Seelensammlungsattribute um +2 erhöht und Ihr opfert 5...3% Eurer maximalen Lebenspunkte, wenn Ihr einen Zauber wirkt.','Verzauberung. (10...40 Sekunden.) Ihr habt +2 Todesmagie und Seelensammlung. Ihr opfert jedes Mal, wenn Ihr einen Zauber wirkt, zusätzlich 5...3% Eurer maximalen Lebenspunkte.'],
2140=>['Durchbohrende Falle','Falle. Wird Durchbohrende Falle aktiviert, erleiden alle Feinde in der Nähe 5...50 Punkt[e] Stichschaden. Alle Feinde mit Beschädigter Rüstung erleiden zusätzlich 15...60 Punkt[e] Schaden. Durchbohrende Falle endet nach 90 Sekunden. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunden: Betrifft Feinde in der Nähe. Richtet 5...50 Punkt[e] Stichschaden an. Richtet bei Feinden mit Beschädigter Rüstung zusätzlich 15...60 Punkt[e] Schaden an. Leicht zu unterbrechen.'],
2141=>['Kameradschaft','Fertigkeit. Wenn Eure Lebenspunkte niedriger als die Eures Tiergefährten sind, werdet Ihr um 30...120 Lebenspunkt[e] geheilt. Wenn die Lebenspunkte Eures Tiergefährten niedriger als Eure eigenen sind, wird er um 30...120 Lebenspunkt[e] geheilt.','Fertigkeit. Heilt Euch um 30...120 Lebenspunkt[e], falls Ihr weniger Lebenspunkte habt als Euer Tiergefährte. Heilt Euren Tiergefährten um 30...120 Lebenspunkt[e], falls er weniger Lebenspunkte hat als Ihr.'],
2142=>['Wilde Aggression','Fertigkeit. 5...20 Sekunde[n] lang greift Euer Tiergefährte um 33% schneller and und fügt 3...10 Punkt[e] zusätzlichen Schaden zu.','Fertigkeit. 5...20 Sekunde[n]: Euer Tiergefährte greift um 33% schneller an und richtet +3...10 Punkt[e] Schaden an.'],
2143=>['Unterbrechender Schuss','Bogenangriff. Wenn dieser Angriff erfolgreich ist, wird die Aktion des Gegners unterbrochen. Wenn diese Aktion eine Fertigkeit war, fügt Ihr +10...40 Punkt[e] Schaden zu.','Bogenangriff. Unterbricht eine Aktion. Unterbrechungswirkung: +10...40 Punkt[e] Schaden, falls Ihr eine Fertigkeit unterbrecht.'],
2144=>['Salve','Bogenangriff. Entfernt alle Eure Vorbereitungen. Schießt Pfeile auf Euren Zielgegner und bis zu 3 um ihn herum stehende Feinde. Diese Pfeile fügen +1...10 Punkt[e] Schaden zu, wenn sie treffen.','Bogenangriff. Richtet +1...10 Punkt[e] Schaden an. Trifft bis zu 3 umstehende Feinde um den Gegner. Entfernt alle Eure Vorbereitungen.'],
2145=>['Expertenfokus','Vorbereitung. 24 Sekunde[n] lang kosten Eure Bogen-Angriffsfertigkeiten 1...2 weniger Energiepunkt[e] und fügen 1...10 Punkt[e] zusätzlichen Schaden zu.','Vorbereitung. (24 Sekunde[n].) Eure Bogen-Angriffsfertigkeiten kosten 1...2 Energiepunkt[e] weniger und richten +1...10 Punkt[e] Schaden an.'],
2146=>['Frommer Zorn','Haltung. Entfernt 1 Derwisch-Verzauberung. 1...7 Sekunde[n] lang sind Eure Angriffe um 25% schneller. Wenn eine Verzauberung entfernt wurde, dauert diese Haltung doppelt so lange an.','Haltung. (1...7 Sekunde[n].) Ihr greift 25% schneller an und entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Diese Haltung dauert doppelt so lange an.'],
2147=>['Verkrüppelnder Sieg','Sensenangriff. Trifft dieser Angriff einen Gegner, wird dieser 3...8 Sekunde[n] lang verkrüppelt. Falls Ihr mehr Lebenspunkte habt als der Gegner, werden erleiden alle umstehenden Feinde 10...30 Punkt[e] Erdschaden.','Sensenangriff. (3...8 Sekunde[n].) Verkrüppelt den Gegner. Falls Ihr mehr Lebenspunkte habt als der Gegner, werden erleiden alle umstehenden Feinde 10...30 Punkt[e] Erdschaden.'],
2148=>['Trennende Waffe','Waffenzauber. 4...10 Sekunde[n] lang haben die nächsten 3 Angriffe des Verbündeten (bzw. Eure eigenen) eine Rüstungsdurchdringung von 10% und führen 5...20 Sekunde[n] lang zu Beschädigter Rüstung.','Waffenzauber. 4...10 Sekunde[n]: Die nächsten 3 Angriff des Verbündeten (bzw. von Euch selbst) verursachen Zustand Beschädigte Rüstung (5...20 Sekunde[n]) und haben 10% Rüstungsdurchdringung.'],
2149=>['Waffe der Erneuerung','Waffenzauber. 5...20 Sekunde[n] lang erhält der Verbündete das nächste Mal, wenn er mit einer Angriffsfertigkeit trifft, 1...7 Energiepunkt[e].','Waffenzauber. 5...20 Sekunde[n]: Der Verbündete (bzw. Ihr selbst) erhält 1...7 Energiepunkt[e], wenn er das nächste Mal mit einer Angriffsfertigkeit trifft.'],
2150=>['Verkrüppelungs-Speer','Speerangriff. Wenn Euer Angriff einen blutenden Feind trifft, wird dieser 5...20 Sekunde[n] lang verkrüppelt.','Speerangriff. Verursacht Zustand Verkrüppelung (5...20 Sekunde[n]), falls der Gegner blutet.'],
2186=>['Siegel der tödlichen Verdorbenheit','Siegel. Der Gegner erleidet pro aktivem Zustand 5...35 Punkt[e] Schaden (maximal 130 Punkt[e]).','Siegel. Richtet für jeden Zustand des Gegners 5...35 Punkt[e] Schaden an (maximal 130).'],
2187=>['Weg des Meisters','Verzauberung. 60 Sekunde[n] lang habt Ihr zusätzlich eine 3...33%ige Chance, einen kritischen Treffer zu erzielen, während Ihr eine Waffe führt, die kein Dolch ist.','Verzauberung. 60 Sekunde[n]: Wenn Ihr eine Waffe führt, die kein Dolch ist, habt Ihr +3...33% zur Chance auf kritische Treffer.'],
2188=>['Verteidigung entweihen','Verhexung. 5...20 Sekunde[n] lang erleidet der Gegner, wenn er das nächste Mal blockt, 30...120 Punkt[e] Schaden.','Verhexung. 5...20 Sekunde[n]: Richtet 30...120 Punkt[e] Schaden an, wenn der Gegner das nächste Mal blockt.'],
2189=>['Angorodons Starren','Zauber. Entzieht dem Gegner 10...50 Lebenspunkt[e]. Wenn Ihr an einem Zustand leidet, erhaltet Ihr 3...12 Energiepunkt[e].','Zauber. Entzieht 10...50 Lebenspunkt[e]. Ihr erhaltet 3...12 Energiepunkt[e], falls Ihr einen Zustand habt.'],
2190=>['Magnetschub','Verzauberung. Der Gegner erleidet 15...75 Punkte Schaden. Wenn Ihr Überzaubert seid, verzaubert Magnetschub alle Verbündeten in Hörweite 1...5 Sekunden, sodass sie den nächsten gegen sie gerichteten Angriff blocken.','Verzauberung. Richtet 15...75 Punkte Schaden an. Wenn Ihr Überzaubert seid, werden alle Verbündeten in Hörweite 1...5 Sekunden lang verzaubert, sodass sie den nächsten gegen sie gerichteten Angriff blocken.'],
2191=>['Rutschiger Boden','Zauber. Wenn der Gegner und die umstehenden Feinde Blind sind, oder sich bewegen, werden sie zu Boden geworfen. Bei einer Wassermagie von 5 oder weniger besteht eine 50%ige Wahrscheinlichkeit eines Misserfolges.','Zauber. Wirft den Gegner zu Boden, falls er geblendet ist oder sich bewegt. Trifft um Euren Zielgegner herum stehende Feinde. Bei Wassermagie von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.'],
2192=>['Leuchtendes Eis','Zauber. Der Gegner erleidet 5...50 Punkt[e] Kälteschaden. Wenn er mit einer Wassermagie-Verhexung belegt ist, erhaltet Ihr 5 Energiepunkt[e] sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung.','Zauber. Richtet 5...50 Punkt[e] Kälteschaden an. Ihr erhaltet 5 Energiepunkt[e] sowie 1 Energiepunkt pro 2 Ränge in Energiespeicherung, wenn der Gegner mit Wassermagie verhext ist.'],
2193=>['Energieexplosion','Zauber. Der Gegner erleidet pro Energiepunkt, den Ihr habt, 1...2 Punkt[e] Schaden (maximal 130 Punkt[e]).','Zauber. Richtet für jeden Eurer Energiepunkte 1...2 Punkt[e] Schaden an (maximal 130).'],
2194=>['Ablenkender Stoß','Nahkampfangriff. Wenn der Ablenkende Stoß erfolgreich ist, fügt er keinen Schaden zu und unterbricht die Aktion des Feindes. Wenn Gegner Beschädigte Rüstung aufweist, ist diese Fertigkeit 30 Sekunde[n] lang deaktiviert.','Nahkampfangriff. Unterbricht eine Aktion. Unterbrechungswirkung: Deaktiviert unterbrochene Fertigkeit (30 Sekunde[n]), falls Gegner Beschädigte Rüstung aufweist. Fügt keinen Schaden zu.'],
2195=>['Symbolischer Schlag','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr pro ausgerüstetem Siegel +12 Punkt[e] Schaden zu (maximal 70 Punkt[e] Schaden).','Nahkampfangriff. Richtet für jedes Siegel, das Ihr ausgerüstet habt, +12 Punkt[e] Schaden an (maximal 70).'],
2196=>['Geschwindigkeit des Soldaten','Haltung. 3...18 Sekunde[n] lang bewegt Ihr Euch um 15% schneller. Ihr bewegt Euch um weitere 15% schneller, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht.','Haltung. (3...18 Sekunde[n].) Ihr bewegt Euch um 15% schneller und um weitere 15%, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht.'],
2197=>['Körperschlag','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, erleidet der Gegner +10...40 Punkt[e] Schaden. Wenn er an Beschädigter Rüstung leidet, hat er 0...15 Sekunde[n] lang eine Tiefe Wunde.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an. Verursacht Tiefe Wunde (0...15 Sekunde[n]), falls Gegner Beschädigte Rüstung hat.'],
2198=>['Körperschuss','Bogenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn Ihr einen Gegner mit Beschädigter Rüstung trefft, erhaltet Ihr 5...10 Energiepunkt[e].','Bogenangriff. Richtet +5...20 Punkt[e] Schaden an. Ihr erhaltet 5...10 Energiepunkt[e], falls Gegner Beschädigte Rüstung hat.'],
2199=>['Giftspitzen-Siegel','Siegel. 60 Sekunde[n] lang führt Euer nächster Angriff außerdem 8...15 Sekunde[n] lang zu Vergiftung.','Siegel. 60 Sekunde[n]: Euer nächster Angriff verursacht Zustand Gift (8...15 Sekunde[n]).'],
2200=>['Siegel der mystischen Geschwindigkeit','Siegel. 30 Sekunde[n] lang wirken Eure nächste[n] 1...3 auf Euch gewirkte[n] Verzauberung[en] sofort. Blitzverzauberungen verbrauchen diese Fertigkeit nicht.','Siegel. (30 Sekunde[n].) Eure nächste[n] 1...3 auf Euch gewirkte[n] Verzauberung[en] wirken sofort. Blitzverzauberungen verbrauchen diese Fertigkeit nicht.'],
2201=>['Kraftschild','Blitzverzauberung. 1...16 Sekunde[n] lang werden die nächsten 1 Angriff[e] gegen Euch geblockt. Wenn ein Angriff geblockt wird, werden alle umstehenden angreifenden Feinde zu Boden geworfen und leiden 5...20 Sekunde[n] lang an "Schwäche".','Blitzverzauberung. (1...16 Sekunde[n].) Blockt die nächsten 1 Angriff[e] gegen Euch. Wirft alle umstehenden angreifenden Feinde zu Boden und fügt "Schwäche" zu (5...20 Sekunde[n]).'],
2202=>['Genesungsgriff','Zauber. Der Verbündete (bzw. Ihr selbst) wird um 30...90 Lebenspunkt[e] geheilt. Wenn dieser Verbündete unter den Auswirkungen eines Waffenzaubers leidet, verliert er einen Zustand.','Zauber. Heilt um 30...90 Lebenspunkt[e]. Entfernt einen Zustand, falls der Verbündete (bzw. Ihr selbst) unter dem Einfluss eines Waffenzaubers steht.'],
2203=>['Geistsauger-Aura','Fertigkeit. Für eine Dauer von 5...20 Sekunde[n] fügen alle Eure Geister in Hörweite 5...20 weniger Schaden zu aber stehlen 5...20 Lebenspunkte, wenn sie angreifen.','Fertigkeit. (5...20 Sekunde[n].) Alle Eure Geister in Hörweite fügen 5...20 weniger Schaden zu und stehlen 5...20 Lebenspunkte, wenn sie angreifen.'],
2204=>['Verjüngung','Binderitual. Erstellt einen Geist der Stufe 1...20. Dieser Geist heilt alle Gruppenmitglieder in Hörweite pro Sekunde um 3...10 Lebenspunkt[e]. Der Geist verliert pro Gruppenmitglied, das auf diese Weise geheilt wird, 3...10 Lebenspunkt[e]. Dieser Geist stirbt nach 30...90 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...20 (30...90 Sekunde[n] Lebensdauer). Heilt Gruppenmitglieder in Hörweite jede Sekunde um 3...10 Lebenspunkt[e]. Heilkosten: Der Geist verliert 3...10 Lebenspunkt[e].'],
2205=>['Todesqual','Binderitual. Erstellt einen Geist der Stufe 1...12. Dieser Geist entzieht Feinden in Hörweite pro Sekunde 3...10 Lebenspunkt[e]. Der Geist verliert pro Feind, der auf diese Weise beeinträchtigt wird, 3...10 Lebenspunkt[e]. Dieser Geist stirbt nach 30...90 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...12 (30...90 Sekunde[n] Lebensdauer). Lässt Feinde in Hörweite jede Sekunde 3...10 Lebenspunkt[e] verlieren. Der Geist verliert für jeden betroffenen Feind 3...10 Lebenspunkt[e].'],
2206=>['Geisterwaffe','Waffenzauber. 5...20 Sekunde[n] lang kann der nächste Angriff des Verbündeten nicht geblockt werden.','Waffenzauber. 5...20 Sekunde[n]: Der nächste Angriff des Verbündeten kann nicht geblockt werden. Sich selbst als Ziel wählen nicht möglich.'],
2207=>['Inspirative Rede','Fertigkeit. Ihr verliert Euer gesamtes Adrenalin und der Verbündete erhält 1...8 Adrenalinstöße.','Fertigkeit. Der Verbündete erhält 1...8 Adrenalinstöße. Sich selbst als Ziel wählen nicht möglich. Ihr verliert alles Adrenalin.'],
2208=>['Brennender Schild','Fertigkeit. 3...9 Sekunde[n] lang wird, wenn Ihr einen Schild benutzt, die nächste Angriffsfertigkeit gegen Euch geblockt. Falls es sich dabei um einen Nahkampfangriff gehandelt hat, wird Euer Angreifer 1...6 Sekunde[n] lang in Brand gesetzt.','Fertigkeit. 3...9 Sekunde[n]: Blockt die nächste Angriffsfertigkeit gegen Euch. Verursacht Zustand Brennen (1...6 Sekunde[n]), falls es sich um einen Nahkampfangriff handelt. Keine Wirkung, falls Ihr keinen Schild benutzt.'],
2209=>['Heiliger Speer','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn dieser Angriff eine herbeigerufene Kreatur trifft, erleiden alle Feinde in der Nähe 15...90 Punkt[e] heiligen Schaden und werden 3 Sekunde[n] lang in Brand gesetzt.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet bei Feinden in der Nähe 15...90 Punkt[e] heiligen Schaden an und verursacht Zustand Brennen (3 Sekunde[n]), falls Ihr eine herbeigerufene Kreatur trefft.'],
2210=>['Speerschlag','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu und der Gegner leidet 4...10 Sekunde[n] lang an Benommenheit. Dieser Angriff hat Nahkampfreichweite.','Speer-Nahkampfangriff. Richtet +5...20 Punkt[e] Schaden an und verursacht Zustand Benommenheit (4...10 Sekunde[n]). Dieser Angriff hat Nahkampfreichweite.'],
2211=>['Alkars Alchemiesäure','Zauber. Bewerft den Gegner mit Alkars Alchemiesäure. Der Gegner und umstehende Feinde erleiden 40...50 Punkt[e] Schaden. Zerstörer erleiden zusätzlich 45...70 Punkt[e] Schaden und haben 14...20 Sekunde[n] lang Beschädigte Rüstung.','Zauber. Geschoss: Richtet beim Gegner und umstehenden Feinden 40...50 Punkt[e] Schaden an. Verursacht bei Zerstörern zusätzlich 45...70 Punkt[e] Schaden und Zustand Beschädigte Rüstung (14...20 Sekunde[n]).'],
2212=>['Licht von Deldrimor','Zauber. Alle Feinde in dem Bereich erleiden 55...80 Punkt[e] heiligen Schaden. Versteckte Gegenstände werden kurz auf Eurem Kompass angezeigt. Alle versteckten Gegenstände in dem Bereich werden enthüllt.','Zauber. Richtet bei umstehenden Feinden in dem Bereich 55...80 Punkt[e] heiligen Schaden an. Versteckte Gegenstände im Bereich werden kurz auf Eurem Kompass angezeigt.'],
2213=>['Ohrenbiss','Fertigkeit. Der berührte Gegner erleidet 50...70 Punkt[e] Stichschaden und leidet 15...25 Sekunde[n] lang an einer Blutung.','Berührungs-Fertigkeit. Richtet 50...70 Punkt[e] Stichschaden an und verursacht Zustand Blutung (15...25 Sekunde[n]).'],
2214=>['Unter der Gürtellinie','Fertigkeit. Fügt dem Gegner 45...70 Punkt[e] Schaden zu. Liegt er am Boden, erleidet er zusätzlich 30...50 Punkt[e] Schaden und leidet 14...20 Sekunde[n] lang an Beschädigter Rüstung.','Berührungs-Fertigkeit. Richtet 45...70 Punkt[e] Schaden an. Richtet +30...50 Punkt[e] zusätzlichen Schaden an und verursacht Beschädigte Rüstung (14...20 Sekunde[n]), falls der Gegner zu Boden geworfen wurde.'],
2215=>['Rauf-Kopfstoß','Fertigkeit. Ihr gebt dem berührten Gegner einen Kopfstoß, fügt ihm 45...70 Punkt[e] Schaden zu und werft ihn zu Boden, wenn Ihr trefft.','Berührungs-Fertigkeit. Richtet 45...70 Punkt[e] Schaden an und wirft zu Boden.'],
2216=>['"Stolpert nicht!"','Schrei. 3...5 Sekunde[n] lang können Gruppenmitglieder in Hörweite nicht zu Boden geworfen werden.','Schrei. 3...5 Sekunde[n]: Gruppenmitglieder in Hörweite können nicht zu Boden geworfen werden.'],
2217=>['"Bei Urals Hammer!"','Schrei. 30 Sekunde[n] lang werden alle Gruppenmitglieder in Hörweite mit vollen Lebens- und Energiepunkten wiederbelebt. Wiederbelebte Gruppenmitglieder fügen zusätzlich 25...33% Schaden zu. Wenn dieser Effekt endet, sterben alle betroffenen Gruppenmitglieder. Diese Fertigkeit verursacht keinen Sterbemalus.','Schrei. (30 Sekunde[n].) Alle toten Gruppenmitglieder in Hörweite werden mit vollen Lebens- und Energiepunkten wiederbelebt. Betroffene Gruppenmitglieder fügen zusätzlich 25...33% Schaden zu. Betroffene Gruppenmitglieder sterben am Ende der Wirkung, erhalten jedoch keinen Sterbemalus.'],
2218=>['Betrunkener Meister','Haltung. 72...90 Sekunde[n] lang sind Eure Bewegungs- und Angriffsgeschwindigkeit um 10...15% erhöht. Wenn Ihr beim Aktivieren dieser Fertigkeit betrunken seid, sind Eure Bewegungs- und Angriffsgeschwindigkeit stattdessen um 25...33% erhöht.','Haltung. 72...90 Sekunde[n]: Eure Bewegungs- und Angriffsgeschwindigkeit ist um 10...15% erhöht, falls Ihr nicht betrunken seid. Eure Bewegungs- und Angriffsgeschwindigkeit ist um 25...33% erhöht, falls Ihr betrunken seid.'],
2219=>['Waffe des Großen Zwergs','Waffenzauber. 20 Sekunde[n] lang fügt die Waffe des Verbündeten +15...20 Punkt[e] Schaden zu und hat eine 28...40%ige Chance Feinde zu Boden zu werfen.','Waffenzauber. 20 Sekunde[n]: +15...20 Punkt[e] Waffenschaden und 28...40%ige Chance, Feinde mit Angriffen zu Boden zu werfen. Sich selbst als Ziel wählen nicht möglich.'],
2220=>['Rüstung des Großen Zwergs','Verzauberung. 22...40 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) +24 Rüstung, +60 maximale Lebenspunkte und zusätzlich +24 Rüstung gegen Zerstörer.','Verzauberung. 22...40 Sekunde[n]: +24 Rüstung und +60 maximale Lebenspunkte. Zusätzlich +24 Rüstung gegen Zerstörer.'],
2221=>['Atem des Großen Zwergs','Zauber. Alle Gruppenmitglieder werden von Brennen befreit und um 50...60 Lebenspunkt[e] geheilt.','Zauber. Entfernt Brennen und heilt um 50...60 Lebenspunkt[e]. Betrifft Gruppenmitglieder.'],
2222=>['Schneesturm','Zauber. An der aktuellen Position des Gegners wird ein Schneesturm erzeugt. 5 Sekunde[n] erleiden umstehende Feinde um diesen Bereich 30...40 Punkt[e] Kälteschaden pro Sekunde.','Zauber. 5 Sekunde[n]: Richtet jede Sekunde 30...40 Punkt[e] Kälteschaden an. Trifft umstehende Feinde um anfängliche Position des Gegners.'],
2223=>['Schwarzpulvermine','Falle. Wird Schwarzpulvermine aktiviert, erleiden alle Gegner in der Nähe 20...30 Punkt[e] Schaden, werden geblendet und leiden 7...10 Sekunde[n] lang an einer Blutung. Schwarzpulvermine endet nach 90 Sekunde[n]. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunde[n]: Betrifft Feinde in der Nähe. Richtet 20...30 Punkt[e] Schaden an. Verursacht die Zustände Blindheit und Blutung (7...10 Sekunde[n]). Leicht zu unterbrechen.'],
2224=>['Mursaat herbeirufen','Zauber. Ruft einen Mursaat der Stufe 14...20 herbei, der 40...60 Sekunde[n] lang lebt und über Schwächende Aufladung verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.','Zauber. Ruft einen Mursaat der Stufe 14...20 herbei (40...60 Sekunde[n] Lebensdauer), der über Schwächende Aufladung verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.'],
2225=>['Rubin-Dschinn herbeirufen','Zauber. Ruft einen Rubin-Dschinn der Stufe 14...20 herbei, der 40...60 Sekunde[n] lang lebt und über Feueropfer verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.','Zauber. Ruft einen Rubin-Dschinn der Stufe 14...20 herbei (40...60 Sekunde[n] Lebensdauer), der über Feueropfer verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.'],
2226=>['Eis-Kobold herbeirufen','Zauber. Ruft einen Eis-Kobold der Stufe 14...20 herbei, der 40...60 Sekunde[n] lang lebt und über Eisdornen verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.','Zauber. Ruft einen Eis-Kobold der Stufe 14...20 herbei (40...60 Sekunde[n] Lebensdauer), der über Eisdornen verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.'],
2227=>['Naga-Schamanen herbeirufen','Zauber. Ruft einen Naga-Schamanen der Stufe 14...20 herbei, der 40...60 Sekunde[n] lang lebt und über Steinigung verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.','Zauber. Ruft einen Naga-Schamanen der Stufe 14...20 herbei (40...60 Sekunde[n] Lebensdauer), der über Steinigung verfügt. Es kann jeweils nur 1 Asura-Beschwörung aktiv sein.'],
2228=>['Geschickter Schlag','Distanzangriff. Wenn dieser Angriff erfolgreich ist, erleidet der Gegner 18...30 Punkt[e] Schaden. Wenn er an Beschädigter Rüstung leidet, blutet er 18...30 Sekunde[n] lang.','Distanzangriff. Richtet 18...30 Punkt[e] Schaden an. Verursacht Zustand Blutung (18...30 Sekunde[n]), falls Gegner Beschädigte Rüstung hat.'],
2229=>['Siegel der Infektion','Siegel. Wenn der Gegner blutet, leidet er zusätzlich 13...20 Sekunde[n] lang an Krankheit.','Siegel. Verursacht Zustand Krankheit (13...20 Sekunde[n]), falls der Gegner blutet.'],
2230=>['Tryptophan-Siegel','Siegel. 14...20 Sekunde[n] lang greifen der Gegner und alle umstehenden Feinde um 23...40% langsamer an.','Siegel. 14...20 Sekunde[n]: Die Bewegungs- und Angriffsgeschwindigkeit des Gegners und umstehender Feinde ist um 23...40% verringert.'],
2231=>['Ebon-Kampfstandarte des Mutes','Abwehrzauber. Ihr setzt eine Ebon-Kampfstandarte des Mutes an Eurer aktuellen Position. 14...20 Sekunde[n] lang erhalten Verbündete, die keine Geister sind, in dem Bereich +24 Rüstung und zusätzlich +24 Rüstung gegen Charr.','Abwehrzauber. 14...20 Sekunde[n]: Verbündete in dieser Abwehr haben +24 Rüstung und zusätzlich +24 Rüstung gegen Charr. Geister sind nicht betroffen.'],
2232=>['Ebon-Kampfstandarte der Weisheit','Abwehrzauber. Ihr setzt eine Ebon-Kampfstandarte der Weisheit an Eurer aktuellen Position. 14...20 Sekunde[n] lang haben Verbündete, die keine Geister sind, in dem Bereich eine 44...60%ige Chance, die Wiederaufladezeit des Zaubers, den sie wirken, zu halbieren.','Abwehrzauber. 14...20 Sekunde[n]: Von Verbündeten in dieser Abwehr gewirkte Zauber haben eine 44...60%ige Chance, sich um 50% schneller aufzuladen. Geister sind nicht betroffen.'],
2233=>['Ebon-Kampfstandarte der Ehre','Abwehrzauber. Ihr setzt eine Ebon-Kampfstandarte der Ehre an Eurer aktuellen Position. 14...20 Sekunde[n] lang verursachen Verbündete, die keine Geister sind, in dem Bereich +8...15 Punkt[e] Schaden und zusätzlich +7...10 Punkt[e] Schaden gegen Charr.','Abwehrzauber. 14...20 Sekunde[n]: Verbündete in dieser Abwehr richten +8...15 Punkt[e] Schaden an und zusätzlich +7...10 Punkt[e] Schaden gegen Charr. Geister sind nicht betroffen.'],
2234=>['Ebon-Vorhut-Heckenschützen-Unterstützung','Zauber. Der Gegner erleidet 54...90 Punkt[e] Stichschaden und leidet 5...25 Sekunde[n] lang an einer Blutung. Bei diesem Angriff besteht eine 10%ige Chance, zusätzlich 540...900 Punkt[e] Stichschaden zuzufügen. Wenn dieser Angriff einen Charr trifft, besteht eine 25%ige Chance auf zusätzlich 540...900 Punkt[e] Stichschaden.','Zauber. Richtet 54...90 Punkt[e] Stichschaden und Zustand Blutung an (5...25 Sekunde[n]). 10%ige Chance auf +540...900 Stichschaden. 25%ige Chance auf +540...900 Stichschaden, wenn Gegner ein Charr ist.'],
2235=>['Ebon-Vorhut-Assassinen-Unterstützung','Zauber. Ruft einen Ebon-Vorhut-Assassinen der Stufe 14...20 mit Eiserne Handfläche, Reißzähne des Fuchses und Neunschwänziger Stoß herbei. Dieser herbeigerufene Assassine unternimmt einen Schattenschritt zum Gegner hin. Wenn es sich beim Gegner um einen Charr handelt, lebt der Assassine 24...30 Sekunde[n] lang. Wenn er kein Charr ist, lebt der Assassine 12...15 Sekunde[n] lang.','Zauber. Ruft einen Assassinen der Stufe 14...20 herbei, der über Eiserne Handfläche, Reißzähne des Fuchses und Neunschwänziger Stoß verfügt; er unternimmt einen Schattenschritt zum Gegner. Ist der Gegner ein Charr, lebt der Assassine 24...30 Sekunde[n] lang. Anderenfalls lebt der Assassine 12...15 Sekunde[n] lang.'],
2236=>['Brunnen des Ruins','Brunnenzauber. Verwertet die nächstgelegene Leiche oder opfert 66 % Lebenspunkte, um an ihrem Standort einen Brunnen des Verderbens zu erschaffen. Für 5...30 Sekunden hat jeder Gegner im Brunnen, der physischen Schaden erleidet, 5...20 Sekunden lang Zerborstene Rüstung.','Brunnenzauber. (5...30 Sekunden). Fügt jedem Gegner im Brunnen, der physischen Schaden erleidet, den Zustand Zerborstene Rüstung zu (5...20 Sekunden). Verwertet eine frische Leiche oder opfert 66 % Lebenspunkte.'],
2237=>['Schwund','Verhexung. 3...7 Sekunde[n] lang ist das Primärattribut des Gegners auf 0 reduziert.','Verhexung. 3...7 Sekunde[n]: Das Primärattribut des Gegners wird auf 0 gesetzt.'],
2238=>['Speer der Erlösung','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn er nicht trifft, verliert Ihr einen Zustand.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Falls der Angriff nicht trifft, verliert Ihr einen Zustand.'],
2353=>['"Erledigt ihn!"','Schrei. Wenn die Lebenspunkte des Gegners weniger als 50% betragen, erleidet er 44...80 Punkt[e] Schaden und leidet 12...20 Sekunde[n] lang an Beschädigter Rüstung und Tiefer Wunde.','Schrei. Richtet 44...80 Punkt[e] Schaden an und verursacht die Zustände Beschädigte Rüstung und Tiefe Wunde (12...20 Sekunde[n]). Der Gegner muss weniger als 50% seiner maximalen Lebenspunkte haben, sonst keine Wirkung.'],
2354=>['"Weicht aus!"','Schrei. Während der nächsten 16...20 Sekunde[n] kann Euer nächster Angriff nicht geblockt werden und fügt +14...20 Punkt[e] Schaden zu.','Schrei. 16...20 Sekunde[n]: Euer nächster Angriff kann nicht geblockt werden und richtet +14...20 Punkt[e] Schaden an.'],
2355=>['Ich bin am stärksten!','Schrei. Eure nächsten 5...8 Angriffe fügen zusätzlich +14...20 Punkt[e] Schaden zu.','Schrei. Eure nächsten 5...8 Angriff[e] richten +14...20 Punkt[e] Schaden an.'],
2356=>['"Ich bin unaufhaltbar!"','Schrei. 16...20 Sekunde[n] habt Ihr +24 Rüstung und könnt weder zu Boden geworfen noch verkrüppelt werden.','Schrei. 16...20 Sekunde[n]: Ihr habt +24 Rüstung und könnt nicht zu Boden geworfen oder verkrüppelt werden.'],
2357=>['Ein Funken Arglist','Verhexung. Der berührte Gegner erleidet 44...80 Punkt[e] Schaden. Wenn er zu Boden geworfen wurde, kann er 5...8 Sekunde[n] lang nicht angreifen.','Berührungs-Verhexung. Richtet 44...80 Punkt[e] Schaden an. Gegner kann nicht angreifen (5...8 Sekunde[n]), falls er zu Boden geworfen ist.'],
2358=>['"Ihr bewegt Euch wie ein Zwerg!"','Schrei. Der Zielgegner wird zu Boden geworfen und erleidet 44...80 Punkt[e] Schaden. Der Gegner leidet außerdem 8...15 Sekunde[n] lang an Verkrüppelung.','Schrei. Richtet 44...80 Punkt[e] Schaden an, wirft zu Boden und verursacht den Zustand Verkrüppelung (8...15 Sekunde[n]).'],
2359=>['"Ihr seid alle Schwächlinge!"','Schrei. Der berührte Gegner und ihn umstehende Feinde werden 8...12 Sekunde[n] lang geschwächt.','Schrei. Verursacht Zustand Schwäche (8...12 Sekunde[n]). Betrifft auch umstehende Feinde.'],
2360=>['Den Schmerz nicht spüren','Fertigkeit. 30 Sekunde[n] lang erfreut Ihr Euch einer Lebenspunktregeneration von +2...3. Wenn Ihr beim Aktivieren dieser Fertigkeit betrunken seid, habt Ihr außerdem +200...300 maximale Lebenspunkte.','Fertigkeit. 30 Sekunde[n]: Ihr habt +2...3 Lebenspunktregeneration. Ihr habt +200...300 maximale Lebenspunkte, falls Ihr beim Aktivieren dieser Fertigkeit betrunken seid.'],
2361=>['Tausend-Bären-Prügel','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, fügt er jedem umstehenden Feind +6...9 Punkt[e] Schaden zu (maximal 60 Punkte). Wenn der Feind kein Mensch ist, wird er zu Boden geworfen.','Nahkampfangriff. Richtet pro umstehendem Feind +6...9 Punkt[e] Schaden an (maximal 60 Punkte). Wirft zu Boden, falls der Gegner kein Mensch ist.'],
2374=>['Segen der Bärin','Elite-Form. Ihr verliert sämtliches Eigentum und nehmt das Erscheinungsbild der Bärin an. 60 Sekunde[n] lang habt Ihr 100 Rüstung und 750...800 Lebenspunkt[e]. Eure Attribute werden auf 0 gesetzt und Eure Fertigkeiten werden durch Bärenangriffe ersetzt.','Elite-Form. Ihr verliert sämtliches Eigentum und nehmt das Erscheinungsbild der Bärin an (60 Sekunde[n]). Eure Attribute werden auf 0 gesetzt, Eure Fertigkeiten werden durch Bärenangriffe ersetzt und Ihr habt 100 Rüstung und 750...800 Lebenspunkt[e].'],
2379=>['Segen des Wolfes','Elite-Form. Ihr verliert sämtliches Eigentum und nehmt das Erscheinungsbild des Wolfes an. 60 Sekunde[n] lang habt Ihr 80 Rüstung, 660...700 Lebenspunkt[e] und 2...4 Lebenspunktregeneration. Eure Attribute werden auf 0 gesetzt und Eure Fertigkeiten werden durch Wolfsangriffe ersetzt.','Elite-Form. Ihr verliert sämtliches Eigentum und nehmt das Erscheinungsbild des Wolfes an (60 Sekunde[n]). Eure Attribute werden auf 0 gesetzt, Eure Fertigkeiten werden durch Wolfsangriffe ersetzt und Ihr habt 80 Rüstung, 660...700 Lebenspunkt[e] und 2...4 Lebenspunktregeneration.'],
2384=>['Segen des Raben','Elite-Form. Ihr verliert sämtliches Eigentum und nehmt das Erscheinungsbild des Raben an. 60 Sekunde[n] lang habt Ihr 80 Rüstung, 660...700 Lebenspunkt[e] und eine 20...30%ige Chance zu blocken. Eure Attribute werden auf 0 gesetzt und Eure Fertigkeiten werden durch Rabenangriffe ersetzt.','Elite-Form. Ihr verliert sämtliches Eigentum und nehmt das Erscheinungsbild des Raben an (60 Sekunde[n]). Eure Attribute werden auf 0 gesetzt, Eure Fertigkeiten werden durch Rabenangriffe ersetzt und Ihr habt 80 Rüstung, 660...700 Lebenspunkt[e] und eine 20...30%ige Chance zu blocken.'],
2411=>['Geistbrecher','Verzauberung. 10...16 Sekunde[n] lang bewegt Ihr Euch um 20...33% schneller und die Wirkzeit Eurer Zauber ist um 20% kürzer.','Verzauberung. (10...16 Sekunden.) Ihr bewegt Euch um 20...33% schneller und wirkt Zauber um 20% schneller.'],
2412=>['Durchtriebener Krimineller','Zauber. 10...20 Sekunde[n] lang wird ein zufällig gewählter Zauber des Gegners deaktiviert und Durchtriebener Krimineller wird durch diesen Zauber ersetzt. Ihr erhaltet 5...10 Energiepunkt[e].','Zauber. 10...20 Sekunde[n]: Deaktiviert einen Zauber. Diese Fertigkeit wird zum betreffenden Zauber. Ihr erhaltet 5...10 Energiepunkt[e].'],
2413=>['Technobabbel','Zauber. Der Gegner und alle umstehenden Feinde erleiden 30...40 Punkt[e] Schaden. Wenn er kein Boss ist, leiden der Gegner und alle umstehenden Feinde 3...5 Sekunde[n] lang an Benommenheit.','Zauber. Richtet beim Gegner und umstehenden Feinden 30...40 Punkt[e] Schaden an. Verursacht bei Feinden Zustand Benommenheit (3...5 Sekunde[n]), falls Gegner kein Boss ist.'],
2414=>['Strahlungsfeld','Abwehrzauber. 5 Sekunden lang unterliegen Feinde in dem Bereich einer Lebenspunktdegeneration von -4...6. Wenn das Portal endet, leiden alle Gegner in dem Bereich 12...20 Sekunde[n] lang an Krankheit.','Abwehrzauber. 5 Sekunden: Verursacht bei Feinden im Bereich -4...6 Lebenspunktdegeneration. Wirkung am Ende: Verursacht bei Feinden im Bereich den Zustand Krankheit (12...20 Sekunde[n]).'],
2415=>['Asurischer Scan','Verhexung. 9...12 Sekunde[n] lang können Eure Angriffe den Gegner nicht verfehlen. Das Töten eines mit "Asurischer Scan" verhexten Feinds entfernt 5% Sterbemalus.','Verhexung. (9...12 Sekunde[n].) Ihr könnt Euren Gegner nicht verfehlen. Wenn Ihr diesen Feind tötet, verliert Ihr 5% Sterbemalus.'],
2416=>['Hochnäsigkeit','Fertigkeit. 20...30 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn Ihr durch das Töten eines Feindes Erfahrung sammelt, einen willkürlichen asurischen Vorteil.','Fertigkeit. 20...30 Sekunde[n]: Jedes Mal, wenn Ihr durch das Töten eines Feindes Erfahrung sammelt, erhaltet Ihr einen willkürlichen asurischen Vorteil.'],
2417=>['Geistige Sperre','Verzauberung. 5...11 Sekunde[n] lang habt Ihr eine 50%ige Chance Angriffe zu blocken. Diese Verzauberung wird jedes Mal, wenn Ihr von einem Feind getroffen werdet, neu aufgetragen.','Verzauberung. 5...11 Sekunde[n]: Ihr habt eine 50%ige Chance zu blocken. Erneuerung: Jedes Mal, wenn ein Feind Euch trifft.'],
2418=>['Schmerztauscher','Verhexung. 6...10 Sekunde[n] lang erleidet der Gegner jedes Mal, wenn er Schaden zufügt, 100...140% des Schadens, den er zufügt (maximal 80 Punkte).','Verhexung. 6...10 Sekunde[n]: Richtet jedes Mal, wenn er Schaden anrichtet, 100...140% des Schadens (maximal 80 Punkte) beim Gegner selbst an.'],
2420=>['Ebon-Flucht','Zauber. Unternehmt einen Schattenschritt zum ausgewählten Verbündeten hin. Ihr und der Verbündete werden um 70...110 Lebenspunkt[e] geheilt.','Zauber. Heilt Euch und den Verbündeten um 70...110 Lebenspunkt[e]. Anfangswirkung: Ihr unternehmt einen Schattenschritt zum Verbündeten. Sich selbst als Ziel wählen nicht möglich.'],
2421=>['Schwäche-Falle','Falle. Wird Schwäche-Falle aktiviert, werden alle Feinde in der Nähe 10...20 Sekunde[n] lang geschwächt und erleiden 24...50 Punkt[e] Blitzschaden. Alle Charr werden zu Boden geworfen. Schwäche-Falle endet nach 90 Sekunden. Bei der Aktivierung dieser Fertigkeit könnt Ihr leicht unterbrochen werden.','Falle. 90 Sekunden: Betrifft Feinde in der Nähe. Richtet 24...50 Punkt[e] Blitzschaden an. Verursacht Zustand Schwäche (10...20 Sekunde[n]). Wirft Charr zu Boden. Leicht zu unterbrechen.'],
2422=>['Winde','Ebon-Vorhut-Ritual. Erstellt einen Geist der Stufe 4...10. Alle Feinde in seiner Reichweite haben eine 15%ige Chance, dass ihre Distanzangriffe fehlschlagen. Dieser Geist stirbt nach 54...90 Sekunde[n].','Ebon-Vorhut-Ritual. Erstellt einen Geist der Stufe 4...10 (54...90 Sekunde[n] Lebensdauer). Betrifft Feinde in Reichweite. Distanzangriffe gehen mit 15%iger Wahrscheinlichkeit daneben.'],
2423=>['Zwergenstabilität','Verzauberung. 24...30 Sekunde[n] lang dauern Eure Haltungen um 55...100% länger an. Wenn Ihr diese Fertigkeit aktiviert, während Ihr betrunken seid, könnt Ihr nicht zu Boden geworfen werden.','Verzauberung. 24...30 Sekunde[n]: Eure Haltungen dauern um 55...100% länger an. Ihr könnt nicht zu Boden geworfen werden, falls Ihr beim Aktivieren dieser Fertigkeit betrunken seid.'],
2657=>['Ruf der Eile (PvP)','Schrei. 30 Sekunden lang erhöht sich die Angriffsgeschwindigkeit Eures Tiergefährten um 25% und er bewegt sich um 25% schneller.','Schrei. (30 Sekunden.) Bewegung und Angriff Eures Tiergefährten sind 25% schneller.'],
2734=>['Geistiges Wrack (PvP)','Verhexung. Ist der Gegner das Ziel einer Eurer Mesmer-Fertigkeiten, die keine Verhexung ist, verliert er 5...40 Sekunde[n] lang 1 Energiepunkt. Sinken die Energiepunkte des Gegners auf 0, erleidet er 15...100 Punkt[e] Schaden und Geistiges Wrack endet.','Verhexung. (5...40 Sekunde[n].) Der Gegner verliert 1 Energiepunkt, wenn er Ziel Eurer Mesmer-Fertigkeiten (keine Verhexung) ist. Sinken die Energiepunkte des Gegners auf 0, erleidet er 15...100 Punkt[e] Schaden und Geistiges Wrack endet.'],
2803=>['Geistige Erfrierung (PvP)','Elite-Verhexung. Der Gegner erleidet 10...60 Punkt[e] Kälteschaden. Wenn Ihr mehr Energie als der Gegner habt, erleidet dieser zusätzlich 10...60 Punkt[e] Kälteschaden und bewegt sich 1...5 Sekunde[n] lang um 90% langsamer. Dieser Zauber ruft Erschöpfung hervor.','Elite-Verhexung. Richtet 10...60 Punkt[e] Kälteschaden an. Falls Ihr mehr Energie habt als der Gegner, erhält er zusätzlich +10...60 Punkt[e] Kälteschaden und bewegt sich um 90% langsamer (1...5 Sekunde[n]).'],
2804=>['Geistiger Schock (PvP)','Elite-Zauber. Der Gegner erleidet 10...50 Punkt[e] Blitzschaden. Wenn Ihr mehr Energie als der Gegner habt, erleidet er 10...50 Punkt[e] zusätzlichen Blitzschaden und wird zu Boden geworfen. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Elite-Zauber. Richtet 10...50 Punkt[e] Blitzschaden an. Wenn Ihr mehr Energie als der Gegner habt, erleidet er +10...50 Punkt[e] Blitzschaden und wird zu Boden geworfen. 25% Rüstungsdurchdringung.'],
2805=>['Nebelform (PvP)','Elite-Verzauberung. 10...45 Sekunde[n] lang erleidet Ihr 33% weniger Schaden von Feinden, die an den Auswirkungen einer Wassermagie-Verhexung leiden. Immer wenn Ihr einen Elementarzauber wirkt, werden alle Verbündete in Hörweite, die keine Geister sind, um 50...250% der Energiekosten dieses Zaubers geheilt. Dieser Zauber heilt keine Verbündeten mit mehr als 80% Gesundheit.','Elite-Verzauberung. (10...45 Sekunde[n].) Ihr erleidet 33% weniger Schaden von Feinden, die an den Auswirkungen einer Wassermagie-Verhexung leiden. Verbündete in Hörweite, die keine Geister sind, werden um 50...250% der Energiekosten Eurer Elementarzauber geheilt. Heilt keine Verbündeten mit mehr als 80% Gesundheit.'],
2806=>['Abwehr gegen Schaden (PvP)','Elite-Abwehrzauber. Errichtet an dieser Position eine Abwehr gegen Schaden. 5...15 Sekunde[n] lang erhalten in diesem Bereich befindliche Verbündete, die keine Geister sind, +1...3 Lebenspunktregeneration, +12...24 Rüstung und zusätzlich +12...24 Rüstung gegen Elementarschaden. Dieser Zauber wird 30 Sekunden lang deaktiviert.','Elite-Abwehrzauber. (5...15 Sekunde[n].) Verbündete in dieser Abwehr haben +1...3 Lebenspunktregeneration, +12...24 Rüstung und zusätzlich +12...24 Rüstung gegen Elementarschaden. Geister sind nicht betroffen. Dieser Zauber wird 30 Sekunden lang deaktiviert.'],
2807=>['Den Blitz reiten (PvP)','Elite-Zauber. Der Blitz bringt Euch zum Ziel. Alle umstehenden Feinde werden 1...5 Sekunde[n] lang geblendet. Wenn Euer Ziel ein Gegner ist, erleidet er 10...70 Punkt[e] Blitzschaden. Dieser Zauber hat eine Rüstungsdurchdringung von 25%.','Elite-Zauber. Richtet 10...70 Punkt[e] Blitzschaden an. 25% Rüstungsdurchdringung. Blendet alle umstehenden Feinde. (1...5 Sekunde[n]). Ihr bewegt Euch sofort zu Eurem Ziel. Das Ziel kann ein Verbündeter sein.'],
2808=>['Erzürnter Schlag (PvP)','Elite-Hammerangriff. Wenn Erzürnter Schlag erfolgreich ist, erhaltet Ihr 1...3 Adrenalinstöße. Wenn Ihr einen sich bewegenden Feind trefft, erleidet dieser +10...40 Punkt[e] Schaden und wird zu Boden geworfen.','Elite-Hammerangriff. Ihr erhaltet 1...3 Adrenalinstöße, falls Ihr trefft. Richtet +10...40 Schaden an und wirft den Gegner zu Boden, wenn er sich bewegt hat.'],
2809=>['Obsidianflamme','Zauber. Fügt dem Gegner 22...92 Punkt[e] Schaden zu. Dieser Zauber ignoriert Rüstung.','Zauber. Richtet 22...92 Punkt[e] Schaden an.'],
2857=>['Aegis (PvP)','Verzauberung. Das andere Gruppenmitglied kann 1...3 Sekunde[n] lang nicht Ziel von feindlichen Zaubern werden und Angriffe gegen dieses Gruppenmitglied versagen.','Verzauberung. (1...3 Sekunde[n].) Das andere Gruppenmitglied kann nicht Ziel von feindlichen Zaubern werden. Angriffe gegen dieses Gruppenmitglied versagen. Sich selbst als Ziel wählen nicht möglich.'],
2858=>['"Passt auf Euch auf!" (PvP)','Schrei. Gruppenmitglieder in Hörweite erhalten 10 Sekunde[n] lang +5...25 Rüstung. Dieser Schrei endet nach 1...3 Angriff[en].','Schrei. 10 Sekunde[n]: Gruppenmitglieder in Hörweite haben +5...25 Rüstung. Endet nach 1...3 erhaltenen Angriff[en].'],
2859=>['Schwächen (PvP)','Zauber. Das ausgewählte Ziel leidet 10...30 Sekunde[n] lang an Schwäche.','Zauber. Verursacht Zustand Schwäche (10...30 Sekunde[n]).'],
2860=>['Äthererneuerung (PvP)','Elite-Verzauberung. 10 Sekunde[n] lang bekommt Ihr jedes Mal, wenn Ihr einen Zauber wirkt, 1...3 Energiepunkt[e] und 5...20 Lebenspunkt[e] für jede Verzauberung, die auf Euch liegt.','Elite-Verzauberung. (10 Sekunde[n].) Jedes Mal, wenn Ihr einen Zauber wirkt, erhaltet Ihr für jede Verzauberung auf Euch 1...3 Energiepunkt[e] und 5...20 Lebenspunkt[e].'],
2861=>['Durchbohr-Angriff (PvP)','Bogenangriff. Wenn "Durchbohr-Angriff" trifft, fügt Ihr fügt Ihr 5...15 Punkt[e] zusätzlichen Schaden zu. Dieser Angriff hat eine Rüstungsdurchdringung von 10%.','Bogenangriff. Richtet +5...15 Punkt[e] Schaden an. 10% Rüstungsdurchdringung.'],
2862=>['Schattenform (PvP)','Elite-Verzauberung. 5...15 Sekunde[n] lang schlagen alle feindlichen Zauber und alle gegen Euch gerichteten Angriffe fehl. Wenn Schattenform endet, verliert Ihr alle Lebenspunkte bis auf 5...50.','Elite-Verzauberung. 5...15 Sekunde[n]: Gegen Euch gerichtete feindliche Zauber und Angriffe schlagen fehl. Wirkung am Ende: Ihr verliert alle Lebenspunkte bis auf 5...50.'],
2863=>['Zwietracht (PvP)','Elite-Zauber. Wenn der Gegner unter einem Zustand und den Auswirkungen einer Verhexung oder einer Verzauberung leidet, erleidet er 30...110 Punkt[e] Schaden.','Elite-Zauber. Richtet 30...110 Punkt[e] Schaden an. Gegner muss einen Zustand haben und verhext oder verzaubert sein, sonst keine Wirkung.'],
2864=>['Trennender Angriff (PvP)','Bogenangriff. Wenn Trennender Angriff trifft, fügt Ihr fügt Ihr +5...15 Punkt[e] Schaden zu. Dieser Angriff hat eine Rüstungsdurchdringung von 10%.','Bogenangriff. Richtet +5...15 Punkt[e] Schaden an. 10% Rüstungsdurchdringung.'],
2866=>['Fleisch von meinem Fleisch (PvP)','Zauber. Verliert die Hälfte Eurer Lebenspunkte. Belebt das Gruppenmitglied mit Euren aktuellen Lebenspunkten und 5...20% der Energiepunkte wieder.','Zauber. Das Gruppenmitglied wird wiederbelebt (Hälfte Eurer aktuellen Lebenspunkte, 5...20% Energiepunkte). Ihr verliert die Hälfte Eurer Lebenspunkte.'],
2867=>['Wut der Vorfahren (PvP)','Fertigkeit. 3 Sekunde[n] lang erleiden alle den Verbündeten umstehenden Feinde pro Sekunde 4...50 Punkt[e] Blitzschaden.','Fertigkeit. 3 Sekunde[n]: Richtet bei den Verbündeten (bzw. Euch selbst) umstehenden Feinden pro Sekunde 4...50 Punkt[e] Blitzschaden an.'],
2868=>['Splitterwaffe (PvP)','Waffenzauber. Ein verbündetes Ziel erhält für eine Dauer von 20 Sekunde[n] eine Splitterwaffe. Die nächsten 1...5 Angriffe des Verbündeten (bzw. Eure eigenen) fügen bis zu 4 umstehenden Feinden 5...40 Punkt[e] Schaden zu.','Waffenzauber. 20 Sekunde[n]: Angriffe richten bei 3 umstehenden Feinden 5...40 Punkt[e] Schaden an. Endet nach 1...5 Angriff[en].'],
2869=>['Mittel des Assassinen (PvP)','Verzauberung. Während der nächsten 30 Sekunde[n] entfernen Eure nächsten 1...10 Angriffsfertigkeiten einen Zustand.','Verzauberung. 30 Sekunde[n]: Eure nächsten 1...10 Angriffsfertigkeit[en] entfernen je einen Zustand.'],
2871=>['Licht der Erlösung (PvP)','Elite-Zauber. Alle Gruppenmitglieder werden für 5...70 Lebenspunkt[e] geheilt. All Eure Peinigungsgebete werden 20 Sekunden lang deaktiviert.','Elite-Zauber. Heilt die gesamte Gruppe für 5...70 Lebenspunkt[e]. Deaktiviert Eure Peinigungsgebete (20 Sekunden).'],
2872=>['Todespakt-Siegel (PvP)','Siegel. Belebt das Gruppenmitglied mit Euren aktuellen Lebenspunkten und 15...100% maximaler Energie wieder. Wenn dieser Verbündete das nächste Mal innerhalb von 120 Sekunde[n] stirbt, sterbt Ihr auch.','Siegel. Das Gruppenmitglied wird wiederbelebt (Eure aktuellen Lebenspunkte, 15...100% maximale Energie). 120 Sekunde[n]: Ihr sterbt, wenn dieses Gruppenmitglied das nächste Mal stirbt.'],
2875=>['Wurf des Läufers (PvP)','Speerangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...20 Punkt[e] Schaden zu. Wenn dieser Angriff einen sich bewegenden Feind trifft, fügt Ihr zusätzlich 5...40 Punkt[e] Schaden zu.','Speerangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet zusätzlich 5...40 Punkt[e] Schaden an, falls der Gegner sich bewegt.'],
2876=>['Verteidigungshymne (PvP)','Elite-Anfeuerungsruf. 4...10 Sekunde[n] lang hat jedes Gruppenmitglied in Hörweite eine 50%ige Chance, Angriffe zu blocken. Dieser Anfeuerungsruf endet, wenn das Gruppenmitglied mit einer Angriffsfertigkeit trifft.','Elite-Anfeuerungsruf. 4...10 Sekunde[n]: Gruppenmitglieder in Hörweite haben eine 50%ige Chance zu blocken. Endet bei einem Treffer mit einer Angriffsfertigkeit.'],
2877=>['Ballade der Wiederherstellung (PvP)','Anfeuerungsruf. 10 Sekunde[n] lang erhält jedes Gruppenmitglied in Hörweite, wenn es das nächste Mal Schaden erleidet, 15...75 Lebenspunkt[e].','Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten 15...75 Lebenspunkt[e], wenn sie das nächste Mal Schaden erleiden.'],
2878=>['Gesang der Wiederherstellung (PvP)','Elite-Anfeuerungsruf. 10 Sekunde[n] lang erhält jedes Gruppenmitglied in Hörweite, wenn es das nächste Mal eine Fertigkeit einsetzt, 45...110 Lebenspunkt[e].','Elite-Anfeuerungsruf. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten bei Benutzung ihrer nächsten Fertigkeit 45...110 Lebenspunkt[e].'],
2879=>['"Schon unterwegs!" (PvP)','Elite-Schrei. 4...10 Sekunden lang bewegen sich alle Verbündeten in Hörweite um 33% schneller und gewinnen 5...15 Lebenspunkte pro Sekunde, während sie in Bewegung sind.','Elite-Schrei. (4...10 Sekunden.) Verbündete in Hörweite bewegen sich 33% schneller und gewinnen 5...15 Lebenspunkte pro Sekunde, solange sie in Bewegung sind.'],
2880=>['"Ergebt Euch nicht!" (PvP)','Schrei. 10 Sekunde[n] lang erfreuen sich alle Gruppenmitglieder in Hörweite, deren Lebenspunkte unter 75% liegen, einer Lebenspunktregeneration von +1...5.','Schrei. 10 Sekunde[n]: Gruppenmitglieder in Hörweite erhalten +1...5 Lebenspunktregeneration. Betrifft nur Gruppenmitglieder, die weniger als 75% ihrer maximalen Lebenspunkte haben.'],
2883=>['"Für höhere Gerechtigkeit!" (PvP)','Schrei. 8 Sekunden lang erhaltet Ihr für jeden Treffer, den Ihr landet, 1 zusätzliche Adrenalinstöße.','Schrei. 8 Sekunden: Ihr erhaltet für jeden Treffer, den Ihr landet, 1 zusätzliche Adrenalinstöße.'],
2884=>['Mystische Regeneration (PvP)','Verzauberung. 5...20 Sekunde[n] lang habt Ihr für jede Verzauberung auf Euch (maximal 3) +1...4 Lebenspunktregeneration.','Verzauberung. 5...20 Sekunde[n]: Ihr habt für jede Verzauberung auf Euch (maximal 3) +1...4 Lebenspunktregeneration.'],
2885=>['Schwächendes Blut (PvP)','Zauber. Der Gegner und alle Feinde in der Nähe leiden 1...16 Sekunde[n] lang unter Schwäche.','Zauber. Verursacht beim Gegner und Feinden in der Nähe Zustand Schwäche (1...16 Sekunde[n]).'],
2887=>['Siegel des Urteils (PvP)','Elite-Siegel. Der Gegner wird zu Boden geworfen. Er und alle umstehenden Feinde erleiden 5...50 Punkt[e] heiligen Schaden. Dieses Siegel hat nur die halbe Reichweite.','Elite-Mitteldistanz-Siegel. Wirft Gegner zu Boden. Richtet beim Gegner und umstehenden Feinden 5...50 Punkt[e] heiligen Schaden an.'],
2891=>['Unbeugsame Aura','Elite-Verzauberung. Belebt ein totes Gruppenmitglied mit vollen Lebenspunkten und voller Energie wieder. Wenn Ihr aufhört, diese Verzauberung aufrechtzuerhalten, oder wenn diese Verzauberung entfernt wird, stirbt dieses Gruppenmitglied, und es hinterlässt einen verwerteten Leichnam. Solange ein Charakter mit Unbeugsame Aura verzaubert ist, ziehen Tode keinen Sterbemalus nach sich. (50 % Chance auf Fehlschlag, wenn Gunst der Götter 4 oder weniger.)','Elite-Verzauberung. Belebt das anvisierte Gruppenmitglied wieder (volle Lebenspunkte, volle Energie). Effekt endet: Dieser Verbündete stirbt und hinterlässt eine verwertete Leiche. Erhält keinen Sterbemalus. 50 % Chance auf Fehlschlag, wenn Gunst der Götter nicht mindestens 5 beträgt.'],
2892=>['Geisterbindung (PvP)','Verzauberung. Während der nächsten 8 Sekunde[n] wird der Verbündete (bzw. Ihr selbst), immer, wenn er mehr als 50 Punkt[e] Schaden durch die nächsten 10 Angriffe oder Zauber erleidet, um 30...90 Lebenspunkt[e] geheilt.','Verzauberung. 8 Sekunde[n]: Heilt jedes Mal um 30...90 Lebenspunkt[e], wenn der Verbündete (bzw. Ihr selbst) mehr als 50 Punkt[e] Schaden erleidet. Endet, nachdem der Verbündete Schaden durch 10 Angriffe oder Zauber erlitten hat.'],
2893=>['Waffe der Abwehr (PvP)','Waffenzauber. 3...8 Sekunde[n] lang hat der Verbündete (bzw. Ihr selbst) eine Waffe der Abwehr, die ihm eine Lebenspunktregeneration von +2...4 und eine 50%ige Chance zum Blocken gewährt. Waffe der Abwehr endet, wenn der betreffende Verbündete angreift.','Waffenzauber. (3...8 Sekunde[n].) +2...4 Lebenspunktregeneration. 50% Chance zu blocken. Endet, wenn der Verbündete angreift.'],
2895=>['Segen des Peinigers (PvP)','Verzauberung. 4 Sekunde[n] lang haben Eure Peinigungsgebete den doppelten Gunst-der-Götter-Bonus.','Verzauberung. 4 Sekunde[n]: Eure Peinigungsgebete haben den doppelten Gunst-der-Götter-Heilbonus.'],
2925=>['Schuss des Faultierjägers (PvP)','Bogenangriff. Wenn dieser Angriff erfolgreich ist, erleidet der Gegner +5...15 Punkt[e] Schaden. Wenn er keine Fertigkeit verwendet, fügt Schuss des Faultierjägers zusätzlich 5...20 Punkt[e] Schaden zu.','Bogenangriff. Richtet +5...15 Punkt[e] Schaden an. Richtet zusätzlich +5...20 Punkt[e] Schaden an, falls der Gegner gerade keine Fertigkeit benutzt.'],
2959=>['Gewandtheit des Profis (PvP)','Elite-Haltung. 1...20 Sekunde[n] lang greift Ihr um 15% schneller an und Euer Attribut Treffsicherheit ist um 1 erhöht.','Elite-Haltung. 1...20 Sekunde[n]: Ihr greift um 15% schneller an und Euer Attribut Treffsicherheit wird um +1 erhöht.'],
2965=>['Siegel der Geister (PvP)','Elite-Siegel. Ihr erhaltet 3...12 Energiepunkt[e], wenn Ihr Euch in Hörweite eines Geistes befindet.','Elite-Siegel. Ihr erhaltet 3...12 Energiepunkt[e]. Ihr müsst Euch in Hörweite eines Geistes befinden, sonst keine Wirkung.'],
2966=>['Siegel der Macht der Geister (PvP)','Elite-Siegel. Die Angriffe der verbündeten herbeigerufenen Kreatur fügen 5...35 Punkt[e] mehr Schaden zu. Diese Kreatur wird nach 10 Sekunde[n] vernichtet.','Elite-Siegel. Die verbündete herbeigerufene Kreatur richtet +5...35 Punkt[e] Schaden an. Diese Kreatur wird nach 10 Sekunde[n] vernichtet.'],
2969=>['Wind lesen (PvP)','Vorbereitung. 24 Sekunden lang fliegen Eure Pfeile doppelt so schnell.','Vorbereitung. (24 Sekunden.) Ihre Pfeile fliegen doppelt so schnell.'],
2998=>['Zerbrechlichkeit (PvP)','Verhexung. 8...20 Sekunde[n] lang erleiden Gegner und umstehende Feinde jedes Mal, wenn sie unter einem neuen Zustand leiden oder sich davon erholen, 5...20 Punkt[e] Schaden.','Verhexung. Verhext außerdem den Gegner und umstehende Feinde (8...20 Sekunde[n]). Diese Gegner erleiden jedes Mal, wenn sie unter einem neuen Zustand leiden oder sich davon erholen, 5...20 Punkt[e] Schaden.'],
2999=>['Stärke der Ehre (PvP)','Verzauberung. Solange Ihr diese Verzauberung aufrechterhaltet, fügt der Verbündete (bzw. Ihr selbst) im Nahkampf zusätzlich 1...5 Punkt[e] Schaden zu.','Verzauberung. Der Verbündete (bzw. Ihr selbst) richtet im Nahkampf zusätzlich 1...5 Punkt[e] Schaden an.'],
3002=>['Ausdauer des Kriegers (PvP)','Elite-Haltung. 5...35 Sekunde[n] lang erhaltet Ihr jedes Mal 3 Energiepunkte, wenn Ihr mit einem Nahangriff einen Treffer erzielt. Ausdauer des Kriegers kann Eure Energiepunkte nicht auf mehr als 10...25 ansteigen lassen.','Elite-Haltung. (5...35 Sekunde[n]) Ihr erhaltet jedes Mal 3 Energiepunkte, wenn Ihr mit einem Nahangriff einen Treffer erzielt. Keine Wirkung, es sei denn, Ihr verfügt über mehr als 10...25 Energiepunkt[e].'],
3003=>['Rüstung der Gefühllosigkeit (PvP)','Verzauberung. 10...35 Sekunde[n] lang habt Ihr beim Wirken von Binderitualen eine Basisschadens-Reduzierung von 10.','Verzauberung. (10...35 Sekunde[n].) Ihr habt eine Basisschaden-Reduzierung von 10 beim Wirken von Binderitualen.'],
3005=>['Vereinigung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Jedes Mal, wenn ein Verbündeter in seiner Reichweite, der kein Geist ist, Schaden erleidet oder Lebenspunkte entzogen bekommt, wird dies um 15 Punkt[e] reduziert und der Geist erleidet 15 Punkt[e] Schaden. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...8 (30...60 Sekunde[n] Lebensdauer). Jedes Mal, wenn ein Verbündeter in seiner Reichweite, der kein Geist ist, Schaden erleidet oder Lebenspunkte entzogen bekommt, wird dies um 15 Punkt[e] reduziert und der Geist erleidet 15 Punkt[e] Schaden.'],
3006=>['Schattengesang (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...6. Die Angriffe dieses Geistes fügen 5...20 Punkte Schaden zu und führen 1...6 Sekunden lang zu Blindheit. Dieser Geist stirbt nach 30 Sekunden.','Binderitual. Erstellt einen Geist der Stufe 1...6 (30 Sekunden Lebensdauer). Seine Angriffe fügen 5...20 Punkte Schaden zu und verursachen den Zustand Blindheit (1...6 Sekunden).'],
3007=>['Schmerz (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Die Angriffe dieses Geistes fügen 5...30 Punkt[e] Schaden zu. Dieser Geist stirbt nach 30...150 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...8 (30...150 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...30 Punkt[e] Schaden an.'],
3008=>['Vernichtung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10, der nach 30 Sekunden stirbt. Wenn dieser Geist stirbt, erleiden alle in dem Bereich befindlichen Gegner für jede Sekunde, die der Geist am Leben war, 1...10 Punkt[e] Schaden (maximal 150 Punkte).','Binderitual. Erstellt einen Geist der Stufe 1...10 (30 Sekunden Lebensdauer). Wenn dieser Geist stirbt, verursacht er bei allen in dem Bereich befindlichen Gegner für jede Sekunde, die er am Leben war, 1...10 Punkt[e] Schaden (maximal 150 Punkte).'],
3009=>['Beruhigung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Alle Feinde in seiner Reichweite benötigen doppelt so lange, um Adrenalin aufzuladen. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...8 (15...45 Sekunde[n] Lebensdauer). Das Aufladen von Adrenalin dauert bei Feinden in Reichweite doppelt so lange.'],
3010=>['Verschiebung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Alle Verbündeten in seiner Reichweite, die keine Geister sind, haben eine 75%ige Chance, Angriffe zu blocken. Jedes Mal, wenn ein Angriff auf diese Weise geblockt wird, erleidet dieser Geist 60 Punkt[e] Schaden. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...10 (30...60 Sekunde[n] Lebensdauer). Verbündete in Reichweite, die keine Geister sind, haben eine 75%ige Chance zu blocken. Blockwirkung: Der Geist erleidet 60 Punkt[e] Schaden.'],
3011=>['Erhaltung (PvP)','Elite-Binderitual. Erstellt einen Geist der Stufe 1...10. Dieser Geist heilt alle 4 Sekunden einen in dem Bereich befindlichen Verbündeten, der kein Geist ist, um 10...115 Lebenspunkt[e]. Dieser Geist stirbt nach 90 Sekunde[n].','Elite-Binderitual. Erstellt einen Geist der Stufe 1...10 (90 Sekunde[n] Lebensdauer). Alle 4 Sekunden heilt der Geist einen Verbündeten, der kein Geist ist, um 10...115 Lebenspunkt[e].'],
3012=>['Leben (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Wenn dieser Geist stirbt, werden alle Verbündeten in seiner Reichweite, die keine Geister sind, pro Sekunde, die der Geist am Leben war, um 1...7 Lebenspunkt[e] geheilt. Dieser Geist stirbt nach 20 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...10 (20 Sekunde[n] Lebensdauer). Betrifft Verbündete in Reichweite, die keine Geister sind. Wirkung am Ende: Heilt pro Sekunde, die der Geist am Leben war, um 1...7 Lebenspunkt[e].'],
3013=>['Erholung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Verbündete in seiner Reichweite, die keine Geister sind, erfreuen sich einer Lebenspunktregeneration von +1...3. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...10 (15...45 Sekunde[n] Lebensdauer). Verbündete in Reichweite, die keine Geister sind, haben +1...3 Lebenspunktregeneration.'],
3014=>['Missklang (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Dieser Geist fügt 5...20 Punkt[e] Schaden zu und all jene, die von einem seiner Angriffe getroffen werden, erleiden eine Unterbrechung. Dieser Geist stirbt nach 10...25 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...8 (10...25 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an und unterbrechen Aktionen.'],
3015=>['Erdbindung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Alle Gegner, die keine Geister sind, die in seiner Reichweite zu Boden geworfen werden, bleiben mindestens 3 Sekunden lang am Boden. Jedes Mal, wenn dies geschieht, verliert der Geist 50...25 Lebenspunkt[e]. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...10 (15...45 Sekunde[n] Lebensdauer). Feinde in Reichweite, die keine Geister sind und zu Boden geworfen werden, bleiben mindestens 3 Sekunden lang am Boden.. Bodenwurfkosten: Der Geist verliert 50...25 Lebenspunkt[e].'],
3016=>['Unterschlupf (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Verbündete in seiner Reichweite, die keine Geister sind, können bei einem einzelnen Angriff höchstens 10% ihrer Lebenspunkte verlieren. Wenn dieser Geist Schaden verhindert, verliert er 75...45 Lebenspunkt[e]. Dieser Geist besteht 30...60 Sekunde[n] lang.','Binderitual. Erstellt einen Geist der Stufe 1...8 (30...60 Sekunde[n] Lebensdauer). Verbündete in Reichweite, die keine Geister sind, können durch einen einzelnen Angriff nicht mehr als 10% ihrer maximalen Lebenspunkte verlieren. Schadensverhinderungskosten: Der Geist verliert 75...45 Lebenspunkt[e].'],
3017=>['Entzauberung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Dieser Geist fügt 5...20 Punkt[e] Schaden zu und all jene, die von einem seiner Angriffe getroffen werden, verlieren eine Verzauberung. Dieser Geist stirbt nach 15...40 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...8 (15...40 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an und entfernen eine Verzauberung.'],
3018=>['Wiederherstellung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Wenn dieser Geist stirbt, werden alle Gruppenmitglieder in dem Bereich mit 5...50% ihrer Lebenspunkte und 0 Energiepunkten wieder belebt. Dieser Geist stirbt nach 30 Sekunden.','Binderitual. Erstellt einen Geist der Stufe 1...10 (30 Sekunde[n] Lebensdauer). Wirkung am Ende: Im Bereich befindliche Gruppenmitglieder werden wiederbelebt (5...50% Lebenspunkte, 0 Energiepunkte).'],
3019=>['Blutgesang (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8, der nach 30...150 Sekunde[n] stirbt. Angriffe durch diesen Geist entziehen bis zu 5...25 Lebenspunkt[e].','Binderitual. Erstellt einen Geist der Stufe 1...8 (30...150 Sekunde[n] Lebensdauer). Seine Angriffe entziehen 5...25 Lebenspunkt[e].'],
3020=>['Fernweh (PvP)','Elite-Binderitual. Erstellt einen Geist der Stufe 1...8. Jedes Mal, wenn ein Angriff dieses Geistes einen Gegner trifft, der sich nicht bewegt, wird dieser zu Boden geworfen und der Geist verliert 70...50 Lebenspunkt[e]. Dieser Geist stirbt nach 30...60 Sekunde[n].','Elite-Binderitual. Erstellt einen Geist der Stufe 1...8 (30...60 Sekunde[n] Lebensdauer). Seine Angriffe werfen Feinde, die sich nicht bewegen, zu Boden. Bodenwurfkosten: Der Geist verliert 70...50 Lebenspunkt[e].'],
3021=>['Hitze der Savanne (PvP)','Elite-Zauber. An der Position des Gegners wird Hitze der Savanne erzeugt. In den nächsten 5 Sekunde[n] erleiden alle Gegner in der Nähe 5...20 Punkt[e] Feuerschaden pro Sekunde der Wirkzeit des Zaubers.','Elite-Zauber. Richtet pro Sekunde ab dem Wirken des Spruchs (5 Sekunde[n]) 5...20 Punkt[e] Feuerschaden an. Trifft Feinde in der Nähe der ursprünglichen Position des Ziels.'],
3022=>['Wütendes Starren (PvP)','Binderitual. Vernichtet den anvisierten Geist und erstellt einen Geist der Wut der Stufe 1...10. Die Angriffe dieses Geistes fügen 5...20 Punkt[e] Schaden zu. Dieser Geist stirbt nach 30...60 Sekunden.','Binderitual. Zerstört einen verbündeten Geist. Erstellt einen Geist der Stufe 1...10 (30...60 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an.'],
3023=>['Qual (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...7. Die Angriffe dieses Geistes fügen 5...20 Punkt[e] Schaden zu und verursachen bei verhexten Feinden doppelten Schaden. Dieser Geist stirbt nach 15...45 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...7 (15...45 Sekunde[n] Lebensdauer). Seine Angriffe richten 5...20 Punkt[e] Schaden an. Doppelter Schaden bei verhexten Feinden.'],
3024=>['Ermächtigung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Alle Verbündeten in seiner Reichweite, die einen Gegenstand halten, erhalten 15...45 maximale Lebenspunkt[e] und 10 maximale Energiepunkte. Dieser Geist stirbt nach 15...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...10 (15...60 Sekunde[n] Lebensdauer). Verbündete in Reichweite erhalten +15...45 maximale Lebenspunkte und +10 maximale Energiepunkte, falls sie einen Gegenstand halten.'],
3025=>['Gesundung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...10. Zustände, mit denen Verbündeten in Reichweite dieses Geistes belegt sind, enden um 20...50% schneller. Dieser Geist stirbt nach 30...60 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...10 (30...60 Sekunde[n] Lebensdauer). Zustände auf Verbündeten in Reichweite enden um 20...50% früher.'],
3026=>['"Zielt auf die Augen!" (PvP)','Schrei. 10 Sekunde[n] lang hat der nächste Angriff jedes Verbündeten in Hörweite zusätzlich eine 30...75%ige Chance, ein kritischen Treffer zu sein.','Schrei. (10 Sekunde[n].) Verbündete in Hörweite haben mit ihrem nächsten Angriff eine um +30...75% größere Chance für einen kritischen Treffer.'],
3027=>['"Seid vorbereitet!" (PvP)','Schrei. 5...15 Sekunde[n] lang erleidet das nächste Mal, wenn der Verbündete zu Boden geworfen würde, 1 Feind in der Nähe stattdessen 15...90 Punkt[e] Schaden.','Schrei. (5...15 Sekunde[n].) Verhindert den nächsten Bodenwurf und richtet bei einem Feind in der Nähe des Verbündeten 15...90 Punkt[e] Schaden an. Sich selbst als Ziel wählen nicht möglich.'],
3028=>['Loderndes Finale (PvP)','Echo. 10...35 Sekunde[n] lang werden jedes Mal, wenn ein auf einen Nicht-Geister-Verbündeten gerichteter Anfeuerungsruf oder Schrei endet, alle diesen Verbündeten umstehenden Feinde 1...5 Sekunde[n] lang in Brand gesetzt.','Echo. (10...35 Sekunde[n].) Verursacht bei umstehenden Feinden jedes Mal Zustand Brennen (1...5 Sekunde[n]), wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten (bzw. Euch selbst) endet. Nicht auf Geister anwendbar.'],
3029=>['Klingenumkehr-Refrain (PvP)','Echo. 20 Sekunde[n] lang hat der Nicht-Geister-Verbündete +10...40 Rüstung gegen Hiebschaden. Dieses Echo wird jedes Mal wiederholt, wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet.','Echo. (20 Sekunde[n].) Der Verbündete hat +10...40 Rüstung gegen Hiebschaden. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf dem Verbündeten endet. Nicht auf Geister anwendbar.'],
3030=>['Siegel der Wiederkehr (PvP)','Siegel. Belebt das ausgewählte Gruppenmitglied mit 5...20% seiner Lebens- und 1...4% seiner Energiepunkte pro Gruppenmitglied in Hörweite.','Siegel. Das Gruppenmitglied wird wiederbelebt (5...20% Lebenspunkte und 1...4% Energiepunkte pro Gruppenmitglied in Hörweite).'],
3031=>['"Darf nicht angerührt werden!" (PvP)','Schrei. Während der nächsten 20 Sekunde[n] scheitern die nächste[n] gegen Euch gerichtete[n] 1...5 Berührungs-Fertigkeit[en].','Schrei. (20 Sekunde[n].) Die nächste[n] 1...5 gegen Euch eingesetzte[n] Fertigkeit[en] mit Berührungsreichweite misslingen.'],
3032=>['"Haltet Eure Stellung!" (PvP)','Schrei. 5...20 Sekunde[n] lang erhalten alle Gruppenmitglieder in Hörweite +24 Rüstung, wenn sie sich nicht bewegen. Dieser Effekt endet bei einem Verbündeten, der von diesem Schrei betroffen ist, wenn er erfolgreich angreift.','Schrei. (5...20 Sekunde[n].) Gruppenmitglieder in Hörweite erhalten +24 Rüstung, wenn sie sich nicht bewegen. Endet für einen Verbündeten, wenn er angreift.'],
3033=>['"Wir kommen wieder!" (PvP)','Schrei. 10 Sekunde[n] lang werden jedes Mal, wenn Gruppenmitglieder in Hörweite eine Wiederbelebungsfertigkeit einsetzen, ihre gefallenen Verbündeten mit 10...75% mehr Lebenspunkten und 5...50% mehr Energie wieder ins Leben gerufen.','Schrei. (10 Sekunde[n].) Wenn Gruppenmitglieder in Hörweite Wiederbelebungsfertigkeiten einsetzen, werden ihre gefallenen Verbündeten mit 10...75% mehr Lebenspunkten und 5...50% mehr Energiepunkten ins Leben zurückgerufen.'],
3034=>['"Findet ihren Schwachpunkt!" (PvP)','Schrei. 5...20 Sekunden[n] lang verursacht der nächste kritische Treffer des Verbündeten (bzw. Euer eigener) auch 5...20 Sekunde[n] lang eine Tiefe Wunde.','Schrei. (5...20 Sekunde[n].) Verbündeter (bzw. Ihr selbst) verursacht mit dem nächsten kritischen Treffer den Zustand Tiefe Wunde (5...20 Sekunde[n]).'],
3035=>['"Gebt niemals auf!"  (PvP)','Schrei. Alle Verbündeten in Hörweite, deren Lebenspunkte unter 75% liegen, erhalten 1...10 Energiepunkt[e].','Schrei. Verbündete in Hörweite erhalten 1...10 Energiepunkt[e]. Betrifft nur Verbündete, die weniger als 75% ihrer maximalen Lebenspunkte haben.'],
3036=>['"Hilfe!" (PvP)','Schrei. Der Zielverbündete, der kein Geist ist, erhält 5...50 Lebenspunkte. 1...10 Sekunden werden Zauber anderer Verbündeter, die diesen Verbündeten zum Ziel haben, 50 % schneller gewirkt.','Schrei. (1...10 Sekunden) Der Zielverbündete, der kein Geist ist, erhält 5...50 Lebenspunkte. Zauber anderer Verbündeter, die diesen Verbündeten zum Ziel haben, werden 50 % schneller gewirkt.'],
3037=>['"Zurückweichen!" (PvP)','Schrei. 4...10 Sekunde[n] erhalten alle Verbündeten in Hörweite 5...15 Lebenspunkt[e] pro Sekunde, wenn sie sich bewegen und bewegen sich um 33% schneller. "Zurückweichen!" endet bei einem Verbündeten, der von diesem Schrei betroffen ist, wenn er erfolgreich angreift.','Schrei. (4...10 Sekunde[n].) Verbündete in Hörweite erhalten 5...15 Lebenspunkt[e] pro Sekunde, wenn sie sich bewegen. Sie bewegen sich um 33% schneller. Endet für einen Verbündeten, wenn er mit einem Angriff trifft.'],
3038=>['Todesqual (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...8. Feinde in Hörweite verlieren pro Sekunde 3...10 Lebenspunkt[e]. Der Geist verliert pro Feind, der auf diese Weise beeinträchtigt wird, 3...10 Lebenspunkt[e]. Dieser Geist stirbt nach 30...90 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...8 (30...90 Sekunde[n] Lebensdauer). Lässt Feinde in Hörweite jede Sekunde 3...10 Lebenspunkt[e] verlieren. Der Geist verliert für jeden betroffenen Feind 3...10 Lebenspunkt[e].'],
3039=>['Verjüngung (PvP)','Binderitual. Erstellt einen Geist der Stufe 1...16. Dieser Geist heilt alle Gruppenmitglieder in Hörweite pro Sekunde um 3...10 Lebenspunkt[e]. Der Geist verliert pro Gruppenmitglied, das auf diese Weise geheilt wird, 3...10 Lebenspunkt[e]. Dieser Geist stirbt nach 30...90 Sekunde[n].','Binderitual. Erstellt einen Geist der Stufe 1...16 (30...90 Sekunde[n] Lebensdauer). Heilt Gruppenmitglieder in Hörweite jede Sekunde um 3...10 Lebenspunkt[e]. Heilkosten: Der Geist verliert 3...10 Lebenspunkt[e].'],
3040=>['Hymne der Störung (PvP)','Anfeuerungsruf. 1...10 Sekunde[n] lang unterbricht die nächste Angriffsfertigkeit jedes Verbündeten in Hörweite außerdem eine Aktion.','Anfeuerungsruf. (1...10 Sekunde[n].) Verbündete in Hörweite unterbrechen bei Benutzung ihrer nächsten Angriffsfertigkeit eine Aktion.'],
3045=>['Tier erquicken (PvP)','Fertigkeit. Ihr heilt Euren Tiergefährten um 40...120 Lebenspunkt[e]. Ist Euer Gefährte tot, wird er mit 10...58% der Lebenspunkte wiederbelebt. Wenn Ihr die Fertigkeit \'Tier erquicken\' benutzt, reist Euer Tiergefährte mit Euch.','Fertigkeit. Euer Tiergefährte gewinnt 40...120 Lebenspunkt[e]. Euer Tiergefährte wird wiederbelebt (10...58% Lebenspunkte). Wenn Ihr die Fertigkeit \'Tier erquicken\' benutzt, reist Euer Tiergefährte mit Euch.'],
3047=>['Melandrus Angriff (Pvp)','Tiergefährtenangriff. Euer Tiergefährte greift mit Melandrus Angriff an, +5...20 Punkt[e] Schaden zufügt. Trifft die Attacke einen Gegner mit einer Verzauberung, nimmt der Gegner und alle umstehenden Gegner +5...35 zusätzlichen Schaden.','Tiergefährtenangriff. Richtet +5...20 Punkt[e] Schaden an. Richtet beim Gegner und umstehenden Feinden zusätzlich +5...35 Punkt[e] Schaden an, falls der Gegner verzaubert ist.'],
3048=>['Schleier des Kummers (PvP)','Verzauberung. 30...60 Sekunden lang habt Ihr eine 75%ige Chance Angriffe zu blocken, wenn Eure Lebenspunkte unter 50% liegen.','Verzauberung. (30...60 Sekunden.) Ihr habt eine 75%ige Chance zu blocken. Eure Lebenspunkte müssen unter 50% liegen, sonst keine Wirkung.'],
3049=>['Unsichtbare Wut (PvP)','Haltung. Während der nächsten 15...60 Sekunden könnt Ihr von geblendeten Gegnern nicht geblockt werden.','Haltung. (15...60 Sekunden.) Geblendete Feinde können Eure Angriffe nicht blocken.'],
3050=>['Raubtierverbindung (PvP)','Schrei. Während der nächsten 5...20 Sekunde[n] werdet Ihr durch erfolgreiche Angriffe Eures Tiergefährten um 1...31 Punkt[e] geheilt.','Schrei. (5...20 Sekunde[n].) Ihr erhaltet bei jedem erfolgreichen Angriff Eures Tiergefährten 1...31 Lebenspunkt[e].'],
3051=>['Erzürnter Ausfall (PvP)','Elite-Tiergefährtenangriff. Euer Tiergefährte greift mit einem Erzürnten Ausfall an, der für jede Eurer sich aufladenden Tierbeherrschungs-Fertigkeiten +3...23 Punkt[e] Schaden (maximaler Bonus 60) zufügt.','Elite-Tiergefährtenangriff. Richtet für jede Eurer sich aufladenden Tierbeherrschungs-Fertigkeiten +3...23 Punkt[e] Schaden an (maximal 60).'],
3053=>['Siegel der tödlichen Verdorbenheit (PvP)','Siegel. Muss einem Doppelangriff folgen. Der Gegner erleidet pro aktivem Zustand 5...35 Punkt[e] Schaden (maximal 130 Punkt[e]).','Siegel. Richtet für jeden Zustand des Gegners 5...35 Punkt[e] Schaden an (maximal 130). Muss einem Doppelangriff folgen.'],
3054=>['Masochismus (PvP)','Verzauberung. 30 Sekunde[n] lang erhaltet Ihr jedes Mal, wenn Ihr Lebenspunkte opfert, 1...3 Energiepunkt[e].','Verzauberung. (30 Sekunde[n].) Ihr erhaltet jedes Mal 1...3 Energiepunkt[e], wenn Ihr Lebenspunkte opfert.'],
3058=>['Unheiliger Schmaus (PvP)','Zauber. Entzieht bis zu 1...4 Gegnern in dem Bereich bis zu 10...65 Lebenspunkt[e].','Zauber. Entzieht 1...4 Feind[en] im Bereich um Euch 10...65 Lebenspunkt[e].'],
3059=>['Siegel der Qual (PvP)','Siegel. Ihr leidet 25 Sekunden lang unter einer Blutung. Alle in der Nähe befindlichen Gegner erleiden 10...70 Punkt[e] Schaden.','Siegel. Richtet bei Feinden in der Nähe 10...70 Punkt[e] Schaden an. Ihr erleidet eine Blutung (25 Sekunden).'],
3060=>['Flucht (PvP)','Elite-Haltung. 1...8 Sekunde[n] lang bewegt Ihr Euch um 33% schneller und habt eine 75%ige Chance, Angriffe zu blocken. Flucht endet, sobald Ihr einen Nahkampfangriff ausführt.','Elite-Haltung. (1...8 Sekunde[n].) Ihr bewegt Euch um 33% schneller und habt eine 75%ige Chance, Angriffe zu blocken. Endet, sobald Ihr einen Nahkampfangriff ausführt.'],
3061=>['Todesblüte (PvP)','Doppelangriff. Muss einem Begleithandangriff folgen. Wenn Todesblüte erfolgreich ist, erleidet der Gegner +20...45 Punkt[e] Schaden und alle umstehenden Feinde 20...45 Punkt[e] Schaden.','Doppelangriff. Richtet +20...45 Punkt[e] Schaden an. Außerdem werden alle umstehenden Feinde betroffen. Muss einem Begleithandangriff folgen.'],
3062=>['Finale der Wiederherstellung (PvP)','Echo. 10...35 Sekunde[n] lang wird der Nicht-Geister-Verbündete bei den nächsten 5 Mal[en], wenn ein auf ihn gerichteter Anfeuerungsruf oder Schrei endet, um 15...75 Lebenspunkt[e] geheilt.','Echo. (10...35 Sekunde[n].) Verbündeter (bzw. Ihr selbst) erhält 15...75 Lebenspunkte die nächsten 5 Mal[e], wenn ein auf diesen Verbündeten gerichteter Anfeuerungsruf oder Schrei endet. Nicht auf Geister anwendbar.'],
3063=>['Mantra des Abschlusses (PvP)','Haltung. Ihr könnt 5 Sekunde[n] lang nicht unterbrochen werden, aber jedes Mal, wenn Ihr normalerweise unterbrochen würdet, verliert Ihr 10...4 Energiepunkt[e] oder Mantra des Abschlusses endet.','Haltung. (5 Sekunde[n].) Verhindert, dass Ihr unterbrochen werdet. Verhinderungskosten: Ihr verliert 10...4 Energiepunkt[e] oder Mantra des Abschlusses endet.'],
3141=>['Blitzreflexe (PvP)','Haltung. 5...11 Sekunde[n] lang habt Ihr eine 75%ige Chance, Nahkampf- und Geschossangriffe zu blocken, außerdem ist Eure Angriffsgeschwindigkeit um 33% höher.','Haltung. (5...11 Sekunde[n].) Ihr greift um 33% schneller an und habt eine 75%ige Chance, Angriffe zu blocken.'],
3143=>['Erneuernder Schlag (PvP)','Hammerangriff. Wenn Erneuernder Schlag trifft, fügt er +5...20 Punkt[e] Schaden zu. Wenn Ihr einen zu Boden geworfenen Feind trefft, erhaltet Ihr 3 Energiepunkt[e] und dieser Angriff wird sofort wieder aufgeladen.','Hammerangriff. Richtet +5...20 Punkt[e] Schaden an. Ihr erhaltet 3 Energiepunkt[e] und dieser Angriff wird sofort wieder aufgeladen, wenn der Gegner zu Boden geworfen wurde.'],
3144=>['Gemeinsame Heilung (PvP)','Elite-Fertigkeit. Wenn Eure Lebenspunkte oder die Eures Tiergefährten unter 75% liegen, werdet Ihr beide für 25...145 Lebenspunkt[e] geheilt. Falls Euer Gefährte tot ist, wird er mit 50% der Lebenspunkte wiederbelebt.','Elite-Fertigkeit. Heilt Euch und Euren Tiergefährten für 25...145 Lebenspunkt[e]. Wenn Euer Gefährte tot ist, wird er mit 50% der Lebenspunkte wiederbelebt. Eure Lebenspunkte oder die Eures Gefährten müssen müssen unter 75% liegen, damit eine Wirkung eintritt.'],
3145=>['Glaspfeile (PvP)','Elite-Vorbereitung. Während der nächsten 10...35 Sekunde[n] fügen Eure Pfeile bei einem Treffer +6...18 Punkt[e] Schaden zu und führen 10...20 Sekunde[n] lang zu einer Blutung, wenn sie geblockt werden.','Elite-Vorbereitung. (10...35 Sekunde[n].) Eure Pfeile richten +6...18 Punkt[e] Schaden an. Verursacht Zustand Blutung (10...20 Sekunde[n]), falls geblockt.'],
3147=>['Scharfer Pfeil (PvP)','Bogenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...15 Punkt[e] Schaden zu. Falls Ihr einen kritischen Treffer landet, fügt Ihr +5...30 Punkt[e] Schaden zu.','Bogenangriff. Richtet +5...15 Punkt[e] Schaden an. Richtet zusätzlich +5...30 Punkt[e] Schaden an, falls Ihr einen kritischen Treffer landet.'],
3148=>['Hymne des Neids (PvP)','Anfeuerungsruf. 10 Sekunde[n] lang führt die nächste Angriffsfertigkeit von jedem Verbündeten in Hörweite bei Feinden mit mehr als 50% Lebenspunkten zu +10...20 Punkt[en] Schaden.','Anfeuerungsruf. (10 Sekunde[n].) Verbündete in Hörweite richten mit ihrer nächsten Angriffsfertigkeit +10...20 Punkt[e] Schaden an. Schadensbonus gilt nur bei Feinden mit mehr als 50% ihrer maximalen Lebenspunkte.'],
3149=>['Genesungsrefrain (PvP)','Echo. 15 Sekunde[n] lang erfreut Ihr Euch einer Lebenspunktregeneration von +2...3. Dieses Echo wird jedes Mal wiederholt, wenn ein auf Euch gerichteter Anfeuerungsruf oder Schrei endet.','Echo. (15 Sekunde[n].) Ihr habt +2...3 Lebenspunktregeneration. Erneuerung: Jedes Mal, wenn ein Schrei oder Anfeuerungsruf auf Euch endet.'],
3151=>['Empathie (PvP)','Verhexung. 5...15 Sekunde[n] lang erleidet der Gegner bei jedem seiner Angriffe 15...45 Punkt[e] Schaden.','Verhexung. (5...15 Sekunde[n].) Der Gegner erleidet bei jedem seiner Angriffe 15...45 Punkt[e] Schaden.'],
3152=>['Verkrüppelnde Qual (PvP)','Elite-Verhexung. 5...20 Sekunde[n] lang bewegt sich das Ziel um 50% langsamer und unterliegt einer Lebenspunktdegeneration von -2...6.','Elite-Verhexung. (5...20 Sekunde[n].) Bewegungen des Gegners sind um 50% langsamer und er hat -2...6 Lebenspunktdegeneration.'],
3156=>['Soldaten-Haltung (PvP)','Elite-Haltung. 4...10 Sekunde[n] lang greift Ihr um 33% schneller an, wenn Ihr mit einem Schrei oder Anfeuerungsruf belegt seid.','Elite-Haltung. (4...10 Sekunde[n].) Ihr greift um 33% schneller an, wenn Ihr unter dem Einfluss eines Anfeuerungsrufs oder Schreis steht.'],
3157=>['Vernichtend war Glaive (PvP)','Elite-Gegenstandszauber. Haltet Glaives Asche bis zu 30...60 Sekunde[n] lang. Während Ihr ihre Asche haltet, haben alle Ritualisten-Fertigkeiten eine Rüstungsdurchdringung von 10%. Wenn Ihr ihre Asche fallen lasst, erleiden alle Feinde in dem Bereich 15...85 Punkt[e] Blitzschaden.','Elite-Gegenstandszauber. (30...60 Sekunde[n].) Eure Ritualisten-Fertigkeiten haben eine Rüstungsdurchdringung von 10%. Fallwirkung: Richtet bei allen Feinden im Bereich 15...85 Punkt[e] Blitzschaden an.'],
3179=>['Mantra der Siegel (PvP','Haltung. Für 10...40 Sekunde[n] habt Ihr für jedes ausgerüstete Siegel +3 Rüstung. Jedes Mal, wenn Ihr ein Siegel verwendet, erhaltet Ihr 5...60 Lebenspunkte.','Haltung. (10...40 Sekunde[n].) Für jedes Siegel habt Ihr +3 Rüstung. Ihr erhaltet jedes Mal 5...60 Lebenspunkte, wenn Ihr ein Siegel verwendet.'],
3180=>['Täuschungen brechen (PvP)','Zauber. Entfernt eine Mesmer-Verhexung vom anvisierten Gegner. Dabei erleidet der Gegner 15...75 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.','Zauber. Entfernt eine Mesmer-Verhexung vom anvisierten Gegner. Dabei erleidet der Gegner 15...75 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.'],
3181=>['Illusion der Waffen (PVP)','Elite-Verzauberung. 30 Sekunden lang sind Eure Nahkampfangriffe weder erfolgreich noch erfolglos. Stattdessen verursacht Illusion der Waffen bei jedem Nahkampfangriff 20...60 Punkt[e] Schaden an Euren Gegnern.','Elite-Verzauberung. (30 Sekunden.) Richtet anstatt von Schaden oder Effekten aus Nahkampfangriffen 20...60 Punkt[e] Schaden bei Gegnern an. Eure Nahkampfangriffe sind weder erfolgreich noch erfolglos.'],
3183=>['Migräne (PvP)','Elite-Verhexung. 4...16 Sekunde[n] lang unterliegt der Gegner einer Lebenspunktdegeneration von -1...8 und benötigt 100% länger, um Fertigkeiten zu aktivieren.','Elite-Verhexung. (4...16 Sekunde[n].) Verursacht -1...8 Lebenspunktdegeneration und verdoppelt die Aktivierungszeit von Fertigkeiten.'],
3184=>['Angehäufter Schmerz (PvP)','Zauber. Der Gegner erleidet 10...35 Punkt[e] Schaden. Wenn der Gegner unter 2 oder mehr Verhexungen leidet, erleidet er 5...20 Sekunde[n] lang eine Tiefe Wunde.','Zauber. Richtet 10...35 Punkt[e] Schaden an. Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]), falls der Gegner 2 oder mehr Verhexungen hat.'],
3185=>['Übernatürliche Labilität (PvP)','Elite-Zauber. Unterbricht die Aktion des Gegners. Handelt es sich bei der Aktion um eine Fertigkeit, werden der Gegner und alle umstehenden Gegner 2...3 Sekunden lang zu Boden geworfen. (Bei Schnellwirkung von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)','Elite-Zauber. Unterbricht die Aktion des gegners. Handelt es sich bei der Aktion um eine Fertigkeit, werden der Gegner und und alle Feinde in der Nähe 2...3 Sekunden lang zu Boden geworfen. Bei Schnellwirkung von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.'],
3186=>['Geteilte Bürde (PvP)','Elite-Verhexung. Der anvisierte Gegner und alle Gegner im Bereich sind für 5...20 Sekunde[n] um 33 % langsamer, wenn sie angreifen, Zauber wirken und sich bewegen.','Elite-Verhexung. Außerdem werden Gegner im Umkreis Eures Ziels verhext (5...20 Sekunde[n]). Ihre Angriffe, gewirkten Zauber und Bewegungen sind um 33 % verlangsamt.'],
3187=>['Gestohlene Eile (PvP)','Elite-Verhexung. 1...10 Sekunde[n] lang brauchen der Gegner und alle umstehenden Feinde um 100% länger, um ihre Zauber zu wirken. Die Wirkzeit von Zaubern, die Ihr auf diese Gegner wirkt, wird um 50% gesenkt.','Elite-Verhexung. Verhext außerdem umstehende Feinde (1...10 Sekunde[n]). Verdoppelt die Wirkzeit von Zaubern. Die Wirkzeit von Zaubern, die Ihr auf verhexte Gegner wirkt, wird um 50% gesenkt.'],
3188=>['Unnatürliches Siegel (PvP)','Siegel. Der Gegner erleidet 10...60 Punkt[e] Schaden. Unterliegt der Gegner einer Verzauberung oder Verhexung, erleiden umstehende Feinde 10...60 Punkt[e] Schaden. Alle Nicht-Mesmer-Fertigkeiten (außer Siegel) sind 10 Sekunden lang deaktiviert.','Siegel. Richtet 10...60 Punkt[e] Schaden an. Richtet bei anderen umstehenden Feinden 10...60 Punkt[e] Schaden an, falls der Gegner verhext oder verzaubert ist. Eure Nicht-Mesmer-Fertigkeiten (außer Siegel) sind 10 Sekunden lang deaktiviert.'],
3189=>['Geisterschmerz (PvP)','Zauber. Der Gegner erleidet 5...40 Punkt[e] Schaden. Alle gegnerischen herbeigerufenen Kreaturen im Bereich des Gegners erleiden 25...125 Punkt[e] Schaden.','Zauber. Richtet 5...40 Punkt[e] Schaden an. Richtet bei allen gegnerischen herbeigerufenen Kreaturen im Bereich des Gegners 25...125 Punkt[e] Schaden an.'],
3190=>['Frustration (PvP)','Verhexung. Während der nächsten 5...20 Sekunde[n] wirkt der Gegner seine Zauber um 50% langsamer und erleidet jedes Mal, wenn er unterbrochen wird, 5...50 Punkt[e] Schaden.','Verhexung. (5...20 Sekunde[n].) Verlangsamt die Wirkungszeit von Zaubern um 50%. Der Gegner erleidet 5...50 Punkt[e] Schaden, wenn er unterbrochen wird.'],
3191=>['Argwohn (PvP)','Verhexung. Für 6 Sekunden schlägt der nächste Zauber, den der anvisierte Gegner auf einen Eurer Verbündeten wirkt, fehl und verursacht bei diesem Gegner 10...60 Schaden, sowie 75 % dieses Schadens bei allen benachbarten Gegnern.','Verhexung. (6 Sekunden). Der nächste Zauber, den der anvisierte Gegner auf einen Eurer Verbündeten wirkt, schlägt fehl und verursacht bei diesem Gegner 10...60 Schaden, sowie 75 % dieses Schadens bei allen benachbarten Gegnern.'],
3192=>['Rätsel des Verzauberers (PvP)','Elite-Verhexung. Für 10 Sekunden wirkt der anvisierte Gegner Verzauberungen um 100...200 % langsamer. Steht der anvisierte Gegner nicht unter dem Einfluss einer Verzauberung, wenn ihm diese Verhexung zugefügt wird, nimmt er 10...100 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens.','Elite-Verhexung. Verursacht um 100...200 % langsameres Wirken von Zaubern (10 Sekunden). Anfangseffekt: Ist der anvisierte Gegner nicht verzaubert, so nimmt er 10...100 Schaden, und benachbarte Gegner erleiden 75 % dieses Schadens.'],
3193=>['Siegel der Unbeholfenheit (PvP)','Siegel. Wenn der Gegner angreift, werden er und alle umstehenden Feinde unterbrochen und erleiden 15...60 Punkt[e] Schaden. Gegner, die Angriffsfertigkeiten verwenden, werden zu Boden geworfen.','Siegel. Unterbricht einen Angriff des Gegners und aller umstehenden Feinde. Unterbrechungswirkung: Richtet 15...60 Punkt[e] Schaden an und wirft Gegner, die Angriffsfertigkeiten verwenden, zu Boden.'],
3194=>['Spiegel der Entzauberung (PvP)','Zauber. Entfernt eine Verzauberung vom Gegner. Gruppenmitglieder des Gegners verlieren diese Verzauberung ebenfalls.','Zauber. Entfernt eine Verzauberung vom Gegner. Gruppenmitglieder des Gegners verlieren diese Verzauberung ebenfalls.'],
3195=>['Wanderndes Auge (PvP)','Verhexung. 4 Sekunde[n] lang wird der nächste Angriff des Gegners, falls dieser anzugreifen versucht, unterbrochen und alle Feinde in der Nähe erleiden 10...92 Punkt[e] Schaden.','Verhexung. (4 Sekunde[n].) Unterbricht den nächsten Angriff des Gegners. Unterbrechungswirkung: 10...92 Punkt[e] Schaden bei Gegnern in der Nähe.'],
3196=>['Kalkuliertes Risiko (PvP)','Verhexung. 3...12 Sekunde[n] lang fügen Angriffe des Gegners +10 Punkte Schaden zu, aber es gibt bei jedem Angriff eine Chance von 50%, dass der Schaden stattdessen dem Gegner zugefügt wird. (Maximal 15...60 Punkt[e] Schaden)','Verhexung. Angriffe des Gegners richten +10 Punkte Schaden an (3...12 Sekunde[n]). Bei jedem Angriff besteht eine Chance von 50%, dass der Schaden (maximal 15...60 Punkt[e]) stattdessen dem Gegner zugefügt wird.'],
3204=>['Schmerz trotzen (PvP)','Elite-Haltung. 20 Sekunde[n] lang habt Ihr zusätzlich 90...300 Lebenspunkt[e] und zusätzlich 20 Punkte Rüstung.','Elite-Haltung. (20 Sekunde[n].) Ihr habt +90...300 maximale Lebenspunkte und +20 Rüstung.'],
3232=>['Gruppe heilen (PvP)','Zauber. Heilt die ganze Gruppe um 30...75 Lebenspunkt[e].','Zauber. Heilt die ganze Gruppe um 30...75.'],
3233=>['Sieger plündern (PvP)','Elite-Verhexung. Während der nächsten 3...15 Sekunde[n] verliert der Gegner jedes Mal, wenn er eine Kreatur mit weniger Lebenspunkten angreift oder einen Zauber auf sie wirkt, 15...75 Lebenspunkt[e].','Elite-Verhexung. (3...15 Sekunde[n].) Lässt den Gegner jedes Mal 15...75 Lebenspunkt[e] verlieren, wenn er eine Kreatur mit weniger Lebenspunkten angreift oder einen Zauber auf eine solche Kreatur wirkt.'],
3234=>['Visionen des Bedauerns (PvP)','Elite-Verhexung. 10 Sekunde[n] lang erleiden der Gegner und umstehende Feinde jedes Mal, wenn sie eine Fertigkeit verwenden, 10...30 Punkt[e] Schaden und zusätzlich 5...40 Punkt[e] Schaden, sofern sie unter keiner weiteren Mesmer-Verhexung leiden.','Elite-Verhexung. Verhext den Gegner und umstehende Feinde (10 Sekunde[n]). Diese Feinde erleiden 10...30 Punkt[e] Schaden, sobald sie eine Fertigkeit verwenden und 5...40 Punkt[e] zusätzlichen Schaden, sofern sie keine andere Mesmer-Verhexung erlitten haben.'],
3251=>['Reißzähne des Fuchses (PvP)','Begleithandangriff. Muss einem Leithandangriff folgen. Reißzähne des Fuchses kann nicht geblockt werden und fügt bei einem Treffer +10...25 Punkt[e] Schaden zu.','Begleithandangriff. Richtet +10...25 Punkt[e] Schaden an. Kann nicht geblockt werden. Muss einem Leithandangriff folgen.'],
3252=>['Wilder Stoß (PvP)','Begleithandangriff. Muss einem Leithandangriff folgen. Wenn dieser Angriff erfolgreich ist, fügt er +10...35 Punkt[e] Schaden zu und jede Haltung, die der Gegner einsetzt, endet. Dieser Angriff kann nicht geblockt werden.','Begleithandangriff. Richtet +10...35 Punkt[e] Schaden an. Entfernt Haltung des Gegners. Kann nicht geblockt werden. Muss einem Leithandangriff folgen.'],
3263=>['Bannstoß (PvP)','Nahkampfangriff. Wenn der Angriff erfolgreich ist, fügt er 10...60 Punkt[e] heiligen Schaden zu. Fügt herbeigerufenen Kreaturen doppelten Schaden zu.','Nahkampfangriff. Richtet 10...60 Punkt[e] heiligen Schaden an. Fügt herbeigerufenen Kreaturen doppelten Schaden zu.'],
3264=>['Doppelter Mondschwung (PvP)','Nahkampfangriff. Ihr verliert 1 Derwisch-Verzauberung und erhaltet 10...20 Lebenspunkt[e]. Wenn eine Verzauberung auf diese Weise entfernt wird, könnt Ihr nicht geblockt werden, trefft zweimal, wobei jeder Treffer 25% weniger Schaden als sonst zufügt, und erhaltet zusätzlich 10...30 Lebenspunkt[e].','Nahkampfangriff. Entfernt 1 Eurer Derwisch-Verzauberungen. Ihr erhaltet 10...20 Energiepunkt[e]. Entfernungseffekt: Unblockbar, zwei Angriffe mit je 25% weniger Schaden pro Treffer und 10...30 Lebenspunkt[e] zusätzlich.'],
3265=>['Unwiderstehlicher Schwung (PvP)','Sensenangriff. Richtet +3...15 Punkt[e] Schaden an und verliert 1 Derwisch-Verzauberung. Wenn Ihr eine Verzauberung auf diese Weise verliert, kann Unwiderstehlicher Schwung nicht geblockt werden und entfernt eine Haltung.','Sensenangriff. Richtet +3...15 Punkt[e] Schaden an. Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Unblockbar, entfernt eine Haltung.'],
3266=>['Frommer Angriff (PvP)','Nahkampfangriff. Ihr entfernt 1 Derwisch-Verzauberung. Wenn eine Derwisch-Verzauberung entfernt wurde, lädt diese Fertigkeit 75% schneller wieder auf und alle umstehenden Feinde erleiden 15...40 Punkt[e] Schaden,','Nahkampfangriff. Entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Diese Fertigkeit lädt 75% schneller wieder auf und alle umstehenden Feinde erleiden 15...40 Punkt[e] Schaden,'],
3269=>['Lenkende Hände (PvP)','Verzauberung. 20 Sekunde[n] lang ist ein Blocken Eurer nächsten 0...3 Angriff[e] nicht möglich. Bei Aktivierung entfernt diese Fertigkeit den Zustand "Blindheit".','Verzauberung. (20 Sekunde[n].) Eure nächsten 0...3 Angriff[e] können nicht geblockt werden. Anfangswirkung: Entfernt "Blindheit".'],
3270=>['Dwaynas Avatar (PvP)','Elite-Form. 10...90 Sekunden lang fügen Eure Angriffe heiligen Schaden zu. Immer wenn Ihr eine Derwisch-Angriffsfähigkeit einsetzt, verliert Ihr 1 Verhexung. Immer wenn Ihr eine Derwisch-Verzauberung verliert, werdet Ihr um 5...50 Lebenspunkte geheilt. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunden.) Richtet heiligen Schaden an. Immer wenn Ihr eine Derwisch-Angriffsfähigkeit einsetzt, verliert Ihr 1 Verhexung. Immer wenn Ihr eine Derwisch-Verzauberung verliert, werdet Ihr um 5...50 Lebenspunkte geheilt. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
3271=>['Melandrus Avatar (PvP)','Elite-Form. 10...90 Sekunde[n] lang habt Ihr +100 Lebenspunkt[e], +30 Elementarrüstung und Eure Angriffe fügen Erdschaden zu. Immer wenn Ihr eine Derwisch-Verzauberung verliert, verliert Ihr 2 Zustände. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.','Elite-Form. (10...90 Sekunde[n].) Ihr habt +100 maximale Lebenspunkt[e], +30 Elementarrüstung und Eure Angriffe fügen Erdschaden zu. Immer wenn Ihr eine Derwisch-Verzauberung verliert, verliert Ihr 2 Zustände. Diese Fertigkeit wird 45 Sekunden lang deaktiviert.'],
3272=>['Mystische Heilung (PvP)','Zauber. Ihr werdet um 5...65 Lebenspunkt[e] geheilt. Heilt zudem alle verzauberten Gruppenmitglieder um 5...65 Lebenspunkt[e].','Zauber. Heilt Euch um 5...65 Lebenspunkt[e]. Heilt alle verzauberten Gruppenmitglieder um 5...65 Lebenspunkt[e].'],
3273=>['Siegel der frommen Zurückhaltung (PvP)','Siegel. Ihr verliert 1 Derwisch-Verzauberung und fügt Eurem Gegner 5...15 Sekunde[n] lang "Verkrüppelung" zu. Wenn eine Verzauberung entfernt wurde, lädt diese Fertigkeit 50% schneller wieder auf.','Siegel. (5...15 Sekunde[n].) Ihr verliert 1 Derwisch-Verzauberung und fügt Eurem Gegner "Verkrüppelung" zu. Entfernungseffekt: 50% schnellere Aufladung der Fertigkeit.'],
3289=>['Fieberträume (PvP)','Elite-Verhexung. 5...15 Sekunde[n] lang leiden jedes Mal, wenn der Gegner unter einem neuen Zustand leidet, alle Feinde in dem Bereich ebenfalls unter diesem.','Elite-Verhexung. (5...15 Sekunde[n].) Alle neuen Zustände, die der Gegner erhält, gehen auch auf Feinde im Bereich über.'],
3346=>['Dornenaura (PvP)','Blitzverzauberung. Alle Feinde in der Nähe leiden 5...15 Sekunde[n] an einer Blutung. 30 Sekunde[n] lang bewirkt diese Verzauberung nichts. Wenn diese Verzauberung endet, werden alle in der Nähe befindliche Feinde 3...8 Sekunde[n] lang verkrüppelt.','Blitzverzauberung. (30 Sekunde[n].) Anfangswirkung: Verursacht bei in der Nähe befindlichen Feinden den Zustand Blutung (5...15 Sekunde[n]). Wirkung am Ende: Verursacht bei in der Nähe befindlichen Feinden den Zustand Verkrüppelung (3...8 Sekunde[n]).'],
3347=>['Staubdecke (PvP)','Blitzverzauberung. Alle in der Nähe befindlichen Feinde erleiden 10...40 Punkt[e] Erdschaden. 30 Sekunde[n] lang fügen Eure Angriffe Erdschaden zu. Wenn diese Verzauberung endet, werden alle in der Nähe befindliche Feinde 1...4 Sekunde[n] lang geblendet.','Blitzverzauberung. (30 Sekunde[n].) Eure Angriffe fügen Erdschaden zu. Anfangswirkung: Richtet bei in der Nähe befindlichen Feinden 10...40 Punkt[e] Erdschaden an. Wirkung am Ende: Verursacht bei in der Nähe befindlichen Feinden Zustand Blindheit (1...4 Sekunde[n]).'],
3348=>['Lyssas Eile (PvP)','Blitzverzauberung. 3...15 Sekunde[n] lang werden Eure Derwisch-Verzauberungen um 33% schneller wieder aufgeladen. Wenn Ihr diese Verzauberung aktiviert, werden alle Aktionen umstehender Feinde unterbrochen. Wenn diese Verzauberung endet, werden alle Aktionen umstehender Feinde unterbrochen. Bei Windgebeten von 5 oder höher, sonst besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.','Blitzverzauberung. (3...15 Sekunde[n].) Eure Derwisch-Verzauberungen werden um 33% schneller wieder aufgeladen. Anfangswirkung: Unterbricht alle Aktionen umstehender Feinde. Wirkung am Ende: Unterbricht alle Aktionen umstehender Feinde. (Bei Windgebeten von 5 oder höher, sonst besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.)'],
3365=>['Attacke (PvP)','Elite-Blitzverzauberung. 2...8 Sekunde[n] lang erfolgen Eure Angriffe und Euer Adrenalingewinn um 25% schneller.','Elite-Blitzverzauberung. (2...8 Sekunde[n].) Eure Angriffe und Euer Adrenalingewinn erfolgen um 25% schneller.'],
3366=>['Herz der Wut (PvP)','Haltung. 2...10 Sekunde[n] lang sind Eure Angriffe um 25% schneller.','Haltung. (2...10 Sekunde[n].) Ihr greift um 25% schneller an.'],
3367=>['Verwundender Schlag (PvP)','Elite-Sensenangriff. Wenn dieser Angriff erfolgreich ist, leidet der Gegner 5...20 Sekunde[n] lang an einer Blutung und Ihr verliert 1 Derwisch-Verzauberung. Wenn eine Verzauberung entfernt wurde, erleidet der Gegner außerdem 5...20 Sekunde[n] lang eine Tiefe Wunde.','Elite-Sensenangriff. Verursacht Zustand Blutung (5...20 Sekunde[n]). Entfernt 1 Derwisch-Verzauberung. Entfernungseffekt: Verursacht Zustand Tiefe Wunde (5...20 Sekunde[n]).'],
3368=>['Frommer Zorn (PvP)','Haltung. Entfernt 1 Derwisch-Verzauberung. 1...5 Sekunde[n] lang sind Eure Angriffe um 25% schneller. Wenn eine Verzauberung entfernt wurde, dauert diese Haltung doppelt so lange an.','Haltung. (1...5 Sekunde[n].) Ihr greift 25% schneller an und entfernt 1 Eurer Derwisch-Verzauberungen. Entfernungseffekt: Diese Haltung dauert doppelt so lange an.'],
3373=>['Illusion der Eile (PvP)','Verzauberung. Ihr bewegt Euch für 5...11 Sekunde[n] um 33% schneller als normal. Wenn Illusion der Eile endet, werdet Ihr 3 Sekunde[n] lang in den Zustand der Verkrüppelung versetzt.','Verzauberung. (5...11 Sekunde[n].) Ihr bewegt Euch um 33% schneller. Wirkung am Ende: Ihr werdet für (3 Sekunde[n]) in den Zustand der Verkrüppelung versetzt.'],
3374=>['Illusion der Schmerzen (PvP)','Verhexung. Der Feind unterliegt 8 Sekunde[n] lang einer Lebenspunktdegeneration von -3...10 und nimmt jede Sekunde 3...10 Punkt[e] Schaden. Wenn Illusion der Schmerzen endet oder wieder einsetzt, wird der Feind um 36...120 Lebenspunkt[e] geheilt.','Verhexung. (8 Sekunde[n].) Verursacht beim Feind eine Lebenspunktdegeneration von -3...10 und er nimmt jede Sekunde 3...10 Punkte Schaden. Wirkung am Ende: Der Feind wird um 36...120 Punkt[e] geheilt. Endet bei erneuter Anwendung.'],
3375=>['Aura der Wiederherstellung (PvP)','Verzauberung. Ihr erhaltet über 60 Sekunden lang jedes Mal, wenn Ihr einen Zauber wirkt, 0...1 Energie und Heilung in Höhe von 200...400% der jeweiligen Energiekosten.','Verzauberung. (60 Sekunden). Ihr erhaltet jedes Mal, wenn Ihr einen Zauber wirkt, 0...1 Energie und Heilung in Höhe von 200...400% der jeweiligen Energiekosten.'],
3386=>['Netz der Störung (PvP)','Verhexung. Unterbricht den Gegner. 10 Sekunden lang wird der Gegner mit Netz der Störung verhext. Wenn diese Verhexung endet, wird dieser Gegner wieder unterbrochen.','Verhexung. (10 Sekunden.) Anfangswirkung: unterbricht eine Fähigkeit. Wirkung am Ende: unterbricht eine Fähigkeit.'],
3396=>['Blitzhammer (PvP)','Zauber. Der Gegner erleidet 10...100 Punkte Blitzschaden. Blitzhammer hat eine Rüstungsdurchdringung von 25%.','Zauber. Richtet 10...100 Punkte Blitzschaden an. 25% Rüstungsdurchdringung.'],
3397=>['Elementare Flamme (PvP)','Verzauberung. Während der nächsten 5...20 Sekunden wird der Gegner jedes Mal, wenn auf ihn eine Elementar-Verhexung gerichtet wird, 1...2 Sekunden lang in Brand gesetzt.','Verzauberung. (5...20 Sekunden.) Verursacht jedes Mal den Zustand Brennen (1...2 Sekunden), wenn eine Elementar-Verhexung auf den Gegner gerichtet wird.'],
3398=>['Rutschiger Boden (PvP)','Zauber. Wenn der Gegner geblendet ist oder sich bewegt, wird er zu Boden geworfen. (Bei einer Wassermagie von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit eines Misserfolges.)','Zauber. Wirft den Gegner zu Boden, falls er geblendet ist oder sich bewegt. Bei Wassermagie von 4 oder weniger besteht eine 50%ige Wahrscheinlichkeit für einen Misserfolg.'],
3422=>['Zeitabwehr','Elite-Abwehrzauber. Ihr erschafft eine Zeitabwehr an Eurem aktuellen Standort. Für 6...20 Sekunden wirken verbündete Nicht-Geister Zauber in diesem Gebiet um 15...20 % schneller und Fertigkeiten laden um 15...20 % schneller auf. PvE-Fertigkeit','Elite-Abwehrzauber. (6...20 Sekunden.) Verbündete in dieser Abwehr wirken Zauber um 15...20 % schneller und Fertigkeiten laden um 15...20 % schneller auf. Betrifft nicht verbündete Geister. PvE-Fertigkeit'],
3423=>['Seelengreifer','Elite-Verzauberung. Für 3...30 Sekunden opfern Eure Angriffe 15...20 Lebenspunkte und verursachen 15...20 Punkte mehr Schaden. PvE-Fertigkeit','Elite-Verzauberung. (3...30 Sekunden.) Angriffe verursachen +15...20 Punkte Schaden und opfern 15...20 Lebenspunkte. PvE-Fertigkeit'],
3424=>['Über die Grenze hinaus','Elite-Verzauberung. Während dieser Verzauberung wirken Eure Zauber um 20...50 % schneller und laden sich 40...80 % schneller auf, aber verursachen zunehmend Überzaubern. PvE-Fertigkeit','Elite-Verzauberung. Zauber wirken um 20...50 % schneller und laden sich um 40...80 % schneller auf. Verursacht bei Aktivierung zunehmend Überzaubern. PvE-Fertigkeit'],
3425=>['Urteilsschlag','Elite-Nahkampfangriff. Attackiert das Ziel und umstehende Feinde. Jeder treffende Angriff verursacht +13...30 Punkte heiliger Schaden und wirft angreifende Feinde zu Boden. PvE-Fertigkeit','Elite-Nahkampfangriff. Attackiert das Ziel und umstehende Feinde und verursacht +13...30 Punkte heiliger Schaden. Wirft angreifende Feinde zu Boden. PvE-Fertigkeit'],
3426=>['Sieben Waffen-Haltung','Elite-Haltung. Für 3...20 Sekunden werden Eure Waffenwerte um 1...15 erhöht und Euer Angriff ist 33 % schneller. PvE-Fertigkeit','Elite-Haltung. (3...20 Sekunden.) Waffenwerte werden um 1...15 erhöht. Euer Angriff ist 33 % schneller. PvE-Fertigkeit'],
3427=>['"Gemeinsam als Eines!"','Elite-Schrei. Für 3...15 Sekunden verursachen alle Gruppenmitglieder in der Nähe von Euch oder Eurem Tiergefährten +5...15 Punkte zusätzlichen Schaden bei Angriffen und erhalten +1...7 Lebenspunkte-Wiederherstellung. PvE-Fertigkeit','Elite-Schrei. (3...15 Sekunden.) Alle Gruppenmitglieder in der Nähe von Euch oder Eurem Tiergefährten verursachen +5...15 Punkte Schaden und erhalten +1...7 Lebenspunkte-Wiederherstellung. PvE-Fertigkeit'],
3428=>['Schattendiebstahl','Elite-Fertigkeit. Macht einen Schattenschritt zum feindlichen Ziel. Für 5...20 Sekunden sind die Werte dieses Feindes um 1...5 reduziert und Eure Werte um 1...5 erhöht. Diese Fertigkeit zählt als Leithandangriff. PvE-Fertigkeit','Elite-Fertigkeit. Macht einen Schattenschritt zum feindlichen Ziel. Für 5...20 Sekunden sind die Werte dieses Feindes um 1...5 reduziert und Eure Werte um 1...5 erhöht. Zählt als Leithandangriff. PvE-Fertigkeit'],
3429=>['Waffen aus drei Schmieden','Elite-Waffenzauber. Für 3...20 Sekunden erhält jeder verbündete Nicht-Geist in Hörweite den Effekt eines zufälligen Waffenzaubers. PvE-Fertigkeit','Elite-Waffenzauber. (3...20 Sekunden.) Verbündete in Hörweite erhalten den Effekt eines zufälligen Waffenzaubers. Betrifft nicht verbündete Geister. PvE-Fertigkeit'],
3430=>['Schwur der Revolution','Elite-Verzauberung. Für 3...10 Sekunden erhaltet Ihr +1...6 Energieregeneration. Diese Fertigkeit erneuert sich jedesmal, wenn Ihr keine Derwisch-Fertigkeit anwendet . PvE-Fertigkeit','Elite-Verzauberung. (3...10 Sekunden.) Erhaltet +1...6 Energieregeneration. Erneuerung: immer wenn Ihr keine Derwisch-Fertigkeit anwendet. PvE-Fertigkeit'],
3431=>['Heroischer Refrain','Elite-Echo. Für 3...15 Sekunden erhält ein gezielter, verbündeter Nicht-Geist +1...3 zu allen Werten. Dieses Echo erneuert sich jedes Mal, wenn ein Anfeuerungsruf oder Schrei bei diesem Verbündeten endet. PvE-Fertigkeit','Elite-Echo. (3...15 Sekunden.) Gezielter Verbündeter erhält +1...3 zu allen Werten. Erneuerung: jedes Mal, wenn ein Anfeuerungsruf oder Schrei bei diesem Verbündeten endet. Geister können nicht anvisiert werden. PvE-Fertigkeit'],
3437=>['Bauernsense (PvP)','Sensenangriff. Wenn dieser Angriff erfolgreich ist, fügt Ihr +5...35 Punkt[e] Schaden zu. Wenn Ihr mehr als einen Feind trefft, wird dieser Angriff sofort wieder aufgeladen.','Sensenangriff. Richtet +5...35 Punkt[e] Schaden an. Wird sofort wieder aufgeladen, falls Ihr mehr als einen Feind trefft.'],
3442=>['Mächtiger Wurf (PvP)','Speerangriff. Euer Speer bewegt sich dreimal so schnell. Wenn er trifft, fügt Ihr +10...40 Punkt[e] Schaden zu.','Speerangriff. Richtet +10...40 Punkt[e] Schaden an. Dieser Speer bewegt sich mit dreifacher Geschwindigkeit.'],
3443=>['Raserei','Haltung. Ihr greift 8 Sekunden lang 33 % schneller an, erleidet aber 200...150 % Schaden.','Haltung. (8 Sekunden) Ihr greift 33 % schneller an. Ihr erleidet 200...150 % Schaden.'],
3444=>['Hundert Klingen','Elite-Fertigkeit. 15 Sekunde[n] lang erleiden alle umstehenden Feinde jedes Mal, wenn Ihr mit einem Schwert angreift, 10...30 Punkt[e] Hiebschaden.','Elite-Fertigkeit. (15 Sekunde[n].) Richtet jedes Mal, wenn Ihr mit einem Schwert angreift, bei allen umstehenden Feinden 10...30 Punkt[e] Hiebschaden an.'],
3445=>['Erneuerung der Natur','Naturritual. Create a level 1...10 spirit. For 30...240 seconds, enchantments and hexes cast by non-spirit creatures take 50...75% longer to cast, and it costs twice as much Energy to maintain enchantments. This spirit dies after 30...240 seconds.','Naturritual. Creates a level 1...10 spirit (30...240 second lifespan). For creatures in range, enchantments and Hexes take 50...75% longer to cast and it costs twice as much Energy to maintain enchantments. Does not affect spirits.'],
3446=>['Soul Ignition','Verzauberung. While you maintain this enchantment, reduce Overcast at a rate of 1...2 per second. You and all adjacent foes are afflicted with burning while this enchantment is active.','Verzauberung. Reduce Overcast by 1...2 per second. You and all adjacent foes are afflicted with burning.'],
3447=>['Verschwendung','Verhexung. Nach 3 Sekunden erleidet der anvisierte Gegner 20...100 Schaden, und alle benachbarten Gegner erleiden 75 % dieses Schadens. Wenn dieser Gegner erfolgreich eine Fertigkeit anwendet, endet Verschwendung frühzeitig und richtet keinen Schaden an.','Verhexung. (3 Sekunden.) Effekt endet: Richtet beim Ziel 20...100 Schaden und bei benachbarten Gegnern 75 % dieses Schadens an. Kein Effekt und vorzeitiges Ende, wenn der anvisierte Gegner eine Fertigkeit verwendet.'],
3448=>['Frieden und Harmonie','Elite-Verzauberung. Der Verbündete (bzw. Ihr selbst) verliert 0...4 Zustände und Verhexungen. 1...3 Sekunde[n] lang enden Zustände und Verhexungen bei diesem Verbündeten um 90% schneller. All Eure Peinigungsgebete werden 20 Sekunden lang deaktiviert.','Elite-Verzauberung. Der Verbündete (bzw. Ihr selbst) verliert 0...4 Zustände und Verhexungen. Zustände und Verhexungen beim Verbündeten enden um 90% schneller (1...3 Sekunde[n]). Deaktiviert Eure Peinigungsgebete (20 Sekunde[n]).'],
3449=>['Schlag des Beschützers','Nahkampfangriff. Trifft dieser Schlag einen Gegner in der Bewegung, fügt Ihr 10...40 Punkt[e] zusätzlichen Schaden zu.','Nahkampfangriff. Richtet +10...40 Punkt[e] Schaden an, falls der Gegner sich bewegt.'],
3450=>['Verkrüppelungs-Schuss','Elite-Bogenangriff. Wenn Verkrüppelungs-Schuss trifft, leidet Euer Ziel 4...14 Sekunde[n] lang an einer Verkrüppelung. Dieser Angriff kann nicht geblockt werden.','Elite-Bogenangriff. Kann nicht geblockt werden. Verursacht Zustand Verkrüppelung (4...14 Sekunde[n]).'],
3451=>['Otyughs Schrei','Schrei. 5...15 Sekunde[n] lang erhält Euer Tiergefährte +24 Rüstung und kann nicht geblockt werden.','Schrei. 5...15 Sekunde[n]: Euer Tiergefährte hat +24 Rüstung und seine Angriffe können nicht geblockt werden.'],
3452=>['Schattenschleier','Elite-Verhexung. 2...7 Sekunde[n] lang kann der Gegner nicht zum Ziel von Verzauberungen werden.','Elite-Verhexung. 2...7 Sekunde[n]: Der Gegner kann nicht Ziel von Verzauberungen sein.'],
3453=>['Preschen','Haltung. 3 Sekunden lang läuft Ihr 50 % schneller. Für je 2 Punkte in "Schattenkünste" wird die Wiederaufladung um 1 Sekunden reduziert (max. 6 Sekunden).','Haltung. (3 Sekunden.) Ihr bewegt Euch 50 % schneller. Für je 2 Punkte in "Schattenkünste" wird die Wiederaufladung um 1 Sekunden reduziert (max. 6 Sekunden).'],
3454=>['Schildwächter','Verzauberung. 1...4 Sekunde[n] lang erhalten alle Gruppenmitglieder in Hörweite eine 75%ige Chance, Angriffe zu blocken. Jedes Mal, wenn ein Angriff geblockt wird, werden alle Verbündeten in Hörweite um 10...35 Lebenspunkt[e] geheilt und Schildwächter endet.','Verzauberung. (1...4 Sekunde[n].) Gruppenmitglieder in Hörweite haben eine 75%ige Chance, Angriffe zu blocken. Blockwirkung: Verbündete in Hörweite werden um 10...35 Lebenspunkt[e] geheilt und Schildwächter endet.'],
3455=>['Günstiger Schlag','Hammerangriff. Wenn Günstiger Schlag trifft, fügt Ihr +5...20 Punkt[e] Schaden zu und erhaltet 2...4 Energiepunkt[e]. Wenn der Gegner unter Schwäche leidet, kann dieser Angriff nicht geblockt werden.','Hammerangriff. Richtet +5...20 Punkt[e] Schaden an. Ihr erhaltet 2...4 Energiepunkt[e]. Kann nicht geblockt werden, wenn der Gegner geschwächt ist.'],
3456=>['"Feigling!"','Elite-Schrei. Wenn sich der Gegner bewegt, wird er zu Boden geworfen.','Elite-Schrei. Wirft zu Boden, falls der Gegner sich bewegt.'],
3457=>['Verteidigung des Beschützers','Fertigkeit. 4...8 Sekunde[n] lang haben Euch umstehende Verbündete eine 75%ige Chance, Angriffe zu blocken. Verteidigung des Beschützers endet, wenn Ihr Euch bewegt.','Fertigkeit. 4...8 Sekunde[n]: Euch umstehende Verbündete haben eine 75%ige Chance zu blocken. Endet, wenn Ihr Euch bewegt.'],
3458=>['Urzorn','Elite-Haltung. 1...9 Sekunden lang greift Ihr 33 % schneller an, und Ihr bewegt Euch 33 % schneller, aber Ihr erleidet 200...150 % Schaden.','Elite-Haltung. (1...9 Sekunden.) Ihr greift 33 % schneller an und bewegt Euch 33 % schneller. Ihr erleidet 200...150 % Schaden.'],
3459=>['Melandrus Schuss','Elite-Bogenangriff. Wenn Melandrus Schuss trifft, leidet Euer Gegner 5...25 Sekunde[n] lang an einer Blutung. Wenn er einen Gegner trifft, der sich bewegt oder zu Boden geworfen wurde, erleidet dieser +10...25 Punkt[e] Schaden und leidet 5...15 Sekunde[n] lang an Verkrüppelung.','Elite-Bogenangriff. Verursacht Blutung (5...25 Sekunde[n]). Richtet +10...25 Punkt[e] Schaden an und verursacht Verkrüppelung (5...15 Sekunde[n]), falls der Gegner sich bewegt oder zu Boden geworfen wurde.'],
3460=>['Ruhe','Naturritual. Erstellt einen Geist der Stufe 1...10. Von Kreaturen in seiner Reichweite, die keine Geister sind, gewirkte Verzauberungen enden 10...30% schneller. Dieser Geist stirbt nach 15...120 Sekunde[n].','Naturritual. Erstellt einen Geist der Stufe 1...10 (15...120 Sekunde[n] Lebensdauer). Verzauberungen enden bei Kreaturen in Reichweite um 10...30% schneller. Keine Wirkung auf Geister.'],
3461=>['Seelenverflechtung','Elite-Fertigkeit. 5...45 Sekunden lang kosten Eure Binderituale 15 Energie weniger (min. 5), und sie laden 25...50 % schneller wieder auf. Seelenverdrehung endet nach 1...3 Binderitualen.','Elite-Fertigkeit. (5...45 Sekunden.) Eure Binderituale kosten 15 Energie weniger (min. 5) und laden 25...50 % schneller wieder auf. Endet nach 1...3 Binderitualen.'],
3462=>['Gelenkte Waffe','Waffenzauber. 4...10 Sekunde[n] lang können die Angriffe des Verbündeten (bzw. Eure eigenen) nicht geblockt werden.','Waffenzauber. 4...10 Sekunde[n]: Angriffe können nicht geblockt werden.'],
3463=>['Reizen','Elite-Zauber. Falls der Gegner eine Fertigkeit verwendet, werden er selbst sowie alle Gegner im Bereich unterbrochen und Ihr entzieht allen unterbrochenen Gegnern im Bereich 0...5 Energiepunkt[e].','Elite-Zauber. Unterbricht eine Fertigkeit. Unterbrechungswirkung: Unterbricht außerdem andere Gegner im Bereich und Ihr entzieht allen Gegnern im Bereich 0...5 Energiepunkte.'],
3464=>['Dreschen','Haltung. 1...15 Sekunden lang greift Ihr um 33 % schneller an und bewegt Euch 33 % langsamer. Endet, sobald Ihr eine Distanzangriff-Fertigkeit benutzt.','Haltung. (1...15 Sekunden.) Ihr greift 33 % schneller an. Endet, sobald Ihr eine Distanzangriff-Fertigkeit benutzt. Ihr bewegt Euch 33 % langsamer.'],
3465=>['Angreifender Schlag','Elite-Haltung. 1...10 Sekunde[n] lang lauft Ihr um 33% schneller. Euer nächster erfolgreicher Nahkampftreffer fügt +10...80 Punkt[e] Schaden zu und diese Haltung endet. Diese Haltung endet, wenn Ihr eine Fertigkeit verwendet.','Elite-Haltung. 1...10 Sekunde[n]: Ihr bewegt Euch um 33% schneller und richtet mit Eurem nächsten Nahkampftreffer +10...80 Punkt[e] Schaden an. Endet, wenn Ihr trefft oder eine Fertigkeit benutzt.'],
3466=>['Irritierende Hitze','Elite-Naturritual. Create a level 1...10 spirit. Non-spirit creatures within its range gain adrenaline 33...66% as fast. This spirit dies after 30...120 seconds.','Elite-Naturritual. Creates a level 1...10 spirit (30...120 second lifespan). Adrenaline gain increased by 33...66% for creatures in range.'],
3467=>['Mystische Verdorbenheit','Blitzverzauberung. Alle umstehenden Feinde leiden 2...6 Sekunde[n] lang an Krankheit. 20 Sekunde[n] lang geschieht nichts. Wenn Ihr verzaubert seid, während Ihr diese Fertigkeit aktiviert, wird die Dauer von Krankheit verdoppelt. Wenn diese Verzauberung endet, werden alle Gruppenmitglieder in Hörweite von Krankheit geheilt.','Blitzverzauberung. (20 Sekunde[n].) Anfangswirkung: Alle umstehenden Feinde leiden unter Krankheit. (2...6 Sekunde[n]). Doppelte Dauer, wenn Ihr bereits verzaubert seid. Wirkung am Ende: Gruppenmitglieder in Hörweite werden von Krankheit geheilt.'],
3468=>['Griff des Läufers','Blitzverzauberung. 5...20 Sekunden lang werden Nahkampfangriffe gegen Gegner, die sich bewegen, diese Gegner außerdem 2...9 Sekunden lang verkrüppeln. Wenn Ihr diese Verzauberung wirkt, wird Verkrüppelung und ein weiterer Zustand von Euch entfernt. Diese Verzauberung endet, nachdem Ihr 1...3-mal Verkrüppelung zugefügt habt.','Blitzverzauberung. (5...20 Sekunden.) Nahkampfangriffe gegen Gegner, die sich bewegen, verkrüppeln sie außerdem. Anfangseffekt: Verkrüppelung und ein weiterer Zustand werden von Euch entfernt. Endet, nachdem Ihr 1...3-mal Verkrüppelung zugefügt habt.'],
3469=>['Trugbild-Umhang','Blitzverzauberung. 1...7 Sekunde[n] lang habt Ihr eine 30...60%ige Chance Angriffe zu blocken. Wenn Ihr Verzauberung wirkt, erleiden alle Feinde in der Nähe 10...40 Punkt[e] Erdschaden.','Blitzverzauberung. (1...7 Sekunde[n].) Ihr habt eine 30...60%ige Chance zu blocken. Anfangswirkung: Richtet bei in der Nähe befindlichen Feinden 10...40 Punkt[e] Erdschaden an.'],
3470=>['Flüchtige Stabilität','Blitzverzauberung. Während der nächsten 2...8 Sekunde[n] könnt Ihr nicht zu Boden geworfen werden und bewegt Euch um 25% schneller. Diese Verzauberung endet vorzeitig, wenn sie verhindert, dass Ihr zu Boden geworfen werdet.','Blitzverzauberung. (2...8 Sekunde[n].) Ihr könnt nicht zu Boden geworfen werden und bewegt Euch um 25% schneller. Endet, wenn sie verhindert, dass Ihr zu Boden geworfen werdet.'],
3471=>['Fromme Wiederherstellung','Zauber. Ihr erhaltet 80...150 Lebenspunkt[e] und entfernt 1 Derwisch-Verzauberung. Wenn eine Verzauberung auf diese Weise entfernt wurde, verliert Ihr außerdem 1 Verhexungen.','Zauber. Ihr erhaltet 80...150 Lebenspunkt[e] und entfernt 1 Derwisch-Verzauberung. Entfernungseffekt: Ihr verliert 1 Verhexungen.'],
3472=>['Wirbelangriff','Blitzverzauberung. 1...6 Sekunde[n] lang bewegt Ihr Euch um 33% schneller als gewöhnlich. Das nächste Mal, wenn Ihr einen Feind trefft, erleiden alle anderen Feinde in der Nähe 10...50 Kälteschaden und diese Verzauberung endet.','Blitzverzauberung. (1...6 Sekunde[n].) Ihr bewegt Euch um 33% schneller. Fügt das nächste Mal, wenn Ihr einen Feind trefft, allen anderen Feinden in der Nähe 10...50 Kälteschaden zu und die Verzauberung endet.'],
3473=>['Auraschneider','Nahkampfangriff. Wenn dieser Angriff erfolgreich ist, leidet Euer Gegner 5...15 Sekunde[n] lang an einer Blutung. Falls Ihr verzaubert seid, fügt Ihr außerdem 1...10 Sekunde[n] lang Beschädigte Rüstung zu.','Nahkampfangriff. (5...15 Sekunde[n].) Verursacht bei stehenden Feinden "Blutung". Verursacht ebenfalls Beschädigte Rüstung (1...10 Sekunde[n]), falls Ihr verzaubert seid.'],
];}
